insert into public.languages (id, code, name, native_name, writing_direction, tts_locale, is_available) values ('ar', 'ar', 'Arabe', 'العربية', 'rtl', 'ar-SA', true) on conflict (id) do update set name = excluded.name, native_name = excluded.native_name, writing_direction = excluded.writing_direction, tts_locale = excluded.tts_locale, is_available = excluded.is_available;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g01.letters1', 'ar', 'grammar', 'reading', 'Alif, bâ, tâ, thâ : ا ب ت ث', 1, '{}'::text[], 1, '{"rule": {"summary": "ا ب ت ث : un bâton et trois barques qui ne diffèrent que par leurs points.", "explanation": "L''arabe se lit de droite à gauche et compte 28 lettres. ا est un bâton sans point (le a long). ب, ت et ث ont le même corps de barque : ب a 1 point dessous (le b de bateau), ت a 2 points dessus (le t de table), ث a 3 points dessus (un t, parfois un s en Égypte).", "pattern": "ا = bâton ; ب = 1 point dessous ; ت = 2 points dessus ; ث = 3 points dessus", "examples": [{"text": "ا", "translation": "alif : le a long, un bâton sans point"}, {"text": "ب", "translation": "bâ : le b de bateau, 1 point dessous"}, {"text": "ت", "translation": "tâ : le t de table, 2 points dessus"}, {"text": "ث", "translation": "thâ : un t (parfois un s) en Égypte, 3 points dessus"}], "commonErrors": [{"wrong": "Lire ت quand il y a 1 point dessous", "right": "ب", "why": "Le point d''en bas fait la barque ب ; ت porte 2 points dessus."}, {"wrong": "Lire ث comme ت", "right": "ث", "why": "Compte les points : 3 points dessus font ث, 2 points dessus font ت."}, {"wrong": "Chercher un point sur ا", "right": "ا", "why": "ا est un bâton nu : aucun point."}], "tip": "Compte les points, puis regarde où ils sont : dessous ou dessus."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g02.letters2', 'ar', 'grammar', 'reading', 'Nûn, yâ et le jeu des points : ن ي', 1, array['ar.g01.letters1']::text[], 1, '{"rule": {"summary": "ن et ي complètent la famille des points : tout dépend de leur nombre et de leur place.", "explanation": "ن est un bol creux avec 1 point dessus (le n de nuit). ي plonge sous la ligne avec 2 points dessous (le y de yaourt ou un i long). Avec ب ت ث, tu as cinq lettres à points : ب 1 dessous, ت 2 dessus, ث 3 dessus, ن 1 dessus, ي 2 dessous.", "pattern": "ب 1 dessous ; ت 2 dessus ; ث 3 dessus ; ن 1 dessus ; ي 2 dessous", "examples": [{"text": "ن", "translation": "nûn : le n de nuit, 1 point dessus"}, {"text": "ي", "translation": "yâ : le y de yaourt, 2 points dessous"}, {"text": "ب", "translation": "bâ : 1 point dessous"}, {"text": "ت", "translation": "tâ : 2 points dessus"}], "commonErrors": [{"wrong": "Confondre ب et ن", "right": "ب = barque plate, point dessous ; ن = bol creux, point dessus", "why": "Le point est dessous pour ب et dessus pour ن."}, {"wrong": "Confondre ت et ي", "right": "ت = 2 points dessus ; ي = 2 points dessous", "why": "Même nombre de points, mais pas la même place."}, {"wrong": "Oublier la queue de ي", "right": "ي plonge sous la ligne", "why": "Aucune autre lettre à points ne descend ainsi."}], "tip": "Pose deux questions : combien de points ? dessus ou dessous ?"}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g03.letters3', 'ar', 'grammar', 'reading', 'Les trois crochets : ج ح خ', 1, array['ar.g02.letters2']::text[], 1, '{"rule": {"summary": "ج ح خ : le même crochet, et un point qui change le son.", "explanation": "ج, ح et خ ont la même forme de crochet. ج a 1 point dans le creux (dessous) et se dit g en Égypte, comme dans gâteau. ح n''a pas de point : c''est un h appuyé du fond de la gorge. خ a 1 point dessus : c''est le ch allemand de Bach.", "pattern": "ج = point dessous = g ; ح = pas de point = h appuyé ; خ = point dessus = ch de Bach", "examples": [{"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous"}, {"text": "ح", "translation": "ḥâ : un h appuyé, aucun point"}, {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus"}], "commonErrors": [{"wrong": "Lire ج comme dans l''arabe littéraire (dj)", "right": "En Égypte, ج se dit g", "why": "Au Caire, on dit g comme dans gâteau."}, {"wrong": "Confondre ح et ه", "right": "ح est un crochet appuyé ; ه est un petit nœud léger", "why": "Les deux sont des h, mais pas les mêmes."}, {"wrong": "Placer le point de خ dessous", "right": "خ a son point dessus", "why": "Dessous, c''est ج."}], "tip": "Dessous = ج, rien = ح, dessus = خ."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g04.letters4', 'ar', 'grammar', 'reading', 'Les petites jumelles : د ذ ر ز', 1, array['ar.g03.letters3']::text[], 1, '{"rule": {"summary": "د ذ ر ز : deux paires de jumelles, chacune distinguée par un seul point.", "explanation": "د (le d de dent) et ر (un r roulé) n''ont pas de point. En ajoutant 1 point dessus, on obtient ذ (un d, parfois un z en Égypte) et ز (le z de zèbre). د reste posée sur la ligne ; ر descend sous la ligne comme une virgule.", "pattern": "د → ذ et ر → ز : on ajoute 1 point dessus", "examples": [{"text": "د", "translation": "dâl : le d de dent, aucun point"}, {"text": "ذ", "translation": "dhâl : un d, parfois un z, 1 point dessus"}, {"text": "ر", "translation": "râ : un r roulé, aucun point"}, {"text": "ز", "translation": "zây : le z de zèbre, 1 point dessus"}], "commonErrors": [{"wrong": "Confondre د et ر", "right": "د reste sur la ligne ; ر descend", "why": "La virgule ر plonge sous la ligne."}, {"wrong": "Lire ذ comme le th anglais en Égypte", "right": "ذ se dit d, parfois z", "why": "L''arabe égyptien n''a pas le th de this."}, {"wrong": "Oublier le point de ز", "right": "ز = ر + 1 point dessus", "why": "Sans le point, c''est ر."}], "tip": "Un point dessus transforme ر en ز et د en ذ."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g05.letters5', 'ar', 'grammar', 'reading', 'Les dents et les boucles : س ش ص ض', 2, array['ar.g04.letters4']::text[], 1, '{"rule": {"summary": "س ش ص ض : les dents, leurs trois points, et leurs jumelles lourdes.", "explanation": "س (trois dents) se dit s comme dans soleil ; avec 3 points dessus, c''est ش (ch de chat). ص (une boucle fermée) est un s lourd ; avec 1 point dessus, c''est ض, un d lourd. Les lettres lourdes se disent plus profondément dans la gorge.", "pattern": "س → ش (+3 points) ; ص → ض (+1 point)", "examples": [{"text": "س", "translation": "sîn : le s de soleil, trois dents"}, {"text": "ش", "translation": "chîn : le ch de chat, 3 points dessus"}, {"text": "ص", "translation": "sâd : un s lourd, une boucle"}, {"text": "ض", "translation": "dâd : un d lourd, 1 point dessus"}], "commonErrors": [{"wrong": "Confondre س et ص", "right": "س a des dents ; ص a une boucle", "why": "Les dents sont légères, la boucle est lourde."}, {"wrong": "Confondre ش et ث", "right": "ش a trois dents ; ث est une barque", "why": "Les deux ont 3 points dessus mais pas le même corps."}, {"wrong": "Confondre ض et د", "right": "ض a une boucle ; د est un petit dos", "why": "ض est lourde, د est légère."}], "tip": "Dents = légère, boucle = lourde."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g06.letters6', 'ar', 'grammar', 'reading', 'Les lourdes et les gorges : ط ظ ع غ', 2, array['ar.g05.letters5']::text[], 1, '{"rule": {"summary": "ط ظ ع غ : la fin des lourdes, puis les deux lettres de gorge.", "explanation": "ط (une boucle avec un mât) est un t lourd ; avec 1 point dessus, ظ est un z lourd. ع (un petit 3 couché sur une queue) est un son de gorge serrée sans équivalent français ; avec 1 point dessus, غ se dit comme le r de rouge.", "pattern": "ط → ظ et ع → غ : on ajoute 1 point dessus", "examples": [{"text": "ط", "translation": "ṭâ : un t lourd, boucle et mât"}, {"text": "ظ", "translation": "ẓâ : un z lourd, 1 point dessus"}, {"text": "ع", "translation": "aïn : un son de gorge serrée"}, {"text": "غ", "translation": "ghaïn : le r de rouge, 1 point dessus"}], "commonErrors": [{"wrong": "Confondre ط et ص", "right": "ط a un mât ; ص n''en a pas", "why": "Le mât distingue la famille ط."}, {"wrong": "Lire ع comme un a ordinaire", "right": "ع est un son de gorge serrée", "why": "Elle serre la gorge, ce que ا ne fait pas."}, {"wrong": "Confondre غ et ر", "right": "غ est un r du fond de la gorge ; ر est roulé", "why": "Deux r différents."}], "tip": "ع est un œil, غ est l''œil avec une larme."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g07.letters7', 'ar', 'grammar', 'reading', 'Les têtes rondes et les bâtons : ف ق ك ل', 2, array['ar.g06.letters6']::text[], 1, '{"rule": {"summary": "ف ق ك ل : deux têtes rondes, un trait à zigzag et un bâton à pied.", "explanation": "ف (1 point dessus) se dit f comme dans feu ; ق (2 points dessus, queue profonde) est un coup de gorge au Caire. ك (un grand trait avec un zigzag) se dit k comme dans kilo. ل (un bâton à pied courbe) se dit l comme dans lune.", "pattern": "ف = 1 point dessus ; ق = 2 points dessus ; ك = zigzag ; ل = bâton à pied", "examples": [{"text": "ف", "translation": "fâ : le f de feu, 1 point dessus"}, {"text": "ق", "translation": "qâf : un coup de gorge au Caire, 2 points dessus"}, {"text": "ك", "translation": "kâf : le k de kilo, un zigzag"}, {"text": "ل", "translation": "lâm : le l de lune, un bâton à pied"}], "commonErrors": [{"wrong": "Confondre ف et ق", "right": "ف a 1 point, ق en a 2", "why": "Compte les points et regarde la queue."}, {"wrong": "Lire ق comme un k", "right": "Au Caire, ق est un coup de gorge", "why": "Le vrai k de l''arabe égyptien, c''est ك."}, {"wrong": "Confondre ل et ا", "right": "ل a un pied qui tourne", "why": "ا est un bâton nu."}], "tip": "Une tête ronde : 1 point = ف, 2 points = ق."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g08.letters8', 'ar', 'grammar', 'reading', 'Dernières lettres et grand bilan : م ه و ء ة ى', 2, array['ar.g07.letters7']::text[], 1, '{"rule": {"summary": "م ه و, puis ء ة ى : les dernières lettres et le bilan des 28.", "explanation": "م (une cerise à queue droite) se dit m comme dans mer ; ه (un petit nœud) est un h soufflé ; و (un petit 9) donne le ou de oui. ء est un coup de gorge ; ة est un ه coiffé de 2 points dessus, à la fin des mots féminins ; ى est un ي sans ses deux points, à la fin d''un mot.", "pattern": "م = cerise ; ه = nœud ; و = petit 9 ; ء = coup de gorge ; ة = ه + 2 points ; ى = ي sans points", "examples": [{"text": "م", "translation": "mîm : le m de mer, aucun point"}, {"text": "ه", "translation": "hâ : un h soufflé, aucun point"}, {"text": "و", "translation": "wâw : le ou de oui, aucun point"}, {"text": "ة", "translation": "tâ marbûta : ه avec 2 points dessus"}], "commonErrors": [{"wrong": "Confondre م et و", "right": "م a une queue droite ; و a une queue courbe", "why": "Regarde la queue."}, {"wrong": "Lire ة comme ه", "right": "ة a 2 points dessus", "why": "Les deux points ajoutent le ت."}, {"wrong": "Chercher 2 points sous ى", "right": "ى n''a aucun point", "why": "Avec 2 points dessous, c''est ي."}], "tip": "Sur les 28 lettres, 13 n''ont aucun point et 15 en ont ; seules ب, ج et ي ont leurs points dessous."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g09.forms_ba_family', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : ب ت ث ن ي', 1, array['ar.g08.letters8']::text[], 2, '{"rule": {"summary": "Dans un mot, une lettre change de forme selon sa place : isolée, début, milieu ou fin. Au milieu, ب ت ث ن ي sont la même dent : seuls les points les distinguent.", "explanation": "Dans un mot, les lettres s''attachent de droite à gauche. Une lettre attachée à la suivante prend la forme du début, attachée des deux côtés la forme du milieu, attachée à la précédente la forme de la fin ; seule, elle garde la forme isolée. Le tatweel ـ montre l''attache. ب ت ث ن ي ont la même dent, seuls les points changent : ب 1 dessous, ت 2 dessus, ث 3 dessus, ن 1 dessus, ي 2 dessous.", "pattern": "بـ (début)  ـبـ (milieu)  ـب (fin)  ب (isolée)", "examples": [{"text": "بيت", "translation": "maison : ب + ي + ت, trois lettres attachées"}, {"text": "بنت", "translation": "fille : même squelette, ـنـ au milieu"}, {"text": "تين", "translation": "figues : ت + ي + ن"}, {"text": "نبي", "translation": "prophète : ن + ب + ي"}], "commonErrors": [{"wrong": "بنت lu comme بيت", "right": "بنت = fille ; بيت = maison", "why": "ـنـ a un point dessus, ـيـ en a deux dessous."}, {"wrong": "ـب pris pour la forme du début", "right": "بـ est la forme du début", "why": "Le trait ـ est du côté de la lettre voisine : à gauche pour le début, à droite pour la fin."}, {"wrong": "ث lu avec deux points", "right": "ث a trois points dessus", "why": "Deux points dessus, c''est ت ; trois points dessus, c''est ث."}], "tip": "Devant une dent, compte les points avant de lire le mot."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g10.letters_that_do_not_connect', 'ar', 'grammar', 'reading', 'Les six lettres qui ne s''attachent pas : ا د ذ ر ز و', 2, array['ar.g09.forms_ba_family']::text[], 2, '{"rule": {"summary": "ا د ذ ر ز و ne s''attachent pas à la lettre suivante : elles coupent le mot en blocs, et la lettre suivante repart à neuf.", "explanation": "Un bloc est une suite de lettres attachées. Les six lettres ا د ذ ر ز و s''attachent à la lettre d''avant mais jamais à celle d''après : elles n''ont que la forme isolée et la forme de la fin. Après elles, le mot se coupe et la lettre suivante prend la forme du début (ou isolée). On lit plus vite bloc par bloc.", "pattern": "ا د ذ ر ز و : fin de bloc. Exemple : باب = با | ب", "examples": [{"text": "باب", "translation": "porte : با | ب, 2 blocs"}, {"text": "ورد", "translation": "fleurs : و | ر | د, 3 blocs"}, {"text": "زيت", "translation": "huile : ز | يت, 2 blocs"}, {"text": "أبونا", "translation": "notre père (le prêtre) : أ | بو | نا, 3 blocs"}], "commonErrors": [{"wrong": "باب lu en un seul bloc", "right": "با | ب : deux blocs", "why": "Le ا ne s''attache jamais à la lettre d''après."}, {"wrong": "ـبـ pour le deuxième ب de بابا", "right": "بـ (forme du début)", "why": "Après le ا, le ب repart à neuf et s''accroche au ا suivant : forme du début."}, {"wrong": "د pris pour ذ", "right": "ذ a un point dessus", "why": "Un point au-dessus du crochet, c''est ذ ; sans point, c''est د."}], "tip": "Cherche ا د ذ ر ز و : après chacune, un nouveau bloc commence."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g11.forms_jim_family', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : ج ح خ', 2, array['ar.g10.letters_that_do_not_connect']::text[], 2, '{"rule": {"summary": "ج ح خ ont la même tête et le même crochet : seul le point change (dessous, aucun, dessus). Au début et au milieu c''est une tête, à la fin le crochet revient.", "explanation": "ج, ح et خ se ressemblent comme ب ت ث : même corps, points différents. ج a un point dessous, ح n''en a pas, خ en a un dessus. Au début et au milieu d''un mot, la lettre est une petite tête (جـ ـجـ) ; à la fin, elle retrouve son crochet (ـج). Le point ne bouge jamais.", "pattern": "جـ ـجـ ـج ج  |  حـ ـحـ ـح ح  |  خـ ـخـ ـخ خ", "examples": [{"text": "حبيبي", "translation": "mon chéri : ح + ب + ي + ب + ي, 1 bloc"}, {"text": "خوخ", "translation": "pêches : خو | خ, 2 blocs"}, {"text": "جيب", "translation": "poche : ج + ي + ب, 1 bloc"}, {"text": "بخور", "translation": "encens : بخو | ر, 2 blocs"}], "commonErrors": [{"wrong": "خد lu comme حد", "right": "خد = prends ; حد = quelqu''un", "why": "خ a un point dessus ; ح n''en a aucun."}, {"wrong": "ج lu comme خ", "right": "ج : point dessous", "why": "Le point de ج est dessous, dans le creux ; celui de خ est dessus."}, {"wrong": "le deuxième خ de خوخ écrit avec un trait", "right": "خ isolé", "why": "Après un و, la lettre repart à neuf ; en fin de mot et seule, elle est isolée."}], "tip": "Devant une tête, cherche d''abord le point : dessous, rien, ou dessus."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g12.forms_sin_family', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : س ش ص ض', 2, array['ar.g11.forms_jim_family']::text[], 2, '{"rule": {"summary": "س ش ont trois dents, ص ض une boucle ; ش et ض sont س et ص avec des points. Les points ne bougent pas quand la forme change.", "explanation": "س et ش partagent trois dents (ش a 3 points dessus). ص et ض partagent une boucle (ض a 1 point dessus). Au début et au milieu, les dents se serrent et la boucle reste ; à la fin, la queue revient. Comme pour ب ت ث ن ي, le point fait la lettre : on le regarde avant de lire le mot.", "pattern": "سـ ـسـ ـس  |  شـ ـشـ ـش  |  صـ ـصـ ـص  |  ضـ ـضـ ـض", "examples": [{"text": "شاي", "translation": "thé : شا | ي"}, {"text": "صباح", "translation": "matin : صبا | ح"}, {"text": "أبيض", "translation": "blanc : أ | بيض"}, {"text": "جرس", "translation": "cloche : جر | س"}], "commonErrors": [{"wrong": "شاي lu ساي", "right": "ش a 3 points dessus", "why": "Sans ses 3 points, la lettre est س, et ساي n''existe pas."}, {"wrong": "ض lu ص", "right": "ض : boucle + 1 point dessus", "why": "ص n''a aucun point : le point de ض est ce qui les sépare."}, {"wrong": "ـضـ pour le ض de حاضر", "right": "ضـ (forme du début)", "why": "Le ا qui précède ne s''attache pas : le ض repart à neuf."}], "tip": "Dents ou boucle ? Puis compte les points : la lettre est là."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g13.forms_ayn_family', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : ط ظ ع غ', 3, array['ar.g12.forms_sin_family']::text[], 2, '{"rule": {"summary": "ط ظ ont une boucle et un mât, ع غ une œil ; ظ et غ sont ط et ع avec 1 point dessus. Le point fait la lettre.", "explanation": "ط et ظ partagent la boucle et le mât ; ع et غ partagent la œil. Dans chaque paire, le point dessus distingue la lettre (ظ, غ). Au début et au milieu on voit la boucle-mât ou la petite tête ; à la fin le crochet revient. Quand une lettre suit un و ou un ا, elle repart à neuf, comme le ع de يسوع qui est isolé.", "pattern": "طـ ـطـ ـط  |  ظـ ـظـ ـظ  |  عـ ـعـ ـع  |  غـ ـغـ ـغ", "examples": [{"text": "عيش", "translation": "pain : ع + ي + ش, 1 bloc"}, {"text": "جعان", "translation": "affamé : جعا | ن"}, {"text": "يسوع", "translation": "Jésus : يسو | ع, ع isolé"}, {"text": "حظ", "translation": "chance : ح + ظ, ظ à la fin"}], "commonErrors": [{"wrong": "غني lu comme عني", "right": "غ a un point dessus", "why": "Le point dessus fait la différence entre ع et غ."}, {"wrong": "طير lu comme طيب", "right": "طير finit par ر", "why": "ب a un point dessous ; ر n''en a aucun et descend sous la ligne."}, {"wrong": "ع de يسوع écrit avec un trait", "right": "ع isolé", "why": "Le و ne s''attache pas à la suivante : le ع repart à neuf, et seul il est isolé."}], "tip": "Cherche d''abord le mât ou la tête, puis le point dessus."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g14.forms_fa_lam', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : ف ق ك ل', 3, array['ar.g13.forms_ayn_family']::text[], 2, '{"rule": {"summary": "ف ق sont des têtes rondes (1 et 2 points dessus), ك ل sont des bâtons. ل s''attache à la suivante, contrairement à ا qui coupe le mot.", "explanation": "ف et ق ont la même tête ronde : ف avec 1 point dessus, ق avec 2 points dessus. ك et ل sont des bâtons : ك est un trait penché avec un petit zigzag, ل est un bâton avec un pied courbé. Au début et au milieu, on voit la boule ou le bâton ; à la fin, le pied revient. ل s''attache à la lettre suivante, alors que ا ne s''attache jamais : le bâton ل ne coupe pas le mot.", "pattern": "فـ ـفـ ـف  |  قـ ـقـ ـق  |  كـ ـكـ ـك  |  لـ ـلـ ـل", "examples": [{"text": "صليب", "translation": "croix : ص + ل + ي + ب, 1 bloc"}, {"text": "قداس", "translation": "liturgie : قد | ا | س, 3 blocs"}, {"text": "كرسي", "translation": "chaise : كر | سي, 2 blocs"}, {"text": "فول", "translation": "fèves : فو | ل, 2 blocs"}], "commonErrors": [{"wrong": "قلب lu فلب", "right": "ق a 2 points dessus", "why": "ف n''a qu''un seul point dessus."}, {"wrong": "ل pris pour ا dans صليب", "right": "ل s''attache : صليب = 1 bloc", "why": "ا coupe le mot, ل non : le ل est attaché des deux côtés."}, {"wrong": "ك pris pour ل", "right": "ك a un petit zigzag", "why": "ل est un bâton sans zigzag ; ك porte un petit zigzag dans l''angle."}], "tip": "Boule : compte les points (1 ou 2). Bâton : lisse, ou un trait avec un zigzag ?"}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g15.forms_mim_ha', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : م ه و ة', 3, array['ar.g14.forms_fa_lam']::text[], 2, '{"rule": {"summary": "م est une boucle fermée, ه une lettre aux quatre visages très différents, و ne s''attache pas, et ة n''existe qu''à la fin d''un mot (ـة attachée ou ة isolée).", "explanation": "م garde sa boucle au début et au milieu, sa queue revient à la fin. ه change complètement de dessin selon sa place : ه هـ ـهـ ـه. و fait partie des lettres qui ne s''attachent pas. ة, un ه avec 2 points dessus, ne s''écrit qu''en fin de mot : ـة si la lettre d''avant s''attache (كنيسة), ة isolée si elle ne s''attache pas (قهوة).", "pattern": "مـ ـمـ ـم  |  هـ ـهـ ـه  |  ـو  |  ـة ة", "examples": [{"text": "مية", "translation": "eau : م + ي + ة, 1 bloc"}, {"text": "قهوة", "translation": "café : قهو | ة, ة isolé"}, {"text": "كنيسة", "translation": "église : 1 bloc, ـة attaché"}, {"text": "ترابيزة", "translation": "table : تر | ا | بيز | ة, 4 blocs"}], "commonErrors": [{"wrong": "ة finale écrite ه", "right": "ة a 2 points dessus", "why": "Sans ses 2 points, la lettre serait un ه."}, {"wrong": "ـة attachée après و dans قهوة", "right": "ة isolée", "why": "Le و ne s''attache pas à la suivante : le ة reste seul."}, {"wrong": "م confondu avec ن", "right": "م n''a aucun point", "why": "ن a un point dessus et une forme de bol ; م est une boucle fermée sans point."}], "tip": "ة = ه + 2 points, toujours à la fin du mot."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g16.article_and_ligature', 'ar', 'grammar', 'reading', 'L''article ال, la ligature لا et le bilan de lecture', 3, array['ar.g15.forms_mim_ha']::text[], 2, '{"rule": {"summary": "ال devant un nom veut dire le / la et ajoute un bloc au début ; ل suivi de ا s''écrit avec la ligature لا, qui ferme le bloc comme un ا.", "explanation": "L''article ال (ا puis ل) se place devant le nom : الكنيسة, البيت. Le ا ne s''attache pas, donc ال forme un bloc à lui seul et le ل s''accroche au nom (forme du début). Quand ل est suivi de ا, les deux se fondent en un seul signe, la ligature لا, qui ferme le bloc. Pour lire un mot : repère ال, coupe en blocs, lis chaque bloc lettre par lettre, assemble.", "pattern": "ال + nom = le / la + nom   |   ل + ا = لا", "examples": [{"text": "الكنيسة", "translation": "l''église : ا | لكنيسة, 2 blocs"}, {"text": "المسيح", "translation": "le Christ : ا | لمسيح"}, {"text": "صلاة", "translation": "prière : صلا | ة, avec la ligature لا"}, {"text": "العدرا", "translation": "la Vierge Marie : ا | لعد | ر | ا, 4 blocs"}], "commonErrors": [{"wrong": "لكنيسة pour « l''église »", "right": "الكنيسة", "why": "L''article commence par le ا : ال = ا puis ل."}, {"wrong": "ل et ا écrits côte à côte dans صلاة", "right": "la ligature لا", "why": "ل suivi de ا se fond en un seul signe."}, {"wrong": "ال lu comme une partie du nom", "right": "ال = le / la", "why": "ال est un mot-outil : cache-le, lis le nom, puis ajoute « le / la »."}], "tip": "Cache ال avec le doigt, lis le nom, puis ajoute « le / la »."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g17.short_vowels', 'ar', 'grammar', 'reading', 'Les trois voyelles brèves : fatha, kasra, damma', 2, array['ar.g16.article_and_ligature']::text[], 3, '{"rule": {"summary": "Trois petits signes donnent les voyelles brèves : la fatha ـَ (a), la kasra ـِ (i) et la damma ـُ (ou).", "explanation": "L''arabe écrit les consonnes ; les voyelles brèves sont des signes, les harakat. La fatha est un trait penché au-dessus de la lettre (a), la kasra le même trait sous la lettre (i), la damma un petit و bouclé au-dessus (ou). La voyelle se dit après sa lettre. En égyptien, un mot finit presque toujours sans voyelle : la dernière lettre n''a pas de signe.", "pattern": "بَ = b + a    بِ = b + i    بُ = b + ou", "examples": [{"text": "جَبَل", "translation": "montagne : ج + a, ب + a, puis ل sans voyelle"}, {"text": "عِنَب", "translation": "raisin : une kasra sous ع, puis deux fathas"}, {"text": "كُتُب", "translation": "livres : deux dammas"}, {"text": "حَمَل", "translation": "agneau : l''Agneau de Dieu est le Christ"}], "commonErrors": [{"wrong": "بِ lu b + a", "right": "بِ = b + i", "why": "Le trait sous la lettre est une kasra : le son est i."}, {"wrong": "كَتَب lu comme كُتُب", "right": "كُتُب = livres ; كَتَب = il a écrit", "why": "Les consonnes sont les mêmes, mais chaque voyelle change le mot."}, {"wrong": "une voyelle sur la dernière lettre de بَلَد", "right": "بَلَد finit par د sans signe", "why": "En égyptien, le mot se termine sans voyelle."}], "tip": "Ouvrir, casser, rassembler : fatha = a, kasra = i, damma = ou."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g18.sukun', 'ar', 'grammar', 'reading', 'Le soukoun ـْ et les sons ـَيْ, ـَوْ', 2, array['ar.g17.short_vowels']::text[], 3, '{"rule": {"summary": "Le soukoun ـْ, un petit rond au-dessus de la lettre, dit qu''elle n''a pas de voyelle : on enchaîne directement avec la lettre suivante.", "explanation": "Une lettre avec soukoun se lit seule, sans voyelle, collée à la lettre d''avant. Dans بُرْج, le ر n''a pas de voyelle : b + ou, puis r, puis j. Avec ـَيْ et ـَوْ, la fatha et la lettre forment un seul son : en égyptien, ـَيْ se dit é long et ـَوْ se dit ô. À la fin d''un mot, le soukoun est souvent omis.", "pattern": "بُرْج : بُ + رْ + ج    ـَيْ = é long    ـَوْ = ô", "examples": [{"text": "بُرْج", "translation": "tour, clocher : ر sans voyelle"}, {"text": "كَلْب", "translation": "chien : ل sans voyelle"}, {"text": "يَوْم", "translation": "jour : ـَوْ se dit ô"}, {"text": "خَيْر", "translation": "bien : ـَيْ se dit é long"}], "commonErrors": [{"wrong": "ـْ lu comme une voyelle", "right": "ـْ = aucune voyelle", "why": "Le petit rond veut dire « rien » : la lettre est collée à la suivante."}, {"wrong": "يَوْم lu en deux syllabes avec un ou séparé", "right": "يَوْم : ـَوْ forme un seul son, ô", "why": "La fatha et و avec soukoun se fondent en un seul son."}, {"wrong": "كَلْب lu avec une voyelle sur ل", "right": "كَلْب : ك + a, ل, ب", "why": "Le soukoun empêche toute voyelle sur ل."}], "tip": "Rond = rien : le soukoun coupe la voyelle."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g19.long_vowels', 'ar', 'grammar', 'reading', 'Les voyelles longues : ـَا, ـُو, ـِي', 2, array['ar.g18.sukun']::text[], 3, '{"rule": {"summary": "ا و ي après la voyelle brève qui leur correspond donnent les voyelles longues : ـَا (a long), ـُو (ou long), ـِي (i long).", "explanation": "Les lettres ا و ي peuvent allonger une voyelle. Après une fatha, ا donne un a long ; après une damma, و donne un ou long ; après une kasra, ي donne un i long. La lettre qui allonge ne porte aucun signe. Une voyelle longue dure à peu près deux fois plus longtemps qu''une brève. Si و ou ي porte une voyelle (وَ، يَ), elle redevient une consonne, comme dans يَوْم.", "pattern": "ـَا = a long    ـُو = ou long    ـِي = i long", "examples": [{"text": "نُور", "translation": "lumière : damma + و = ou long"}, {"text": "مَلَاك", "translation": "ange : fatha + ا = a long"}, {"text": "كِبِير", "translation": "grand : kasra + ي = i long"}, {"text": "خَلَاص", "translation": "c''est fini, salut"}], "commonErrors": [{"wrong": "نُور lu avec un ou court puis un w", "right": "نُور : ou long", "why": "و sans signe après une damma allonge la voyelle."}, {"wrong": "كِبِير lu avec un y après le i", "right": "كِبِير : i long", "why": "ي sans signe après une kasra allonge la voyelle."}, {"wrong": "ـَا lu a + a", "right": "ـَا = un seul a long", "why": "ا n''ajoute pas une deuxième voyelle : il rallonge la fatha."}], "tip": "Voyelle brève + lettre sœur = voyelle longue."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g20.shadda', 'ar', 'grammar', 'reading', 'La chadda ـّ : lettre doublée', 3, array['ar.g18.sukun']::text[], 3, '{"rule": {"summary": "La chadda ـّ, un petit w au-dessus de la lettre, double la lettre : on la prononce deux fois.", "explanation": "La chadda remplace une lettre répétée : كُبَّايَة s''écrit avec un seul ب, mais on prononce bb. La première moitié ferme la syllabe d''avant, la seconde ouvre la suivante. La voyelle se pose avec la chadda : fatha ـَّ, damma ـُّ au-dessus, kasra ـِّ sous la lettre. En égyptien, une lettre doublée peut aussi finir un mot : رَبّ.", "pattern": "بَّ = bb + a    بُّ = bb + ou    بِّ = bb + i", "examples": [{"text": "كُبَّايَة", "translation": "verre : ب doublé"}, {"text": "مَيَّة", "translation": "eau : ي doublé"}, {"text": "قُدَّاس", "translation": "messe : د doublé"}, {"text": "رَبّ", "translation": "Seigneur : ب doublé en fin de mot"}], "commonErrors": [{"wrong": "كُبَّايَة lu avec un seul ب", "right": "كُبَّايَة : bb", "why": "La chadda compte pour deux lettres."}, {"wrong": "chadda lue comme une voyelle", "right": "chadda = lettre doublée", "why": "Elle ne donne pas de son nouveau : elle double la consonne, et la voyelle vient à côté."}, {"wrong": "chadda confondue avec le soukoun", "right": "soukoun = petit rond, chadda = petit w", "why": "Rond : aucune voyelle. W : lettre doublée."}], "tip": "Chadda = deux fois la lettre."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g21.tanwin', 'ar', 'grammar', 'reading', 'Le tanwin : ـً, ـٍ, ـٌ', 3, array['ar.g20.shadda']::text[], 3, '{"rule": {"summary": "Le tanwin est un signe doublé à la fin d''un mot : ـً (an), ـٍ (in), ـٌ (oun). Le plus courant en égyptien est ـً, comme dans شُكْرًا.", "explanation": "Tanwin veut dire « nounation » : on double le signe et on ajoute un n à la fin du mot. Fathatan ـً : an, avec un alif muet (شُكْرًا). Kasratan ـٍ : in. Dammatan ـٌ : oun. En égyptien, tu verras surtout ـً dans des adverbes : شُكْرًا, جِدًّا, طَبْعًا. ـٍ et ـٌ se rencontrent dans les textes d''église et les livres.", "pattern": "ـً = an    ـٍ = in    ـٌ = oun", "examples": [{"text": "شُكْرًا", "translation": "merci : tanwin fatha, alif muet"}, {"text": "جِدًّا", "translation": "très : chadda + tanwin"}, {"text": "طَبْعًا", "translation": "bien sûr"}, {"text": "بَيْتٌ  بَيْتٍ  بَيْتًا", "translation": "les trois tanwins sur la même base"}], "commonErrors": [{"wrong": "ـً lu comme une simple fatha", "right": "ـً = an", "why": "Le signe est doublé : on entend un n à la fin."}, {"wrong": "l''alif de شُكْرًا lu comme un a de plus", "right": "l''alif de شُكْرًا est muet", "why": "Il porte seulement le tanwin, il ne se dit pas à part."}, {"wrong": "tanwin au milieu du mot", "right": "tanwin = toujours à la fin du mot", "why": "Il remplace la voyelle de fin de mot."}], "tip": "Tanwin = signe doublé = un n à la fin."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g22.hamza_madda', 'ar', 'grammar', 'reading', 'La hamza ء et la madda آ', 3, array['ar.g19.long_vowels']::text[], 3, '{"rule": {"summary": "La hamza (coup de gorge) s''écrit seule ء ou sur un support : أ إ ؤ ئ. Sur ا, une madda donne آ : hamza + a long.", "explanation": "ء est un coup de gorge. Elle prend un support selon la voyelle la plus forte (kasra, puis damma, puis fatha) : أ sur ا avec fatha ou damma, إ sous ا avec kasra, ؤ sur و avec damma, ئ sur ي sans points avec kasra. Après une voyelle longue ou un soukoun, elle s''écrit seule : مَسَاء. آ = ا + hamza + a long : آمِين. Un ا avec une voyelle mais sans hamza, comme dans اِرْحَم, ne fait que porter la voyelle.", "pattern": "أَ أُ    إِ    ؤُ    ئِ    ء    آ", "examples": [{"text": "أَيْوَه", "translation": "oui : hamza sur ا avec fatha"}, {"text": "إِيه", "translation": "quoi : hamza sous ا avec kasra"}, {"text": "سُؤَال", "translation": "question : ؤ sur و"}, {"text": "آمِين", "translation": "amen : madda"}], "commonErrors": [{"wrong": "إِ lu avec une fatha", "right": "إِ = hamza + i", "why": "Quand la hamza est sous ا, elle porte une kasra."}, {"wrong": "آ lu comme un ا simple", "right": "آ = hamza + a long", "why": "La madda ajoute un coup de gorge avant le a long."}, {"wrong": "ؤ lu comme un و simple", "right": "ؤ = hamza sur و", "why": "Le petit signe sur و est la hamza : on entend un coup de gorge."}], "tip": "Le support suit la voyelle la plus forte : kasra, damma, fatha."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g23.article_sun_moon', 'ar', 'grammar', 'reading', 'ال, lettres solaires et lunaires', 3, array['ar.g20.shadda']::text[], 3, '{"rule": {"summary": "ال veut dire « le / la / les ». Devant une lettre lunaire, le ل se dit ; devant une lettre solaire, le ل s''efface et la lettre est doublée par une chadda.", "explanation": "ال s''écrit collé au nom. Devant les 14 lettres lunaires (أ ب ج ح خ ع غ ف ق ك م ه و ي), le ل garde un soukoun et se dit : الْقَمَر. Devant les 14 lettres solaires (ت ث د ذ ر ز س ش ص ض ط ظ ل ن), le ل s''efface et la lettre qui suit porte une chadda : الشَّمْس. En égyptien, ال se lit comme la fin de « hôtel ». Dans un texte vocalisé, la chadda après ال t''indique tout de suite une lettre solaire.", "pattern": "الْ + lunaire    ال + solaire avec chadda", "examples": [{"text": "الْقَمَر", "translation": "la lune : ق est lunaire, le ل se dit"}, {"text": "الشَّمْس", "translation": "le soleil : ش est solaire, il est doublé"}, {"text": "الْكَنِيسَة", "translation": "l''église : ك est lunaire"}, {"text": "النَّهَارْدَه", "translation": "aujourd''hui : ن est solaire"}], "commonErrors": [{"wrong": "الشَّمْس lu avec le ل dit", "right": "الشَّمْس : le ل s''efface", "why": "ش est solaire : il absorbe le ل et se double."}, {"wrong": "الْقَمَر lu avec ق doublé", "right": "الْقَمَر : le ل se dit", "why": "ق est lunaire : rien ne s''efface."}, {"wrong": "ال écrit sans le ا", "right": "ال = ا + ل", "why": "L''article est toujours composé de ces deux lettres collées au nom."}], "tip": "Chadda après ال = lettre solaire. Soukoun sur le ل = lettre lunaire."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g24.ta_marbuta_alif_maqsura', 'ar', 'grammar', 'reading', 'ة et ى, et lire des mots vocalisés', 3, array['ar.g23.article_sun_moon']::text[], 3, '{"rule": {"summary": "ة marque le féminin et ne se dit pas : le a final vient de la fatha d''avant. ى est un a long final écrit comme un ي sans points.", "explanation": "ة (tâ marbûta) termine la plupart des mots féminins et suit toujours une fatha (ou un alif long) : dans قَهْوَة, le a final est celui de la fatha sur و. Quand le mot est suivi de son complément, elle se lit parfois t : كَنِيسَةِ الْعَدْرَا. ى (alif maqsûra) ne se trouve qu''à la fin d''un mot ; après une fatha, elle donne un a long : عَلَى, مُوسَى, مَتَّى.", "pattern": "ـَة = a final    ـَى = a long final", "examples": [{"text": "قَهْوَة", "translation": "café : le a final vient de la fatha sur و"}, {"text": "كَنِيسَة", "translation": "église"}, {"text": "مُوسَى", "translation": "Moïse : ى donne un a long"}, {"text": "مَتَّى", "translation": "Matthieu, l''évangéliste"}], "commonErrors": [{"wrong": "قَهْوَة lu avec un a de plus après و", "right": "قَهْوَة : le a de وَ suffit", "why": "ة est muette, elle ne rajoute pas de son."}, {"wrong": "ى lu comme un i (ي)", "right": "ى = a long", "why": "ى n''a pas de points et suit une fatha : c''est un a long."}, {"wrong": "ة toujours lue t", "right": "ة se dit a, parfois t devant un complément", "why": "Seul le lien avec le mot suivant la fait entendre t."}], "tip": "ة : le a est déjà dans la fatha d''avant. ى : sans points, c''est un a long."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g25.syllabes', 'ar', 'grammar', 'reading', 'Lire par syllabes : consonne + voyelle', 1, array['ar.g22.hamza_madda']::text[], 4, '{"rule": {"summary": "Une syllabe est une consonne suivie d''une voyelle. Lire vite, c''est reconnaître ces petits paquets d''un coup d''œil au lieu d''épeler lettre par lettre.", "explanation": "Les voyelles longues s''écrivent avec les lettres ا و ي : elles te montrent où sont les paquets longs. Les voyelles courtes ne sont pas écrites quand il n''y a pas de harakat ; ton oreille de locuteur égyptien les ajoute dès que tu reconnais le mot. La méthode : repère les lettres ا و ي, coupe en paquets, dis chaque paquet, recolle.", "pattern": "consonne + voyelle = 1 paquet : مَا | مَا = ماما", "examples": [{"text": "ماما", "translation": "maman : deux paquets ما | ما"}, {"text": "تيتة", "translation": "mamie : تي | تة, le ي est la balise"}, {"text": "موز", "translation": "banane : un paquet long مو, puis ز"}, {"text": "سمك", "translation": "poisson : trois consonnes écrites, les voyelles viennent de l''oreille"}], "commonErrors": [{"wrong": "Lire ماما en épelant م, ا, م, ا", "right": "Lire deux paquets : ما | ما", "why": "L''alif prolonge la voyelle de la consonne qui le précède : les deux forment un seul paquet."}, {"wrong": "Chercher une lettre pour chaque voyelle dans سمك", "right": "Lire س م ك et laisser l''oreille ajouter les voyelles", "why": "Sans harakat, les voyelles courtes ne sont jamais écrites."}, {"wrong": "Couper تيتة en ت | يتة", "right": "Couper en تي | تة", "why": "La balise ي reste collée à la consonne qui la précède."}], "tip": "Repère d''abord les lettres ا و ي : ce sont tes balises."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g26.long_words', 'ar', 'grammar', 'reading', 'Lire les mots longs : couper en blocs', 2, array['ar.g25.syllabes','ar.g10.letters_that_do_not_connect']::text[], 4, '{"rule": {"summary": "Un mot long n''est qu''une suite de petits blocs. Les lettres ا د ذ ر ز و ferment un bloc ; si un bloc reste long, on le coupe en paquets, et on lit ال d''un coup.", "explanation": "Un bloc est une suite de lettres attachées (module 2). Pour lire un long mot, coupe-le à chaque ا د ذ ر ز و, lis chaque bloc, puis recolle. Quand il n''y a aucune coupure, comme dans مستشفى, coupe en paquets de deux ou trois lettres. Reconnais aussi les morceaux qui reviennent : ال (« le, la »), la fin ـة, la fin ـنا (« notre ») et le و collé devant un mot (« et »).", "pattern": "ال + blocs + fin : ا | لقا | هر | ة", "examples": [{"text": "تليفون", "translation": "téléphone : تليفو | ن, deux blocs"}, {"text": "جامعة", "translation": "université : جا | معة"}, {"text": "القاهرة", "translation": "Le Caire : ا | لقا | هر | ة, avec ال au début"}, {"text": "مستشفى", "translation": "hôpital : un seul bloc, coupé en paquets مس | تش | فى"}], "commonErrors": [{"wrong": "Lire مستشفى lettre par lettre : م, س, ت, ش, ف, ى", "right": "Couper en paquets : مس | تش | فى", "why": "Sans lettre de coupure, on découpe soi-même en paquets de deux ou trois lettres."}, {"wrong": "Chercher ال au milieu du mot القاهرة", "right": "Lire ال au début, puis le reste du mot", "why": "ال s''écrit collé au début du mot : le ا ferme son bloc, puis le ل s''attache à la suite."}, {"wrong": "Prendre le و de بابا وماما pour une lettre du mot", "right": "Le lire comme le petit mot « et »", "why": "Le و ne s''attache pas au mot suivant : il reste seul, comme un mot d''une lettre."}], "tip": "Coupe d''abord aux six lettres, puis en paquets si le bloc est encore long."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g27.short_sentences', 'ar', 'grammar', 'reading', 'Lire de petites phrases égyptiennes', 2, array['ar.g26.long_words']::text[], 4, '{"rule": {"summary": "Les phrases égyptiennes de tous les jours s''écrivent sans voyelles, comme on les dit. Pour les lire, on repère les mots un par un, de droite à gauche, et on vérifie le sens.", "explanation": "Au présent, l''arabe égyptien n''a pas de verbe « être » : أنا كويس veut dire à la lettre « moi bien ». Les phrases sont donc courtes et faciles à lire. Les mots qui reviennent sont à connaître comme des images : إزيك (comment vas-tu ?), كويس (bien), فين (où), شكرا (merci), لو سمحت (excuse-moi). Une femme termine souvent le mot par ـة : عايز devient عايزة.", "pattern": "question → réponse : إزيك ؟ → أنا كويس، الحمد لله", "examples": [{"text": "إزيك يا مينا؟", "translation": "Comment vas-tu, Mina ?"}, {"text": "أنا كويس، الحمد لله.", "translation": "Je vais bien, Dieu merci."}, {"text": "عايز شاي.", "translation": "Je veux du thé."}, {"text": "فين الكنيسة؟", "translation": "Où est l''église ?"}], "commonErrors": [{"wrong": "Chercher un verbe « être » dans أنا كويس", "right": "Lire « moi bien » : أنا كويس", "why": "Au présent, l''égyptien n''a pas de verbe « être » : on met les deux mots côte à côte."}, {"wrong": "Lire فين comme في", "right": "Lire فين (où) avec son ن final", "why": "في (dans) et فين (où) ne diffèrent que par le ن : regarde la fin du mot."}, {"wrong": "Répondre صباح الخير par صباح الخير", "right": "Répondre صباح النور", "why": "On renvoie un souhait plus beau : « matin de lumière »."}], "tip": "Lis la phrase à voix basse, comme tu la dirais dans la rue."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g28.liturgy', 'ar', 'grammar', 'reading', 'Les réponses de la liturgie', 2, array['ar.g27.short_sentences']::text[], 4, '{"rule": {"summary": "Les réponses de la liturgie s''écrivent comme dans les livres coptes arabes. Comme tu les connais par cœur, ta mémoire aide tes yeux : tu reconnais le début et le reste vient tout seul.", "explanation": "Un dialogue revient sans cesse : le prêtre dit السلام لكل et le peuple répond ولروحك أيضا. Le ك final veut dire « toi, ton » (لك, ولروحك). Le و du début de ولروحك est le petit mot « et ». Les mots des offices (قداس, تسبحة, أجبية, نبوات, مزمور) se lisent bloc par bloc comme n''importe quel mot, mais tu les as déjà entendus des centaines de fois.", "pattern": "prêtre : السلام لكل → peuple : ولروحك أيضا", "examples": [{"text": "يا رب ارحم", "translation": "Seigneur, aie pitié"}, {"text": "السلام لكل", "translation": "La paix à tous, souhait du prêtre"}, {"text": "ولروحك أيضا", "translation": "Et à ton esprit aussi, réponse du peuple"}, {"text": "المجد لك يا رب", "translation": "Gloire à toi, Seigneur"}], "commonErrors": [{"wrong": "Lire ولروحك comme un seul mot sans analyse", "right": "Voir و + لروحك : « et à ton esprit »", "why": "Le و du début est le petit mot « et », séparé par sa forme isolée."}, {"wrong": "Confondre لك et لكل", "right": "لك = « à toi » ; لكل = « à tous »", "why": "Il y a une lettre de plus dans لكل : un ل final."}, {"wrong": "Chercher une voyelle pour chaque lettre", "right": "Lire le groupe entier, que la mémoire connaît", "why": "À l''église, tu reconnais le groupe avant d''avoir lu toutes les lettres."}], "tip": "Reconnais le groupe en entier : ta mémoire fait la moitié du travail."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g29.read_with_meaning', 'ar', 'grammar', 'reading', 'Lire sans voyelles en s''aidant du sens', 3, array['ar.g28.liturgy']::text[], 4, '{"rule": {"summary": "Les Égyptiens n''écrivent pas les voyelles courtes : plusieurs mots s''écrivent donc pareil. Pour choisir, on lit les consonnes, on laisse l''oreille proposer un mot, puis on vérifie avec le sens de la phrase.", "explanation": "Le même squelette de consonnes peut cacher deux mots : كتب (livres ou il a écrit), علم (drapeau ou science), أكل (nourriture ou il a mangé). Le contexte décide : après عندي on attend un nom, après une personne on attend une action, et ال annonce un nom. Un même mot peut aussi s''écrire de deux façons (مدرسة ou مدرسه, على ou علي) : on oublie souvent les petits signes.", "pattern": "consonnes + oreille + sens de la phrase = le bon mot", "examples": [{"text": "عندي كتب كتير", "translation": "J''ai beaucoup de livres : كتب = livres"}, {"text": "بابا كتب جواب", "translation": "Papa a écrit une lettre : كتب = il a écrit"}, {"text": "علم مصر", "translation": "le drapeau de l''Égypte : علم = drapeau"}, {"text": "العلم نور", "translation": "La science est une lumière : علم = science"}], "commonErrors": [{"wrong": "Lire كتب toujours « il a écrit »", "right": "Choisir livres ou il a écrit selon la phrase", "why": "Les consonnes ne suffisent pas : le sens de la phrase tranche."}, {"wrong": "Croire que مدرسه est un autre mot que مدرسة", "right": "C''est le même mot, écrit avec ه", "why": "Dans l''écriture rapide, le ة s''écrit souvent comme un ه."}, {"wrong": "Chercher les voyelles courtes dans le texte", "right": "Les ajouter de tête", "why": "Elles ne sont presque jamais écrites : le lecteur les connaît."}], "tip": "Dis les consonnes à voix basse : si le mot est dans ta langue, il te revient."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g30.little_words', 'ar', 'grammar', 'reading', 'Les petits mots les plus fréquents', 2, array['ar.g29.read_with_meaning']::text[], 4, '{"rule": {"summary": "Un mot sur trois est un petit mot : ده, دي, دول, في, على, مش et les mots de question. Courts et fréquents, ils se lisent comme des images, sans épeler.", "explanation": "ده, دي et دول veulent dire « ça » (masculin, féminin, pluriel). في veut dire « dans » ou « il y a », على veut dire « sur », مش nie. Cinq mots posent presque toutes les questions : إيه (quoi), مين (qui), فين (où), ليه (pourquoi), إمتى (quand). Beaucoup se ressemblent (في, فين, مين) : regarde le début et la fin.", "pattern": "ده / دي / دول · في / على / مش · إيه / مين / فين / ليه / إمتى", "examples": [{"text": "ده بيت", "translation": "C''est une maison."}, {"text": "الكتاب على الترابيزة", "translation": "Le livre est sur la table."}, {"text": "إيه ده؟", "translation": "C''est quoi ?"}, {"text": "إمتى القداس؟", "translation": "Quand est la liturgie ?"}], "commonErrors": [{"wrong": "Lire في comme فين", "right": "Regarder si le ن final est là", "why": "فين (où) a un ن de plus que في (dans)."}, {"wrong": "Dire ده pour un mot féminin comme كنيسة", "right": "Dire دي كنيسة", "why": "ده est pour le masculin, دي pour le féminin."}, {"wrong": "Lire مين comme مش", "right": "مين = qui, مش = ne… pas", "why": "Les deux commencent par م, mais la fin n''est pas la même."}], "tip": "Apprends chaque petit mot comme une image : début, fin, et c''est tout."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g31.sentence_flow', 'ar', 'grammar', 'reading', 'Lire une phrase d''un seul trait', 3, array['ar.g30.little_words']::text[], 4, '{"rule": {"summary": "Lire une phrase d''un seul trait, c''est la lire par groupes de sens, pas mot à mot : qui, fait quoi, où, quand. L''œil avance de droite à gauche sans revenir en arrière.", "explanation": "Une phrase égyptienne suit souvent l''ordre qui, fait quoi, où, quand. La fin du mot indique qui agit : رايح (un homme), رايحة (une femme), رايحين (plusieurs personnes). Les mots de la rue (النهارده, دلوقتي, كمان, أوي, خلاص, يلا, ماشي, تمام, كده) se lisent comme des images. Si un mot t''arrête, saute-le, lis la suite, puis reviens.", "pattern": "qui + fait quoi + où + quand : أنا رايح الكنيسة النهارده", "examples": [{"text": "أنا رايح الكنيسة النهارده", "translation": "Je vais à l''église aujourd''hui."}, {"text": "بابا عايز شاي دلوقتي", "translation": "Papa veut du thé maintenant."}, {"text": "أنا جعان أوي", "translation": "J''ai très faim."}, {"text": "بكرة القداس، ماشي؟", "translation": "Demain, c''est la liturgie, d''accord ?"}], "commonErrors": [{"wrong": "Lire رايحة quand c''est un homme qui parle", "right": "Utiliser رايح pour un homme, رايحة pour une femme", "why": "La fin du mot dit qui agit : ـة pour une femme."}, {"wrong": "Lire une phrase mot à mot en revenant en arrière", "right": "Lire par groupes de sens, sans reculer", "why": "Le sens des autres mots aide à deviner le mot qui bloque."}, {"wrong": "Chercher « quand » au début de la phrase", "right": "Le chercher à la fin", "why": "النهارده et دلوقتي se mettent souvent en dernier."}], "tip": "Cache la traduction et lis d''un seul trait : si tu hésites, cherche les groupes de sens."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g32.reading_review', 'ar', 'grammar', 'reading', 'Bilan de lecture : la rue et l''église', 3, array['ar.g31.sentence_flow']::text[], 4, '{"rule": {"summary": "Lire couramment, c''est combiner tous les outils : paquets, blocs, ال, petits mots, groupes de sens. Et avant de lire, on devine déjà ce qu''on va trouver, grâce au lieu et au genre de texte.", "explanation": "Sur un panneau de rue, on attend des mots comme مخرج ou ممنوع ; sur une affiche d''église, قداس, تسبحة ou مدارس الأحد. Ce contexte souffle déjà la moitié du texte. Ensuite, on coupe en blocs, on lit ال d''un coup, on reconnaît les petits mots comme des images et on lit la phrase par groupes de sens.", "pattern": "contexte → groupes de sens → mots → vérification", "examples": [{"text": "لو سمحت، فين محطة المترو؟", "translation": "Excuse-moi, où est la station de métro ? : une phrase de la rue"}, {"text": "قداس الأحد", "translation": "la liturgie du dimanche : une affiche d''église"}, {"text": "ممنوع", "translation": "interdit : un panneau"}, {"text": "أنا رايح مدارس الأحد", "translation": "Je vais à l''école du dimanche"}], "commonErrors": [{"wrong": "Lire chaque panneau lettre par lettre", "right": "Lire le mot d''un coup grâce au contexte", "why": "Sur un panneau, le contexte te dit déjà quels mots sont possibles."}, {"wrong": "Confondre في, فين et مين", "right": "Regarder le début et la fin", "why": "فين (où) et مين (qui) ont un ن final ; في (dans) n''en a pas."}, {"wrong": "Oublier de couper aux ا د ذ ر ز و", "right": "Couper d''abord aux six lettres", "why": "Elles ferment un bloc et rendent les longs mots faciles."}], "tip": "Avant de lire, demande-toi où tu es : le contexte souffle les mots."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g33.salutations_politesse', 'ar', 'grammar', 'vocabulary', 'Salutations et politesse : la question et sa réponse', 1, array['ar.g32.reading_review']::text[], 5, '{"rule": {"summary": "En égyptien, une salutation est un petit dialogue : on lance une phrase et l''autre répond en renchérissant.", "explanation": "Le matin, صباح الخير appelle صباح النور ; le soir, مساء الخير appelle مساء النور. Pour prendre des nouvelles, إزيك ou عامل إيه (عاملة إيه à une femme) appellent الحمد لله. Un merci appelle العفو. Pour la politesse : من فضلك (s''il te plaît), لو سمحت et عن إذنك (excuse-moi), معلش (pardon). On se quitte avec مع السلامة.", "pattern": "صباح الخير ← صباح النور  |  شكرا ← العفو  |  إزيك ← الحمد لله", "examples": [{"text": "مساء الخير يا أبونا — مساء النور", "translation": "Bonsoir, notre père — Bonsoir (réponse)"}, {"text": "عاملة إيه يا مريم؟ — الحمد لله", "translation": "Comment ça va, Mariam ? — Dieu merci"}, {"text": "شكرا — العفو", "translation": "Merci — De rien"}, {"text": "عن إذنك، مع السلامة", "translation": "Avec ta permission, au revoir"}], "commonErrors": [{"wrong": "عامل إيه يا مريم؟", "right": "عاملة إيه يا مريم؟", "why": "À une femme, on ajoute ة : عاملة, au lieu de عامل."}, {"wrong": "مساء الخير (à 8 h du matin)", "right": "صباح الخير", "why": "Le matin on dit صباح, à partir de l''après-midi مساء."}, {"wrong": "شكرا ← شكرا", "right": "شكرا ← العفو", "why": "Quand on te dit شكرا, on répond العفو (de rien), pas un deuxième merci."}], "tip": "Retiens les salutations par paires : صباح الخير ← صباح النور, مساء الخير ← مساء النور."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g34.la_famille', 'ar', 'grammar', 'vocabulary', 'La famille : ـي (mon, ma) et ـنا (notre)', 1, array['ar.g33.salutations_politesse']::text[], 5, '{"rule": {"summary": "Un petit ي collé à la fin d''un nom veut dire « mon » ou « ma » ; ـنا veut dire « notre ».", "explanation": "Les mots de la famille s''emploient presque toujours avec « mon » ou « ma » collé : ابن (fils) devient ابني (mon fils), بنت (fille) devient بنتي (ma fille). Pour « notre », on colle ـنا : أبونا (notre père). Le frère est un cas particulier : أخويا. Pour appeler quelqu''un, on met يا devant : يا ماما.", "pattern": "nom + ـي = mon / ma   |   nom + ـنا = notre", "examples": [{"text": "ابني مينا", "translation": "Mon fils Mina"}, {"text": "بنتي مريم", "translation": "Ma fille Mariam"}, {"text": "أخويا وأختي", "translation": "Mon frère et ma sœur"}, {"text": "يا ماما، إزيك؟", "translation": "Maman, comment vas-tu ?"}], "commonErrors": [{"wrong": "مراتي = mon mari", "right": "جوزي = mon mari", "why": "جوزي est le mari ; مراتي est l''épouse."}, {"wrong": "ابني = ma fille", "right": "بنتي = ma fille", "why": "ابن (fils) donne ابني ; بنت (fille) donne بنتي."}, {"wrong": "خالتو = la sœur de mon père", "right": "خالتو = la sœur de ma mère", "why": "La sœur de la mère est خالتو ; le frère du père est عمو."}], "tip": "Quand un nom de la famille finit par ي, traduis-le par « mon » ou « ma »."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g35.la_maison', 'ar', 'grammar', 'vocabulary', 'La maison : dire où est quoi avec في', 1, array['ar.g34.la_famille']::text[], 5, '{"rule": {"summary": "Pour dire où se trouve une chose, on place في (« dans, à ») entre la chose et le lieu.", "explanation": "La phrase égyptienne n''a pas de verbe « être » au présent : السرير في الأوضة se lit « le lit [est] dans la chambre ». ال veut dire « le / la ». Les mots de la maison s''apprennent par pièces : cuisine (مطبخ, تلاجة), salle de bain (حمام), chambre (سرير), salon (كنبة), ouvertures (شباك, باب, بلكونة).", "pattern": "الشيء + في + المكان   (la chose + dans + le lieu)", "examples": [{"text": "السرير في الأوضة", "translation": "Le lit est dans la chambre"}, {"text": "التلاجة في المطبخ", "translation": "Le frigo est dans la cuisine"}, {"text": "الكنبة في الصالة", "translation": "Le canapé est dans le salon"}, {"text": "الكرسي في البلكونة", "translation": "La chaise est sur le balcon"}], "commonErrors": [{"wrong": "مطبخ = salle de bain", "right": "مطبخ = cuisine ; حمام = salle de bain", "why": "مطبخ commence par م, حمام par ح."}, {"wrong": "شباك = porte", "right": "شباك = fenêtre ; باب = porte", "why": "La porte est باب, tu la connais déjà."}, {"wrong": "الأوضة (les pièces)", "right": "الأوض (les pièces)", "why": "Au pluriel, le ة de أوضة tombe : أوض."}], "tip": "Pas de verbe : chose + في + lieu suffit pour dire où elle est."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g36.la_nourriture', 'ar', 'grammar', 'vocabulary', 'Au menu : les noms de nourriture et le ة de l''unité', 2, array['ar.g35.la_maison']::text[], 5, '{"rule": {"summary": "Un nom de nourriture désigne le groupe ; un ة final désigne une seule pièce.", "explanation": "بيض veut dire « des œufs » en général, et بيضة « un œuf ». Même logique pour موز (des bananes) et موزة (une banane), تين (des figues) et تينة (une figue). Pour commander, on dit عايز devant le plat. Un و collé au mot suivant veut dire « et » : فول وطعمية, « fèves et croquettes de fèves ».", "pattern": "بيض (des œufs) + ة = بيضة (un œuf)   |   و + mot = « et » + mot", "examples": [{"text": "فول وطعمية", "translation": "Des fèves et des croquettes de fèves"}, {"text": "عايز بيضة", "translation": "Je veux un œuf"}, {"text": "رز وفراخ", "translation": "Du riz et du poulet"}, {"text": "عيش وجبنة", "translation": "Du pain et du fromage"}], "commonErrors": [{"wrong": "بيضة = des œufs", "right": "بيض = des œufs ; بيضة = un œuf", "why": "Le ة final désigne une seule pièce."}, {"wrong": "كشري = soupe verte", "right": "كشري = riz, pâtes et lentilles ; ملوخية = soupe verte", "why": "Deux plats très différents : un mélange de féculents et une soupe d''herbe."}, {"wrong": "فراخ = viande de bœuf", "right": "فراخ = poulet ; لحمة = viande", "why": "فراخ est la volaille ; لحمة est la viande, surtout le bœuf et l''agneau."}], "tip": "Pour un seul œuf, une seule banane, une seule figue : ajoute ة."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g37.cafe_et_marche', 'ar', 'grammar', 'vocabulary', 'Commander et marchander : عايز, بكام, غالي / رخيص', 2, array['ar.g36.la_nourriture']::text[], 5, '{"rule": {"summary": "On commande avec عايز, on demande le prix avec بكام, et l''adjectif s''accorde avec le nom : غالي (masculin), غالية (féminin).", "explanation": "عايز + chose veut dire « je veux… » ; une femme dit عايزة. Pour le prix : بكام + chose ? (« combien ça coûte ? »). Cher se dit غالي, bon marché رخيص ; si le nom est féminin, on ajoute ة : اللحمة غالية. À la fin du repas : الحساب لو سمحت.", "pattern": "عايز + chose   |   بكام + chose ؟   |   adjectif + ة = féminin", "examples": [{"text": "عايز كباية شاي", "translation": "Je veux un verre de thé"}, {"text": "بكام ده؟", "translation": "Combien ça coûte ?"}, {"text": "اللحمة غالية", "translation": "La viande est chère"}, {"text": "الكشري رخيص", "translation": "Ce plat de riz et de pâtes est bon marché"}], "commonErrors": [{"wrong": "اللحمة غالي", "right": "اللحمة غالية", "why": "لحمة est un nom féminin : l''adjectif prend ة."}, {"wrong": "عايز (dit par une dame)", "right": "عايزة", "why": "Une femme ajoute ة : عايزة."}, {"wrong": "فلوس = la monnaie du pays", "right": "جنيه = la monnaie ; فلوس = l''argent en général", "why": "جنيه est l''unité (la livre égyptienne), فلوس désigne l''argent."}], "tip": "Au féminin, ajoute ة : عايزة, غالية, رخيصة."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g38.nombres_et_prix', 'ar', 'grammar', 'vocabulary', 'Nombres et prix : les chiffres ١٢٣', 2, array['ar.g37.cafe_et_marche']::text[], 5, '{"rule": {"summary": "Les nombres s''écrivent en chiffres arabes orientaux (١ ٢ ٣…), toujours de gauche à droite, et se disent avec des mots simples.", "explanation": "Au Caire tu lis ١ ٢ ٣ ٤ ٥ ٦ ٧ ٨ ٩ ٠ sur les prix, les billets et les tickets. Les nombres à plusieurs chiffres se lisent de gauche à droite : ١٢ est douze. Les dizaines se terminent en ـين : عشرة (10) donne عشرين (20), خمسة (5) donne خمسين (50). Pour un prix, ب (« pour ») s''ajoute devant : بخمسة جنيه.", "pattern": "١ ٢ ٣ ٤ ٥ ٦ ٧ ٨ ٩ ١٠   |   ب + nombre + جنيه = pour… livres", "examples": [{"text": "بخمسة جنيه", "translation": "Pour cinq livres"}, {"text": "بعشرين جنيه", "translation": "Pour vingt livres"}, {"text": "اتنين شاي", "translation": "Deux thés"}, {"text": "مية جنيه", "translation": "Cent livres"}], "commonErrors": [{"wrong": "٥ = zéro", "right": "٥ = cinq ; ٠ = zéro", "why": "Le ٥ est rond comme un zéro, mais le vrai zéro est un simple point."}, {"wrong": "٧ = 8 et ٨ = 7", "right": "٧ = 7 (un V) ; ٨ = 8 (un V à l''envers)", "why": "٧ ressemble à un V ; ٨ à un V à l''envers."}, {"wrong": "مية = seulement l''eau", "right": "مية = l''eau ou cent, selon le contexte", "why": "Deux mots différents s''écrivent pareil : le sens dépend de la phrase."}], "tip": "٠ est un point, ٥ est un rond, ٧ est un V, ٨ est un V à l''envers."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g39.le_temps', 'ar', 'grammar', 'vocabulary', 'Le temps : امبارح, النهارده, بكرة et l''heure', 2, array['ar.g38.nombres_et_prix']::text[], 5, '{"rule": {"summary": "Pour situer dans le temps, on pose un mot de temps (امبارح, النهارده, بكرة, الصبح…) ; l''heure se dit الساعة + nombre.", "explanation": "Trois repères de base : امبارح (hier), النهارده (aujourd''hui), بكرة (demain). Les moments de la journée : الصبح (le matin), الضهر (à midi), بالليل (la nuit) ; ب veut dire « à, pendant ». L''heure : الساعة كام ؟ demande l''heure, on répond الساعة + nombre, avec ونص (et demie) et وربع (et quart). La semaine démarre le dimanche et suit les nombres : الأحد (un), الاتنين (deux), التلات (trois), الأربع (quatre), الخميس (cinq).", "pattern": "امبارح — النهارده — بكرة   |   الساعة + nombre (+ ونص / وربع)", "examples": [{"text": "بكرة الساعة تمانية", "translation": "Demain à huit heures"}, {"text": "الساعة تلاتة ونص", "translation": "Il est trois heures et demie"}, {"text": "النهارده الأحد", "translation": "Aujourd''hui c''est dimanche"}, {"text": "بالليل بنصلي", "translation": "La nuit, on prie"}], "commonErrors": [{"wrong": "الساعة تلاتة وربع = 3 h 30", "right": "الساعة تلاتة ونص = 3 h 30 ; وربع = 3 h 15", "why": "نص veut dire la moitié, ربع le quart."}, {"wrong": "الاتنين = mardi", "right": "الاتنين = lundi", "why": "La semaine commence au dimanche (un) : الاتنين (deux) est le lundi."}, {"wrong": "بكرة = hier", "right": "بكرة = demain ; امبارح = hier", "why": "Les deux commencent par une lettre à bâton mais ne se lisent pas pareil : امبارح a un ا au début."}], "tip": "Dimanche = un, lundi = deux, mardi = trois, mercredi = quatre, jeudi = cinq : les jours suivent les nombres."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g40.a_l_eglise', 'ar', 'grammar', 'vocabulary', 'À l''église : lieux, personnes, offices et fêtes', 2, array['ar.g39.le_temps']::text[], 5, '{"rule": {"summary": "Les mots d''église se rangent en trois familles : le lieu (هيكل, مذبح, أيقونة), les personnes (أبونا, شماس, القديسين) et le temps (عشية, قداس, صيام, عيد).", "explanation": "L''église (كنيسة) contient le هيكل, le sanctuaire où se trouve le مذبح (l''autel), et des أيقونة (icônes). Les personnes : أبونا (le prêtre), شماس (le diacre), القديسين (les saints, avec le pluriel en ـين) et مارجرجس (saint Georges ; مار = saint devant un nom). Le temps : عشية (le soir), قداس (la liturgie), صيام (les jours de jeûne), عيد (les fêtes). ـنا veut dire « notre » : أبونا, ربنا, أمنا.", "pattern": "lieu : هيكل · مذبح · أيقونة   |   personnes : أبونا · شماس · القديسين   |   temps : عشية · قداس · صيام · عيد", "examples": [{"text": "الأيقونة في الكنيسة", "translation": "L''icône est dans l''église"}, {"text": "أبونا في الهيكل", "translation": "Notre père est dans le sanctuaire"}, {"text": "القداس يوم الأحد", "translation": "La liturgie est le dimanche"}, {"text": "الأربع والجمعة صيام", "translation": "Mercredi et vendredi : jeûne"}], "commonErrors": [{"wrong": "هيكل = toute l''église", "right": "كنيسة = l''église entière ; هيكل = le sanctuaire avec l''autel", "why": "Le هيكل est seulement la partie où se trouve le مذبح."}, {"wrong": "عيد الميلاد = 25 décembre", "right": "عيد الميلاد = 7 janvier", "why": "Les coptes fêtent Noël le 7 janvier."}, {"wrong": "القديسين = le saint", "right": "القديسين = les saints", "why": "Le ـين final marque le pluriel des personnes ; le singulier est قديس."}], "tip": "Quand tu lis un mot d''église, demande-toi : c''est un lieu, une personne ou un moment ?"}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
