insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e13', 'ar', 'ar.l02', 'ar.v.ba', array['ar.v.ba','ar.v.ta','ar.g02.letters2']::text[], 'mcq', 'lesson', 'Quelle lettre vient juste avant ت dans l''alphabet ?', array['ب']::text[], 'L''ordre est ا, ب, ت, ث : ب vient juste avant ت.', 3, '{"id": "ar.l02.e13", "unitIds": ["ar.v.ba", "ar.v.ta", "ar.g02.letters2"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre vient juste avant ت dans l''alphabet ?", "promptLanguage": "fr", "options": ["ب", "ا", "ث"], "answer": "ب", "acceptedAnswers": ["ب"], "explanation": "L''ordre est ا, ب, ت, ث : ب vient juste avant ت.", "tip": "Une barque, et son ancre en dessous.", "extraExample": {"text": "ب", "translation": "bâ : le b de bateau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e14', 'ar', 'ar.l02', 'ar.v.tha', array['ar.v.tha','ar.g02.letters2']::text[], 'mcq', 'lesson', 'Quel son fait la lettre ث en Égypte ?', array['un t, parfois un s']::text[], 'En Égypte, ث se dit comme un t, parfois comme un s. Les 3 points dessus la distinguent de ت à l''écrit.', 3, '{"id": "ar.l02.e14", "unitIds": ["ar.v.tha", "ar.g02.letters2"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "Quel son fait la lettre ث en Égypte ?", "promptLanguage": "fr", "options": ["le y de yaourt", "un t, parfois un s", "le b de bateau", "le n de nuit"], "answer": "un t, parfois un s", "acceptedAnswers": ["un t, parfois un s"], "explanation": "En Égypte, ث se dit comme un t, parfois comme un s. Les 3 points dessus la distinguent de ت à l''écrit.", "tip": "Trois mouettes en triangle sur la barque.", "extraExample": {"text": "ث", "translation": "thâ : un t, parfois un s, 3 points dessus."}, "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e15', 'ar', 'ar.l02', 'ar.g02.letters2', array['ar.g02.letters2','ar.v.ya']::text[], 'mcq', 'lesson', 'Qui suis-je ? « J''ai deux points, mais ils sont sous la ligne, au bout d''une longue queue. »', array['ي']::text[], 'Deux points dessous et une queue qui plonge : c''est ي, le y de yaourt.', 3, '{"id": "ar.l02.e15", "unitIds": ["ar.g02.letters2", "ar.v.ya"], "type": "mcq", "difficulty": 3, "instruction": "Devine la lettre.", "prompt": "Qui suis-je ? « J''ai deux points, mais ils sont sous la ligne, au bout d''une longue queue. »", "promptLanguage": "fr", "options": ["ن", "ب", "ت", "ي"], "answer": "ي", "acceptedAnswers": ["ي"], "explanation": "Deux points dessous et une queue qui plonge : c''est ي, le y de yaourt.", "tip": "Une queue qui plonge, deux points dessous.", "extraExample": {"text": "ي", "translation": "yâ : le y de yaourt, 2 points dessous."}, "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e16', 'ar', 'ar.l02', 'ar.v.ta', array['ar.v.ta','ar.g02.letters2']::text[], 'mcq', 'lesson', 'Tu vois 2 points dessus d''une barque plate. Quelle lettre est-ce ?', array['ت']::text[], '2 points dessus d''une barque plate : c''est ت. Avec 2 points dessous et une queue, ce serait ي.', 3, '{"id": "ar.l02.e16", "unitIds": ["ar.v.ta", "ar.g02.letters2"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lettre.", "prompt": "Tu vois 2 points dessus d''une barque plate. Quelle lettre est-ce ?", "promptLanguage": "fr", "options": ["ت", "ث", "ن", "ي"], "answer": "ت", "acceptedAnswers": ["ت"], "explanation": "2 points dessus d''une barque plate : c''est ت. Avec 2 points dessous et une queue, ce serait ي.", "tip": "Deux mouettes sur la barque.", "extraExample": {"text": "ت", "translation": "tâ : le t de table, 2 points dessus."}, "errorPatterns": [{"equals": "ي", "category": "word_confusion", "feedback": "ي a 2 points aussi, mais dessous et au bout d''une queue."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e17', 'ar', 'ar.l02', 'ar.g02.letters2', array['ar.g02.letters2','ar.v.nun']::text[], 'free_answer', 'lesson', 'Combien de points a la lettre ن ? Réponds avec un chiffre.', array['1','un']::text[], 'ن a un seul point, posé dessus. Quand tu vois un seul point, demande-toi : dessus ou dessous ?', 2, '{"id": "ar.l02.e17", "unitIds": ["ar.g02.letters2", "ar.v.nun"], "type": "free_answer", "difficulty": 2, "instruction": "Écris le nombre.", "prompt": "Combien de points a la lettre ن ? Réponds avec un chiffre.", "promptLanguage": "fr", "answer": "1", "acceptedAnswers": ["1", "un"], "explanation": "ن a un seul point, posé dessus. Quand tu vois un seul point, demande-toi : dessus ou dessous ?", "tip": "Un bol avec une cerise dessus.", "extraExample": {"text": "ن", "translation": "nûn : le n de nuit, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l02", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e18', 'ar', 'ar.l02', 'ar.g02.letters2', array['ar.g02.letters2','ar.v.nun']::text[], 'free_answer', 'lesson', 'Comment s''appelle la lettre qui fait le son n ?', array['nûn','nun','noun']::text[], 'La lettre qui fait n s''appelle nûn : son nom commence par son son.', 3, '{"id": "ar.l02.e18", "unitIds": ["ar.g02.letters2", "ar.v.nun"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le nom de la lettre.", "prompt": "Comment s''appelle la lettre qui fait le son n ?", "promptLanguage": "fr", "answer": "nûn", "acceptedAnswers": ["nûn", "nun", "noun"], "explanation": "La lettre qui fait n s''appelle nûn : son nom commence par son son.", "tip": "Un bol avec une cerise dessus.", "extraExample": {"text": "ن", "translation": "nûn : le n de nuit, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l02", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e19', 'ar', 'ar.l02', 'ar.g02.letters2', array['ar.g02.letters2','ar.v.ya']::text[], 'mcq', 'lesson', 'Quel est le nom de la lettre ي ?', array['yâ']::text[], 'ي s''appelle yâ, comme le son y de yaourt.', 3, '{"id": "ar.l02.e19", "unitIds": ["ar.g02.letters2", "ar.v.ya"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon nom.", "prompt": "Quel est le nom de la lettre ي ?", "promptLanguage": "fr", "options": ["bâ", "yâ", "nûn", "tâ"], "answer": "yâ", "acceptedAnswers": ["yâ"], "explanation": "ي s''appelle yâ, comme le son y de yaourt.", "tip": "Une queue qui plonge, deux points dessous.", "extraExample": {"text": "ي", "translation": "yâ : le y de yaourt, 2 points dessous."}, "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e20', 'ar', 'ar.l02', 'ar.v.ba', array['ar.v.ba','ar.v.ta','ar.v.nun','ar.v.ya','ar.g02.letters2']::text[], 'match', 'lesson', 'Relie ن, ي, ب et ت à leur son.', '{}'::text[], 'Quatre lettres, quatre sons : n, y, b, t. Les noms nûn, yâ, bâ et tâ les rappellent.', 3, '{"id": "ar.l02.e20", "unitIds": ["ar.v.ba", "ar.v.ta", "ar.v.nun", "ar.v.ya", "ar.g02.letters2"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ن, ي, ب et ت à leur son.", "promptLanguage": "fr", "pairs": [{"left": "ن", "right": "le n de nuit"}, {"left": "ي", "right": "le y de yaourt"}, {"left": "ب", "right": "le b de bateau"}, {"left": "ت", "right": "le t de table"}], "acceptedAnswers": [], "explanation": "Quatre lettres, quatre sons : n, y, b, t. Les noms nûn, yâ, bâ et tâ les rappellent.", "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition", "answer": "ن = le n de nuit ; ي = le y de yaourt ; ب = le b de bateau ; ت = le t de table"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e01', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son g, comme dans gâteau, en Égypte ?', array['ج']::text[], 'En Égypte, ج se dit g comme dans gâteau. Son point est dans le creux du crochet.', 1, '{"id": "ar.l03.e01", "unitIds": ["ar.g03.letters3", "ar.v.jim"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son g, comme dans gâteau, en Égypte ?", "promptLanguage": "fr", "options": ["ن", "ب", "ج", "ي"], "answer": "ج", "acceptedAnswers": ["ج"], "explanation": "En Égypte, ج se dit g comme dans gâteau. Son point est dans le creux du crochet.", "tip": "Un hameçon avec une bille dans le creux.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e02', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.ha']::text[], 'mcq', 'lesson', 'Quelle lettre est un crochet sans aucun point ?', array['ح']::text[], 'ح est le crochet vide : ni bille dans le creux (ج), ni chapeau dessus (خ).', 1, '{"id": "ar.l03.e02", "unitIds": ["ar.g03.letters3", "ar.v.ha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un crochet sans aucun point ?", "promptLanguage": "fr", "options": ["ت", "ج", "ح", "خ"], "answer": "ح", "acceptedAnswers": ["ح"], "explanation": "ح est le crochet vide : ni bille dans le creux (ج), ni chapeau dessus (خ).", "tip": "Le crochet vide : rien dedans, rien dessus.", "extraExample": {"text": "ح", "translation": "ḥâ : un h appuyé, aucun point."}, "errorPatterns": [{"equals": "ج", "category": "word_confusion", "feedback": "ج a 1 point dans le creux."}, {"equals": "خ", "category": "word_confusion", "feedback": "خ a 1 point dessus."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e03', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.kha']::text[], 'mcq', 'lesson', 'Quelle lettre fait un raclement de gorge, comme le ch allemand de Bach ?', array['خ']::text[], 'خ se lit comme le ch allemand de Bach. Elle porte 1 point dessus, comme un chapeau.', 1, '{"id": "ar.l03.e03", "unitIds": ["ar.g03.letters3", "ar.v.kha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait un raclement de gorge, comme le ch allemand de Bach ?", "promptLanguage": "fr", "options": ["ج", "ح", "خ", "ث"], "answer": "خ", "acceptedAnswers": ["خ"], "explanation": "خ se lit comme le ch allemand de Bach. Elle porte 1 point dessus, comme un chapeau.", "tip": "Le crochet avec un chapeau (le point dessus).", "extraExample": {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e04', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim','ar.v.ha','ar.v.kha']::text[], 'match', 'lesson', 'Relie ج, ح et خ à leurs points.', '{}'::text[], 'Même crochet, trois places pour le point : dessous (ج), nulle part (ح), dessus (خ).', 1, '{"id": "ar.l03.e04", "unitIds": ["ar.g03.letters3", "ar.v.jim", "ar.v.ha", "ar.v.kha"], "type": "match", "difficulty": 1, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ج, ح et خ à leurs points.", "promptLanguage": "fr", "pairs": [{"left": "ج", "right": "1 point dessous"}, {"left": "ح", "right": "aucun point"}, {"left": "خ", "right": "1 point dessus"}], "acceptedAnswers": [], "explanation": "Même crochet, trois places pour le point : dessous (ج), nulle part (ح), dessus (خ).", "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition", "answer": "ج = 1 point dessous ; ح = aucun point ; خ = 1 point dessus"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e05', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.kha']::text[], 'mcq', 'lesson', 'Quelle lettre a 1 point dessus, sur un crochet ?', array['خ']::text[], 'Le crochet à chapeau est خ. ن a aussi 1 point dessus, mais c''est un bol, pas un crochet.', 2, '{"id": "ar.l03.e05", "unitIds": ["ar.g03.letters3", "ar.v.kha"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a 1 point dessus, sur un crochet ?", "promptLanguage": "fr", "options": ["ح", "ن", "خ", "ج"], "answer": "خ", "acceptedAnswers": ["خ"], "explanation": "Le crochet à chapeau est خ. ن a aussi 1 point dessus, mais c''est un bol, pas un crochet.", "tip": "Le crochet avec un chapeau (le point dessus).", "extraExample": {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus."}, "errorPatterns": [{"equals": "ن", "category": "word_confusion", "feedback": "ن a bien 1 point dessus, mais sa forme est un bol creux."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e06', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim']::text[], 'mcq', 'lesson', 'Quelle lettre a 1 point dans le creux du crochet ?', array['ج']::text[], 'ج a sa bille dans le creux, donc 1 point dessous. ب a aussi 1 point dessous, mais c''est une barque.', 2, '{"id": "ar.l03.e06", "unitIds": ["ar.g03.letters3", "ar.v.jim"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a 1 point dans le creux du crochet ?", "promptLanguage": "fr", "options": ["ح", "خ", "ب", "ج"], "answer": "ج", "acceptedAnswers": ["ج"], "explanation": "ج a sa bille dans le creux, donc 1 point dessous. ب a aussi 1 point dessous, mais c''est une barque.", "tip": "Un hameçon avec une bille dans le creux.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "errorPatterns": [{"equals": "ب", "category": "word_confusion", "feedback": "ب a bien 1 point dessous, mais c''est une barque, pas un crochet."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e07', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim']::text[], 'fill_blank', 'lesson', 'Le point de ج est ___, dans le creux du crochet.', array['dessous']::text[], 'Le point de ج est dessous, comme une bille dans une cuillère. Dessus, c''est خ.', 2, '{"id": "ar.l03.e07", "unitIds": ["ar.g03.letters3", "ar.v.jim"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "Le point de ج est ___, dans le creux du crochet.", "promptLanguage": "fr", "options": ["dessous", "au milieu", "dessus"], "answer": "dessous", "acceptedAnswers": ["dessous"], "explanation": "Le point de ج est dessous, comme une bille dans une cuillère. Dessus, c''est خ.", "tip": "Un hameçon avec une bille dans le creux.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "errorPatterns": [{"equals": "dessus", "category": "word_confusion", "feedback": "Dessus, c''est le chapeau de خ."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e08', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.kha']::text[], 'fill_blank', 'lesson', 'خ porte 1 point ___, comme un chapeau sur le crochet.', array['dessus']::text[], 'Le point de خ est dessus, comme un chapeau. Dessous, c''est ج.', 2, '{"id": "ar.l03.e08", "unitIds": ["ar.g03.letters3", "ar.v.kha"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "خ porte 1 point ___, comme un chapeau sur le crochet.", "promptLanguage": "fr", "options": ["dessus", "au milieu", "dessous"], "answer": "dessus", "acceptedAnswers": ["dessus"], "explanation": "Le point de خ est dessus, comme un chapeau. Dessous, c''est ج.", "tip": "Le crochet avec un chapeau (le point dessus).", "extraExample": {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e09', 'ar', 'ar.l03', 'ar.v.ya', array['ar.v.ya','ar.g03.letters3']::text[], 'mcq', 'lesson', 'Quelle lettre a 2 points dessous et une queue qui plonge ?', array['ي']::text[], 'ي a 2 points dessous et une queue qui plonge sous la ligne. ت a aussi 2 points, mais dessus.', 2, '{"id": "ar.l03.e09", "unitIds": ["ar.v.ya", "ar.g03.letters3"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a 2 points dessous et une queue qui plonge ?", "promptLanguage": "fr", "options": ["ي", "ت", "ن", "ج"], "answer": "ي", "acceptedAnswers": ["ي"], "explanation": "ي a 2 points dessous et une queue qui plonge sous la ligne. ت a aussi 2 points, mais dessus.", "tip": "Une queue qui plonge, deux points dessous.", "extraExample": {"text": "ي", "translation": "yâ : le y de yaourt, 2 points dessous."}, "errorPatterns": [{"equals": "ت", "category": "word_confusion", "feedback": "ت a 2 points, mais dessus, sur une barque plate."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e10', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim','ar.v.ha','ar.v.kha','ar.v.ba']::text[], 'mcq', 'lesson', 'Trois de ces lettres sont des crochets. Laquelle est l''intruse ?', array['ب']::text[], 'ج, ح et خ sont des crochets. ب est une barque plate : c''est l''intruse.', 2, '{"id": "ar.l03.e10", "unitIds": ["ar.g03.letters3", "ar.v.jim", "ar.v.ha", "ar.v.kha", "ar.v.ba"], "type": "mcq", "difficulty": 2, "instruction": "Trouve l''intruse.", "prompt": "Trois de ces lettres sont des crochets. Laquelle est l''intruse ?", "promptLanguage": "fr", "options": ["خ", "ج", "ح", "ب"], "answer": "ب", "acceptedAnswers": ["ب"], "explanation": "ج, ح et خ sont des crochets. ب est une barque plate : c''est l''intruse.", "tip": "Un hameçon avec une bille dans le creux.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e11', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.ha']::text[], 'fill_blank', 'lesson', 'ح est le crochet sans point : elle se lit comme ___.', array['un h appuyé']::text[], 'ح se lit comme un h appuyé, soufflé du fond de la gorge, alors que ج se dit g.', 2, '{"id": "ar.l03.e11", "unitIds": ["ar.g03.letters3", "ar.v.ha"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon son.", "prompt": "ح est le crochet sans point : elle se lit comme ___.", "promptLanguage": "fr", "options": ["un h appuyé", "le g de gâteau", "le n de nuit"], "answer": "un h appuyé", "acceptedAnswers": ["un h appuyé"], "explanation": "ح se lit comme un h appuyé, soufflé du fond de la gorge, alors que ج se dit g.", "tip": "Le crochet vide : rien dedans, rien dessus.", "extraExample": {"text": "ح", "translation": "ḥâ : un h appuyé, aucun point."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e12', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim']::text[], 'mcq', 'lesson', 'En Égypte, comment dit-on la lettre ج ?', array['le g de gâteau']::text[], 'En arabe littéraire, ج se dit dj, mais en Égypte on la dit g, comme dans gâteau.', 3, '{"id": "ar.l03.e12", "unitIds": ["ar.g03.letters3", "ar.v.jim"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "En Égypte, comment dit-on la lettre ج ?", "promptLanguage": "fr", "options": ["le n de nuit", "le ch allemand de Bach", "le g de gâteau", "le b de bateau"], "answer": "le g de gâteau", "acceptedAnswers": ["le g de gâteau"], "explanation": "En arabe littéraire, ج se dit dj, mais en Égypte on la dit g, comme dans gâteau.", "tip": "Tu dis déjà ce g tous les jours : relie-le au crochet à bille.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e13', 'ar', 'ar.l03', 'ar.v.ta', array['ar.v.ta','ar.g03.letters3']::text[], 'mcq', 'lesson', 'Quels points porte la lettre ت ?', array['2 points dessus']::text[], 'ت porte 2 points dessus, comme deux mouettes. Avec 2 points dessous, ce serait ي.', 3, '{"id": "ar.l03.e13", "unitIds": ["ar.v.ta", "ar.g03.letters3"], "type": "mcq", "difficulty": 3, "instruction": "Choisis les bons points.", "prompt": "Quels points porte la lettre ت ?", "promptLanguage": "fr", "options": ["3 points dessus", "2 points dessus", "1 point dessous", "2 points dessous"], "answer": "2 points dessus", "acceptedAnswers": ["2 points dessus"], "explanation": "ت porte 2 points dessus, comme deux mouettes. Avec 2 points dessous, ce serait ي.", "tip": "Deux mouettes sur la barque.", "extraExample": {"text": "ت", "translation": "tâ : le t de table, 2 points dessus."}, "errorPatterns": [{"equals": "2 points dessous", "category": "word_confusion", "feedback": "2 points dessous, c''est ي, la lettre à queue."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
