insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e17', 'ar', 'ar.l03', 'ar.v.ba', array['ar.v.ba','ar.v.ta','ar.v.tha','ar.v.nun','ar.v.ya','ar.g03.letters3']::text[], 'match', 'lesson', 'Relie ب, ت, ث, ن et ي à leurs points.', '{}'::text[], 'Cinq lettres de la famille des points : le nombre ET la place les distinguent.', 3, '{"id": "ar.l03.e17", "unitIds": ["ar.v.ba", "ar.v.ta", "ar.v.tha", "ar.v.nun", "ar.v.ya", "ar.g03.letters3"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ب, ت, ث, ن et ي à leurs points.", "promptLanguage": "fr", "pairs": [{"left": "ب", "right": "1 point dessous"}, {"left": "ت", "right": "2 points dessus"}, {"left": "ث", "right": "3 points dessus"}, {"left": "ن", "right": "1 point dessus"}, {"left": "ي", "right": "2 points dessous"}], "acceptedAnswers": [], "explanation": "Cinq lettres de la famille des points : le nombre ET la place les distinguent.", "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition", "answer": "ب = 1 point dessous ; ت = 2 points dessus ; ث = 3 points dessus ; ن = 1 point dessus ; ي = 2 points dessous"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e18', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim','ar.v.ha','ar.v.kha','ar.v.nun']::text[], 'match', 'lesson', 'Relie ج, ح, خ et ن à leur son.', '{}'::text[], 'Trois crochets, trois sons de gorge ou de bouche : g, h appuyé, ch de Bach. ن est le n de nuit.', 3, '{"id": "ar.l03.e18", "unitIds": ["ar.g03.letters3", "ar.v.jim", "ar.v.ha", "ar.v.kha", "ar.v.nun"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ج, ح, خ et ن à leur son.", "promptLanguage": "fr", "pairs": [{"left": "ج", "right": "le g de gâteau"}, {"left": "ح", "right": "un h appuyé"}, {"left": "خ", "right": "le ch allemand de Bach"}, {"left": "ن", "right": "le n de nuit"}], "acceptedAnswers": [], "explanation": "Trois crochets, trois sons de gorge ou de bouche : g, h appuyé, ch de Bach. ن est le n de nuit.", "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition", "answer": "ج = le g de gâteau ; ح = un h appuyé ; خ = le ch allemand de Bach ; ن = le n de nuit"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e19', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.ha']::text[], 'free_answer', 'lesson', 'Combien de points a la lettre ح ? Réponds avec un chiffre.', array['0','zéro','aucun']::text[], 'ح est le crochet vide : aucun point. C''est ce qui la distingue de ج et de خ.', 2, '{"id": "ar.l03.e19", "unitIds": ["ar.g03.letters3", "ar.v.ha"], "type": "free_answer", "difficulty": 2, "instruction": "Écris le nombre.", "prompt": "Combien de points a la lettre ح ? Réponds avec un chiffre.", "promptLanguage": "fr", "answer": "0", "acceptedAnswers": ["0", "zéro", "aucun"], "explanation": "ح est le crochet vide : aucun point. C''est ce qui la distingue de ج et de خ.", "tip": "Le crochet vide : rien dedans, rien dessus.", "extraExample": {"text": "ح", "translation": "ḥâ : un h appuyé, aucun point."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e20', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim']::text[], 'free_answer', 'lesson', 'Comment s''appelle la lettre qui fait le son g en Égypte ?', array['gîm','gim','jîm','jim']::text[], 'La lettre ج s''appelle gîm en Égypte (jîm en arabe littéraire).', 3, '{"id": "ar.l03.e20", "unitIds": ["ar.g03.letters3", "ar.v.jim"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le nom de la lettre.", "prompt": "Comment s''appelle la lettre qui fait le son g en Égypte ?", "promptLanguage": "fr", "answer": "gîm", "acceptedAnswers": ["gîm", "gim", "jîm", "jim"], "explanation": "La lettre ج s''appelle gîm en Égypte (jîm en arabe littéraire).", "tip": "Un hameçon avec une bille dans le creux.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e01', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.dal']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son d, comme dans dent ?', array['د']::text[], 'د se lit comme le d de dent : un petit dos arrondi posé sur la ligne, sans point.', 1, '{"id": "ar.l04.e01", "unitIds": ["ar.g04.letters4", "ar.v.dal"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son d, comme dans dent ?", "promptLanguage": "fr", "options": ["ز", "د", "ر", "ب"], "answer": "د", "acceptedAnswers": ["د"], "explanation": "د se lit comme le d de dent : un petit dos arrondi posé sur la ligne, sans point.", "tip": "Un petit dos arrondi posé sur la ligne.", "extraExample": {"text": "د", "translation": "dâl : le d de dent, aucun point."}, "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e02', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.zay']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son z, comme dans zèbre ?', array['ز']::text[], 'ز se lit comme le z de zèbre. C''est la virgule ر, coiffée d''un point dessus.', 1, '{"id": "ar.l04.e02", "unitIds": ["ar.g04.letters4", "ar.v.zay"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son z, comme dans zèbre ?", "promptLanguage": "fr", "options": ["ر", "ز", "ن", "د"], "answer": "ز", "acceptedAnswers": ["ز"], "explanation": "ز se lit comme le z de zèbre. C''est la virgule ر, coiffée d''un point dessus.", "tip": "La virgule avec un point : zzz.", "extraExample": {"text": "ز", "translation": "zây : le z de zèbre, 1 point dessus."}, "errorPatterns": [{"equals": "ر", "category": "word_confusion", "feedback": "ر est le r roulé : c''est la même virgule, mais sans point."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e03', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.ra']::text[], 'mcq', 'lesson', 'Quelle lettre est une virgule qui descend sous la ligne, sans point ?', array['ر']::text[], 'ر descend sous la ligne comme une virgule. ز lui ressemble, mais elle porte un point dessus.', 1, '{"id": "ar.l04.e03", "unitIds": ["ar.g04.letters4", "ar.v.ra"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est une virgule qui descend sous la ligne, sans point ?", "promptLanguage": "fr", "options": ["ا", "ر", "ز", "د"], "answer": "ر", "acceptedAnswers": ["ر"], "explanation": "ر descend sous la ligne comme une virgule. ز lui ressemble, mais elle porte un point dessus.", "tip": "Une virgule qui descend sous la ligne.", "extraExample": {"text": "ر", "translation": "râ : un r roulé, aucun point."}, "errorPatterns": [{"equals": "ز", "category": "word_confusion", "feedback": "ز a la même forme, mais avec 1 point dessus."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
