insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e20', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.zay']::text[], 'free_answer', 'lesson', 'Comment s''appelle la lettre qui fait le son z, comme dans zèbre ?', array['zây','zay','zai','zaï']::text[], 'ز s''appelle zây : son nom commence par son son, z.', 3, '{"id": "ar.l04.e20", "unitIds": ["ar.g04.letters4", "ar.v.zay"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le nom de la lettre.", "prompt": "Comment s''appelle la lettre qui fait le son z, comme dans zèbre ?", "promptLanguage": "fr", "answer": "zây", "acceptedAnswers": ["zây", "zay", "zai", "zaï"], "explanation": "ز s''appelle zây : son nom commence par son son, z.", "tip": "La virgule avec un point : zzz.", "extraExample": {"text": "ز", "translation": "zây : le z de zèbre, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l04", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
