insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e02', 'ar', 'ar.l05', 'ar.g05.letters5', array['ar.g05.letters5','ar.v.shin']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son ch, comme dans chat ?', array['ش']::text[], 'ش se lit comme le ch de chat. C''est س avec 3 points de vapeur dessus.', 1, '{"id": "ar.l05.e02", "unitIds": ["ar.g05.letters5", "ar.v.shin"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son ch, comme dans chat ?", "promptLanguage": "fr", "options": ["س", "ش", "ن", "ر"], "answer": "ش", "acceptedAnswers": ["ش"], "explanation": "ش se lit comme le ch de chat. C''est س avec 3 points de vapeur dessus.", "tip": "Les trois dents et trois points de vapeur : chhh.", "extraExample": {"text": "ش", "translation": "chîn : le ch de chat, 3 points dessus."}, "errorPatterns": [{"equals": "س", "category": "word_confusion", "feedback": "س fait s, comme soleil. Il lui manque les 3 points de vapeur."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e03', 'ar', 'ar.l05', 'ar.g05.letters5', array['ar.g05.letters5','ar.v.sin']::text[], 'mcq', 'lesson', 'Quelle lettre est faite de trois petites dents, sans aucun point ?', array['س']::text[], 'س a trois dents et aucun point. ش a les mêmes dents, mais avec 3 points dessus.', 1, '{"id": "ar.l05.e03", "unitIds": ["ar.g05.letters5", "ar.v.sin"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est faite de trois petites dents, sans aucun point ?", "promptLanguage": "fr", "options": ["ش", "ض", "ص", "س"], "answer": "س", "acceptedAnswers": ["س"], "explanation": "س a trois dents et aucun point. ش a les mêmes dents, mais avec 3 points dessus.", "tip": "Trois petites dents, comme une scie.", "extraExample": {"text": "س", "translation": "sîn : le s de soleil, aucun point."}, "errorPatterns": [{"equals": "ش", "category": "word_confusion", "feedback": "ش a bien des dents, mais aussi 3 points dessus."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e04', 'ar', 'ar.l05', 'ar.g05.letters5', array['ar.g05.letters5','ar.v.sin','ar.v.shin','ar.v.sad','ar.v.dad']::text[], 'match', 'lesson', 'Relie س, ش, ص et ض à leur nom.', '{}'::text[], 'Les noms commencent par le son de la lettre : sîn (s), chîn (ch), sâd (s lourd), dâd (d lourd).', 1, '{"id": "ar.l05.e04", "unitIds": ["ar.g05.letters5", "ar.v.sin", "ar.v.shin", "ar.v.sad", "ar.v.dad"], "type": "match", "difficulty": 1, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie س, ش, ص et ض à leur nom.", "promptLanguage": "fr", "pairs": [{"left": "س", "right": "sîn"}, {"left": "ش", "right": "chîn"}, {"left": "ص", "right": "sâd"}, {"left": "ض", "right": "dâd"}], "acceptedAnswers": [], "explanation": "Les noms commencent par le son de la lettre : sîn (s), chîn (ch), sâd (s lourd), dâd (d lourd).", "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition", "answer": "س = sîn ; ش = chîn ; ص = sâd ; ض = dâd"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
