insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e14', 'ar', 'ar.l05', 'ar.v.kha', array['ar.v.kha','ar.g05.letters5']::text[], 'mcq', 'lesson', 'Laquelle de ces lettres est le crochet coiffé d''un chapeau ?', array['خ']::text[], 'خ est le crochet avec 1 point dessus, qui se lit comme le ch allemand de Bach.', 3, '{"id": "ar.l05.e14", "unitIds": ["ar.v.kha", "ar.g05.letters5"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lettre.", "prompt": "Laquelle de ces lettres est le crochet coiffé d''un chapeau ?", "promptLanguage": "fr", "options": ["ج", "ش", "خ", "ح"], "answer": "خ", "acceptedAnswers": ["خ"], "explanation": "خ est le crochet avec 1 point dessus, qui se lit comme le ch allemand de Bach.", "tip": "Le crochet avec un chapeau (le point dessus).", "extraExample": {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus."}, "errorPatterns": [{"equals": "ج", "category": "word_confusion", "feedback": "ج a son point dans le creux, pas en chapeau."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e15', 'ar', 'ar.l05', 'ar.g05.letters5', array['ar.g05.letters5','ar.v.shin']::text[], 'mcq', 'lesson', 'Qui suis-je ? « Je suis une scie : trois dents et trois bouffées de vapeur au-dessus. »', array['ش']::text[], 'Trois dents et 3 points dessus : c''est ش, le ch de chat.', 3, '{"id": "ar.l05.e15", "unitIds": ["ar.g05.letters5", "ar.v.shin"], "type": "mcq", "difficulty": 3, "instruction": "Devine la lettre.", "prompt": "Qui suis-je ? « Je suis une scie : trois dents et trois bouffées de vapeur au-dessus. »", "promptLanguage": "fr", "options": ["ص", "ث", "ش", "س"], "answer": "ش", "acceptedAnswers": ["ش"], "explanation": "Trois dents et 3 points dessus : c''est ش, le ch de chat.", "tip": "Les trois dents et trois points de vapeur : chhh.", "extraExample": {"text": "ش", "translation": "chîn : le ch de chat, 3 points dessus."}, "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e16', 'ar', 'ar.l05', 'ar.g05.letters5', array['ar.g05.letters5','ar.v.dad']::text[], 'mcq', 'lesson', 'Quel son fait la lettre ض ?', array['un d lourd']::text[], 'ض est un d lourd, dit en creusant la gorge. Le d léger, c''est د.', 3, '{"id": "ar.l05.e16", "unitIds": ["ar.g05.letters5", "ar.v.dad"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "Quel son fait la lettre ض ?", "promptLanguage": "fr", "options": ["un d lourd", "le d de dent", "un s lourd", "le s de soleil"], "answer": "un d lourd", "acceptedAnswers": ["un d lourd"], "explanation": "ض est un d lourd, dit en creusant la gorge. Le d léger, c''est د.", "tip": "La boucle avec un point dessus.", "extraExample": {"text": "ض", "translation": "dâd : un d lourd, 1 point dessus."}, "errorPatterns": [{"equals": "un s lourd", "category": "word_confusion", "feedback": "Le s lourd, c''est ص. ض a 1 point dessus et se dit d lourd."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e17', 'ar', 'ar.l05', 'ar.v.dhal', array['ar.v.dhal','ar.v.ra','ar.v.zay','ar.v.kha','ar.g05.letters5']::text[], 'match', 'lesson', 'Relie ذ, ر, ز et خ à leur son.', '{}'::text[], 'Quatre sons à relier : ذ (d ou z), ر (r roulé), ز (z) et خ (ch de Bach).', 3, '{"id": "ar.l05.e17", "unitIds": ["ar.v.dhal", "ar.v.ra", "ar.v.zay", "ar.v.kha", "ar.g05.letters5"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ذ, ر, ز et خ à leur son.", "promptLanguage": "fr", "pairs": [{"left": "ذ", "right": "un d, parfois un z"}, {"left": "ر", "right": "un r roulé"}, {"left": "ز", "right": "le z de zèbre"}, {"left": "خ", "right": "le ch allemand de Bach"}], "acceptedAnswers": [], "explanation": "Quatre sons à relier : ذ (d ou z), ر (r roulé), ز (z) et خ (ch de Bach).", "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition", "answer": "ذ = un d, parfois un z ; ر = un r roulé ; ز = le z de zèbre ; خ = le ch allemand de Bach"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e18', 'ar', 'ar.l05', 'ar.g05.letters5', array['ar.g05.letters5','ar.v.sin','ar.v.shin','ar.v.sad','ar.v.dad']::text[], 'match', 'lesson', 'Relie س, ش, ص et ض à leur son.', '{}'::text[], 'Les dents donnent des sons légers (s, ch), la boucle donne des sons lourds (s, d).', 3, '{"id": "ar.l05.e18", "unitIds": ["ar.g05.letters5", "ar.v.sin", "ar.v.shin", "ar.v.sad", "ar.v.dad"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie س, ش, ص et ض à leur son.", "promptLanguage": "fr", "pairs": [{"left": "س", "right": "le s de soleil"}, {"left": "ش", "right": "le ch de chat"}, {"left": "ص", "right": "un s lourd"}, {"left": "ض", "right": "un d lourd"}], "acceptedAnswers": [], "explanation": "Les dents donnent des sons légers (s, ch), la boucle donne des sons lourds (s, d).", "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition", "answer": "س = le s de soleil ; ش = le ch de chat ; ص = un s lourd ; ض = un d lourd"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e19', 'ar', 'ar.l05', 'ar.g05.letters5', array['ar.g05.letters5','ar.v.shin']::text[], 'free_answer', 'lesson', 'Combien de points a la lettre ش ? Réponds avec un chiffre.', array['3','trois']::text[], 'ش a 3 points dessus, trois bouffées de vapeur au-dessus des dents.', 2, '{"id": "ar.l05.e19", "unitIds": ["ar.g05.letters5", "ar.v.shin"], "type": "free_answer", "difficulty": 2, "instruction": "Écris le nombre.", "prompt": "Combien de points a la lettre ش ? Réponds avec un chiffre.", "promptLanguage": "fr", "answer": "3", "acceptedAnswers": ["3", "trois"], "explanation": "ش a 3 points dessus, trois bouffées de vapeur au-dessus des dents.", "tip": "Les trois dents et trois points de vapeur : chhh.", "extraExample": {"text": "ش", "translation": "chîn : le ch de chat, 3 points dessus."}, "pool": "lesson", "lessonId": "ar.l05", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
