insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e05', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.zah']::text[], 'mcq', 'lesson', 'Quelle lettre est un ط coiffé de 1 point dessus ?', array['ظ']::text[], 'ظ est le drapeau avec un point : un z lourd.', 2, '{"id": "ar.l06.e05", "unitIds": ["ar.g06.letters6", "ar.v.zah"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un ط coiffé de 1 point dessus ?", "promptLanguage": "fr", "options": ["ض", "ظ", "غ", "ط"], "answer": "ظ", "acceptedAnswers": ["ظ"], "explanation": "ظ est le drapeau avec un point : un z lourd.", "tip": "Le drapeau avec un point.", "extraExample": {"text": "ظ", "translation": "ẓâ : un z lourd, 1 point dessus."}, "errorPatterns": [{"equals": "ض", "category": "word_confusion", "feedback": "ض a 1 point dessus, mais sa boucle n''a pas de mât."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e06', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.ghayn']::text[], 'mcq', 'lesson', 'Quelle lettre est un œil avec une larme, c''est-à-dire 1 point dessus ?', array['غ']::text[], 'غ est ع avec 1 point dessus. خ a aussi 1 point dessus, mais c''est un crochet.', 2, '{"id": "ar.l06.e06", "unitIds": ["ar.g06.letters6", "ar.v.ghayn"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un œil avec une larme, c''est-à-dire 1 point dessus ?", "promptLanguage": "fr", "options": ["خ", "غ", "ظ", "ع"], "answer": "غ", "acceptedAnswers": ["غ"], "explanation": "غ est ع avec 1 point dessus. خ a aussi 1 point dessus, mais c''est un crochet.", "tip": "L''œil avec une larme dessus.", "extraExample": {"text": "غ", "translation": "ghaïn : le r de rouge, 1 point dessus."}, "errorPatterns": [{"equals": "خ", "category": "word_confusion", "feedback": "خ est un crochet. L''œil à larme, c''est غ."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e07', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.ayn']::text[], 'mcq', 'lesson', 'Quelle lettre fait un son de gorge serrée, sans équivalent en français ?', array['ع']::text[], 'ع serre la gorge : aucun son français n''y ressemble. ح souffle simplement fort, غ fait le r de rouge.', 2, '{"id": "ar.l06.e07", "unitIds": ["ar.g06.letters6", "ar.v.ayn"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait un son de gorge serrée, sans équivalent en français ?", "promptLanguage": "fr", "options": ["ح", "غ", "ع", "ا"], "answer": "ع", "acceptedAnswers": ["ع"], "explanation": "ع serre la gorge : aucun son français n''y ressemble. ح souffle simplement fort, غ fait le r de rouge.", "tip": "Un œil de profil : aïn veut dire œil.", "extraExample": {"text": "ع", "translation": "aïn : un son de gorge serrée, aucun point."}, "errorPatterns": [{"equals": "ح", "category": "word_confusion", "feedback": "ح est un h appuyé, un souffle. ع serre la gorge."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e08', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.tah']::text[], 'fill_blank', 'lesson', 'ط est un t ___ : le t de ت dit en creusant la gorge.', array['lourd']::text[], 'ط est le t lourd, alors que ت est le t léger, comme dans table.', 2, '{"id": "ar.l06.e08", "unitIds": ["ar.g06.letters6", "ar.v.tah"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "ط est un t ___ : le t de ت dit en creusant la gorge.", "promptLanguage": "fr", "options": ["doux", "lourd", "léger"], "answer": "lourd", "acceptedAnswers": ["lourd"], "explanation": "ط est le t lourd, alors que ت est le t léger, comme dans table.", "tip": "Une boucle avec un mât : un drapeau.", "extraExample": {"text": "ط", "translation": "ṭâ : un t lourd, aucun point."}, "pool": "lesson", "lessonId": "ar.l06", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e09', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.ghayn','ar.v.ayn']::text[], 'fill_blank', 'lesson', 'Si tu ajoutes 1 point dessus à ع, tu obtiens ___.', array['غ']::text[], 'ع + 1 point dessus = غ : l''œil se met à pleurer et prend le son du r de rouge.', 2, '{"id": "ar.l06.e09", "unitIds": ["ar.g06.letters6", "ar.v.ghayn", "ar.v.ayn"], "type": "fill_blank", "difficulty": 2, "instruction": "Choisis la lettre qui manque.", "prompt": "Si tu ajoutes 1 point dessus à ع, tu obtiens ___.", "promptLanguage": "fr", "options": ["ظ", "غ", "خ", "ض"], "answer": "غ", "acceptedAnswers": ["غ"], "explanation": "ع + 1 point dessus = غ : l''œil se met à pleurer et prend le son du r de rouge.", "tip": "L''œil avec une larme dessus.", "extraExample": {"text": "غ", "translation": "ghaïn : le r de rouge, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l06", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
