insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e20', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.lam']::text[], 'free_answer', 'lesson', 'Comment s''appelle la lettre qui fait le son l, comme dans lune ?', array['lâm','lam','laam']::text[], 'ل s''appelle lâm : son nom commence par son son, l.', 3, '{"id": "ar.l07.e20", "unitIds": ["ar.g07.letters7", "ar.v.lam"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le nom de la lettre.", "prompt": "Comment s''appelle la lettre qui fait le son l, comme dans lune ?", "promptLanguage": "fr", "answer": "lâm", "acceptedAnswers": ["lâm", "lam", "laam"], "explanation": "ل s''appelle lâm : son nom commence par son son, l.", "tip": "Un L dans un miroir : un bâton avec un pied.", "extraExample": {"text": "ل", "translation": "lâm : le l de lune, aucun point."}, "pool": "lesson", "lessonId": "ar.l07", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e01', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.waw']::text[], 'mcq', 'lesson', 'Quelle lettre est un petit 9, qui se lit comme le ou de oui ?', array['و']::text[], 'و est le petit 9 à queue courbe : le ou de oui. م a une queue droite.', 1, '{"id": "ar.l08.e01", "unitIds": ["ar.g08.letters8", "ar.v.waw"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un petit 9, qui se lit comme le ou de oui ?", "promptLanguage": "fr", "options": ["ر", "م", "و", "ف"], "answer": "و", "acceptedAnswers": ["و"], "explanation": "و est le petit 9 à queue courbe : le ou de oui. م a une queue droite.", "tip": "Un petit 9 : une tête et une queue qui pend.", "extraExample": {"text": "و", "translation": "wâw : le ou de oui, aucun point."}, "errorPatterns": [{"equals": "م", "category": "word_confusion", "feedback": "م a une queue droite, et se dit m comme dans mer."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e02', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.mim','ar.v.heh','ar.v.waw','ar.v.hamza','ar.v.ta_marbuta']::text[], 'match', 'lesson', 'Relie م, ه, و, ء et ة à leur nom.', '{}'::text[], 'mîm pour m, wâw pour w/ou, hâ pour le h soufflé. ء s''appelle hamza, ة s''appelle tâ marbûta, « ta attaché ».', 1, '{"id": "ar.l08.e02", "unitIds": ["ar.g08.letters8", "ar.v.mim", "ar.v.heh", "ar.v.waw", "ar.v.hamza", "ar.v.ta_marbuta"], "type": "match", "difficulty": 1, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie م, ه, و, ء et ة à leur nom.", "promptLanguage": "fr", "pairs": [{"left": "م", "right": "mîm"}, {"left": "ه", "right": "hâ"}, {"left": "و", "right": "wâw"}, {"left": "ء", "right": "hamza"}, {"left": "ة", "right": "tâ marbûta"}], "acceptedAnswers": [], "explanation": "mîm pour m, wâw pour w/ou, hâ pour le h soufflé. ء s''appelle hamza, ة s''appelle tâ marbûta, « ta attaché ».", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition", "answer": "م = mîm ; ه = hâ ; و = wâw ; ء = hamza ; ة = tâ marbûta"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e03', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.heh']::text[], 'mcq', 'lesson', 'Quelle lettre est un petit nœud à deux boucles, qui se lit comme un h soufflé ?', array['ه']::text[], 'ه est le petit nœud : un simple souffle. ح est un crochet à h appuyé.', 2, '{"id": "ar.l08.e03", "unitIds": ["ar.g08.letters8", "ar.v.heh"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un petit nœud à deux boucles, qui se lit comme un h soufflé ?", "promptLanguage": "fr", "options": ["ه", "ح", "ع", "خ"], "answer": "ه", "acceptedAnswers": ["ه"], "explanation": "ه est le petit nœud : un simple souffle. ح est un crochet à h appuyé.", "tip": "Un petit nœud à deux boucles.", "extraExample": {"text": "ه", "translation": "hâ : un h soufflé, aucun point."}, "errorPatterns": [{"equals": "ح", "category": "word_confusion", "feedback": "ح est un crochet, avec un h appuyé, beaucoup plus fort."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e04', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.ta_marbuta']::text[], 'mcq', 'lesson', 'Quelle lettre est un ه coiffé de 2 points dessus, à la fin des mots féminins ?', array['ة']::text[], 'ة est le ه couronné des 2 points de ت : tâ marbûta, « ta attaché », qui se dit a à la fin du mot.', 2, '{"id": "ar.l08.e04", "unitIds": ["ar.g08.letters8", "ar.v.ta_marbuta"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un ه coiffé de 2 points dessus, à la fin des mots féminins ?", "promptLanguage": "fr", "options": ["ة", "ت", "ق", "ه"], "answer": "ة", "acceptedAnswers": ["ة"], "explanation": "ة est le ه couronné des 2 points de ت : tâ marbûta, « ta attaché », qui se dit a à la fin du mot.", "tip": "Un ه coiffé des deux points de ت.", "extraExample": {"text": "ة", "translation": "tâ marbûta : un a à la fin du mot, 2 points dessus."}, "errorPatterns": [{"equals": "ه", "category": "word_confusion", "feedback": "ه n''a pas de point : il lui manque la couronne de 2 points."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e05', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.alif_maqsura']::text[], 'mcq', 'lesson', 'Quelle lettre est un ي qui a perdu ses 2 points ?', array['ى']::text[], 'ى est un ي sans ses 2 points dessous. Elle ne se trouve qu''à la fin d''un mot.', 2, '{"id": "ar.l08.e05", "unitIds": ["ar.g08.letters8", "ar.v.alif_maqsura"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un ي qui a perdu ses 2 points ?", "promptLanguage": "fr", "options": ["ى", "ن", "ا", "ي"], "answer": "ى", "acceptedAnswers": ["ى"], "explanation": "ى est un ي sans ses 2 points dessous. Elle ne se trouve qu''à la fin d''un mot.", "tip": "Un ي qui a perdu ses deux points.", "extraExample": {"text": "ى", "translation": "alif maqsûra : un a long à la fin du mot, aucun point."}, "errorPatterns": [{"equals": "ي", "category": "word_confusion", "feedback": "ي garde ses 2 points dessous."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
