insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e21', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.la']::text[], 'translation', 'lesson', 'لا', array['non']::text[], 'لا est la ligature ل + ا, un seul signe. C''est le mot « non ».', 1, '{"id": "ar.l16.e21", "type": "translation", "unitIds": ["ar.g16.article_and_ligature", "ar.v.la"], "difficulty": 1, "instruction": "Écris le sens en français.", "prompt": "لا", "promptLanguage": "ar", "answer": "non", "acceptedAnswers": ["non"], "explanation": "لا est la ligature ل + ا, un seul signe. C''est le mot « non ».", "tip": "ل + ا = لا, et c''est aussi « non ».", "extraExample": {"text": "لا، شكرا.", "translation": "Non, merci."}, "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e22', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.talata']::text[], 'translation', 'lesson', 'ثلاثة', array['trois','3']::text[], 'ثلاثة = ثلا | ثة : ث (3 points dessus), la ligature لا, puis ث et ة. C''est le chiffre trois.', 3, '{"id": "ar.l16.e22", "type": "translation", "unitIds": ["ar.g16.article_and_ligature", "ar.v.talata"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "ثلاثة", "promptLanguage": "ar", "answer": "trois", "acceptedAnswers": ["trois", "3"], "explanation": "ثلاثة = ثلا | ثة : ث (3 points dessus), la ligature لا, puis ث et ة. C''est le chiffre trois.", "tip": "Deux ث avec 3 points dessus, et la ligature au milieu.", "extraExample": {"text": "عندي ثلاثة أولاد.", "translation": "J''ai trois enfants."}, "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e23', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.kalam']::text[], 'free_answer', 'lesson', 'Que veut dire كلام ?', array['paroles','parole','discours','mots','les paroles','le discours','propos']::text[], 'كلام = كلا | م : ك, la ligature لا, puis م. Ce sont les paroles, ce qu''on dit.', 3, '{"id": "ar.l16.e23", "type": "free_answer", "unitIds": ["ar.g16.article_and_ligature", "ar.v.kalam"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire كلام ?", "promptLanguage": "fr", "answer": "paroles", "acceptedAnswers": ["paroles", "parole", "discours", "mots", "les paroles", "le discours", "propos"], "explanation": "كلام = كلا | م : ك, la ligature لا, puis م. Ce sont les paroles, ce qu''on dit.", "tip": "كلا + م : la ligature ferme le premier bloc.", "extraExample": {"text": "كلامك صح.", "translation": "Ce que tu dis est juste."}, "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e24', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.balash']::text[], 'free_answer', 'lesson', 'Que veut dire بلاش ?', array['gratuit','gratuitement','gratis','pour rien','laisse tomber']::text[], 'بلاش = بلا | ش : ب, la ligature لا, puis ش (3 dents, 3 points). C''est « gratuit », « pour rien ».', 3, '{"id": "ar.l16.e24", "type": "free_answer", "unitIds": ["ar.g16.article_and_ligature", "ar.v.balash"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire بلاش ?", "promptLanguage": "fr", "answer": "gratuit", "acceptedAnswers": ["gratuit", "gratuitement", "gratis", "pour rien", "laisse tomber"], "explanation": "بلاش = بلا | ش : ب, la ligature لا, puis ش (3 dents, 3 points). C''est « gratuit », « pour rien ».", "tip": "بلا + ش : la ligature ferme le premier bloc.", "extraExample": {"text": "الأكل ده بلاش.", "translation": "Ce repas est gratuit."}, "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e01', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels']::text[], 'mcq', 'lesson', 'Laquelle de ces syllabes porte une fatha ?', array['بَ']::text[], 'La fatha est le petit trait penché au-dessus de la lettre. بِ a un trait sous la lettre (kasra) et بُ un petit و bouclé (damma).', 1, '{"id": "ar.l17.e01", "unitIds": ["ar.g17.short_vowels"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne syllabe.", "prompt": "Laquelle de ces syllabes porte une fatha ?", "promptLanguage": "fr", "answer": "بَ", "acceptedAnswers": ["بَ"], "explanation": "La fatha est le petit trait penché au-dessus de la lettre. بِ a un trait sous la lettre (kasra) et بُ un petit و bouclé (damma).", "tip": "Fatha = ouvrir : le trait est au-dessus.", "extraExample": {"text": "تَ", "translation": "t + a"}, "options": ["بَ", "بِ", "بُ"], "errorPatterns": [{"equals": "بِ", "category": "spelling", "feedback": "Ce trait est sous la lettre : c''est une kasra (le son i)."}, {"equals": "بُ", "category": "spelling", "feedback": "Ce petit و bouclé est une damma (le son ou)."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e02', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels']::text[], 'mcq', 'lesson', 'Quel signe se place sous la lettre ?', array['la kasra']::text[], 'Seule la kasra va sous la lettre. La fatha et la damma sont au-dessus.', 1, '{"id": "ar.l17.e02", "unitIds": ["ar.g17.short_vowels"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Quel signe se place sous la lettre ?", "promptLanguage": "fr", "answer": "la kasra", "acceptedAnswers": ["la kasra"], "explanation": "Seule la kasra va sous la lettre. La fatha et la damma sont au-dessus.", "tip": "Kasra = casser : le i tombe sous la lettre.", "extraExample": {"text": "بِ", "translation": "b + i"}, "options": ["la fatha", "la kasra", "la damma"], "errorPatterns": [{"equals": "la fatha", "category": "spelling", "feedback": "La fatha est un trait au-dessus de la lettre."}, {"equals": "la damma", "category": "spelling", "feedback": "La damma est un petit و bouclé au-dessus de la lettre."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e03', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels']::text[], 'mcq', 'lesson', 'Quel son donne la damma ?', array['ou comme dans loup']::text[], 'La damma (ضَمَّة, « rassembler ») donne le son ou : les lèvres se rassemblent en rond.', 1, '{"id": "ar.l17.e03", "unitIds": ["ar.g17.short_vowels"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Quel son donne la damma ?", "promptLanguage": "fr", "answer": "ou comme dans loup", "acceptedAnswers": ["ou comme dans loup"], "explanation": "La damma (ضَمَّة, « rassembler ») donne le son ou : les lèvres se rassemblent en rond.", "tip": "Lèvres en rond : ou.", "extraExample": {"text": "بُ", "translation": "b + ou"}, "options": ["a comme dans table", "ou comme dans loup", "i comme dans midi"], "errorPatterns": [{"equals": "a comme dans table", "category": "spelling", "feedback": "Le son a vient de la fatha, le trait au-dessus."}, {"equals": "i comme dans midi", "category": "spelling", "feedback": "Le son i vient de la kasra, le trait sous la lettre."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e04', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels']::text[], 'mcq', 'lesson', 'Comment se lit la syllabe بُ ?', array['b + ou']::text[], 'ب porte une damma : le b est suivi du son ou.', 2, '{"id": "ar.l17.e04", "unitIds": ["ar.g17.short_vowels"], "type": "mcq", "difficulty": 2, "instruction": "Lis la syllabe.", "prompt": "Comment se lit la syllabe بُ ?", "promptLanguage": "fr", "answer": "b + ou", "acceptedAnswers": ["b + ou"], "explanation": "ب porte une damma : le b est suivi du son ou.", "tip": "Lis la lettre, puis ajoute sa voyelle.", "extraExample": {"text": "تُ", "translation": "t + ou"}, "options": ["b + i", "b + a", "b + ou"], "errorPatterns": [{"equals": "b + a", "category": "spelling", "feedback": "b + a s''écrit بَ, avec une fatha."}, {"equals": "b + i", "category": "spelling", "feedback": "b + i s''écrit بِ, avec une kasra sous la lettre."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e05', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.gabal']::text[], 'mcq', 'lesson', 'جَبَل', array['montagne']::text[], 'ج + a, ب + a, ل : deux fathas, puis ل sans voyelle. C''est la montagne.', 2, '{"id": "ar.l17.e05", "unitIds": ["ar.g17.short_vowels", "ar.v.gabal"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "جَبَل", "promptLanguage": "ar", "answer": "montagne", "acceptedAnswers": ["montagne"], "explanation": "ج + a, ب + a, ل : deux fathas, puis ل sans voyelle. C''est la montagne.", "tip": "Lis lettre par lettre, voyelle comprise.", "extraExample": {"text": "جَبَل سِينَا.", "translation": "Le mont Sinaï."}, "options": ["miel", "montagne", "lune", "pays"], "errorPatterns": [{"equals": "pays", "category": "word_confusion", "feedback": "Le pays s''écrit بَلَد : la première lettre est ب, pas ج."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e06', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.hamal']::text[], 'mcq', 'lesson', 'حَمَل', array['agneau']::text[], 'ح + a, م + a, ل : l''agneau. Dans l''Église, l''Agneau de Dieu est le Christ.', 2, '{"id": "ar.l17.e06", "unitIds": ["ar.g17.short_vowels", "ar.v.hamal"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "حَمَل", "promptLanguage": "ar", "answer": "agneau", "acceptedAnswers": ["agneau"], "explanation": "ح + a, م + a, ل : l''agneau. Dans l''Église, l''Agneau de Dieu est le Christ.", "tip": "Trois lettres, deux fathas.", "extraExample": {"text": "حَمَل اللَّه.", "translation": "L''Agneau de Dieu."}, "options": ["agneau", "apôtres", "livres", "lune"], "errorPatterns": [{"equals": "lune", "category": "word_confusion", "feedback": "La lune est قَمَر : elle commence par ق, pas par ح."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e07', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.enab']::text[], 'mcq', 'lesson', 'Quelle voyelle porte le ع au début de عِنَب ?', array['la kasra']::text[], 'Le signe est sous le ع : c''est une kasra, donc le son i. Les deux autres voyelles de عِنَب sont des fathas.', 3, '{"id": "ar.l17.e07", "unitIds": ["ar.g17.short_vowels", "ar.v.enab"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Quelle voyelle porte le ع au début de عِنَب ?", "promptLanguage": "fr", "answer": "la kasra", "acceptedAnswers": ["la kasra"], "explanation": "Le signe est sous le ع : c''est une kasra, donc le son i. Les deux autres voyelles de عِنَب sont des fathas.", "tip": "Regarde si le signe est au-dessus ou sous la lettre.", "extraExample": {"text": "عِنَب أَحْمَر.", "translation": "Du raisin rouge."}, "options": ["la kasra", "la fatha", "la damma"], "errorPatterns": [{"equals": "la fatha", "category": "spelling", "feedback": "Les fathas de عِنَب sont sur ن et ب ; sur ع, le signe est sous la lettre."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e08', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels']::text[], 'mcq', 'lesson', 'Quel mot veut dire « livres » ?', array['كُتُب']::text[], 'كُتُب porte deux dammas : ك + ou, ت + ou, ب. كَتَب, avec des fathas, veut dire « il a écrit ». كُتَب n''est pas un mot.', 3, '{"id": "ar.l17.e08", "unitIds": ["ar.g17.short_vowels"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « livres » ?", "promptLanguage": "fr", "answer": "كُتُب", "acceptedAnswers": ["كُتُب"], "explanation": "كُتُب porte deux dammas : ك + ou, ت + ou, ب. كَتَب, avec des fathas, veut dire « il a écrit ». كُتَب n''est pas un mot.", "tip": "Mêmes lettres, voyelles différentes : mot différent.", "extraExample": {"text": "كُتُب كِتِير.", "translation": "Beaucoup de livres."}, "options": ["كَتَب", "كُتُب", "كُتَب"], "errorPatterns": [{"equals": "كَتَب", "category": "word_confusion", "feedback": "كَتَب (fathas) veut dire « il a écrit ». Pour « livres », on veut deux dammas."}, {"equals": "كُتَب", "category": "spelling", "feedback": "Cette combinaison n''existe pas : pour « livres », les deux voyelles sont des dammas."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e09', 'ar', 'ar.l17', 'ar.v.jim', array['ar.v.jim','ar.g17.short_vowels']::text[], 'mcq', 'lesson', 'Quelle lettre se lit comme le g de « gâteau » ?', array['ج']::text[], 'En Égypte, ج se dit g, comme dans gâteau : c''est la lettre du crochet avec un point dessous.', 1, '{"id": "ar.l17.e09", "unitIds": ["ar.v.jim", "ar.g17.short_vowels"], "type": "mcq", "difficulty": 1, "instruction": "Retrouve la lettre.", "prompt": "Quelle lettre se lit comme le g de « gâteau » ?", "promptLanguage": "fr", "answer": "ج", "acceptedAnswers": ["ج"], "explanation": "En Égypte, ج se dit g, comme dans gâteau : c''est la lettre du crochet avec un point dessous.", "tip": "ج a un point sous le crochet : g de gâteau.", "extraExample": {"text": "جَبَل", "translation": "montagne"}, "options": ["خ", "ح", "ج"], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e10', 'ar', 'ar.l17', 'ar.v.laban', array['ar.v.laban','ar.g17.short_vowels']::text[], 'mcq', 'lesson', 'لبن', array['lait']::text[], 'ل + ب + ن, sans voyelles : c''est le lait. Sans harakat, tu lis grâce au mot que tu connais.', 1, '{"id": "ar.l17.e10", "unitIds": ["ar.v.laban", "ar.g17.short_vowels"], "type": "mcq", "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "لبن", "promptLanguage": "ar", "answer": "lait", "acceptedAnswers": ["lait"], "explanation": "ل + ب + ن, sans voyelles : c''est le lait. Sans harakat, tu lis grâce au mot que tu connais.", "tip": "Sans voyelles, ton oreille complète le mot.", "extraExample": {"text": "لَبَن", "translation": "lait (avec ses voyelles)"}, "options": ["eau", "thé", "pain", "lait"], "errorPatterns": [{"equals": "pain", "category": "word_confusion", "feedback": "« pain » s''écrit عيش."}, {"equals": "thé", "category": "word_confusion", "feedback": "« thé » s''écrit شاي."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e11', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.gabal']::text[], 'fill_blank', 'lesson', 'جَ___ل', array['بَ']::text[], 'La montagne, جَبَل : après جَ vient ب avec une fatha, puis ل sans voyelle.', 2, '{"id": "ar.l17.e11", "unitIds": ["ar.g17.short_vowels", "ar.v.gabal"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne syllabe.", "prompt": "جَ___ل", "promptLanguage": "ar", "answer": "بَ", "acceptedAnswers": ["بَ"], "explanation": "La montagne, جَبَل : après جَ vient ب avec une fatha, puis ل sans voyelle.", "tip": "Dis le mot à voix haute : ton oreille entend le a.", "extraExample": {"text": "جَبَل", "translation": "montagne"}, "options": ["بُ", "بِ", "بَ"], "errorPatterns": [{"equals": "بِ", "category": "spelling", "feedback": "Avec une kasra, ce serait un i : la montagne a un a."}, {"equals": "بُ", "category": "spelling", "feedback": "Avec une damma, ce serait un ou : la montagne a un a."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e12', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.enab']::text[], 'fill_blank', 'lesson', 'عِ___ب', array['نَ']::text[], 'عِنَب : عِ (kasra), puis نَ (fatha), puis ب sans voyelle. Il n''y a qu''une kasra dans ce mot.', 2, '{"id": "ar.l17.e12", "unitIds": ["ar.g17.short_vowels", "ar.v.enab"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne syllabe.", "prompt": "عِ___ب", "promptLanguage": "ar", "answer": "نَ", "acceptedAnswers": ["نَ"], "explanation": "عِنَب : عِ (kasra), puis نَ (fatha), puis ب sans voyelle. Il n''y a qu''une kasra dans ce mot.", "tip": "Une seule kasra, au début.", "extraExample": {"text": "عِنَب أَحْمَر.", "translation": "Du raisin rouge."}, "options": ["نُ", "نِ", "نَ"], "errorPatterns": [{"equals": "نِ", "category": "spelling", "feedback": "Une seconde kasra ? Non : la kasra est seulement sur ع."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e13', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.balad']::text[], 'fill_blank', 'lesson', 'بَلَ___', array['د']::text[], 'La dernière lettre d''un mot n''a presque jamais de signe : en égyptien, il finit sans voyelle. On écrit donc د seul.', 3, '{"id": "ar.l17.e13", "unitIds": ["ar.g17.short_vowels", "ar.v.balad"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la dernière lettre.", "prompt": "بَلَ___", "promptLanguage": "ar", "answer": "د", "acceptedAnswers": ["د"], "explanation": "La dernière lettre d''un mot n''a presque jamais de signe : en égyptien, il finit sans voyelle. On écrit donc د seul.", "tip": "Dernière lettre : pas de signe.", "extraExample": {"text": "بَلَدِي مِصْر.", "translation": "Mon pays, c''est l''Égypte."}, "options": ["د", "دِ", "دَ"], "errorPatterns": [{"equals": "دَ", "category": "spelling", "feedback": "Ce serait un a de plus à la fin : en égyptien, بَلَد finit par la lettre د, sans voyelle."}, {"equals": "دِ", "category": "spelling", "feedback": "Ce serait un i à la fin : بَلَد finit sans voyelle."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e14', 'ar', 'ar.l17', 'ar.v.laban', array['ar.v.laban','ar.g17.short_vowels']::text[], 'fill_blank', 'lesson', 'لَ___ن', array['بَ']::text[], 'Tu dis déjà ce mot à l''oral : lait se dit avec a, a. Donc ب porte une fatha : لَبَن.', 2, '{"id": "ar.l17.e14", "unitIds": ["ar.v.laban", "ar.g17.short_vowels"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « lait ».", "prompt": "لَ___ن", "promptLanguage": "ar", "answer": "بَ", "acceptedAnswers": ["بَ"], "explanation": "Tu dis déjà ce mot à l''oral : lait se dit avec a, a. Donc ب porte une fatha : لَبَن.", "tip": "Dis-le tout haut : tu entends la voyelle.", "extraExample": {"text": "لَبَن", "translation": "lait"}, "options": ["بِ", "بُ", "بَ"], "errorPatterns": [{"equals": "بِ", "category": "spelling", "feedback": "Dis le mot à voix haute : tu n''entends pas de i."}, {"equals": "بُ", "category": "spelling", "feedback": "Dis le mot à voix haute : tu n''entends pas de ou."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e15', 'ar', 'ar.l17', 'ar.v.jaras', array['ar.v.jaras','ar.g17.short_vowels']::text[], 'fill_blank', 'lesson', 'جَ___س', array['رَ']::text[], 'Cloche, جَرَس : deux fathas, puis س sans voyelle. Ton oreille entend a, a.', 2, '{"id": "ar.l17.e15", "unitIds": ["ar.v.jaras", "ar.g17.short_vowels"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « cloche ».", "prompt": "جَ___س", "promptLanguage": "ar", "answer": "رَ", "acceptedAnswers": ["رَ"], "explanation": "Cloche, جَرَس : deux fathas, puis س sans voyelle. Ton oreille entend a, a.", "tip": "Deux fois le son a.", "extraExample": {"text": "جَرَس الْكَنِيسَة", "translation": "la cloche de l''église"}, "options": ["رِ", "رَ", "رُ"], "errorPatterns": [{"equals": "رِ", "category": "spelling", "feedback": "Pas de i dans ce mot : la voyelle est un a."}, {"equals": "رُ", "category": "spelling", "feedback": "Pas de ou dans ce mot : la voyelle est un a."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e16', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels']::text[], 'match', 'lesson', 'Syllabes et sons', '{}'::text[], 'La fatha donne a, la kasra donne i, la damma donne ou. La lettre se dit d''abord, la voyelle après.', 1, '{"id": "ar.l17.e16", "unitIds": ["ar.g17.short_vowels"], "type": "match", "difficulty": 1, "instruction": "Associe chaque syllabe à son son.", "prompt": "Syllabes et sons", "promptLanguage": "fr", "answer": "بَ = b + a ; تِ = t + i ; نُ = n + ou ; سَ = s + a", "acceptedAnswers": [], "explanation": "La fatha donne a, la kasra donne i, la damma donne ou. La lettre se dit d''abord, la voyelle après.", "pairs": [{"left": "بَ", "right": "b + a"}, {"left": "تِ", "right": "t + i"}, {"left": "نُ", "right": "n + ou"}, {"left": "سَ", "right": "s + a"}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e17', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.gabal','ar.v.asal','ar.v.qalam','ar.v.qamar']::text[], 'match', 'lesson', 'Mots du quotidien', '{}'::text[], 'Lis chaque mot lettre par lettre, voyelle comprise : trois lettres et deux fathas à chaque fois.', 2, '{"id": "ar.l17.e17", "unitIds": ["ar.g17.short_vowels", "ar.v.gabal", "ar.v.asal", "ar.v.qalam", "ar.v.qamar"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots du quotidien", "promptLanguage": "fr", "answer": "جَبَل = montagne ; عَسَل = miel ; قَلَم = stylo ; قَمَر = lune", "acceptedAnswers": [], "explanation": "Lis chaque mot lettre par lettre, voyelle comprise : trois lettres et deux fathas à chaque fois.", "pairs": [{"left": "جَبَل", "right": "montagne"}, {"left": "عَسَل", "right": "miel"}, {"left": "قَلَم", "right": "stylo"}, {"left": "قَمَر", "right": "lune"}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e18', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.hamal','ar.v.rusul','ar.v.qudus']::text[], 'match', 'lesson', 'Mots d''église et de livres', '{}'::text[], 'حَمَل : l''Agneau de Dieu ; رُسُل : les apôtres ; قُدُس : la sainteté (الرُّوح الْقُدُس) ; كُتُب : des livres.', 3, '{"id": "ar.l17.e18", "unitIds": ["ar.g17.short_vowels", "ar.v.hamal", "ar.v.rusul", "ar.v.qudus"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots d''église et de livres", "promptLanguage": "fr", "answer": "حَمَل = agneau ; رُسُل = apôtres ; قُدُس = sainteté ; كُتُب = livres", "acceptedAnswers": [], "explanation": "حَمَل : l''Agneau de Dieu ; رُسُل : les apôtres ; قُدُس : la sainteté (الرُّوح الْقُدُس) ; كُتُب : des livres.", "pairs": [{"left": "حَمَل", "right": "agneau"}, {"left": "رُسُل", "right": "apôtres"}, {"left": "قُدُس", "right": "sainteté"}, {"left": "كُتُب", "right": "livres"}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e19', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.balad']::text[], 'translation', 'lesson', 'بَلَد', array['pays','un pays','le pays','village','un village']::text[], 'ب + a, ل + a, د : un pays, ou le village d''où l''on vient.', 2, '{"id": "ar.l17.e19", "unitIds": ["ar.g17.short_vowels", "ar.v.balad"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "بَلَد", "promptLanguage": "ar", "answer": "pays", "acceptedAnswers": ["pays", "un pays", "le pays", "village", "un village"], "explanation": "ب + a, ل + a, د : un pays, ou le village d''où l''on vient.", "tip": "Deux fathas, puis د sans voyelle.", "extraExample": {"text": "بَلَد كِبِير.", "translation": "Un grand pays."}, "errorPatterns": [{"equals": "montagne", "category": "word_confusion", "feedback": "La montagne est جَبَل : ici tu lis ب + ل + د."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e20', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.qalam']::text[], 'translation', 'lesson', 'قَلَم', array['stylo','un stylo','le stylo','crayon','un crayon']::text[], 'ق + a, ل + a, م : le stylo. Au Caire, ق se dit comme un coup de gorge.', 2, '{"id": "ar.l17.e20", "unitIds": ["ar.g17.short_vowels", "ar.v.qalam"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "قَلَم", "promptLanguage": "ar", "answer": "stylo", "acceptedAnswers": ["stylo", "un stylo", "le stylo", "crayon", "un crayon"], "explanation": "ق + a, ل + a, م : le stylo. Au Caire, ق se dit comme un coup de gorge.", "tip": "Deux fathas.", "extraExample": {"text": "عِنْدِي قَلَم.", "translation": "J''ai un stylo."}, "errorPatterns": [{"equals": "lune", "category": "word_confusion", "feedback": "La lune est قَمَر : ici tu lis ق + ل + م."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e21', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels']::text[], 'free_answer', 'lesson', 'Comment s''appelle le signe en forme de petit و bouclé, posé au-dessus de la lettre ?', array['damma','la damma','une damma','dhamma']::text[], 'C''est la damma (ضَمَّة, « rassembler ») : elle donne le son ou.', 2, '{"id": "ar.l17.e21", "unitIds": ["ar.g17.short_vowels"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Comment s''appelle le signe en forme de petit و bouclé, posé au-dessus de la lettre ?", "promptLanguage": "fr", "answer": "damma", "acceptedAnswers": ["damma", "la damma", "une damma", "dhamma"], "explanation": "C''est la damma (ضَمَّة, « rassembler ») : elle donne le son ou.", "tip": "Un petit و bouclé : ou.", "extraExample": {"text": "بُ", "translation": "b + ou"}, "errorPatterns": [{"equals": "fatha", "category": "word_confusion", "feedback": "La fatha est un trait penché, pas un petit و bouclé."}, {"equals": "kasra", "category": "word_confusion", "feedback": "La kasra est un trait penché sous la lettre."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e22', 'ar', 'ar.l17', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.rusul']::text[], 'free_answer', 'lesson', 'Que veut dire رُسُل ?', array['apôtres','les apôtres','des apôtres','apôtre']::text[], 'رُسُل : deux dammas, donc ر + ou, س + ou, ل. Ce sont les apôtres, les envoyés du Christ.', 3, '{"id": "ar.l17.e22", "unitIds": ["ar.g17.short_vowels", "ar.v.rusul"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire رُسُل ?", "promptLanguage": "fr", "answer": "apôtres", "acceptedAnswers": ["apôtres", "les apôtres", "des apôtres", "apôtre"], "explanation": "رُسُل : deux dammas, donc ر + ou, س + ou, ل. Ce sont les apôtres, les envoyés du Christ.", "tip": "Deux dammas, deux ou.", "extraExample": {"text": "عِيد الرُّسُل.", "translation": "La fête des apôtres."}, "errorPatterns": [{"equals": "agneau", "category": "word_confusion", "feedback": "L''agneau est حَمَل, avec des fathas."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e01', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun']::text[], 'mcq', 'lesson', 'Quel signe veut dire « pas de voyelle » ?', array['le soukoun']::text[], 'Le soukoun, petit rond au-dessus de la lettre, veut dire : aucune voyelle. La fatha et la damma sont des voyelles.', 1, '{"id": "ar.l18.e01", "unitIds": ["ar.g18.sukun"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Quel signe veut dire « pas de voyelle » ?", "promptLanguage": "fr", "answer": "le soukoun", "acceptedAnswers": ["le soukoun"], "explanation": "Le soukoun, petit rond au-dessus de la lettre, veut dire : aucune voyelle. La fatha et la damma sont des voyelles.", "tip": "Rond = rien.", "extraExample": {"text": "نْ", "translation": "n sans voyelle"}, "options": ["la damma", "la fatha", "le soukoun"], "errorPatterns": [{"equals": "la fatha", "category": "spelling", "feedback": "La fatha est un trait penché : elle donne le son a."}, {"equals": "la damma", "category": "spelling", "feedback": "La damma est un petit و bouclé : elle donne le son ou."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e02', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun']::text[], 'mcq', 'lesson', 'Où écrit-on surtout le soukoun ?', array['au milieu du mot']::text[], 'Au milieu du mot. À la fin, la dernière lettre se lit sans voyelle sans qu''on le note, et un mot ne peut pas commencer sans voyelle.', 1, '{"id": "ar.l18.e02", "unitIds": ["ar.g18.sukun"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Où écrit-on surtout le soukoun ?", "promptLanguage": "fr", "answer": "au milieu du mot", "acceptedAnswers": ["au milieu du mot"], "explanation": "Au milieu du mot. À la fin, la dernière lettre se lit sans voyelle sans qu''on le note, et un mot ne peut pas commencer sans voyelle.", "tip": "Soukoun : au milieu, rarement ailleurs.", "extraExample": {"text": "كَلْب", "translation": "chien : soukoun sur ل"}, "options": ["à la fin du mot", "au milieu du mot", "au début du mot"], "errorPatterns": [{"equals": "à la fin du mot", "category": "spelling", "feedback": "À la fin, la dernière lettre reste le plus souvent nue : on ne note presque jamais de soukoun."}, {"equals": "au début du mot", "category": "spelling", "feedback": "Un mot ne commence jamais sans voyelle : le soukoun ne s''écrit pas au début."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e03', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.nagm']::text[], 'mcq', 'lesson', 'نَجْم', array['étoile']::text[], 'ن + a, ج sans voyelle, م : l''étoile. Le soukoun sur ج dit qu''on enchaîne g et m sans voyelle.', 2, '{"id": "ar.l18.e03", "unitIds": ["ar.g18.sukun", "ar.v.nagm"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "نَجْم", "promptLanguage": "ar", "answer": "étoile", "acceptedAnswers": ["étoile"], "explanation": "ن + a, ج sans voyelle, م : l''étoile. Le soukoun sur ج dit qu''on enchaîne g et m sans voyelle.", "tip": "Une seule voyelle : le a de ن.", "extraExample": {"text": "نَجْم كِبِير.", "translation": "Une grande étoile."}, "options": ["chien", "mer", "soleil", "étoile"], "errorPatterns": [{"equals": "soleil", "category": "word_confusion", "feedback": "Le soleil est شَمْس : il commence par ش, pas par ن."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e04', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.kalb']::text[], 'mcq', 'lesson', 'كَلْب', array['chien']::text[], 'ك + a, ل sans voyelle, ب : le chien. Le ب final n''a aucun signe.', 2, '{"id": "ar.l18.e04", "unitIds": ["ar.g18.sukun", "ar.v.kalb"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "كَلْب", "promptLanguage": "ar", "answer": "chien", "acceptedAnswers": ["chien"], "explanation": "ك + a, ل sans voyelle, ب : le chien. Le ب final n''a aucun signe.", "tip": "Dernière lettre : pas de signe.", "extraExample": {"text": "عِنْدِي كَلْب.", "translation": "J''ai un chien."}, "options": ["étoile", "chien", "tour", "mer"], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e05', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.sawm']::text[], 'mcq', 'lesson', 'صَوْم', array['jeûne']::text[], 'ص + a, و avec soukoun : ـَوْ se fond en un ô. Puis م. C''est le jeûne, comme dans le Grand Carême.', 2, '{"id": "ar.l18.e05", "unitIds": ["ar.g18.sukun", "ar.v.sawm"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "صَوْم", "promptLanguage": "ar", "answer": "jeûne", "acceptedAnswers": ["jeûne"], "explanation": "ص + a, و avec soukoun : ـَوْ se fond en un ô. Puis م. C''est le jeûne, comme dans le Grand Carême.", "tip": "ـَوْ : un seul son, ô.", "extraExample": {"text": "الصَّوْم الْكَبِير.", "translation": "Le Grand Carême."}, "options": ["invité", "jeûne", "gloire", "couleur"], "errorPatterns": [{"equals": "couleur", "category": "word_confusion", "feedback": "La couleur est لَوْن : même ـَوْ, mais la première lettre est ل."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e06', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.magd']::text[], 'mcq', 'lesson', 'مَجْد', array['gloire']::text[], 'م + a, ج sans voyelle, د : la gloire, mot de la liturgie (الْمَجْد لِلَّه).', 2, '{"id": "ar.l18.e06", "unitIds": ["ar.g18.sukun", "ar.v.magd"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "مَجْد", "promptLanguage": "ar", "answer": "gloire", "acceptedAnswers": ["gloire"], "explanation": "م + a, ج sans voyelle, د : la gloire, mot de la liturgie (الْمَجْد لِلَّه).", "tip": "Même schéma que نَجْم : a, puis soukoun.", "extraExample": {"text": "الْمَجْد لِلَّه.", "translation": "Gloire à Dieu."}, "options": ["jeûne", "étoile", "gloire", "mer"], "errorPatterns": [{"equals": "étoile", "category": "word_confusion", "feedback": "L''étoile est نَجْم : elle commence par ن, pas par م."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e07', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.ain_eye']::text[], 'mcq', 'lesson', 'Comment se lit ـَيْ dans عَيْن en égyptien ?', array['é long, comme dans thé']::text[], 'Une fatha suivie de ي avec soukoun forme un seul son : en égyptien, un é long, comme dans thé.', 3, '{"id": "ar.l18.e07", "unitIds": ["ar.g18.sukun", "ar.v.ain_eye"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Comment se lit ـَيْ dans عَيْن en égyptien ?", "promptLanguage": "fr", "answer": "é long, comme dans thé", "acceptedAnswers": ["é long, comme dans thé"], "explanation": "Une fatha suivie de ي avec soukoun forme un seul son : en égyptien, un é long, comme dans thé.", "tip": "Tu dis déjà عَيْن avec ce é.", "extraExample": {"text": "ضَيْف", "translation": "invité"}, "options": ["a bref, comme dans table", "ou long, comme dans loup", "é long, comme dans thé"], "errorPatterns": [{"equals": "ou long, comme dans loup", "category": "spelling", "feedback": "Le ou vient de la damma ; ici il y a une fatha et ي."}, {"equals": "a bref, comme dans table", "category": "spelling", "feedback": "Le ي avec soukoun change le son : ce n''est plus un simple a."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e08', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.lawn']::text[], 'mcq', 'lesson', 'Comment se lit ـَوْ dans لَوْن en égyptien ?', array['ô, comme dans rôle']::text[], 'Une fatha suivie de و avec soukoun donne un seul son : un ô en égyptien, comme dans rôle.', 3, '{"id": "ar.l18.e08", "unitIds": ["ar.g18.sukun", "ar.v.lawn"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Comment se lit ـَوْ dans لَوْن en égyptien ?", "promptLanguage": "fr", "answer": "ô, comme dans rôle", "acceptedAnswers": ["ô, comme dans rôle"], "explanation": "Une fatha suivie de و avec soukoun donne un seul son : un ô en égyptien, comme dans rôle.", "tip": "ـَوْ : ô ; ـَيْ : é.", "extraExample": {"text": "صَوْم", "translation": "jeûne"}, "options": ["é long, comme dans thé", "ô, comme dans rôle", "ou, comme dans loup"], "errorPatterns": [{"equals": "é long, comme dans thé", "category": "spelling", "feedback": "Le é long vient de ـَيْ, avec ي ; ici c''est و."}, {"equals": "ou, comme dans loup", "category": "spelling", "feedback": "Le ou vient de la damma ; ici il y a une fatha et و avec soukoun."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e09', 'ar', 'ar.l18', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.g18.sukun']::text[], 'mcq', 'lesson', 'Laquelle de ces syllabes porte une kasra ?', array['بِ']::text[], 'La kasra est le trait sous la lettre. Le soukoun est un rond, la fatha un trait au-dessus.', 1, '{"id": "ar.l18.e09", "unitIds": ["ar.g17.short_vowels", "ar.g18.sukun"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne syllabe.", "prompt": "Laquelle de ces syllabes porte une kasra ?", "promptLanguage": "fr", "answer": "بِ", "acceptedAnswers": ["بِ"], "explanation": "La kasra est le trait sous la lettre. Le soukoun est un rond, la fatha un trait au-dessus.", "tip": "Kasra : sous la lettre, son i.", "extraExample": {"text": "تِ", "translation": "t + i"}, "options": ["بُ", "بَ", "بِ"], "errorPatterns": [{"equals": "بَ", "category": "spelling", "feedback": "Le trait de بَ est au-dessus : c''est une fatha."}, {"equals": "بُ", "category": "spelling", "feedback": "Le petit و bouclé de بُ est une damma."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e10', 'ar', 'ar.l18', 'ar.v.qamar', array['ar.v.qamar','ar.g18.sukun']::text[], 'mcq', 'lesson', 'قَمَر', array['lune']::text[], 'ق + a, م + a, ر : deux fathas, aucun soukoun. C''est la lune ; le soleil est شَمْس, avec un soukoun.', 1, '{"id": "ar.l18.e10", "unitIds": ["ar.v.qamar", "ar.g18.sukun"], "type": "mcq", "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "قَمَر", "promptLanguage": "ar", "answer": "lune", "acceptedAnswers": ["lune"], "explanation": "ق + a, م + a, ر : deux fathas, aucun soukoun. C''est la lune ; le soleil est شَمْس, avec un soukoun.", "tip": "Compte les soukouns : aucun ici.", "extraExample": {"text": "الْقَمَر طَالِع.", "translation": "La lune est levée."}, "options": ["soleil", "mer", "lune", "étoile"], "errorPatterns": [{"equals": "soleil", "category": "word_confusion", "feedback": "Le soleil est شَمْس, avec un soukoun sur م. Ici : قَمَر, deux fathas."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e11', 'ar', 'ar.l18', 'ar.v.bayt', array['ar.v.bayt','ar.g18.sukun']::text[], 'mcq', 'lesson', 'بَيْت', array['maison']::text[], 'ب + a, ي avec soukoun : ـَيْ forme un seul son, un é long. Puis ت. C''est la maison, que tu lisais بيت.', 2, '{"id": "ar.l18.e11", "unitIds": ["ar.v.bayt", "ar.g18.sukun"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "بَيْت", "promptLanguage": "ar", "answer": "maison", "acceptedAnswers": ["maison"], "explanation": "ب + a, ي avec soukoun : ـَيْ forme un seul son, un é long. Puis ت. C''est la maison, que tu lisais بيت.", "tip": "ـَيْ : le é de ton mot de tous les jours.", "extraExample": {"text": "بَيْتِي", "translation": "ma maison"}, "options": ["maison", "porte", "fille", "café"], "errorPatterns": [{"equals": "fille", "category": "word_confusion", "feedback": "La fille est بِنْت, avec ن et un soukoun."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e12', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.burj']::text[], 'fill_blank', 'lesson', 'بُرْ___', array['ج']::text[], 'Le soukoun est sur ر, au milieu du mot. La dernière lettre ج reste nue : en égyptien, le mot finit sans voyelle.', 2, '{"id": "ar.l18.e12", "unitIds": ["ar.g18.sukun", "ar.v.burj"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne lettre.", "prompt": "بُرْ___", "promptLanguage": "ar", "answer": "ج", "acceptedAnswers": ["ج"], "explanation": "Le soukoun est sur ر, au milieu du mot. La dernière lettre ج reste nue : en égyptien, le mot finit sans voyelle.", "tip": "Fin de mot : lettre nue.", "extraExample": {"text": "بُرْج الْكَنِيسَة.", "translation": "Le clocher de l''église."}, "options": ["جَ", "ج", "جُ"], "errorPatterns": [{"equals": "جَ", "category": "spelling", "feedback": "Pas de voyelle à la fin du mot."}, {"equals": "جُ", "category": "spelling", "feedback": "Pas de voyelle à la fin du mot."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e13', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.bahr']::text[], 'fill_blank', 'lesson', 'بَ___ر', array['حْ']::text[], 'Mer, بَحْر : بَ (b + a), حْ (h appuyé, sans voyelle), ر. Ton oreille entend une seule voyelle, le a.', 3, '{"id": "ar.l18.e13", "unitIds": ["ar.g18.sukun", "ar.v.bahr"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne syllabe.", "prompt": "بَ___ر", "promptLanguage": "ar", "answer": "حْ", "acceptedAnswers": ["حْ"], "explanation": "Mer, بَحْر : بَ (b + a), حْ (h appuyé, sans voyelle), ر. Ton oreille entend une seule voyelle, le a.", "tip": "Une voyelle seulement : le ح est collé.", "extraExample": {"text": "رُحْنَا الْبَحْر.", "translation": "Nous sommes allés à la mer."}, "options": ["حْ", "حَ", "حِ"], "errorPatterns": [{"equals": "حَ", "category": "spelling", "feedback": "Avec une fatha, il y aurait deux a : mais le mot n''en a qu''un."}, {"equals": "حِ", "category": "spelling", "feedback": "Avec une kasra, on entendrait un i : le mot n''en a pas."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e14', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.lawn']::text[], 'fill_blank', 'lesson', 'لَ___ن  (couleur)', array['وْ']::text[], 'لَوْن : لَ, puis و avec soukoun (ـَوْ se fond en ô), puis ن.', 3, '{"id": "ar.l18.e14", "unitIds": ["ar.g18.sukun", "ar.v.lawn"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne syllabe.", "prompt": "لَ___ن  (couleur)", "promptLanguage": "ar", "answer": "وْ", "acceptedAnswers": ["وْ"], "explanation": "لَوْن : لَ, puis و avec soukoun (ـَوْ se fond en ô), puis ن.", "tip": "ـَوْ : fatha, puis و avec soukoun.", "extraExample": {"text": "لَوْن جَمِيل.", "translation": "Une belle couleur."}, "options": ["وَ", "وْ", "وُ"], "errorPatterns": [{"equals": "وَ", "category": "spelling", "feedback": "Avec une fatha sur و, il n''y aurait plus de ô : on lirait une syllabe en plus."}, {"equals": "وُ", "category": "spelling", "feedback": "Avec une damma, on lirait ou, pas ô."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e15', 'ar', 'ar.l18', 'ar.v.bint', array['ar.v.bint','ar.g18.sukun']::text[], 'fill_blank', 'lesson', 'بِ___ت', array['نْ']::text[], 'بِنْت : بِ (b + i), نْ (n, sans voyelle), ت. Tu dis ce mot avec un seul i.', 2, '{"id": "ar.l18.e15", "unitIds": ["ar.v.bint", "ar.g18.sukun"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « fille ».", "prompt": "بِ___ت", "promptLanguage": "ar", "answer": "نْ", "acceptedAnswers": ["نْ"], "explanation": "بِنْت : بِ (b + i), نْ (n, sans voyelle), ت. Tu dis ce mot avec un seul i.", "tip": "Après le i, la lettre suivante est nue.", "extraExample": {"text": "بِنْتِي", "translation": "ma fille"}, "options": ["نُ", "نَ", "نْ"], "errorPatterns": [{"equals": "نَ", "category": "spelling", "feedback": "Un a de plus ? Ce n''est pas ce que tu dis : le ن s''enchaîne directement."}, {"equals": "نُ", "category": "spelling", "feedback": "Un ou de plus ? Le mot n''a qu''une voyelle : le i."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e16', 'ar', 'ar.l18', 'ar.v.eish', array['ar.v.eish','ar.g18.sukun']::text[], 'fill_blank', 'lesson', 'عَ___ش', array['يْ']::text[], 'عَيْش : عَ, puis ي avec soukoun (ـَيْ, un é long), puis ش. C''est le mot que tu dis tous les jours.', 2, '{"id": "ar.l18.e16", "unitIds": ["ar.v.eish", "ar.g18.sukun"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « pain ».", "prompt": "عَ___ش", "promptLanguage": "ar", "answer": "يْ", "acceptedAnswers": ["يْ"], "explanation": "عَيْش : عَ, puis ي avec soukoun (ـَيْ, un é long), puis ش. C''est le mot que tu dis tous les jours.", "tip": "Dis-le tout haut : tu entends un é long.", "extraExample": {"text": "عَيْش بَلَدِي", "translation": "pain traditionnel"}, "options": ["يِ", "يْ", "يَ"], "errorPatterns": [{"equals": "يَ", "category": "spelling", "feedback": "Avec une fatha sur ي, on lirait deux syllabes : toi, tu dis une seule syllabe."}, {"equals": "يِ", "category": "spelling", "feedback": "Avec une kasra, on lirait un i en plus : le mot n''en a pas."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e17', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.g17.short_vowels']::text[], 'match', 'lesson', 'Les quatre signes', '{}'::text[], 'Fatha : a. Kasra : i. Damma : ou. Soukoun : aucune voyelle.', 1, '{"id": "ar.l18.e17", "unitIds": ["ar.g18.sukun", "ar.g17.short_vowels"], "type": "match", "difficulty": 1, "instruction": "Associe chaque signe à ce qu''il donne.", "prompt": "Les quatre signes", "promptLanguage": "fr", "answer": "ـَ = a ; ـِ = i ; ـُ = ou ; ـْ = aucune voyelle", "acceptedAnswers": [], "explanation": "Fatha : a. Kasra : i. Damma : ou. Soukoun : aucune voyelle.", "pairs": [{"left": "ـَ", "right": "a"}, {"left": "ـِ", "right": "i"}, {"left": "ـُ", "right": "ou"}, {"left": "ـْ", "right": "aucune voyelle"}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e18', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.burj','ar.v.nagm','ar.v.kalb','ar.v.bahr']::text[], 'match', 'lesson', 'Mots avec soukoun', '{}'::text[], 'Chaque mot a une voyelle, un soukoun, puis une dernière lettre nue.', 2, '{"id": "ar.l18.e18", "unitIds": ["ar.g18.sukun", "ar.v.burj", "ar.v.nagm", "ar.v.kalb", "ar.v.bahr"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots avec soukoun", "promptLanguage": "fr", "answer": "بُرْج = tour ; نَجْم = étoile ; كَلْب = chien ; بَحْر = mer", "acceptedAnswers": [], "explanation": "Chaque mot a une voyelle, un soukoun, puis une dernière lettre nue.", "pairs": [{"left": "بُرْج", "right": "tour"}, {"left": "نَجْم", "right": "étoile"}, {"left": "كَلْب", "right": "chien"}, {"left": "بَحْر", "right": "mer"}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e19', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.ain_eye','ar.v.dayf','ar.v.lawn','ar.v.shams']::text[], 'match', 'lesson', 'Mots avec ـَيْ, ـَوْ et soukoun', '{}'::text[], 'عَيْن et ضَيْف : ـَيْ, un é long. لَوْن : ـَوْ, un ô. شَمْس : fatha puis م après un soukoun.', 3, '{"id": "ar.l18.e19", "unitIds": ["ar.g18.sukun", "ar.v.ain_eye", "ar.v.dayf", "ar.v.lawn", "ar.v.shams"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots avec ـَيْ, ـَوْ et soukoun", "promptLanguage": "fr", "answer": "عَيْن = œil ; ضَيْف = invité ; لَوْن = couleur ; شَمْس = soleil", "acceptedAnswers": [], "explanation": "عَيْن et ضَيْف : ـَيْ, un é long. لَوْن : ـَوْ, un ô. شَمْس : fatha puis م après un soukoun.", "pairs": [{"left": "عَيْن", "right": "œil"}, {"left": "ضَيْف", "right": "invité"}, {"left": "لَوْن", "right": "couleur"}, {"left": "شَمْس", "right": "soleil"}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e20', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.shams']::text[], 'translation', 'lesson', 'شَمْس', array['soleil','le soleil']::text[], 'ش + a, م sans voyelle, س : le soleil.', 2, '{"id": "ar.l18.e20", "unitIds": ["ar.g18.sukun", "ar.v.shams"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "شَمْس", "promptLanguage": "ar", "answer": "soleil", "acceptedAnswers": ["soleil", "le soleil"], "explanation": "ش + a, م sans voyelle, س : le soleil.", "tip": "Une voyelle, un soukoun, une lettre nue.", "extraExample": {"text": "الشَّمْس حَامْيَة.", "translation": "Le soleil est brûlant."}, "errorPatterns": [{"equals": "lune", "category": "word_confusion", "feedback": "La lune est قَمَر, sans soukoun."}, {"equals": "étoile", "category": "word_confusion", "feedback": "L''étoile est نَجْم : ici tu lis ش + م + س."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e21', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun','ar.v.burj']::text[], 'free_answer', 'lesson', 'Que veut dire بُرْج ?', array['tour','une tour','la tour','clocher','un clocher','le clocher']::text[], 'بُرْج : بُ (b + ou), ر sans voyelle, ج. C''est une tour, et le clocher d''une église.', 3, '{"id": "ar.l18.e21", "unitIds": ["ar.g18.sukun", "ar.v.burj"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire بُرْج ?", "promptLanguage": "fr", "answer": "tour", "acceptedAnswers": ["tour", "une tour", "la tour", "clocher", "un clocher", "le clocher"], "explanation": "بُرْج : بُ (b + ou), ر sans voyelle, ج. C''est une tour, et le clocher d''une église.", "tip": "Damma, puis soukoun.", "extraExample": {"text": "بُرْج الْقَاهِرَة.", "translation": "La tour du Caire."}, "errorPatterns": [{"equals": "chien", "category": "word_confusion", "feedback": "Le chien est كَلْب : ici tu lis ب + ر + ج."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e22', 'ar', 'ar.l18', 'ar.g18.sukun', array['ar.g18.sukun']::text[], 'free_answer', 'lesson', 'Comment s''appelle le petit rond posé sur une lettre qui n''a pas de voyelle ?', array['soukoun','le soukoun','sukun','le sukun','soukoune','sokoun']::text[], 'C''est le soukoun (سُكُون, « silence ») : il dit qu''il n''y a aucune voyelle sur la lettre.', 2, '{"id": "ar.l18.e22", "unitIds": ["ar.g18.sukun"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Comment s''appelle le petit rond posé sur une lettre qui n''a pas de voyelle ?", "promptLanguage": "fr", "answer": "soukoun", "acceptedAnswers": ["soukoun", "le soukoun", "sukun", "le sukun", "soukoune", "sokoun"], "explanation": "C''est le soukoun (سُكُون, « silence ») : il dit qu''il n''y a aucune voyelle sur la lettre.", "tip": "Rond = rien.", "extraExample": {"text": "نْ", "translation": "n sans voyelle"}, "errorPatterns": [{"equals": "fatha", "category": "word_confusion", "feedback": "La fatha est un trait penché, qui donne le son a."}, {"equals": "chadda", "category": "word_confusion", "feedback": "La chadda double la lettre : tu la verras bientôt."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e01', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels']::text[], 'match', 'lesson', 'Voyelles et lettres sœurs', '{}'::text[], 'Fatha + ا : a long. Damma + و : ou long. Kasra + ي : i long.', 1, '{"id": "ar.l19.e01", "unitIds": ["ar.g19.long_vowels"], "type": "match", "difficulty": 1, "instruction": "Associe chaque voyelle à sa lettre sœur.", "prompt": "Voyelles et lettres sœurs", "promptLanguage": "fr", "answer": "ـَ = ا ; ـُ = و ; ـِ = ي", "acceptedAnswers": [], "explanation": "Fatha + ا : a long. Damma + و : ou long. Kasra + ي : i long.", "pairs": [{"left": "ـَ", "right": "ا"}, {"left": "ـُ", "right": "و"}, {"left": "ـِ", "right": "ي"}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e02', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels']::text[], 'free_answer', 'lesson', 'Une voyelle longue dure combien de fois plus longtemps qu''une voyelle brève ?', array['deux fois','2 fois','deux fois plus','le double','double','x2']::text[], 'La lettre sœur allonge la voyelle : elle dure deux fois plus longtemps.', 2, '{"id": "ar.l19.e02", "unitIds": ["ar.g19.long_vowels"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Une voyelle longue dure combien de fois plus longtemps qu''une voyelle brève ?", "promptLanguage": "fr", "answer": "deux fois", "acceptedAnswers": ["deux fois", "2 fois", "deux fois plus", "le double", "double", "x2"], "explanation": "La lettre sœur allonge la voyelle : elle dure deux fois plus longtemps.", "tip": "Brève = 1, longue = 2.", "extraExample": {"text": "رُوح", "translation": "ou long"}, "pool": "lesson", "lessonId": "ar.l19", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e03', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.ruh']::text[], 'mcq', 'lesson', 'رُوح', array['esprit']::text[], 'ر + damma, puis و sans signe : un ou long, puis ح. C''est l''esprit, comme dans الرُّوح الْقُدُس.', 2, '{"id": "ar.l19.e03", "unitIds": ["ar.g19.long_vowels", "ar.v.ruh"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "رُوح", "promptLanguage": "ar", "answer": "esprit", "acceptedAnswers": ["esprit"], "explanation": "ر + damma, puis و sans signe : un ou long, puis ح. C''est l''esprit, comme dans الرُّوح الْقُدُس.", "tip": "Damma + و sans signe : ou long.", "extraExample": {"text": "الرُّوح الْقُدُس.", "translation": "Le Saint-Esprit."}, "options": ["ami", "esprit", "feu", "route"], "errorPatterns": [{"equals": "route", "category": "word_confusion", "feedback": "La route est طَرِيق : elle commence par ط."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e04', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.tariq']::text[], 'mcq', 'lesson', 'طَرِيق', array['chemin']::text[], 'ط + a, ر + i long (kasra + ي), ق : le chemin, la route.', 2, '{"id": "ar.l19.e04", "unitIds": ["ar.g19.long_vowels", "ar.v.tariq"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "طَرِيق", "promptLanguage": "ar", "answer": "chemin", "acceptedAnswers": ["chemin"], "explanation": "ط + a, ر + i long (kasra + ي), ق : le chemin, la route.", "tip": "Kasra + ي : un i tenu.", "extraExample": {"text": "الطَّرِيق طَوِيل.", "translation": "La route est longue."}, "options": ["esprit", "chemin", "ami", "voisin"], "errorPatterns": [{"equals": "ami", "category": "word_confusion", "feedback": "L''ami est صَدِيق : même ـِيق final, mais le début est ص."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e05', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.kahin']::text[], 'mcq', 'lesson', 'كَاهِن', array['prêtre']::text[], 'ك + a long (fatha + ا), ه + i, ن : le prêtre de l''église.', 2, '{"id": "ar.l19.e05", "unitIds": ["ar.g19.long_vowels", "ar.v.kahin"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "كَاهِن", "promptLanguage": "ar", "answer": "prêtre", "acceptedAnswers": ["prêtre"], "explanation": "ك + a long (fatha + ا), ه + i, ن : le prêtre de l''église.", "tip": "ـَا au début, puis une kasra.", "extraExample": {"text": "كَاهِن الْكَنِيسَة.", "translation": "Le prêtre de l''église."}, "options": ["prêtre", "docteur", "moine", "élève"], "errorPatterns": [{"equals": "moine", "category": "word_confusion", "feedback": "Le moine est رَاهِب : la première lettre est ر, pas ك."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e06', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.rahib']::text[], 'mcq', 'lesson', 'رَاهِب', array['moine']::text[], 'ر + a long (fatha + ا), ه + i, ب : le moine, qui vit au monastère.', 2, '{"id": "ar.l19.e06", "unitIds": ["ar.g19.long_vowels", "ar.v.rahib"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "رَاهِب", "promptLanguage": "ar", "answer": "moine", "acceptedAnswers": ["moine"], "explanation": "ر + a long (fatha + ا), ه + i, ب : le moine, qui vit au monastère.", "tip": "Même schéma que كَاهِن, première lettre différente.", "extraExample": {"text": "رَاهِب فِي الدَّيْر.", "translation": "Un moine dans le monastère."}, "options": ["prêtre", "voisin", "moine", "ami"], "errorPatterns": [{"equals": "prêtre", "category": "word_confusion", "feedback": "Le prêtre est كَاهِن : il commence par ك. Ici tu lis ر."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e07', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.tilmiz']::text[], 'mcq', 'lesson', 'تِلْمِيذ', array['disciple']::text[], 'ت + i, ل sans voyelle (soukoun), م + i long (kasra + ي), ذ : un élève, un disciple.', 3, '{"id": "ar.l19.e07", "unitIds": ["ar.g19.long_vowels", "ar.v.tilmiz"], "type": "mcq", "difficulty": 3, "instruction": "Lis le mot et choisis son sens.", "prompt": "تِلْمِيذ", "promptLanguage": "ar", "answer": "disciple", "acceptedAnswers": ["disciple"], "explanation": "ت + i, ل sans voyelle (soukoun), م + i long (kasra + ي), ذ : un élève, un disciple.", "tip": "Un soukoun, puis ـِي.", "extraExample": {"text": "تَلَامِيذ الْمَسِيح.", "translation": "Les disciples du Christ."}, "options": ["docteur", "disciple", "chemin", "moine"], "errorPatterns": [{"equals": "moine", "category": "word_confusion", "feedback": "Le moine est رَاهِب. Ici tu lis ت + ل + م + ي + ذ."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e08', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.duktur']::text[], 'mcq', 'lesson', 'دُكْتُور', array['docteur']::text[], 'د + ou, ك sans voyelle, ت + ou long (damma + و), ر : le docteur.', 3, '{"id": "ar.l19.e08", "unitIds": ["ar.g19.long_vowels", "ar.v.duktur"], "type": "mcq", "difficulty": 3, "instruction": "Lis le mot et choisis son sens.", "prompt": "دُكْتُور", "promptLanguage": "ar", "answer": "docteur", "acceptedAnswers": ["docteur"], "explanation": "د + ou, ك sans voyelle, ت + ou long (damma + و), ر : le docteur.", "tip": "Deux dammas, dont la seconde est allongée par و.", "extraExample": {"text": "الدُّكْتُور جَاي.", "translation": "Le docteur arrive."}, "options": ["élève", "docteur", "prêtre", "voisin"], "errorPatterns": [{"equals": "prêtre", "category": "word_confusion", "feedback": "Le prêtre est كَاهِن. Ici tu lis د + ك + ت + و + ر."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e09', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.kibir']::text[], 'mcq', 'lesson', 'Combien de voyelles longues y a-t-il dans كِبِير ?', array['une']::text[], 'كِبِير : كِ est brève, بِ est suivie de ي (i long) : une seule voyelle longue, car il n''y a qu''une seule lettre ي.', 3, '{"id": "ar.l19.e09", "unitIds": ["ar.g19.long_vowels", "ar.v.kibir"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Combien de voyelles longues y a-t-il dans كِبِير ?", "promptLanguage": "fr", "answer": "une", "acceptedAnswers": ["une"], "explanation": "كِبِير : كِ est brève, بِ est suivie de ي (i long) : une seule voyelle longue, car il n''y a qu''une seule lettre ي.", "tip": "Compte les lettres ا و ي nues, pas les kasras.", "extraExample": {"text": "بَيْت كِبِير.", "translation": "Une grande maison."}, "options": ["une", "deux", "trois"], "errorPatterns": [{"equals": "deux", "category": "spelling", "feedback": "Il y a deux kasras, mais un seul ي : une seule voyelle longue."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e10', 'ar', 'ar.l19', 'ar.v.sawm', array['ar.v.sawm','ar.g19.long_vowels']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit avec un ô (ـَوْ) ?', array['صَوْم']::text[], 'صَوْم : fatha + و avec soukoun, donc ô. رُوح a un و nu après une damma : ou long. كَاهِن n''a pas de و.', 2, '{"id": "ar.l19.e10", "unitIds": ["ar.v.sawm", "ar.g19.long_vowels"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit avec un ô (ـَوْ) ?", "promptLanguage": "fr", "answer": "صَوْم", "acceptedAnswers": ["صَوْم"], "explanation": "صَوْم : fatha + و avec soukoun, donc ô. رُوح a un و nu après une damma : ou long. كَاهِن n''a pas de و.", "tip": "Un و avec soukoun : ô. Un و nu : ou long.", "extraExample": {"text": "لَوْن", "translation": "couleur"}, "options": ["كَاهِن", "رُوح", "صَوْم"], "errorPatterns": [{"equals": "رُوح", "category": "spelling", "feedback": "Dans رُوح, le و est nu, après une damma : c''est un ou long, pas un ô."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e11', 'ar', 'ar.l19', 'ar.v.salib', array['ar.v.salib','ar.g19.long_vowels']::text[], 'mcq', 'lesson', 'صَلِيب', array['croix']::text[], 'ص + a, ل + i long (kasra + ي), ب : la croix, mot que tu lisais صليب.', 1, '{"id": "ar.l19.e11", "unitIds": ["ar.v.salib", "ar.g19.long_vowels"], "type": "mcq", "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "صَلِيب", "promptLanguage": "ar", "answer": "croix", "acceptedAnswers": ["croix"], "explanation": "ص + a, ل + i long (kasra + ي), ب : la croix, mot que tu lisais صليب.", "tip": "Dans صَلِيب, le ي allonge la kasra de ل.", "extraExample": {"text": "صَلِيب الْمَسِيح", "translation": "la croix du Christ"}, "options": ["esprit", "croix", "pain", "chemin"], "errorPatterns": [{"equals": "chemin", "category": "word_confusion", "feedback": "Le chemin est طَرِيق, un autre mot : ici tu lis ص + ل + ي + ب."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e12', 'ar', 'ar.l19', 'ar.v.malak', array['ar.v.malak','ar.g19.long_vowels']::text[], 'mcq', 'lesson', 'مَلَاك', array['ange']::text[], 'م + a, ل + a long (fatha + ا), ك : un ange, que tu lisais ملاك.', 1, '{"id": "ar.l19.e12", "unitIds": ["ar.v.malak", "ar.g19.long_vowels"], "type": "mcq", "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "مَلَاك", "promptLanguage": "ar", "answer": "ange", "acceptedAnswers": ["ange"], "explanation": "م + a, ل + a long (fatha + ا), ك : un ange, que tu lisais ملاك.", "tip": "Fatha + ا : a long.", "extraExample": {"text": "مَلَاك الرَّبّ", "translation": "l''ange du Seigneur"}, "options": ["prêtre", "ange", "voisin", "moine"], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e13', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.gar']::text[], 'fill_blank', 'lesson', 'جَ___ر', array['ا']::text[], 'Le voisin, جَار : ج + fatha, puis ا allonge en a long, puis ر.', 2, '{"id": "ar.l19.e13", "unitIds": ["ar.g19.long_vowels", "ar.v.gar"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la lettre qui allonge.", "prompt": "جَ___ر", "promptLanguage": "ar", "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "Le voisin, جَار : ج + fatha, puis ا allonge en a long, puis ر.", "tip": "Fatha → ا.", "extraExample": {"text": "جَارِي طَيِّب.", "translation": "Mon voisin est gentil."}, "options": ["ا", "و", "ي"], "errorPatterns": [{"equals": "و", "category": "spelling", "feedback": "Le و allonge une damma, pas une fatha."}, {"equals": "ي", "category": "spelling", "feedback": "Le ي allonge une kasra, pas une fatha."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e14', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.sadiq']::text[], 'fill_blank', 'lesson', 'صَدِ___ق', array['ي']::text[], 'L''ami, صَدِيق : la kasra sous د est allongée par ي : i long.', 2, '{"id": "ar.l19.e14", "unitIds": ["ar.g19.long_vowels", "ar.v.sadiq"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la lettre qui allonge.", "prompt": "صَدِ___ق", "promptLanguage": "ar", "answer": "ي", "acceptedAnswers": ["ي"], "explanation": "L''ami, صَدِيق : la kasra sous د est allongée par ي : i long.", "tip": "Kasra → ي.", "extraExample": {"text": "صَدِيق قَدِيم.", "translation": "Un vieil ami."}, "options": ["ا", "ي", "و"], "errorPatterns": [{"equals": "ا", "category": "spelling", "feedback": "Le ا allonge une fatha, pas une kasra."}, {"equals": "و", "category": "spelling", "feedback": "Le و allonge une damma, pas une kasra."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e15', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.duktur']::text[], 'fill_blank', 'lesson', 'دُكْتُ___ر', array['و']::text[], 'Le docteur, دُكْتُور : la damma sur ت est allongée par و.', 3, '{"id": "ar.l19.e15", "unitIds": ["ar.g19.long_vowels", "ar.v.duktur"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la lettre qui allonge.", "prompt": "دُكْتُ___ر", "promptLanguage": "ar", "answer": "و", "acceptedAnswers": ["و"], "explanation": "Le docteur, دُكْتُور : la damma sur ت est allongée par و.", "tip": "Damma → و.", "extraExample": {"text": "الدُّكْتُور جَاي.", "translation": "Le docteur arrive."}, "options": ["ا", "ي", "و"], "errorPatterns": [{"equals": "ا", "category": "spelling", "feedback": "Le ا allonge une fatha, pas une damma."}, {"equals": "ي", "category": "spelling", "feedback": "Le ي allonge une kasra, pas une damma."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e16', 'ar', 'ar.l19', 'ar.v.kitab', array['ar.v.kitab','ar.g19.long_vowels']::text[], 'fill_blank', 'lesson', 'كِتَ___ب', array['ا']::text[], 'كِتَاب : la fatha sur ت est suivie de ا : a long. Tu dis ce mot avec un a long.', 2, '{"id": "ar.l19.e16", "unitIds": ["ar.v.kitab", "ar.g19.long_vowels"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « livre ».", "prompt": "كِتَ___ب", "promptLanguage": "ar", "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "كِتَاب : la fatha sur ت est suivie de ا : a long. Tu dis ce mot avec un a long.", "tip": "Dis-le tout haut : tu entends un a tenu.", "extraExample": {"text": "كِتَاب الْكَنِيسَة", "translation": "le livre de l''église"}, "options": ["ا", "ي", "و"], "errorPatterns": [{"equals": "ي", "category": "spelling", "feedback": "Un i long s''entendrait après une kasra, pas après la fatha de ت."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
