insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e21', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.fil']::text[], 'translation', 'lesson', 'فِيل', array['éléphant','un éléphant','l''éléphant']::text[], 'ف + i long (kasra + ي), ل : l''éléphant.', 2, '{"id": "ar.l19.e21", "unitIds": ["ar.g19.long_vowels", "ar.v.fil"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "فِيل", "promptLanguage": "ar", "answer": "éléphant", "acceptedAnswers": ["éléphant", "un éléphant", "l''éléphant"], "explanation": "ف + i long (kasra + ي), ل : l''éléphant.", "tip": "Kasra → ي.", "extraExample": {"text": "فِيل كِبِير.", "translation": "Un grand éléphant."}, "pool": "lesson", "lessonId": "ar.l19", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e22', 'ar', 'ar.l19', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.v.sadiq']::text[], 'free_answer', 'lesson', 'Que veut dire صَدِيق ?', array['ami','un ami','l''ami','copain']::text[], 'صَدِيق : ص + a, د + i long (kasra + ي), ق. C''est un ami.', 3, '{"id": "ar.l19.e22", "unitIds": ["ar.g19.long_vowels", "ar.v.sadiq"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire صَدِيق ?", "promptLanguage": "fr", "answer": "ami", "acceptedAnswers": ["ami", "un ami", "l''ami", "copain"], "explanation": "صَدِيق : ص + a, د + i long (kasra + ي), ق. C''est un ami.", "tip": "Un seul i long.", "extraExample": {"text": "صَدِيق قَدِيم.", "translation": "Un vieil ami."}, "errorPatterns": [{"equals": "moine", "category": "word_confusion", "feedback": "Le moine est رَاهِب. Ici tu lis ص + د + ي + ق."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e01', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda']::text[], 'mcq', 'lesson', 'Quel signe double la lettre ?', array['la chadda']::text[], 'La chadda, petit w sur la lettre, la fait dire deux fois. Le soukoun, petit rond, dit qu''il n''y a aucune voyelle.', 1, '{"id": "ar.l20.e01", "unitIds": ["ar.g20.shadda"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Quel signe double la lettre ?", "promptLanguage": "fr", "answer": "la chadda", "acceptedAnswers": ["la chadda"], "explanation": "La chadda, petit w sur la lettre, la fait dire deux fois. Le soukoun, petit rond, dit qu''il n''y a aucune voyelle.", "tip": "Petit w = lettre doublée.", "extraExample": {"text": "بّ", "translation": "bb"}, "options": ["la kasra", "le soukoun", "la chadda"], "errorPatterns": [{"equals": "le soukoun", "category": "spelling", "feedback": "Le soukoun est un petit rond : aucune voyelle, pas de doublement."}, {"equals": "la kasra", "category": "spelling", "feedback": "La kasra est un trait sous la lettre : le son i."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e02', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.kubbaya']::text[], 'mcq', 'lesson', 'Combien de fois dit-on le ب dans كُبَّايَة ?', array['deux fois']::text[], 'Un seul ب est écrit, mais la chadda le fait dire deux fois.', 2, '{"id": "ar.l20.e02", "unitIds": ["ar.g20.shadda", "ar.v.kubbaya"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Combien de fois dit-on le ب dans كُبَّايَة ?", "promptLanguage": "fr", "answer": "deux fois", "acceptedAnswers": ["deux fois"], "explanation": "Un seul ب est écrit, mais la chadda le fait dire deux fois.", "tip": "Chadda : on lit la lettre deux fois.", "extraExample": {"text": "مَيَّة", "translation": "eau : deux y"}, "options": ["trois fois", "une fois", "deux fois"], "errorPatterns": [{"equals": "une fois", "category": "spelling", "feedback": "Il n''y a qu''un ب écrit, mais la chadda en fait deux dits."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e03', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.kubbaya']::text[], 'mcq', 'lesson', 'كُبَّايَة', array['verre']::text[], 'ك + ou, ب doublé, puis ب + a long, ي + a : كُبَّايَة, le verre. Le dernier ة est muet.', 2, '{"id": "ar.l20.e03", "unitIds": ["ar.g20.shadda", "ar.v.kubbaya"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "كُبَّايَة", "promptLanguage": "ar", "answer": "verre", "acceptedAnswers": ["verre"], "explanation": "ك + ou, ب doublé, puis ب + a long, ي + a : كُبَّايَة, le verre. Le dernier ة est muet.", "tip": "Cherche la chadda sur le ب.", "extraExample": {"text": "كُبَّايَة مَيَّة.", "translation": "Un verre d''eau."}, "options": ["eau", "boutique", "tasse", "verre"], "errorPatterns": [{"equals": "eau", "category": "word_confusion", "feedback": "L''eau est مَيَّة. Ici tu lis ك + ب + ا + ي + ة."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e04', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.rabb']::text[], 'mcq', 'lesson', 'رَبّ', array['Seigneur']::text[], 'ر + a, ب doublé en fin de mot : le Seigneur. C''est le mot de يَا رَبّ.', 2, '{"id": "ar.l20.e04", "unitIds": ["ar.g20.shadda", "ar.v.rabb"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "رَبّ", "promptLanguage": "ar", "answer": "Seigneur", "acceptedAnswers": ["Seigneur"], "explanation": "ر + a, ب doublé en fin de mot : le Seigneur. C''est le mot de يَا رَبّ.", "tip": "Chadda finale : le ب est long.", "extraExample": {"text": "الرَّبّ رَاعِيّ.", "translation": "Le Seigneur est mon berger."}, "options": ["amour", "Seigneur", "tout", "paradis"], "errorPatterns": [{"equals": "amour", "category": "word_confusion", "feedback": "L''amour est حُبّ : même fin, mais la voyelle est une damma et la première lettre est ح."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e05', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.janna']::text[], 'mcq', 'lesson', 'جَنَّة', array['paradis']::text[], 'ج + a, ن doublé, puis ة : le paradis, ou le jardin.', 2, '{"id": "ar.l20.e05", "unitIds": ["ar.g20.shadda", "ar.v.janna"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "جَنَّة", "promptLanguage": "ar", "answer": "paradis", "acceptedAnswers": ["paradis"], "explanation": "ج + a, ن doublé, puis ة : le paradis, ou le jardin.", "tip": "Le ن est écrit une fois, dit deux fois.", "extraExample": {"text": "جَنَّة عَدْن.", "translation": "Le jardin d''Éden."}, "options": ["paradis", "dame", "saint", "boutique"], "errorPatterns": [{"equals": "saint", "category": "word_confusion", "feedback": "Le saint est قِدِّيس."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e06', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.qiddis']::text[], 'mcq', 'lesson', 'قِدِّيس', array['saint']::text[], 'ق + i, د doublé, ي (i long), س : un saint. La kasra est sous la chadda.', 3, '{"id": "ar.l20.e06", "unitIds": ["ar.g20.shadda", "ar.v.qiddis"], "type": "mcq", "difficulty": 3, "instruction": "Lis le mot et choisis son sens.", "prompt": "قِدِّيس", "promptLanguage": "ar", "answer": "saint", "acceptedAnswers": ["saint"], "explanation": "ق + i, د doublé, ي (i long), س : un saint. La kasra est sous la chadda.", "tip": "Kasra + ي : i long, après le د doublé.", "extraExample": {"text": "الْقِدِّيس مَار جِرْجِس.", "translation": "Saint Georges."}, "options": ["maître", "monsieur", "paradis", "saint"], "errorPatterns": [{"equals": "monsieur", "category": "word_confusion", "feedback": "Monsieur, seigneur est سَيِّد : ici tu lis ق + د + ي + س."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e07', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.sayyid']::text[], 'mcq', 'lesson', 'سَيِّد', array['monsieur']::text[], 'س + a, ي doublé avec une kasra, puis د : monsieur, ou seigneur.', 3, '{"id": "ar.l20.e07", "unitIds": ["ar.g20.shadda", "ar.v.sayyid"], "type": "mcq", "difficulty": 3, "instruction": "Lis le mot et choisis son sens.", "prompt": "سَيِّد", "promptLanguage": "ar", "answer": "monsieur", "acceptedAnswers": ["monsieur"], "explanation": "س + a, ي doublé avec une kasra, puis د : monsieur, ou seigneur.", "tip": "Le ي est doublé et porte une kasra.", "extraExample": {"text": "السَّيِّد الْمَسِيح.", "translation": "Le Seigneur le Christ."}, "options": ["monsieur", "saint", "maître", "dame"], "errorPatterns": [{"equals": "dame", "category": "word_confusion", "feedback": "La dame est سِتّ."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e08', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.muallim']::text[], 'mcq', 'lesson', 'مُعَلِّم', array['maître']::text[], 'م + ou, ع + a, ل doublé avec une kasra, م : le maître, le patron.', 3, '{"id": "ar.l20.e08", "unitIds": ["ar.g20.shadda", "ar.v.muallim"], "type": "mcq", "difficulty": 3, "instruction": "Lis le mot et choisis son sens.", "prompt": "مُعَلِّم", "promptLanguage": "ar", "answer": "maître", "acceptedAnswers": ["maître"], "explanation": "م + ou, ع + a, ل doublé avec une kasra, م : le maître, le patron.", "tip": "Chadda sur ل, kasra dessous.", "extraExample": {"text": "يَا مُعَلِّم!", "translation": "Patron !"}, "options": ["maître", "ami", "boutique", "saint"], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e09', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda']::text[], 'mcq', 'lesson', 'Où se place la kasra quand la lettre porte une chadda ?', array['sous la lettre']::text[], 'La kasra reste sous la lettre, comme toujours, même si la chadda est au-dessus : قِدِّيس.', 3, '{"id": "ar.l20.e09", "unitIds": ["ar.g20.shadda"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Où se place la kasra quand la lettre porte une chadda ?", "promptLanguage": "fr", "answer": "sous la lettre", "acceptedAnswers": ["sous la lettre"], "explanation": "La kasra reste sous la lettre, comme toujours, même si la chadda est au-dessus : قِدِّيس.", "tip": "Kasra : toujours sous.", "extraExample": {"text": "سَيِّد", "translation": "monsieur"}, "options": ["après la lettre", "sur la chadda", "sous la lettre"], "errorPatterns": [{"equals": "sur la chadda", "category": "spelling", "feedback": "La fatha et la damma se posent au-dessus ; la kasra reste en dessous."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e10', 'ar', 'ar.l20', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.g20.shadda']::text[], 'mcq', 'lesson', 'Dans كُبَّايَة, quelle lettre allonge la fatha de بَّ ?', array['ا']::text[], 'Après بَّ, le ا allonge la fatha : a long. Puis يَ est une consonne avec sa fatha.', 2, '{"id": "ar.l20.e10", "unitIds": ["ar.g19.long_vowels", "ar.g20.shadda"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Dans كُبَّايَة, quelle lettre allonge la fatha de بَّ ?", "promptLanguage": "fr", "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "Après بَّ, le ا allonge la fatha : a long. Puis يَ est une consonne avec sa fatha.", "tip": "Fatha + ا : a long, même avec une chadda.", "extraExample": {"text": "قُدَّاس", "translation": "liturgie"}, "options": ["ي", "ب", "ا"], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e11', 'ar', 'ar.l20', 'ar.v.quddas', array['ar.v.quddas','ar.g20.shadda']::text[], 'mcq', 'lesson', 'قُدَّاس', array['liturgie']::text[], 'ق + ou, د doublé, puis ا (a long), س : c''est la liturgie, le mot que tu lisais قداس.', 2, '{"id": "ar.l20.e11", "unitIds": ["ar.v.quddas", "ar.g20.shadda"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "قُدَّاس", "promptLanguage": "ar", "answer": "liturgie", "acceptedAnswers": ["liturgie"], "explanation": "ق + ou, د doublé, puis ا (a long), س : c''est la liturgie, le mot que tu lisais قداس.", "tip": "Lettre doublée, puis ا.", "extraExample": {"text": "رُحْت الْقُدَّاس.", "translation": "Je suis allé à la liturgie."}, "options": ["encens", "croix", "prière", "liturgie"], "errorPatterns": [{"equals": "prière", "category": "word_confusion", "feedback": "La prière est صَلَاة : un autre mot."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e12', 'ar', 'ar.l20', 'ar.v.tayyib', array['ar.v.tayyib','ar.g20.shadda']::text[], 'mcq', 'lesson', 'طَيِّب', array['bon']::text[], 'ط + a, ي doublé avec une kasra, ب : bon, gentil. Tu le disais tous les jours.', 2, '{"id": "ar.l20.e12", "unitIds": ["ar.v.tayyib", "ar.g20.shadda"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "طَيِّب", "promptLanguage": "ar", "answer": "bon", "acceptedAnswers": ["bon"], "explanation": "ط + a, ي doublé avec une kasra, ب : bon, gentil. Tu le disais tous les jours.", "tip": "Chadda sur ي, kasra dessous.", "extraExample": {"text": "عَيْش طَيِّب.", "translation": "Du bon pain."}, "options": ["grand", "blanc", "gratuit", "bon"], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e13', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.dukkan']::text[], 'fill_blank', 'lesson', 'دُ___ان', array['كَّ']::text[], 'دُكَّان : دُ, puis ك doublé avec une fatha, puis ا (a long) et ن.', 2, '{"id": "ar.l20.e13", "unitIds": ["ar.g20.shadda", "ar.v.dukkan"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la lettre doublée.", "prompt": "دُ___ان", "promptLanguage": "ar", "answer": "كَّ", "acceptedAnswers": ["كَّ"], "explanation": "دُكَّان : دُ, puis ك doublé avec une fatha, puis ا (a long) et ن.", "tip": "Chadda + fatha, puis ا.", "extraExample": {"text": "رُحْت الدُّكَّان.", "translation": "Je suis allé à la boutique."}, "options": ["كْ", "كَّ", "كَ"], "errorPatterns": [{"equals": "كْ", "category": "spelling", "feedback": "Le soukoun n''ajoute rien : le ك est doublé dans ce mot."}, {"equals": "كَ", "category": "spelling", "feedback": "Il manque la chadda : le ك est dit deux fois."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e14', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.hubb']::text[], 'fill_blank', 'lesson', 'حُ___', array['بّ']::text[], 'En égyptien, حُبّ finit par un ب doublé : la chadda est sur la dernière lettre.', 3, '{"id": "ar.l20.e14", "unitIds": ["ar.g20.shadda", "ar.v.hubb"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la dernière lettre.", "prompt": "حُ___", "promptLanguage": "ar", "answer": "بّ", "acceptedAnswers": ["بّ"], "explanation": "En égyptien, حُبّ finit par un ب doublé : la chadda est sur la dernière lettre.", "tip": "Fin de mot doublée : chadda sur la dernière lettre.", "extraExample": {"text": "حُبّ كِبِير.", "translation": "Un grand amour."}, "options": ["بّ", "بْ", "ب"], "errorPatterns": [{"equals": "ب", "category": "spelling", "feedback": "Sans chadda, le ب serait simple : le mot se dirait plus court."}, {"equals": "بْ", "category": "spelling", "feedback": "Le soukoun dit « aucune voyelle », mais ici le ب est doublé."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e15', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.qiddis']::text[], 'fill_blank', 'lesson', 'قِ___يس', array['دِّ']::text[], 'قِدِّيس : قِ, puis د doublé avec une kasra (sous la lettre), puis ي (i long) et س.', 3, '{"id": "ar.l20.e15", "unitIds": ["ar.g20.shadda", "ar.v.qiddis"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la lettre doublée.", "prompt": "قِ___يس", "promptLanguage": "ar", "answer": "دِّ", "acceptedAnswers": ["دِّ"], "explanation": "قِدِّيس : قِ, puis د doublé avec une kasra (sous la lettre), puis ي (i long) et س.", "tip": "Kasra : toujours sous la lettre.", "extraExample": {"text": "الْقِدِّيس مَار جِرْجِس.", "translation": "Saint Georges."}, "options": ["دِّ", "دَّ", "دْ"], "errorPatterns": [{"equals": "دَّ", "category": "spelling", "feedback": "Avec une fatha, ce serait un a ; ici la voyelle est un i."}, {"equals": "دْ", "category": "spelling", "feedback": "Le soukoun n''ajoute rien : le د est doublé."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e16', 'ar', 'ar.l20', 'ar.v.mayya', array['ar.v.mayya','ar.g20.shadda']::text[], 'fill_blank', 'lesson', 'مَ___ة', array['يَّ']::text[], 'مَيَّة : مَ, puis ي doublé avec une fatha, puis ة. Tu dis deux y : eau se dit avec un y long.', 2, '{"id": "ar.l20.e16", "unitIds": ["ar.v.mayya", "ar.g20.shadda"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « eau ».", "prompt": "مَ___ة", "promptLanguage": "ar", "answer": "يَّ", "acceptedAnswers": ["يَّ"], "explanation": "مَيَّة : مَ, puis ي doublé avec une fatha, puis ة. Tu dis deux y : eau se dit avec un y long.", "tip": "Chadda + fatha sur ي.", "extraExample": {"text": "كُبَّايَة مَيَّة.", "translation": "Un verre d''eau."}, "options": ["يْ", "يَ", "يَّ"], "errorPatterns": [{"equals": "يْ", "category": "spelling", "feedback": "Un ي avec soukoun donnerait un é long (comme dans عَيْن), pas le double y."}, {"equals": "يَ", "category": "spelling", "feedback": "Il manque la chadda : le ي est dit deux fois."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e17', 'ar', 'ar.l20', 'ar.v.sukkar', array['ar.v.sukkar','ar.g20.shadda']::text[], 'fill_blank', 'lesson', 'سُ___ر', array['كَّ']::text[], 'سُكَّر : سُ, puis ك doublé avec une fatha, puis ر. Tu dis deux k.', 2, '{"id": "ar.l20.e17", "unitIds": ["ar.v.sukkar", "ar.g20.shadda"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « sucre ».", "prompt": "سُ___ر", "promptLanguage": "ar", "answer": "كَّ", "acceptedAnswers": ["كَّ"], "explanation": "سُكَّر : سُ, puis ك doublé avec une fatha, puis ر. Tu dis deux k.", "tip": "Dis-le tout haut : tu sens le k doublé.", "extraExample": {"text": "سُكَّر زِيَادَة.", "translation": "Beaucoup de sucre."}, "options": ["كَّ", "كُ", "كْ"], "errorPatterns": [{"equals": "كْ", "category": "spelling", "feedback": "Un soukoun ne double pas la lettre."}, {"equals": "كُ", "category": "spelling", "feedback": "La voyelle est un a après le k doublé, pas un ou."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e18', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.g18.sukun']::text[], 'match', 'lesson', 'Les signes à retenir', '{}'::text[], 'Fatha : a. Damma : ou. Soukoun : aucune voyelle. Chadda : lettre doublée.', 1, '{"id": "ar.l20.e18", "unitIds": ["ar.g20.shadda", "ar.g18.sukun"], "type": "match", "difficulty": 1, "instruction": "Associe chaque signe à ce qu''il fait.", "prompt": "Les signes à retenir", "promptLanguage": "fr", "answer": "ـَ = a ; ـُ = ou ; ـْ = aucune voyelle ; ـّ = lettre doublée", "acceptedAnswers": [], "explanation": "Fatha : a. Damma : ou. Soukoun : aucune voyelle. Chadda : lettre doublée.", "pairs": [{"left": "ـَ", "right": "a"}, {"left": "ـُ", "right": "ou"}, {"left": "ـْ", "right": "aucune voyelle"}, {"left": "ـّ", "right": "lettre doublée"}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e19', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.kubbaya','ar.v.rabb','ar.v.hubb','ar.v.kull']::text[], 'match', 'lesson', 'Mots avec chadda', '{}'::text[], 'Dans chaque mot, une lettre est écrite une fois et dite deux fois.', 2, '{"id": "ar.l20.e19", "unitIds": ["ar.g20.shadda", "ar.v.kubbaya", "ar.v.rabb", "ar.v.hubb", "ar.v.kull"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots avec chadda", "promptLanguage": "fr", "answer": "كُبَّايَة = verre ; رَبّ = Seigneur ; حُبّ = amour ; كُلّ = tout", "acceptedAnswers": [], "explanation": "Dans chaque mot, une lettre est écrite une fois et dite deux fois.", "pairs": [{"left": "كُبَّايَة", "right": "verre"}, {"left": "رَبّ", "right": "Seigneur"}, {"left": "حُبّ", "right": "amour"}, {"left": "كُلّ", "right": "tout"}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e20', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.qiddis','ar.v.sayyid','ar.v.muallim','ar.v.janna']::text[], 'match', 'lesson', 'Mots d''église avec chadda', '{}'::text[], 'قِدِّيس : د doublé. سَيِّد : ي doublé. مُعَلِّم : ل doublé. جَنَّة : ن doublé.', 3, '{"id": "ar.l20.e20", "unitIds": ["ar.g20.shadda", "ar.v.qiddis", "ar.v.sayyid", "ar.v.muallim", "ar.v.janna"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots d''église avec chadda", "promptLanguage": "fr", "answer": "قِدِّيس = saint ; سَيِّد = monsieur ; مُعَلِّم = maître ; جَنَّة = paradis", "acceptedAnswers": [], "explanation": "قِدِّيس : د doublé. سَيِّد : ي doublé. مُعَلِّم : ل doublé. جَنَّة : ن doublé.", "pairs": [{"left": "قِدِّيس", "right": "saint"}, {"left": "سَيِّد", "right": "monsieur"}, {"left": "مُعَلِّم", "right": "maître"}, {"left": "جَنَّة", "right": "paradis"}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e21', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.dukkan']::text[], 'translation', 'lesson', 'دُكَّان', array['boutique','une boutique','la boutique','magasin','échoppe']::text[], 'د + ou, ك doublé, ا (a long), ن : une petite boutique de quartier.', 2, '{"id": "ar.l20.e21", "unitIds": ["ar.g20.shadda", "ar.v.dukkan"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "دُكَّان", "promptLanguage": "ar", "answer": "boutique", "acceptedAnswers": ["boutique", "une boutique", "la boutique", "magasin", "échoppe"], "explanation": "د + ou, ك doublé, ا (a long), ن : une petite boutique de quartier.", "tip": "Chadda sur ك.", "extraExample": {"text": "دُكَّان صُغَيَّر.", "translation": "Une petite boutique."}, "errorPatterns": [{"equals": "verre", "category": "word_confusion", "feedback": "Le verre est كُبَّايَة : ici tu lis د + ك + ا + ن."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e22', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.sitt']::text[], 'translation', 'lesson', 'سِتّ', array['dame','madame','la dame','une dame','six','le chiffre six']::text[], 'س + i, ت doublé en fin de mot. Une dame, et aussi le chiffre six : le contexte te dit lequel.', 3, '{"id": "ar.l20.e22", "unitIds": ["ar.g20.shadda", "ar.v.sitt"], "type": "translation", "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "سِتّ", "promptLanguage": "ar", "answer": "dame", "acceptedAnswers": ["dame", "madame", "la dame", "une dame", "six", "le chiffre six"], "explanation": "س + i, ت doublé en fin de mot. Une dame, et aussi le chiffre six : le contexte te dit lequel.", "tip": "Chadda finale, kasra sous le س.", "extraExample": {"text": "سِتّ سَاعَات.", "translation": "Six heures."}, "errorPatterns": [{"equals": "saint", "category": "word_confusion", "feedback": "Le saint est قِدِّيس."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e23', 'ar', 'ar.l20', 'ar.v.mayya', array['ar.v.mayya','ar.g20.shadda']::text[], 'free_answer', 'lesson', 'Que veut dire مَيَّة ?', array['eau','de l''eau','l''eau','une eau']::text[], 'مَيَّة : م + a, ي doublé, ة. C''est l''eau, que tu lisais مية.', 2, '{"id": "ar.l20.e23", "unitIds": ["ar.v.mayya", "ar.g20.shadda"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire مَيَّة ?", "promptLanguage": "fr", "answer": "eau", "acceptedAnswers": ["eau", "de l''eau", "l''eau", "une eau"], "explanation": "مَيَّة : م + a, ي doublé, ة. C''est l''eau, que tu lisais مية.", "tip": "Le ي doublé est le cœur du mot.", "extraExample": {"text": "كُبَّايَة مَيَّة.", "translation": "Un verre d''eau."}, "errorPatterns": [{"equals": "verre", "category": "word_confusion", "feedback": "Le verre est كُبَّايَة : ici tu lis م + ي + ي + ة."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e24', 'ar', 'ar.l20', 'ar.g20.shadda', array['ar.g20.shadda','ar.v.kull']::text[], 'free_answer', 'lesson', 'Que veut dire كُلّ ?', array['tout','chaque','tous','toute','tous les','tout le']::text[], 'كُلّ : ك + ou, ل doublé en fin de mot. Tout, chaque : كُلّ يَوْم, chaque jour.', 3, '{"id": "ar.l20.e24", "unitIds": ["ar.g20.shadda", "ar.v.kull"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire كُلّ ?", "promptLanguage": "fr", "answer": "tout", "acceptedAnswers": ["tout", "chaque", "tous", "toute", "tous les", "tout le"], "explanation": "كُلّ : ك + ou, ل doublé en fin de mot. Tout, chaque : كُلّ يَوْم, chaque jour.", "tip": "Chadda finale sur ل.", "extraExample": {"text": "كُلّ يَوْم.", "translation": "Chaque jour."}, "errorPatterns": [{"equals": "chien", "category": "word_confusion", "feedback": "Le chien est كَلْب, avec un soukoun. كُلّ a une chadda."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e01', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin']::text[], 'mcq', 'lesson', 'Où écrit-on le tanwin ?', array['à la fin du mot']::text[], 'Le tanwin ne s''écrit qu''à la fin d''un mot : il ajoute un n final.', 1, '{"id": "ar.l21.e01", "unitIds": ["ar.g21.tanwin"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Où écrit-on le tanwin ?", "promptLanguage": "fr", "answer": "à la fin du mot", "acceptedAnswers": ["à la fin du mot"], "explanation": "Le tanwin ne s''écrit qu''à la fin d''un mot : il ajoute un n final.", "tip": "Tanwin = n de la fin.", "extraExample": {"text": "شُكْرًا", "translation": "merci"}, "options": ["au début du mot", "à la fin du mot", "au milieu du mot"], "errorPatterns": [{"equals": "au début du mot", "category": "spelling", "feedback": "Jamais au début : un mot ne commence pas par un n supplémentaire."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e02', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin']::text[], 'mcq', 'lesson', 'Quel son donne ـً ?', array['an']::text[], 'Deux fathas donnent le son an. Deux kasras donnent in, deux dammas oun.', 1, '{"id": "ar.l21.e02", "unitIds": ["ar.g21.tanwin"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Quel son donne ـً ?", "promptLanguage": "fr", "answer": "an", "acceptedAnswers": ["an"], "explanation": "Deux fathas donnent le son an. Deux kasras donnent in, deux dammas oun.", "tip": "Deux fathas : an.", "extraExample": {"text": "طَبْعًا", "translation": "bien sûr"}, "options": ["oun", "in", "an"], "errorPatterns": [{"equals": "in", "category": "spelling", "feedback": "Le son in vient des deux kasras ـٍ, sous la lettre."}, {"equals": "oun", "category": "spelling", "feedback": "Le son oun vient des deux dammas ـٌ."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e03', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin']::text[], 'mcq', 'lesson', 'Dans شُكْرًا, le ا final se prononce-t-il à part ?', array['non, il est muet']::text[], 'Le ا ne fait que porter le tanwin : non, il est muet. On dit ش + ou, ك, ر + an.', 2, '{"id": "ar.l21.e03", "unitIds": ["ar.g21.tanwin"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Dans شُكْرًا, le ا final se prononce-t-il à part ?", "promptLanguage": "fr", "answer": "non, il est muet", "acceptedAnswers": ["non, il est muet"], "explanation": "Le ا ne fait que porter le tanwin : non, il est muet. On dit ش + ou, ك, ر + an.", "tip": "Le ا final du tanwin ne se dit pas.", "extraExample": {"text": "جِدًّا", "translation": "très"}, "options": ["oui, comme un a long", "oui, comme un i long", "non, il est muet"], "errorPatterns": [{"equals": "oui, comme un a long", "category": "spelling", "feedback": "Ce ا n''allonge rien : il est muet, le tanwin donne déjà le son an."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e04', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin']::text[], 'mcq', 'lesson', 'شُكْرًا', array['merci']::text[], 'ش + ou, ك sans voyelle, ر + an (tanwin) : merci.', 2, '{"id": "ar.l21.e04", "unitIds": ["ar.g21.tanwin"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "شُكْرًا", "promptLanguage": "ar", "answer": "merci", "acceptedAnswers": ["merci"], "explanation": "ش + ou, ك sans voyelle, ر + an (tanwin) : merci.", "tip": "Ce que tu dis après un cadeau.", "extraExample": {"text": "شُكْرًا لَكَ يَا رَبّ.", "translation": "Merci à toi, Seigneur."}, "options": ["toujours", "de rien", "très", "merci"], "errorPatterns": [{"equals": "de rien", "category": "word_confusion", "feedback": "Pour répondre à un merci, on dit عَفْوًا."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e05', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.afwan']::text[], 'mcq', 'lesson', 'عَفْوًا', array['de rien']::text[], 'ع + a, ف sans voyelle, و + an : c''est la réponse à un merci, ou « pardon ».', 2, '{"id": "ar.l21.e05", "unitIds": ["ar.g21.tanwin", "ar.v.afwan"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "عَفْوًا", "promptLanguage": "ar", "answer": "de rien", "acceptedAnswers": ["de rien"], "explanation": "ع + a, ف sans voyelle, و + an : c''est la réponse à un merci, ou « pardon ».", "tip": "Le و porte le tanwin : c''est une consonne.", "extraExample": {"text": "شُكْرًا. - عَفْوًا.", "translation": "Merci. - De rien."}, "options": ["bien sûr", "merci", "vraiment", "de rien"], "errorPatterns": [{"equals": "merci", "category": "word_confusion", "feedback": "Merci est شُكْرًا. Ici tu lis ع + ف + و."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e06', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.giddan']::text[], 'mcq', 'lesson', 'Que veut dire جِدًّا dans عَيْش طَيِّب جِدًّا ?', array['très']::text[], 'جِدًّا veut dire « très » : du pain très bon. Il s''ajoute après l''adjectif.', 2, '{"id": "ar.l21.e06", "unitIds": ["ar.g21.tanwin", "ar.v.giddan"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Que veut dire جِدًّا dans عَيْش طَيِّب جِدًّا ?", "promptLanguage": "fr", "answer": "très", "acceptedAnswers": ["très"], "explanation": "جِدًّا veut dire « très » : du pain très bon. Il s''ajoute après l''adjectif.", "tip": "Dis-le : « très ».", "extraExample": {"text": "كُوَيِّس جِدًّا.", "translation": "Très bien."}, "options": ["très", "toujours", "tout de suite"], "errorPatterns": [{"equals": "toujours", "category": "word_confusion", "feedback": "Toujours est دَايِمًا."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e07', 'ar', 'ar.l21', 'ar.g20.shadda', array['ar.g20.shadda','ar.g21.tanwin']::text[], 'mcq', 'lesson', 'Dans جِدًّا, quelle lettre est doublée par la chadda ?', array['د']::text[], 'La chadda est sur د : ج + i, puis د doublé, qui porte aussi le tanwin.', 2, '{"id": "ar.l21.e07", "unitIds": ["ar.g20.shadda", "ar.g21.tanwin"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Dans جِدًّا, quelle lettre est doublée par la chadda ?", "promptLanguage": "fr", "answer": "د", "acceptedAnswers": ["د"], "explanation": "La chadda est sur د : ج + i, puis د doublé, qui porte aussi le tanwin.", "tip": "Cherche le petit w.", "extraExample": {"text": "كُبَّايَة", "translation": "verre"}, "options": ["ج", "ا", "د"], "errorPatterns": [{"equals": "ج", "category": "spelling", "feedback": "ج porte seulement la kasra."}, {"equals": "ا", "category": "spelling", "feedback": "Le ا final est muet."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e08', 'ar', 'ar.l21', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.g21.tanwin']::text[], 'mcq', 'lesson', 'Dans عَفْوًا, le و porte un signe : est-ce une voyelle longue ou une consonne ?', array['une consonne']::text[], 'Un و qui porte un signe (ici le tanwin) est une consonne. La voyelle longue ou est un و nu, après une damma.', 3, '{"id": "ar.l21.e08", "unitIds": ["ar.g19.long_vowels", "ar.g21.tanwin"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Dans عَفْوًا, le و porte un signe : est-ce une voyelle longue ou une consonne ?", "promptLanguage": "fr", "answer": "une consonne", "acceptedAnswers": ["une consonne"], "explanation": "Un و qui porte un signe (ici le tanwin) est une consonne. La voyelle longue ou est un و nu, après une damma.", "tip": "Signe sur و ou ي : consonne.", "extraExample": {"text": "رُوح", "translation": "esprit : ici le و est nu"}, "options": ["une consonne", "une voyelle longue", "une lettre muette"], "errorPatterns": [{"equals": "une voyelle longue", "category": "spelling", "feedback": "Une voyelle longue serait un و nu après une damma : ici il y a une fatha et un tanwin."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e09', 'ar', 'ar.l21', 'ar.g18.sukun', array['ar.g18.sukun','ar.g21.tanwin']::text[], 'mcq', 'lesson', 'Dans تَقْرِيبًا, quel signe est posé sur le ق ?', array['le soukoun']::text[], 'Le ق n''a pas de voyelle : il porte un soukoun. Le tanwin est à la fin, sur ب.', 3, '{"id": "ar.l21.e09", "unitIds": ["ar.g18.sukun", "ar.g21.tanwin"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Dans تَقْرِيبًا, quel signe est posé sur le ق ?", "promptLanguage": "fr", "answer": "le soukoun", "acceptedAnswers": ["le soukoun"], "explanation": "Le ق n''a pas de voyelle : il porte un soukoun. Le tanwin est à la fin, sur ب.", "tip": "Petit rond : aucune voyelle.", "extraExample": {"text": "نَجْم", "translation": "étoile"}, "options": ["le soukoun", "la chadda", "le tanwin"], "errorPatterns": [{"equals": "la chadda", "category": "spelling", "feedback": "La chadda double une lettre ; ici le ق est seul, avec un petit rond."}, {"equals": "le tanwin", "category": "spelling", "feedback": "Le tanwin est seulement à la fin du mot, sur ب."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e10', 'ar', 'ar.l21', 'ar.v.bayt', array['ar.v.bayt','ar.g21.tanwin']::text[], 'mcq', 'lesson', 'Quelle forme de « maison » se termine par le son an ?', array['بَيْتًا']::text[], 'Deux fathas (ـً) donnent an, avec un ا muet après. بَيْتٌ finit par oun, بَيْتٍ par in.', 2, '{"id": "ar.l21.e10", "unitIds": ["ar.v.bayt", "ar.g21.tanwin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "Quelle forme de « maison » se termine par le son an ?", "promptLanguage": "fr", "answer": "بَيْتًا", "acceptedAnswers": ["بَيْتًا"], "explanation": "Deux fathas (ـً) donnent an, avec un ا muet après. بَيْتٌ finit par oun, بَيْتٍ par in.", "tip": "Deux fathas + ا : an.", "extraExample": {"text": "بَيْتًا", "translation": "une maison (finit par an)"}, "options": ["بَيْتٌ", "بَيْتٍ", "بَيْتًا"], "errorPatterns": [{"equals": "بَيْتٌ", "category": "spelling", "feedback": "Les deux dammas ـٌ donnent oun."}, {"equals": "بَيْتٍ", "category": "spelling", "feedback": "Les deux kasras ـٍ donnent in."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e11', 'ar', 'ar.l21', 'ar.v.sukkar', array['ar.v.sukkar','ar.g21.tanwin']::text[], 'mcq', 'lesson', 'Dans سُكَّر, combien de fois lit-on le ك ?', array['deux fois']::text[], 'La chadda sur ك le fait dire deux fois, même s''il n''est écrit qu''une fois.', 2, '{"id": "ar.l21.e11", "unitIds": ["ar.v.sukkar", "ar.g21.tanwin"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Dans سُكَّر, combien de fois lit-on le ك ?", "promptLanguage": "fr", "answer": "deux fois", "acceptedAnswers": ["deux fois"], "explanation": "La chadda sur ك le fait dire deux fois, même s''il n''est écrit qu''une fois.", "tip": "Chadda : deux fois.", "extraExample": {"text": "مَيَّة", "translation": "eau"}, "options": ["deux fois", "trois fois", "une fois"], "errorPatterns": [{"equals": "une fois", "category": "spelling", "feedback": "Avec la chadda, le ك est dit deux fois."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e12', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.afwan']::text[], 'fill_blank', 'lesson', 'شُكْرًا. - ___.', array['عَفْوًا']::text[], 'On répond « merci » par « de rien » : عَفْوًا.', 2, '{"id": "ar.l21.e12", "unitIds": ["ar.g21.tanwin", "ar.v.afwan"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le dialogue.", "prompt": "شُكْرًا. - ___.", "promptLanguage": "ar", "answer": "عَفْوًا", "acceptedAnswers": ["عَفْوًا"], "explanation": "On répond « merci » par « de rien » : عَفْوًا.", "tip": "Merci, de rien.", "extraExample": {"text": "شُكْرًا. - عَفْوًا.", "translation": "Merci. - De rien."}, "options": ["حَالًا", "جِدًّا", "عَفْوًا"], "errorPatterns": [{"equals": "جِدًّا", "category": "spelling", "feedback": "جِدًّا veut dire « très » : ça ne répond pas à un merci."}, {"equals": "حَالًا", "category": "spelling", "feedback": "حَالًا veut dire « tout de suite »."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e13', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.giddan']::text[], 'fill_blank', 'lesson', 'كُوَيِّس ___.', array['جِدًّا']::text[], '« Très bien » : كُوَيِّس جِدًّا. جِدًّا s''ajoute après l''adjectif pour dire « très ».', 2, '{"id": "ar.l21.e13", "unitIds": ["ar.g21.tanwin", "ar.v.giddan"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "كُوَيِّس ___.", "promptLanguage": "ar", "answer": "جِدًّا", "acceptedAnswers": ["جِدًّا"], "explanation": "« Très bien » : كُوَيِّس جِدًّا. جِدًّا s''ajoute après l''adjectif pour dire « très ».", "tip": "Après l''adjectif : très.", "extraExample": {"text": "الطَّرِيق طَوِيل جِدًّا.", "translation": "La route est très longue."}, "options": ["غَالِبًا", "حَالًا", "جِدًّا"], "errorPatterns": [{"equals": "حَالًا", "category": "spelling", "feedback": "Tout de suite ne va pas avec « bien »."}, {"equals": "غَالِبًا", "category": "spelling", "feedback": "Souvent ne va pas ici : on veut dire « très bien »."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e14', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.tabaan']::text[], 'fill_blank', 'lesson', 'هَتِيجِي بُكْرَة؟ - ___!', array['طَبْعًا']::text[], '« Tu viens demain ? – Bien sûr ! » : طَبْعًا.', 2, '{"id": "ar.l21.e14", "unitIds": ["ar.g21.tanwin", "ar.v.tabaan"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le dialogue.", "prompt": "هَتِيجِي بُكْرَة؟ - ___!", "promptLanguage": "ar", "answer": "طَبْعًا", "acceptedAnswers": ["طَبْعًا"], "explanation": "« Tu viens demain ? – Bien sûr ! » : طَبْعًا.", "tip": "Réponse enthousiaste : bien sûr.", "extraExample": {"text": "طَبْعًا هَاجِي.", "translation": "Bien sûr que je viens."}, "options": ["تَقْرِيبًا", "طَبْعًا", "مَثَلًا"], "errorPatterns": [{"equals": "مَثَلًا", "category": "spelling", "feedback": "Par exemple ne répond pas à une question oui/non."}, {"equals": "تَقْرِيبًا", "category": "spelling", "feedback": "Environ ne convient pas pour une réponse franche."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e15', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.dayiman']::text[], 'fill_blank', 'lesson', 'الْمَجْد لِلَّه ___.', array['دَايِمًا']::text[], '« Gloire à Dieu toujours » : الْمَجْد لِلَّه دَايِمًا.', 2, '{"id": "ar.l21.e15", "unitIds": ["ar.g21.tanwin", "ar.v.dayiman"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "الْمَجْد لِلَّه ___.", "promptLanguage": "ar", "answer": "دَايِمًا", "acceptedAnswers": ["دَايِمًا"], "explanation": "« Gloire à Dieu toujours » : الْمَجْد لِلَّه دَايِمًا.", "tip": "Toujours : دَايِمًا.", "extraExample": {"text": "دَايِمًا كُوَيِّس.", "translation": "Toujours bien."}, "options": ["مَثَلًا", "دَايِمًا", "حَالًا"], "errorPatterns": [{"equals": "حَالًا", "category": "spelling", "feedback": "Tout de suite ne va pas avec une louange de toujours."}, {"equals": "مَثَلًا", "category": "spelling", "feedback": "Par exemple ne va pas ici."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e16', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.halan']::text[], 'fill_blank', 'lesson', 'هَاجِي ___.', array['حَالًا']::text[], '« J''arrive tout de suite » : هَاجِي حَالًا.', 3, '{"id": "ar.l21.e16", "unitIds": ["ar.g21.tanwin", "ar.v.halan"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "هَاجِي ___.", "promptLanguage": "ar", "answer": "حَالًا", "acceptedAnswers": ["حَالًا"], "explanation": "« J''arrive tout de suite » : هَاجِي حَالًا.", "tip": "Tout de suite : حَالًا.", "extraExample": {"text": "حَالًا!", "translation": "Tout de suite !"}, "options": ["تَقْرِيبًا", "دَايِمًا", "حَالًا"], "errorPatterns": [{"equals": "دَايِمًا", "category": "spelling", "feedback": "Toujours ne va pas avec « j''arrive »."}, {"equals": "تَقْرِيبًا", "category": "spelling", "feedback": "Environ n''a pas de sens ici."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e17', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin']::text[], 'match', 'lesson', 'Les trois tanwins', '{}'::text[], 'Deux fathas : an. Deux kasras : in. Deux dammas : oun.', 1, '{"id": "ar.l21.e17", "unitIds": ["ar.g21.tanwin"], "type": "match", "difficulty": 1, "instruction": "Associe chaque tanwin à son son.", "prompt": "Les trois tanwins", "promptLanguage": "fr", "answer": "ـً = an ; ـٍ = in ; ـٌ = oun", "acceptedAnswers": [], "explanation": "Deux fathas : an. Deux kasras : in. Deux dammas : oun.", "pairs": [{"left": "ـً", "right": "an"}, {"left": "ـٍ", "right": "in"}, {"left": "ـٌ", "right": "oun"}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e18', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.tabaan','ar.v.filan','ar.v.masalan','ar.v.taqriban']::text[], 'match', 'lesson', 'Petits mots à tanwin (1)', '{}'::text[], 'Chacun se termine par ـًا : le son an.', 2, '{"id": "ar.l21.e18", "unitIds": ["ar.g21.tanwin", "ar.v.tabaan", "ar.v.filan", "ar.v.masalan", "ar.v.taqriban"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Petits mots à tanwin (1)", "promptLanguage": "fr", "answer": "طَبْعًا = bien sûr ; فِعْلًا = vraiment ; مَثَلًا = par exemple ; تَقْرِيبًا = environ", "acceptedAnswers": [], "explanation": "Chacun se termine par ـًا : le son an.", "pairs": [{"left": "طَبْعًا", "right": "bien sûr"}, {"left": "فِعْلًا", "right": "vraiment"}, {"left": "مَثَلًا", "right": "par exemple"}, {"left": "تَقْرِيبًا", "right": "environ"}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e19', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.dayiman','ar.v.halan','ar.v.ghaliban','ar.v.giddan']::text[], 'match', 'lesson', 'Petits mots à tanwin (2)', '{}'::text[], 'Des mots invariables qui ne changent jamais : on apprend leur fin en an.', 3, '{"id": "ar.l21.e19", "unitIds": ["ar.g21.tanwin", "ar.v.dayiman", "ar.v.halan", "ar.v.ghaliban", "ar.v.giddan"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à son sens.", "prompt": "Petits mots à tanwin (2)", "promptLanguage": "fr", "answer": "دَايِمًا = toujours ; حَالًا = tout de suite ; غَالِبًا = souvent ; جِدًّا = très", "acceptedAnswers": [], "explanation": "Des mots invariables qui ne changent jamais : on apprend leur fin en an.", "pairs": [{"left": "دَايِمًا", "right": "toujours"}, {"left": "حَالًا", "right": "tout de suite"}, {"left": "غَالِبًا", "right": "souvent"}, {"left": "جِدًّا", "right": "très"}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e20', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.taqriban']::text[], 'translation', 'lesson', 'تَقْرِيبًا', array['environ','à peu près','presque','approximativement']::text[], 'تَقْرِيبًا : environ, à peu près. ق porte un soukoun et le tanwin est à la fin.', 2, '{"id": "ar.l21.e20", "unitIds": ["ar.g21.tanwin", "ar.v.taqriban"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "تَقْرِيبًا", "promptLanguage": "ar", "answer": "environ", "acceptedAnswers": ["environ", "à peu près", "presque", "approximativement"], "explanation": "تَقْرِيبًا : environ, à peu près. ق porte un soukoun et le tanwin est à la fin.", "tip": "Soukoun sur ق, tanwin à la fin.", "extraExample": {"text": "تَقْرِيبًا سِتّ سَاعَات.", "translation": "À peu près six heures."}, "errorPatterns": [{"equals": "toujours", "category": "word_confusion", "feedback": "Toujours est دَايِمًا."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e21', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.masalan']::text[], 'translation', 'lesson', 'مَثَلًا', array['par exemple','exemple','par exemples']::text[], 'مَثَلًا sert à donner un exemple : par exemple.', 3, '{"id": "ar.l21.e21", "unitIds": ["ar.g21.tanwin", "ar.v.masalan"], "type": "translation", "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "مَثَلًا", "promptLanguage": "ar", "answer": "par exemple", "acceptedAnswers": ["par exemple", "exemple", "par exemples"], "explanation": "مَثَلًا sert à donner un exemple : par exemple.", "tip": "Quand tu dis « par exemple... ».", "extraExample": {"text": "مَثَلًا بُكْرَة.", "translation": "Par exemple demain."}, "errorPatterns": [{"equals": "bien sûr", "category": "word_confusion", "feedback": "Bien sûr est طَبْعًا."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e22', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.v.halan']::text[], 'free_answer', 'lesson', 'Que veut dire حَالًا ?', array['tout de suite','de suite','immédiatement','maintenant','tout de suite !']::text[], 'حَالًا : ح + a, ل + an (tanwin), puis un ا muet. C''est « tout de suite ».', 3, '{"id": "ar.l21.e22", "unitIds": ["ar.g21.tanwin", "ar.v.halan"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire حَالًا ?", "promptLanguage": "fr", "answer": "tout de suite", "acceptedAnswers": ["tout de suite", "de suite", "immédiatement", "maintenant", "tout de suite !"], "explanation": "حَالًا : ح + a, ل + an (tanwin), puis un ا muet. C''est « tout de suite ».", "tip": "Un seul ل, puis le tanwin.", "extraExample": {"text": "هَاجِي حَالًا.", "translation": "J''arrive tout de suite."}, "errorPatterns": [{"equals": "souvent", "category": "word_confusion", "feedback": "Souvent est غَالِبًا."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e23', 'ar', 'ar.l21', 'ar.g21.tanwin', array['ar.g21.tanwin']::text[], 'free_answer', 'lesson', 'Comment s''appelle le signe doublé qui ajoute un n à la fin d''un mot ?', array['tanwin','le tanwin','tanouin']::text[], 'C''est le tanwin (تَنْوِين, « mettre un n »).', 2, '{"id": "ar.l21.e23", "unitIds": ["ar.g21.tanwin"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Comment s''appelle le signe doublé qui ajoute un n à la fin d''un mot ?", "promptLanguage": "fr", "answer": "tanwin", "acceptedAnswers": ["tanwin", "le tanwin", "tanouin"], "explanation": "C''est le tanwin (تَنْوِين, « mettre un n »).", "tip": "Signe doublé = n final.", "extraExample": {"text": "شُكْرًا", "translation": "merci"}, "errorPatterns": [{"equals": "chadda", "category": "word_confusion", "feedback": "La chadda double une lettre au milieu du mot. Le tanwin est à la fin."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e01', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda']::text[], 'mcq', 'lesson', 'Que marque la lettre ء ?', array['un coup de gorge']::text[], 'ء (hamza) est un coup de gorge, un petit arrêt dans la voix, comme celui de ق au Caire.', 1, '{"id": "ar.l22.e01", "unitIds": ["ar.g22.hamza_madda"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Que marque la lettre ء ?", "promptLanguage": "fr", "answer": "un coup de gorge", "acceptedAnswers": ["un coup de gorge"], "explanation": "ء (hamza) est un coup de gorge, un petit arrêt dans la voix, comme celui de ق au Caire.", "tip": "Dis un petit arrêt dans la gorge.", "extraExample": {"text": "أَمَل", "translation": "espoir"}, "options": ["un h soufflé", "un a long", "un coup de gorge"], "errorPatterns": [{"equals": "un h soufflé", "category": "spelling", "feedback": "Le h soufflé est ه. La hamza est un arrêt de la gorge."}, {"equals": "un a long", "category": "spelling", "feedback": "Le a long est ا, ou آ qui a aussi un coup de gorge."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e02', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda']::text[], 'mcq', 'lesson', 'Où se place la hamza quand elle a une kasra, au début d''un mot ?', array['sous le ا']::text[], 'Avec une kasra, la hamza passe sous le ا : إِ. Avec fatha ou damma, elle est au-dessus : أ.', 2, '{"id": "ar.l22.e02", "unitIds": ["ar.g22.hamza_madda"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Où se place la hamza quand elle a une kasra, au début d''un mot ?", "promptLanguage": "fr", "answer": "sous le ا", "acceptedAnswers": ["sous le ا"], "explanation": "Avec une kasra, la hamza passe sous le ا : إِ. Avec fatha ou damma, elle est au-dessus : أ.", "tip": "Kasra : en dessous, comme toujours.", "extraExample": {"text": "إِيمَان", "translation": "foi"}, "options": ["sous le ا", "au-dessus du ا", "sur un و"], "errorPatterns": [{"equals": "au-dessus du ا", "category": "spelling", "feedback": "Au-dessus, c''est pour la fatha ou la damma (أ)."}, {"equals": "sur un و", "category": "spelling", "feedback": "Le support و (ؤ) vient avec une damma, au milieu d''un mot."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e03', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.suaal']::text[], 'mcq', 'lesson', 'Sur quelle lettre s''appuie la hamza de سُؤَال ?', array['و']::text[], 'La damma est plus forte que la fatha : le support est و, ce qui donne ؤ.', 3, '{"id": "ar.l22.e03", "unitIds": ["ar.g22.hamza_madda", "ar.v.suaal"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Sur quelle lettre s''appuie la hamza de سُؤَال ?", "promptLanguage": "fr", "answer": "و", "acceptedAnswers": ["و"], "explanation": "La damma est plus forte que la fatha : le support est و, ce qui donne ؤ.", "tip": "Damma : ؤ.", "extraExample": {"text": "سُؤَال سَهْل.", "translation": "Une question facile."}, "options": ["و", "ا", "ي"], "errorPatterns": [{"equals": "ا", "category": "spelling", "feedback": "ا est pour la fatha ou la damma au début. Ici la damma de س choisit و."}, {"equals": "ي", "category": "spelling", "feedback": "ي sans points est pour la kasra."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e04', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.raees']::text[], 'mcq', 'lesson', 'Sur quelle lettre s''appuie la hamza de رَئِيس ?', array['ي sans points']::text[], 'La hamza porte une kasra : le support est un ي sans points, ce qui donne ئ.', 3, '{"id": "ar.l22.e04", "unitIds": ["ar.g22.hamza_madda", "ar.v.raees"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Sur quelle lettre s''appuie la hamza de رَئِيس ?", "promptLanguage": "fr", "answer": "ي sans points", "acceptedAnswers": ["ي sans points"], "explanation": "La hamza porte une kasra : le support est un ي sans points, ce qui donne ئ.", "tip": "Kasra : ئ.", "extraExample": {"text": "رَئِيس الدَّيْر.", "translation": "Le supérieur du monastère."}, "options": ["و", "ا", "ي sans points"], "errorPatterns": [{"equals": "ا", "category": "spelling", "feedback": "ا est pour fatha ou damma, ou pour la kasra au début du mot (إ)."}, {"equals": "و", "category": "spelling", "feedback": "و est pour la damma (ؤ)."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e05', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.suaal']::text[], 'mcq', 'lesson', 'سُؤَال', array['question']::text[], 'س + ou, ؤ (coup de gorge + a), ا (a long), ل : une question.', 2, '{"id": "ar.l22.e05", "unitIds": ["ar.g22.hamza_madda", "ar.v.suaal"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "سُؤَال", "promptLanguage": "ar", "answer": "question", "acceptedAnswers": ["question"], "explanation": "س + ou, ؤ (coup de gorge + a), ا (a long), ل : une question.", "tip": "Cherche la hamza sur و.", "extraExample": {"text": "عِنْدِي سُؤَال.", "translation": "J''ai une question."}, "options": ["chef", "foi", "soir", "question"], "errorPatterns": [{"equals": "chef", "category": "word_confusion", "feedback": "Le chef est رَئِيس, avec une hamza sur ي."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e06', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.masaa']::text[], 'mcq', 'lesson', 'مَسَاء', array['soir']::text[], 'م + a, س + a long, puis ء seule : le soir. La hamza est seule après le ا long.', 2, '{"id": "ar.l22.e06", "unitIds": ["ar.g22.hamza_madda", "ar.v.masaa"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "مَسَاء", "promptLanguage": "ar", "answer": "soir", "acceptedAnswers": ["soir"], "explanation": "م + a, س + a long, puis ء seule : le soir. La hamza est seule après le ا long.", "tip": "Hamza finale seule : ء.", "extraExample": {"text": "فِي الْمَسَاء.", "translation": "Le soir."}, "options": ["soir", "anges", "question", "espoir"], "errorPatterns": [{"equals": "espoir", "category": "word_confusion", "feedback": "L''espoir est أَمَل, avec une hamza au début."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e07', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda']::text[], 'mcq', 'lesson', 'Comment se lit آ ?', array['coup de gorge + a long']::text[], 'La madda sur ا donne deux sons en un : un coup de gorge, puis un a long.', 2, '{"id": "ar.l22.e07", "unitIds": ["ar.g22.hamza_madda"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Comment se lit آ ?", "promptLanguage": "fr", "answer": "coup de gorge + a long", "acceptedAnswers": ["coup de gorge + a long"], "explanation": "La madda sur ا donne deux sons en un : un coup de gorge, puis un a long.", "tip": "Madda = أَا.", "extraExample": {"text": "آمِين", "translation": "amen"}, "options": ["coup de gorge + i", "a bref seulement", "coup de gorge + a long"], "errorPatterns": [{"equals": "a bref seulement", "category": "spelling", "feedback": "Il y a aussi un coup de gorge, et le a est long."}, {"equals": "coup de gorge + i", "category": "spelling", "feedback": "Le son i vient d''une kasra : ici, c''est un a."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e08', 'ar', 'ar.l22', 'ar.v.amin', array['ar.v.amin','ar.g22.hamza_madda']::text[], 'mcq', 'lesson', 'آمِين', array['amen']::text[], 'آ (coup de gorge + a long), م + i long (kasra + ي), ن : amen, la réponse de l''assemblée à la fin des prières.', 1, '{"id": "ar.l22.e08", "unitIds": ["ar.v.amin", "ar.g22.hamza_madda"], "type": "mcq", "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "آمِين", "promptLanguage": "ar", "answer": "amen", "acceptedAnswers": ["amen"], "explanation": "آ (coup de gorge + a long), م + i long (kasra + ي), ن : amen, la réponse de l''assemblée à la fin des prières.", "tip": "La madda ouvre le mot.", "extraExample": {"text": "آمِين يَا رَبّ.", "translation": "Amen, Seigneur."}, "options": ["oui", "bonsoir", "merci", "amen"], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e09', 'ar', 'ar.l22', 'ar.v.abouna', array['ar.v.abouna','ar.g22.hamza_madda']::text[], 'mcq', 'lesson', 'أَبُونَا', array['notre père']::text[], 'أ (hamza + fatha), ب + ou long, ن + a long : notre père, la façon de dire « le prêtre ».', 2, '{"id": "ar.l22.e09", "unitIds": ["ar.v.abouna", "ar.g22.hamza_madda"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "أَبُونَا", "promptLanguage": "ar", "answer": "notre père", "acceptedAnswers": ["notre père"], "explanation": "أ (hamza + fatha), ب + ou long, ن + a long : notre père, la façon de dire « le prêtre ».", "tip": "Hamza + fatha au début, puis ou long.", "extraExample": {"text": "أَبُونَا بِيصَلِّي.", "translation": "Notre père (le prêtre) prie."}, "options": ["notre maison", "notre père", "notre Seigneur", "notre frère"], "errorPatterns": [{"equals": "notre Seigneur", "category": "word_confusion", "feedback": "Notre Seigneur est رَبِّنَا : un autre mot."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e10', 'ar', 'ar.l22', 'ar.g19.long_vowels', array['ar.g19.long_vowels','ar.g22.hamza_madda']::text[], 'mcq', 'lesson', 'Dans اِرْحَم, que fait le ا ?', array['il porte seulement la voyelle i']::text[], 'Ce ا a une kasra mais pas de hamza : il porte seulement la voyelle i. Pour un coup de gorge, il faudrait إ.', 3, '{"id": "ar.l22.e10", "unitIds": ["ar.g19.long_vowels", "ar.g22.hamza_madda"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Dans اِرْحَم, que fait le ا ?", "promptLanguage": "fr", "answer": "il porte seulement la voyelle i", "acceptedAnswers": ["il porte seulement la voyelle i"], "explanation": "Ce ا a une kasra mais pas de hamza : il porte seulement la voyelle i. Pour un coup de gorge, il faudrait إ.", "tip": "Pas de petit ء : pas de coup de gorge.", "extraExample": {"text": "يَا رَبّ اِرْحَم", "translation": "Seigneur, aie pitié"}, "options": ["il fait un coup de gorge", "il allonge la fatha", "il porte seulement la voyelle i"], "errorPatterns": [{"equals": "il fait un coup de gorge", "category": "spelling", "feedback": "Sans hamza, pas de coup de gorge : il porte seulement le i."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e11', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.raees']::text[], 'fill_blank', 'lesson', 'رَ___يس', array['ئِ']::text[], 'رَئِيس : la hamza a une kasra, son support est donc ي sans points : ئِ. Puis ي (i long) et س.', 3, '{"id": "ar.l22.e11", "unitIds": ["ar.g22.hamza_madda", "ar.v.raees"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne syllabe.", "prompt": "رَ___يس", "promptLanguage": "ar", "answer": "ئِ", "acceptedAnswers": ["ئِ"], "explanation": "رَئِيس : la hamza a une kasra, son support est donc ي sans points : ئِ. Puis ي (i long) et س.", "tip": "Kasra : ئ.", "extraExample": {"text": "رَئِيسِي فِي الشُّغْل.", "translation": "Mon chef au travail."}, "options": ["ئِ", "أَ", "ؤُ"], "errorPatterns": [{"equals": "ؤُ", "category": "spelling", "feedback": "ؤ va avec une damma : ici la hamza a une kasra."}, {"equals": "أَ", "category": "spelling", "feedback": "أ va avec fatha ou damma, en début de mot."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e12', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.suaal']::text[], 'fill_blank', 'lesson', 'سُ___ال', array['ؤَ']::text[], 'سُؤَال : la damma de س est la voyelle la plus forte, la hamza s''appuie donc sur و : ؤَ.', 3, '{"id": "ar.l22.e12", "unitIds": ["ar.g22.hamza_madda", "ar.v.suaal"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne syllabe.", "prompt": "سُ___ال", "promptLanguage": "ar", "answer": "ؤَ", "acceptedAnswers": ["ؤَ"], "explanation": "سُؤَال : la damma de س est la voyelle la plus forte, la hamza s''appuie donc sur و : ؤَ.", "tip": "Damma : ؤ.", "extraExample": {"text": "سُؤَال سَهْل.", "translation": "Une question facile."}, "options": ["ؤَ", "أَ", "ئِ"], "errorPatterns": [{"equals": "ئِ", "category": "spelling", "feedback": "ئ va avec une kasra : ici la voyelle la plus forte est la damma de س."}, {"equals": "أَ", "category": "spelling", "feedback": "Au milieu du mot, après une damma, la hamza s''appuie sur و."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e13', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.masaa']::text[], 'fill_blank', 'lesson', 'مَسَا___', array['ء']::text[], 'Après un ا long, à la fin du mot, la hamza s''écrit seule : ء.', 2, '{"id": "ar.l22.e13", "unitIds": ["ar.g22.hamza_madda", "ar.v.masaa"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la fin du mot.", "prompt": "مَسَا___", "promptLanguage": "ar", "answer": "ء", "acceptedAnswers": ["ء"], "explanation": "Après un ا long, à la fin du mot, la hamza s''écrit seule : ء.", "tip": "Après ا long : ء seule.", "extraExample": {"text": "مَسَاء الْخَيْر.", "translation": "Bonsoir."}, "options": ["أ", "ئ", "ء"], "errorPatterns": [{"equals": "أ", "category": "spelling", "feedback": "أ est pour le début du mot."}, {"equals": "ئ", "category": "spelling", "feedback": "ئ est pour une hamza avec kasra."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e14', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.amal']::text[], 'fill_blank', 'lesson', '___مَل', array['أَ']::text[], 'أَمَل : la hamza a une fatha, elle est donc au-dessus du ا : أَ.', 2, '{"id": "ar.l22.e14", "unitIds": ["ar.g22.hamza_madda", "ar.v.amal"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne syllabe.", "prompt": "___مَل", "promptLanguage": "ar", "answer": "أَ", "acceptedAnswers": ["أَ"], "explanation": "أَمَل : la hamza a une fatha, elle est donc au-dessus du ا : أَ.", "tip": "Fatha : au-dessus.", "extraExample": {"text": "عِنْدِي أَمَل.", "translation": "J''ai de l''espoir."}, "options": ["إِ", "أَ", "آ"], "errorPatterns": [{"equals": "إِ", "category": "spelling", "feedback": "إ est pour la kasra, sous le ا."}, {"equals": "آ", "category": "spelling", "feedback": "آ ajoute un a long : le mot n''en a pas ici."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e15', 'ar', 'ar.l22', 'ar.v.oda', array['ar.v.oda','ar.g22.hamza_madda']::text[], 'fill_blank', 'lesson', 'أُ___ضَة', array['و']::text[], 'أُوضَة : la damma de أُ est allongée par و, ce qui donne un ou long. C''est ton mot de tous les jours.', 2, '{"id": "ar.l22.e15", "unitIds": ["ar.v.oda", "ar.g22.hamza_madda"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « chambre ».", "prompt": "أُ___ضَة", "promptLanguage": "ar", "answer": "و", "acceptedAnswers": ["و"], "explanation": "أُوضَة : la damma de أُ est allongée par و, ce qui donne un ou long. C''est ton mot de tous les jours.", "tip": "Damma → و.", "extraExample": {"text": "أُوضَة كِبِيرَة.", "translation": "Une grande chambre."}, "options": ["ا", "و", "ي"], "errorPatterns": [{"equals": "ا", "category": "spelling", "feedback": "ا allonge une fatha, pas une damma."}, {"equals": "ي", "category": "spelling", "feedback": "ي allonge une kasra, pas une damma."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e16', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda']::text[], 'match', 'lesson', 'Les lettres de la hamza', '{}'::text[], 'أ : fatha ou damma. إ : kasra. ؤ : damma. ئ : kasra, au milieu du mot.', 1, '{"id": "ar.l22.e16", "unitIds": ["ar.g22.hamza_madda"], "type": "match", "difficulty": 1, "instruction": "Associe chaque lettre à son rôle.", "prompt": "Les lettres de la hamza", "promptLanguage": "fr", "answer": "أ = hamza sur ا, au-dessus ; إ = hamza sous ا ; ؤ = hamza sur و ; ئ = hamza sur ي sans points", "acceptedAnswers": [], "explanation": "أ : fatha ou damma. إ : kasra. ؤ : damma. ئ : kasra, au milieu du mot.", "pairs": [{"left": "أ", "right": "hamza sur ا, au-dessus"}, {"left": "إ", "right": "hamza sous ا"}, {"left": "ؤ", "right": "hamza sur و"}, {"left": "ئ", "right": "hamza sur ي sans points"}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e17', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.suaal','ar.v.raees','ar.v.masaa','ar.v.malaika']::text[], 'match', 'lesson', 'Mots avec hamza au milieu', '{}'::text[], 'Dans ces mots, la hamza est au milieu ou à la fin : ؤ, ئ, ء.', 2, '{"id": "ar.l22.e17", "unitIds": ["ar.g22.hamza_madda", "ar.v.suaal", "ar.v.raees", "ar.v.masaa", "ar.v.malaika"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots avec hamza au milieu", "promptLanguage": "fr", "answer": "سُؤَال = question ; رَئِيس = chef ; مَسَاء = soir ; مَلَائِكَة = anges", "acceptedAnswers": [], "explanation": "Dans ces mots, la hamza est au milieu ou à la fin : ؤ, ئ, ء.", "pairs": [{"left": "سُؤَال", "right": "question"}, {"left": "رَئِيس", "right": "chef"}, {"left": "مَسَاء", "right": "soir"}, {"left": "مَلَائِكَة", "right": "anges"}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
