insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e20', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.rabb']::text[], 'reorder', 'lesson', 'Seigneur, aie pitié', array['يَا رَبّ اِرْحَم']::text[], 'يَا رَبّ اِرْحَم : l''appel (يَا), le Seigneur (رَبّ), puis l''ordre « aie pitié » (اِرْحَم).', 3, '{"id": "ar.l22.e20", "unitIds": ["ar.g22.hamza_madda", "ar.v.rabb"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Seigneur, aie pitié", "promptLanguage": "fr", "answer": "يَا رَبّ اِرْحَم", "acceptedAnswers": ["يَا رَبّ اِرْحَم"], "explanation": "يَا رَبّ اِرْحَم : l''appel (يَا), le Seigneur (رَبّ), puis l''ordre « aie pitié » (اِرْحَم).", "tip": "On appelle d''abord, on demande ensuite.", "extraExample": {"text": "آمِين يَا رَبّ.", "translation": "Amen, Seigneur."}, "tokens": ["اِرْحَم", "يَا", "رَبّ"], "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
