insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e23', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.v.iman']::text[], 'free_answer', 'lesson', 'Que veut dire إِيمَان ?', array['foi','la foi','une foi','croyance']::text[], 'إِيمَان : إِ (hamza sous le ا, kasra) + ي (i long), م + a long, ن. C''est la foi.', 3, '{"id": "ar.l22.e23", "unitIds": ["ar.g22.hamza_madda", "ar.v.iman"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire إِيمَان ?", "promptLanguage": "fr", "answer": "foi", "acceptedAnswers": ["foi", "la foi", "une foi", "croyance"], "explanation": "إِيمَان : إِ (hamza sous le ا, kasra) + ي (i long), م + a long, ن. C''est la foi.", "tip": "Kasra : hamza sous le ا.", "extraExample": {"text": "الْإِيمَان بِالْمَسِيح.", "translation": "La foi au Christ."}, "errorPatterns": [{"equals": "espoir", "category": "word_confusion", "feedback": "L''espoir est أَمَل, avec أ au-dessus du ا."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e24', 'ar', 'ar.l22', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda']::text[], 'free_answer', 'lesson', 'Comment s''appelle la petite vague posée sur le ا dans آ ?', array['madda','la madda']::text[], 'C''est la madda (مَدَّة, « allongement ») : elle donne un coup de gorge suivi d''un a long.', 2, '{"id": "ar.l22.e24", "unitIds": ["ar.g22.hamza_madda"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Comment s''appelle la petite vague posée sur le ا dans آ ?", "promptLanguage": "fr", "answer": "madda", "acceptedAnswers": ["madda", "la madda"], "explanation": "C''est la madda (مَدَّة, « allongement ») : elle donne un coup de gorge suivi d''un a long.", "tip": "Madda = coup de gorge + a long.", "extraExample": {"text": "آمِين", "translation": "amen"}, "errorPatterns": [{"equals": "chadda", "category": "word_confusion", "feedback": "La chadda est un petit w qui double une lettre. La madda est une petite vague sur le ا."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e01', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon']::text[], 'mcq', 'lesson', 'Rappel : que veut dire ال devant un nom ?', array['le, la, les']::text[], 'ال est l''article défini : il veut dire le, la ou les.', 1, '{"id": "ar.l23.e01", "unitIds": ["ar.g23.article_sun_moon"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Rappel : que veut dire ال devant un nom ?", "promptLanguage": "fr", "answer": "le, la, les", "acceptedAnswers": ["le, la, les"], "explanation": "ال est l''article défini : il veut dire le, la ou les.", "tip": "ال est collé au nom.", "extraExample": {"text": "الْكَنِيسَة", "translation": "l''église"}, "options": ["le, la, les", "de, du", "un, une"], "errorPatterns": [{"equals": "un, une", "category": "spelling", "feedback": "Un, une (article indéfini) ne s''écrit pas en arabe : on laisse le nom seul."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e02', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon']::text[], 'mcq', 'lesson', 'Devant une lettre lunaire, que fait le ل de ال ?', array['le ل se dit']::text[], 'Devant une lettre lunaire, le ل se dit : on lui met un soukoun. Seules les solaires l''effacent.', 1, '{"id": "ar.l23.e02", "unitIds": ["ar.g23.article_sun_moon"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Devant une lettre lunaire, que fait le ل de ال ?", "promptLanguage": "fr", "answer": "le ل se dit", "acceptedAnswers": ["le ل se dit"], "explanation": "Devant une lettre lunaire, le ل se dit : on lui met un soukoun. Seules les solaires l''effacent.", "tip": "Lune : le ل reste.", "extraExample": {"text": "الْقَمَر", "translation": "la lune"}, "options": ["le ل s''efface", "le ل se double", "le ل se dit"], "errorPatterns": [{"equals": "le ل s''efface", "category": "spelling", "feedback": "C''est le cas des lettres solaires, avec une chadda."}, {"equals": "le ل se double", "category": "spelling", "feedback": "Le ل ne se double jamais : c''est la lettre qui suit qui se double, devant les solaires."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e03', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon']::text[], 'mcq', 'lesson', 'Devant une lettre solaire, que devient le ل de ال ?', array['le ل s''efface']::text[], 'Devant une lettre solaire, le ل s''efface et la lettre est doublée par une chadda : الشَّمْس.', 1, '{"id": "ar.l23.e03", "unitIds": ["ar.g23.article_sun_moon"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Devant une lettre solaire, que devient le ل de ال ?", "promptLanguage": "fr", "answer": "le ل s''efface", "acceptedAnswers": ["le ل s''efface"], "explanation": "Devant une lettre solaire, le ل s''efface et la lettre est doublée par une chadda : الشَّمْس.", "tip": "Soleil : le ل disparaît.", "extraExample": {"text": "الشَّمْس", "translation": "le soleil"}, "options": ["le ل se dit", "le ل s''efface", "le ل porte une madda"], "errorPatterns": [{"equals": "le ل se dit", "category": "spelling", "feedback": "C''est le cas des lettres lunaires, avec un soukoun."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e04', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon']::text[], 'mcq', 'lesson', 'Comment reconnaît-on une lettre solaire dans un texte vocalisé ?', array['elle porte une chadda']::text[], 'Une lettre solaire est doublée : elle porte une chadda juste après ال. Le soukoun sur ل annonce, lui, une lettre lunaire.', 2, '{"id": "ar.l23.e04", "unitIds": ["ar.g23.article_sun_moon"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Comment reconnaît-on une lettre solaire dans un texte vocalisé ?", "promptLanguage": "fr", "answer": "elle porte une chadda", "acceptedAnswers": ["elle porte une chadda"], "explanation": "Une lettre solaire est doublée : elle porte une chadda juste après ال. Le soukoun sur ل annonce, lui, une lettre lunaire.", "tip": "Chadda après ال = soleil.", "extraExample": {"text": "الرَّبّ", "translation": "le Seigneur"}, "options": ["elle porte une madda", "elle porte une chadda", "le ل porte un soukoun"], "errorPatterns": [{"equals": "le ل porte un soukoun", "category": "spelling", "feedback": "Le soukoun sur ل annonce une lettre lunaire."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e05', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon','ar.v.el_ard']::text[], 'mcq', 'lesson', 'الْأَرْض', array['la terre']::text[], 'ال, puis أَرْض : le ل porte un soukoun car أ est lunaire. C''est la terre.', 2, '{"id": "ar.l23.e05", "unitIds": ["ar.g23.article_sun_moon", "ar.v.el_ard"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "الْأَرْض", "promptLanguage": "ar", "answer": "la terre", "acceptedAnswers": ["la terre"], "explanation": "ال, puis أَرْض : le ل porte un soukoun car أ est lunaire. C''est la terre.", "tip": "Soukoun sur ل : lunaire.", "extraExample": {"text": "السَّمَا وَالْأَرْض.", "translation": "Le ciel et la terre."}, "options": ["le peuple", "la terre", "le ciel", "le monde"], "errorPatterns": [{"equals": "le ciel", "category": "word_confusion", "feedback": "Le ciel est السَّمَاء : le س y est doublé."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e06', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon','ar.v.el_sama']::text[], 'mcq', 'lesson', 'السَّمَاء', array['le ciel']::text[], 'ال, puis سَّ doublé, puis مَاء : le ل s''efface devant س solaire. C''est le ciel.', 2, '{"id": "ar.l23.e06", "unitIds": ["ar.g23.article_sun_moon", "ar.v.el_sama"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "السَّمَاء", "promptLanguage": "ar", "answer": "le ciel", "acceptedAnswers": ["le ciel"], "explanation": "ال, puis سَّ doublé, puis مَاء : le ل s''efface devant س solaire. C''est le ciel.", "tip": "Chadda après ال : solaire.", "extraExample": {"text": "السَّمَاء زَرْقَا.", "translation": "Le ciel est bleu."}, "options": ["la Parole", "l''autel", "le ciel", "la terre"], "errorPatterns": [{"equals": "la terre", "category": "word_confusion", "feedback": "La terre est الْأَرْض : son ل porte un soukoun."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e07', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon','ar.v.el_dunya']::text[], 'mcq', 'lesson', 'Dans الدُّنْيَا, la lettre د est…', array['solaire']::text[], 'د porte une chadda, c''est une lettre solaire : le ل s''efface et le د est doublé.', 3, '{"id": "ar.l23.e07", "unitIds": ["ar.g23.article_sun_moon", "ar.v.el_dunya"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Dans الدُّنْيَا, la lettre د est…", "promptLanguage": "fr", "answer": "solaire", "acceptedAnswers": ["solaire"], "explanation": "د porte une chadda, c''est une lettre solaire : le ل s''efface et le د est doublé.", "tip": "Chadda = solaire.", "extraExample": {"text": "الدُّنْيَا حَرّ.", "translation": "Il fait chaud."}, "options": ["lunaire", "solaire", "muette"], "errorPatterns": [{"equals": "lunaire", "category": "spelling", "feedback": "Une lettre lunaire n''a pas de chadda : le ل porterait un soukoun."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
