insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e09', 'ar', 'ar.l23', 'ar.v.qamar', array['ar.v.qamar','ar.g23.article_sun_moon']::text[], 'mcq', 'lesson', 'Dans الْقَمَر, la lettre ق est…', array['lunaire']::text[], 'Le ل a un soukoun et ق ne porte pas de chadda : ق est lunaire, comme dans le nom de la lune.', 1, '{"id": "ar.l23.e09", "unitIds": ["ar.v.qamar", "ar.g23.article_sun_moon"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Dans الْقَمَر, la lettre ق est…", "promptLanguage": "fr", "answer": "lunaire", "acceptedAnswers": ["lunaire"], "explanation": "Le ل a un soukoun et ق ne porte pas de chadda : ق est lunaire, comme dans le nom de la lune.", "tip": "Lune : ق lunaire.", "extraExample": {"text": "الْقَمَر طَالِع.", "translation": "La lune est levée."}, "options": ["solaire", "lunaire", "muette"], "errorPatterns": [{"equals": "solaire", "category": "spelling", "feedback": "Une lettre solaire porterait une chadda : ici le ق n''en a pas."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e10', 'ar', 'ar.l23', 'ar.v.shams', array['ar.v.shams','ar.g23.article_sun_moon']::text[], 'mcq', 'lesson', 'Dans الشَّمْس, la lettre ش est…', array['solaire']::text[], 'ش porte une chadda et le ل n''a pas de signe : ش est solaire, comme dans le nom du soleil.', 1, '{"id": "ar.l23.e10", "unitIds": ["ar.v.shams", "ar.g23.article_sun_moon"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Dans الشَّمْس, la lettre ش est…", "promptLanguage": "fr", "answer": "solaire", "acceptedAnswers": ["solaire"], "explanation": "ش porte une chadda et le ل n''a pas de signe : ش est solaire, comme dans le nom du soleil.", "tip": "Soleil : ش solaire.", "extraExample": {"text": "الشَّمْس حَامْيَة.", "translation": "Le soleil est brûlant."}, "options": ["lunaire", "solaire", "muette"], "errorPatterns": [{"equals": "lunaire", "category": "spelling", "feedback": "Une lettre lunaire n''a pas de chadda : ici ش en porte une."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e11', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon','ar.v.el_sama']::text[], 'fill_blank', 'lesson', 'ال___مَاء', array['سَّ']::text[], 'Devant ا, ل puis س solaire : le س porte une chadda. On lit un س doublé : السَّمَاء.', 2, '{"id": "ar.l23.e11", "unitIds": ["ar.g23.article_sun_moon", "ar.v.el_sama"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot.", "prompt": "ال___مَاء", "promptLanguage": "ar", "answer": "سَّ", "acceptedAnswers": ["سَّ"], "explanation": "Devant ا, ل puis س solaire : le س porte une chadda. On lit un س doublé : السَّمَاء.", "tip": "Solaire : chadda.", "extraExample": {"text": "السَّمَاء زَرْقَا.", "translation": "Le ciel est bleu."}, "options": ["سَّ", "سَ", "سْ"], "errorPatterns": [{"equals": "سْ", "category": "spelling", "feedback": "Le soukoun dit « aucune voyelle » : ici le س est doublé."}, {"equals": "سَ", "category": "spelling", "feedback": "Il manque la chadda : le س est solaire."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e12', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon','ar.v.el_qummus']::text[], 'fill_blank', 'lesson', 'الْ___مُّص', array['قُ']::text[], 'ق est lunaire : pas de chadda sur lui, le ل garde son soukoun. On lit قُ, puis م doublé : الْقُمُّص.', 2, '{"id": "ar.l23.e12", "unitIds": ["ar.g23.article_sun_moon", "ar.v.el_qummus"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot.", "prompt": "الْ___مُّص", "promptLanguage": "ar", "answer": "قُ", "acceptedAnswers": ["قُ"], "explanation": "ق est lunaire : pas de chadda sur lui, le ل garde son soukoun. On lit قُ, puis م doublé : الْقُمُّص.", "tip": "Lunaire : le ل se dit.", "extraExample": {"text": "الْقُمُّص جَاي.", "translation": "L''archiprêtre arrive."}, "options": ["قُ", "قْ", "قَّ"], "errorPatterns": [{"equals": "قَّ", "category": "spelling", "feedback": "La chadda va avec les solaires : ق est lunaire. Ici la chadda est sur م, plus loin."}, {"equals": "قْ", "category": "spelling", "feedback": "Le قْ n''a pas de voyelle : mais ici on lit قُ."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e13', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon','ar.v.el_dunya']::text[], 'fill_blank', 'lesson', 'ال___نْيَا', array['دُّ']::text[], 'د est solaire : il porte une chadda, avec une damma. On lit un د doublé : الدُّنْيَا.', 3, '{"id": "ar.l23.e13", "unitIds": ["ar.g23.article_sun_moon", "ar.v.el_dunya"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète le mot.", "prompt": "ال___نْيَا", "promptLanguage": "ar", "answer": "دُّ", "acceptedAnswers": ["دُّ"], "explanation": "د est solaire : il porte une chadda, avec une damma. On lit un د doublé : الدُّنْيَا.", "tip": "Solaire : chadda + voyelle.", "extraExample": {"text": "الدُّنْيَا صُغَيَّرَة.", "translation": "Le monde est petit."}, "options": ["دْ", "دُّ", "دُ"], "errorPatterns": [{"equals": "دْ", "category": "spelling", "feedback": "Le soukoun dit « aucune voyelle » : ici le د est doublé."}, {"equals": "دُ", "category": "spelling", "feedback": "Il manque la chadda : le د est solaire."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
