insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e19', 'ar', 'ar.l23', 'ar.v.kanisa', array['ar.v.kanisa','ar.g23.article_sun_moon','ar.v.masih','ar.v.adra','ar.v.salib']::text[], 'match', 'lesson', 'Mots de m02, avec ال', '{}'::text[], 'Ce sont des mots de m02, maintenant vocalisés : ك م ع sont lunaires, ص solaire.', 2, '{"id": "ar.l23.e19", "unitIds": ["ar.v.kanisa", "ar.g23.article_sun_moon", "ar.v.masih", "ar.v.adra", "ar.v.salib"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots de m02, avec ال", "promptLanguage": "fr", "answer": "الْكَنِيسَة = l''église ; الْمَسِيح = le Christ ; الْعَدْرَا = la Vierge Marie ; الصَّلِيب = la croix", "acceptedAnswers": [], "explanation": "Ce sont des mots de m02, maintenant vocalisés : ك م ع sont lunaires, ص solaire.", "pairs": [{"left": "الْكَنِيسَة", "right": "l''église"}, {"left": "الْمَسِيح", "right": "le Christ"}, {"left": "الْعَدْرَا", "right": "la Vierge Marie"}, {"left": "الصَّلِيب", "right": "la croix"}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e20', 'ar', 'ar.l23', 'ar.v.dayiman', array['ar.v.dayiman','ar.g23.article_sun_moon']::text[], 'reorder', 'lesson', 'Gloire à Dieu toujours', array['الْمَجْد لِلَّه دَايِمًا']::text[], 'الْمَجْد لِلَّه دَايِمًا : d''abord le mot avec ال (la gloire), puis « à Dieu », puis « toujours ».', 3, '{"id": "ar.l23.e20", "unitIds": ["ar.v.dayiman", "ar.g23.article_sun_moon"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Gloire à Dieu toujours", "promptLanguage": "fr", "answer": "الْمَجْد لِلَّه دَايِمًا", "acceptedAnswers": ["الْمَجْد لِلَّه دَايِمًا"], "explanation": "الْمَجْد لِلَّه دَايِمًا : d''abord le mot avec ال (la gloire), puis « à Dieu », puis « toujours ».", "tip": "ال ouvre la phrase.", "extraExample": {"text": "الْمَجْد لِلَّه.", "translation": "Gloire à Dieu."}, "tokens": ["دَايِمًا", "لِلَّه", "الْمَجْد"], "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e21', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon','ar.v.el_kalima']::text[], 'translation', 'lesson', 'الْكَلِمَة', array['parole','la parole','le mot','mot','verbe','le verbe']::text[], 'الْكَلِمَة : ال avec soukoun, puis كَلِمَة. Le mot, et dans l''Évangile la Parole : le Christ.', 2, '{"id": "ar.l23.e21", "unitIds": ["ar.g23.article_sun_moon", "ar.v.el_kalima"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "الْكَلِمَة", "promptLanguage": "ar", "answer": "parole", "acceptedAnswers": ["parole", "la parole", "le mot", "mot", "verbe", "le verbe"], "explanation": "الْكَلِمَة : ال avec soukoun, puis كَلِمَة. Le mot, et dans l''Évangile la Parole : le Christ.", "tip": "Lunaire : le ل se dit.", "extraExample": {"text": "كَلِمَة حَلْوَة.", "translation": "Un mot doux."}, "errorPatterns": [{"equals": "terre", "category": "word_confusion", "feedback": "La terre est الْأَرْض."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e22', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon','ar.v.el_usquf']::text[], 'translation', 'lesson', 'الْأُسْقُف', array['évêque','l''évêque','un évêque']::text[], 'الْأُسْقُف : ال, puis أُسْقُف. Le ل porte un soukoun car أ est lunaire. C''est l''évêque.', 3, '{"id": "ar.l23.e22", "unitIds": ["ar.g23.article_sun_moon", "ar.v.el_usquf"], "type": "translation", "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "الْأُسْقُف", "promptLanguage": "ar", "answer": "évêque", "acceptedAnswers": ["évêque", "l''évêque", "un évêque"], "explanation": "الْأُسْقُف : ال, puis أُسْقُف. Le ل porte un soukoun car أ est lunaire. C''est l''évêque.", "tip": "Lunaire : le ل se dit.", "extraExample": {"text": "زِيَارَة الْأُسْقُف.", "translation": "La visite de l''évêque."}, "errorPatterns": [{"equals": "prêtre", "category": "word_confusion", "feedback": "Le prêtre est كَاهِن ou أَبُونَا : ici tu lis الْأُسْقُف."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e23', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon','ar.v.el_shaab']::text[], 'free_answer', 'lesson', 'Que veut dire الشَّعْب ?', array['peuple','le peuple','assemblée','l''assemblée','foule']::text[], 'الشَّعْب : ال, puis ش solaire doublé, ع sans voyelle, ب. Le peuple, l''assemblée.', 3, '{"id": "ar.l23.e23", "unitIds": ["ar.g23.article_sun_moon", "ar.v.el_shaab"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire الشَّعْب ?", "promptLanguage": "fr", "answer": "peuple", "acceptedAnswers": ["peuple", "le peuple", "assemblée", "l''assemblée", "foule"], "explanation": "الشَّعْب : ال, puis ش solaire doublé, ع sans voyelle, ب. Le peuple, l''assemblée.", "tip": "Chadda après ال : solaire.", "extraExample": {"text": "الشَّعْب بِيَرُدّ: آمِين.", "translation": "L''assemblée répond : amen."}, "errorPatterns": [{"equals": "monde", "category": "word_confusion", "feedback": "Le monde est الدُّنْيَا."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e24', 'ar', 'ar.l23', 'ar.g23.article_sun_moon', array['ar.g23.article_sun_moon']::text[], 'free_answer', 'lesson', 'Combien y a-t-il de lettres solaires ?', array['14','quatorze']::text[], 'Il y a 14 lettres solaires et 14 lettres lunaires : 28 lettres en tout.', 2, '{"id": "ar.l23.e24", "unitIds": ["ar.g23.article_sun_moon"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse en chiffres.", "prompt": "Combien y a-t-il de lettres solaires ?", "promptLanguage": "fr", "answer": "14", "acceptedAnswers": ["14", "quatorze"], "explanation": "Il y a 14 lettres solaires et 14 lettres lunaires : 28 lettres en tout.", "tip": "14 + 14 = 28.", "extraExample": {"text": "الشَّمْس", "translation": "le soleil"}, "errorPatterns": [{"equals": "28", "category": "instruction", "feedback": "28, c''est le total des lettres de l''alphabet. Les solaires en sont la moitié."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e01', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura']::text[], 'mcq', 'lesson', 'Dans قَهْوَة, d''où vient le a de la fin ?', array['de la fatha sur و']::text[], 'ة est muette : le a final vient de la fatha sur و, juste avant elle.', 1, '{"id": "ar.l24.e01", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Dans قَهْوَة, d''où vient le a de la fin ?", "promptLanguage": "fr", "answer": "de la fatha sur و", "acceptedAnswers": ["de la fatha sur و"], "explanation": "ة est muette : le a final vient de la fatha sur و, juste avant elle.", "tip": "Cherche la fatha avant ة.", "extraExample": {"text": "كَنِيسَة", "translation": "église : le a vient de la fatha sur س"}, "options": ["d''un ا caché", "du ة lui-même", "de la fatha sur و"], "errorPatterns": [{"equals": "du ة lui-même", "category": "spelling", "feedback": "ة ne se dit pas à part : c''est la fatha d''avant qui donne le a."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e02', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura']::text[], 'mcq', 'lesson', 'Comment se lit ى à la fin d''un mot ?', array['a long']::text[], 'Après une fatha, ى donne un a long : مُوسَى. Le i long vient d''un ي avec ses points après une kasra.', 1, '{"id": "ar.l24.e02", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura"], "type": "mcq", "difficulty": 1, "instruction": "Réponds.", "prompt": "Comment se lit ى à la fin d''un mot ?", "promptLanguage": "fr", "answer": "a long", "acceptedAnswers": ["a long"], "explanation": "Après une fatha, ى donne un a long : مُوسَى. Le i long vient d''un ي avec ses points après une kasra.", "tip": "ى = a long.", "extraExample": {"text": "مَتَّى", "translation": "Matthieu"}, "options": ["ou long", "i long", "a long"], "errorPatterns": [{"equals": "i long", "category": "spelling", "feedback": "Le i long vient de ي avec une kasra avant."}, {"equals": "ou long", "category": "spelling", "feedback": "Le ou long vient de و avec une damma avant."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e03', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura']::text[], 'mcq', 'lesson', 'Comment reconnaît-on ى ?', array['ى est un ي sans ses deux points']::text[], 'ى est un ي dont on a enlevé les 2 points, et il n''est qu''à la fin des mots.', 2, '{"id": "ar.l24.e03", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura"], "type": "mcq", "difficulty": 2, "instruction": "Réponds.", "prompt": "Comment reconnaît-on ى ?", "promptLanguage": "fr", "answer": "ى est un ي sans ses deux points", "acceptedAnswers": ["ى est un ي sans ses deux points"], "explanation": "ى est un ي dont on a enlevé les 2 points, et il n''est qu''à la fin des mots.", "tip": "Pas de points : alif maqsûra.", "extraExample": {"text": "مُوسَى", "translation": "Moïse"}, "options": ["ى est un ي sans ses deux points", "ى est un ا courbé", "ى est un ي avec un point en plus"], "errorPatterns": [{"equals": "ى est un ا courbé", "category": "spelling", "feedback": "Le ا est un bâton droit ; ى garde la forme d''un ي."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e04', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.rahma']::text[], 'mcq', 'lesson', 'رَحْمَة', array['miséricorde']::text[], 'ر + a, ح sans voyelle, م + a, ة muette : la miséricorde. C''est ce qu''on demande avec يَا رَبّ اِرْحَم.', 2, '{"id": "ar.l24.e04", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.rahma"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "رَحْمَة", "promptLanguage": "ar", "answer": "miséricorde", "acceptedAnswers": ["miséricorde"], "explanation": "ر + a, ح sans voyelle, م + a, ة muette : la miséricorde. C''est ce qu''on demande avec يَا رَبّ اِرْحَم.", "tip": "Fatha avant ة : le a final.", "extraExample": {"text": "رَحْمَة رَبِّنَا وَاسْعَة.", "translation": "La miséricorde de notre Seigneur est vaste."}, "options": ["bénédiction", "joie", "résurrection", "miséricorde"], "errorPatterns": [{"equals": "bénédiction", "category": "word_confusion", "feedback": "La bénédiction est بَرَكَة : trois fathas."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e05', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.qiyama']::text[], 'mcq', 'lesson', 'قِيَامَة', array['résurrection']::text[], 'ق + i, ي + a long (ي consonne avec fatha, puis ا), م + a, ة muette : la résurrection, la fête de Pâques.', 3, '{"id": "ar.l24.e05", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.qiyama"], "type": "mcq", "difficulty": 3, "instruction": "Lis le mot et choisis son sens.", "prompt": "قِيَامَة", "promptLanguage": "ar", "answer": "résurrection", "acceptedAnswers": ["résurrection"], "explanation": "ق + i, ي + a long (ي consonne avec fatha, puis ا), م + a, ة muette : la résurrection, la fête de Pâques.", "tip": "Le ي porte une fatha : c''est une consonne.", "extraExample": {"text": "عِيد الْقِيَامَة.", "translation": "La fête de la Résurrection."}, "options": ["prière", "miséricorde", "église", "résurrection"], "errorPatterns": [{"equals": "prière", "category": "word_confusion", "feedback": "La prière est صَلَاة : un autre mot."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e06', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.musa']::text[], 'mcq', 'lesson', 'مُوسَى', array['Moïse']::text[], 'م + ou long (damma + و), س + a long final (fatha + ى) : Moïse, le prophète.', 2, '{"id": "ar.l24.e06", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.musa"], "type": "mcq", "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "مُوسَى", "promptLanguage": "ar", "answer": "Moïse", "acceptedAnswers": ["Moïse"], "explanation": "م + ou long (damma + و), س + a long final (fatha + ى) : Moïse, le prophète.", "tip": "ى final : a long.", "extraExample": {"text": "جَبَل مُوسَى.", "translation": "Le mont de Moïse."}, "options": ["Moïse", "Adam", "Jean", "Matthieu"], "errorPatterns": [{"equals": "Matthieu", "category": "word_confusion", "feedback": "Matthieu est مَتَّى : avec un ت doublé."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e07', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.yohanna']::text[], 'mcq', 'lesson', 'يُوحَنَّا', array['Jean']::text[], 'ي + ou long, ح + a, ن doublé + a long final, écrit ici avec un ا : Jean.', 3, '{"id": "ar.l24.e07", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.yohanna"], "type": "mcq", "difficulty": 3, "instruction": "Lis le mot et choisis son sens.", "prompt": "يُوحَنَّا", "promptLanguage": "ar", "answer": "Jean", "acceptedAnswers": ["Jean"], "explanation": "ي + ou long, ح + a, ن doublé + a long final, écrit ici avec un ا : Jean.", "tip": "Un a long final peut s''écrire ا.", "extraExample": {"text": "إِنْجِيل يُوحَنَّا.", "translation": "L''Évangile selon Jean."}, "options": ["Moïse", "Matthieu", "Jean", "Abraham"], "errorPatterns": [{"equals": "Moïse", "category": "word_confusion", "feedback": "Moïse est مُوسَى, avec un ى final."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e08', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura']::text[], 'mcq', 'lesson', 'Dans مَلَائِكَة, quelle voyelle précède ة ?', array['la fatha']::text[], 'ة est toujours précédée d''une fatha (ou d''un ا long) : ici celle de ك.', 3, '{"id": "ar.l24.e08", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura"], "type": "mcq", "difficulty": 3, "instruction": "Réponds.", "prompt": "Dans مَلَائِكَة, quelle voyelle précède ة ?", "promptLanguage": "fr", "answer": "la fatha", "acceptedAnswers": ["la fatha"], "explanation": "ة est toujours précédée d''une fatha (ou d''un ا long) : ici celle de ك.", "tip": "ة : toujours après une fatha.", "extraExample": {"text": "رَحْمَة", "translation": "miséricorde"}, "options": ["la fatha", "la kasra", "la damma"], "errorPatterns": [{"equals": "la kasra", "category": "spelling", "feedback": "La kasra de مَلَائِكَة est sous la hamza ئ, pas sous ك."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e09', 'ar', 'ar.l24', 'ar.v.kanisa', array['ar.v.kanisa','ar.g24.ta_marbuta_alif_maqsura']::text[], 'mcq', 'lesson', 'كَنِيسَة', array['église']::text[], 'ك + a, ن + i long, س + a, ة muette : l''église. Le mot que tu lisais كنيسة.', 1, '{"id": "ar.l24.e09", "unitIds": ["ar.v.kanisa", "ar.g24.ta_marbuta_alif_maqsura"], "type": "mcq", "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "كَنِيسَة", "promptLanguage": "ar", "answer": "église", "acceptedAnswers": ["église"], "explanation": "ك + a, ن + i long, س + a, ة muette : l''église. Le mot que tu lisais كنيسة.", "tip": "Dis le mot tout haut : ton oreille le reconnaît.", "extraExample": {"text": "كَنِيسَة الْعَدْرَا", "translation": "l''église de la Vierge"}, "options": ["chambre", "école", "maison", "église"], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e10', 'ar', 'ar.l24', 'ar.v.qahwa', array['ar.v.qahwa','ar.g24.ta_marbuta_alif_maqsura']::text[], 'mcq', 'lesson', 'قَهْوَة', array['café (boisson)']::text[], 'ق + a, ه sans voyelle, و + a, ة muette : le café que l''on boit. Le café en grains est بُنّ.', 1, '{"id": "ar.l24.e10", "unitIds": ["ar.v.qahwa", "ar.g24.ta_marbuta_alif_maqsura"], "type": "mcq", "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "قَهْوَة", "promptLanguage": "ar", "answer": "café (boisson)", "acceptedAnswers": ["café (boisson)"], "explanation": "ق + a, ه sans voyelle, و + a, ة muette : le café que l''on boit. Le café en grains est بُنّ.", "tip": "Le a final vient de la fatha sur و.", "extraExample": {"text": "قَهْوَة سَادَة", "translation": "un café sans sucre"}, "options": ["thé", "café (grains)", "café (boisson)", "lait"], "errorPatterns": [{"equals": "café (grains)", "category": "word_confusion", "feedback": "Le café en grains est بُنّ, avec une chadda."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e11', 'ar', 'ar.l24', 'ar.g21.tanwin', array['ar.g21.tanwin','ar.g24.ta_marbuta_alif_maqsura']::text[], 'mcq', 'lesson', 'Lequel de ces mots se termine par le son an ?', array['دَايِمًا']::text[], 'دَايِمًا se termine par le tanwin fatha (ـًا) : an. شَجَرَة finit par ة muette, مُوسَى par un a long.', 2, '{"id": "ar.l24.e11", "unitIds": ["ar.g21.tanwin", "ar.g24.ta_marbuta_alif_maqsura"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se termine par le son an ?", "promptLanguage": "fr", "answer": "دَايِمًا", "acceptedAnswers": ["دَايِمًا"], "explanation": "دَايِمًا se termine par le tanwin fatha (ـًا) : an. شَجَرَة finit par ة muette, مُوسَى par un a long.", "tip": "Deux fathas : an.", "extraExample": {"text": "الْمَجْد لِلَّه دَايِمًا.", "translation": "Gloire à Dieu toujours."}, "options": ["شَجَرَة", "دَايِمًا", "مُوسَى"], "errorPatterns": [{"equals": "شَجَرَة", "category": "spelling", "feedback": "ة est muette : elle donne un simple a, sans n."}, {"equals": "مُوسَى", "category": "spelling", "feedback": "ى donne un a long, sans n."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e12', 'ar', 'ar.l24', 'ar.g22.hamza_madda', array['ar.g22.hamza_madda','ar.g24.ta_marbuta_alif_maqsura']::text[], 'mcq', 'lesson', 'Lequel de ces mots commence par un coup de gorge + a long ?', array['آمِين']::text[], 'آ (madda) donne un coup de gorge suivi d''un a long. أَبُونَا a un coup de gorge + a bref, إِيمَان un coup de gorge + i.', 2, '{"id": "ar.l24.e12", "unitIds": ["ar.g22.hamza_madda", "ar.g24.ta_marbuta_alif_maqsura"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots commence par un coup de gorge + a long ?", "promptLanguage": "fr", "answer": "آمِين", "acceptedAnswers": ["آمِين"], "explanation": "آ (madda) donne un coup de gorge suivi d''un a long. أَبُونَا a un coup de gorge + a bref, إِيمَان un coup de gorge + i.", "tip": "Madda = coup de gorge + a long.", "extraExample": {"text": "آدَم", "translation": "Adam"}, "options": ["إِيمَان", "أَبُونَا", "آمِين"], "errorPatterns": [{"equals": "أَبُونَا", "category": "spelling", "feedback": "Ici la hamza a une fatha : coup de gorge + a bref."}, {"equals": "إِيمَان", "category": "spelling", "feedback": "Ici la hamza a une kasra : coup de gorge + i."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e13', 'ar', 'ar.l24', 'ar.v.qahwa', array['ar.v.qahwa','ar.g24.ta_marbuta_alif_maqsura']::text[], 'fill_blank', 'lesson', 'قَهْوَ___', array['ة']::text[], 'قَهْوَة se termine par ة, le ت attaché au ه : deux points dessus. Le a final est celui de la fatha sur و.', 1, '{"id": "ar.l24.e13", "unitIds": ["ar.v.qahwa", "ar.g24.ta_marbuta_alif_maqsura"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète le mot « café ».", "prompt": "قَهْوَ___", "promptLanguage": "ar", "answer": "ة", "acceptedAnswers": ["ة"], "explanation": "قَهْوَة se termine par ة, le ت attaché au ه : deux points dessus. Le a final est celui de la fatha sur و.", "tip": "ة : deux points dessus.", "extraExample": {"text": "قَهْوَة سَادَة", "translation": "un café sans sucre"}, "options": ["ت", "ة", "ه"], "errorPatterns": [{"equals": "ه", "category": "spelling", "feedback": "ه n''a pas de points : ce n''est pas le ة du féminin."}, {"equals": "ت", "category": "spelling", "feedback": "ت a deux points mais ne se termine pas ainsi : le mot féminin finit par ة."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e14', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.musa']::text[], 'fill_blank', 'lesson', 'مُوسَ___', array['ى']::text[], 'Moïse s''écrit avec un ى final, sans points, après la fatha de س.', 2, '{"id": "ar.l24.e14", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.musa"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le nom « Moïse ».", "prompt": "مُوسَ___", "promptLanguage": "ar", "answer": "ى", "acceptedAnswers": ["ى"], "explanation": "Moïse s''écrit avec un ى final, sans points, après la fatha de س.", "tip": "Moïse : ى.", "extraExample": {"text": "مُوسَى النَّبِي.", "translation": "Moïse le prophète."}, "options": ["ى", "ي", "ا"], "errorPatterns": [{"equals": "ي", "category": "spelling", "feedback": "ي aurait deux points, et suivrait une kasra : ici c''est un ى après une fatha."}, {"equals": "ا", "category": "spelling", "feedback": "Moïse s''écrit avec un ى, alors que Jean s''écrit avec un ا."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e15', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.yohanna']::text[], 'fill_blank', 'lesson', 'يُوحَنَّ___', array['ا']::text[], 'Jean s''écrit avec un ا final, bien que le son soit le même qu''avec ى. On apprend chaque nom tel qu''il est écrit.', 3, '{"id": "ar.l24.e15", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.yohanna"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète le nom « Jean ».", "prompt": "يُوحَنَّ___", "promptLanguage": "ar", "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "Jean s''écrit avec un ا final, bien que le son soit le même qu''avec ى. On apprend chaque nom tel qu''il est écrit.", "tip": "Jean : ا ; Moïse : ى.", "extraExample": {"text": "يُوحَنَّا الْحَبِيب.", "translation": "Jean le bien-aimé."}, "options": ["ا", "ي", "ى"], "errorPatterns": [{"equals": "ى", "category": "spelling", "feedback": "C''est Moïse qui prend ى. Jean prend un ا."}, {"equals": "ي", "category": "spelling", "feedback": "ي aurait deux points et suivrait une kasra."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e16', 'ar', 'ar.l24', 'ar.v.kursi', array['ar.v.kursi','ar.g24.ta_marbuta_alif_maqsura']::text[], 'fill_blank', 'lesson', 'كُرْسِ___', array['ي']::text[], 'Après la kasra sous س, un ي final donne un i long : كُرْسِي. Avec un ى, on lirait un a long.', 3, '{"id": "ar.l24.e16", "unitIds": ["ar.v.kursi", "ar.g24.ta_marbuta_alif_maqsura"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète le mot « chaise ».", "prompt": "كُرْسِ___", "promptLanguage": "ar", "answer": "ي", "acceptedAnswers": ["ي"], "explanation": "Après la kasra sous س, un ي final donne un i long : كُرْسِي. Avec un ى, on lirait un a long.", "tip": "Kasra + ي : i long.", "extraExample": {"text": "كُرْسِي", "translation": "chaise"}, "options": ["ا", "ي", "ى"], "errorPatterns": [{"equals": "ى", "category": "spelling", "feedback": "ى va avec une fatha. Après la kasra de س, il faut ي."}, {"equals": "ا", "category": "spelling", "feedback": "ا allonge une fatha ; après une kasra, c''est ي."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e17', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.rahma','ar.v.qiyama','ar.v.baraka','ar.v.farha','ar.v.shagara']::text[], 'match', 'lesson', 'Mots en ة', '{}'::text[], 'Tous finissent par ة muette, après une fatha.', 2, '{"id": "ar.l24.e17", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.rahma", "ar.v.qiyama", "ar.v.baraka", "ar.v.farha", "ar.v.shagara"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots en ة", "promptLanguage": "fr", "answer": "رَحْمَة = miséricorde ; قِيَامَة = résurrection ; بَرَكَة = bénédiction ; فَرْحَة = joie ; شَجَرَة = arbre", "acceptedAnswers": [], "explanation": "Tous finissent par ة muette, après une fatha.", "pairs": [{"left": "رَحْمَة", "right": "miséricorde"}, {"left": "قِيَامَة", "right": "résurrection"}, {"left": "بَرَكَة", "right": "bénédiction"}, {"left": "فَرْحَة", "right": "joie"}, {"left": "شَجَرَة", "right": "arbre"}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e18', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.musa','ar.v.matta','ar.v.yohanna','ar.v.zikra','ar.v.maana']::text[], 'match', 'lesson', 'Mots en ى et en ا', '{}'::text[], 'Les noms de Moïse et Matthieu finissent par ى ; Jean par ا. Le son est le même : un a long.', 2, '{"id": "ar.l24.e18", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.musa", "ar.v.matta", "ar.v.yohanna", "ar.v.zikra", "ar.v.maana"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots en ى et en ا", "promptLanguage": "fr", "answer": "مُوسَى = Moïse ; مَتَّى = Matthieu ; يُوحَنَّا = Jean ; ذِكْرَى = souvenir ; مَعْنَى = sens", "acceptedAnswers": [], "explanation": "Les noms de Moïse et Matthieu finissent par ى ; Jean par ا. Le son est le même : un a long.", "pairs": [{"left": "مُوسَى", "right": "Moïse"}, {"left": "مَتَّى", "right": "Matthieu"}, {"left": "يُوحَنَّا", "right": "Jean"}, {"left": "ذِكْرَى", "right": "souvenir"}, {"left": "مَعْنَى", "right": "sens"}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
