insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e21', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.shagara']::text[], 'translation', 'lesson', 'شَجَرَة', array['arbre','un arbre','l''arbre']::text[], 'ش + a, ج + a, ر + a, ة muette : un arbre.', 2, '{"id": "ar.l24.e21", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.shagara"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "شَجَرَة", "promptLanguage": "ar", "answer": "arbre", "acceptedAnswers": ["arbre", "un arbre", "l''arbre"], "explanation": "ش + a, ج + a, ر + a, ة muette : un arbre.", "tip": "Trois fathas, puis ة.", "extraExample": {"text": "شَجَرَة كِبِيرَة.", "translation": "Un grand arbre."}, "errorPatterns": [{"equals": "joie", "category": "word_confusion", "feedback": "La joie est فَرْحَة, avec un soukoun sur ر."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e22', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.farha']::text[], 'translation', 'lesson', 'فَرْحَة', array['joie','une joie','la joie','bonheur']::text[], 'ف + a, ر sans voyelle, ح + a, ة muette : la joie.', 2, '{"id": "ar.l24.e22", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.farha"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "فَرْحَة", "promptLanguage": "ar", "answer": "joie", "acceptedAnswers": ["joie", "une joie", "la joie", "bonheur"], "explanation": "ف + a, ر sans voyelle, ح + a, ة muette : la joie.", "tip": "Un soukoun sur ر.", "extraExample": {"text": "فَرْحَة الْعِيد.", "translation": "La joie de la fête."}, "errorPatterns": [{"equals": "arbre", "category": "word_confusion", "feedback": "L''arbre est شَجَرَة, avec trois fathas."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e23', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.zikra']::text[], 'free_answer', 'lesson', 'Que veut dire ذِكْرَى ?', array['souvenir','un souvenir','commémoration','la commémoration','mémoire']::text[], 'ذِكْرَى : ذ + i, ك sans voyelle, ر + a long final (fatha + ى). Un souvenir, et dans l''Église la commémoration d''un saint.', 3, '{"id": "ar.l24.e23", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.zikra"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire ذِكْرَى ?", "promptLanguage": "fr", "answer": "souvenir", "acceptedAnswers": ["souvenir", "un souvenir", "commémoration", "la commémoration", "mémoire"], "explanation": "ذِكْرَى : ذ + i, ك sans voyelle, ر + a long final (fatha + ى). Un souvenir, et dans l''Église la commémoration d''un saint.", "tip": "Fatha + ى : a long.", "extraExample": {"text": "ذِكْرَى جَمِيلَة.", "translation": "Un beau souvenir."}, "errorPatterns": [{"equals": "sens", "category": "word_confusion", "feedback": "Le sens est مَعْنَى : ici tu lis ذ + ك + ر + ى."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e24', 'ar', 'ar.l24', 'ar.g24.ta_marbuta_alif_maqsura', array['ar.g24.ta_marbuta_alif_maqsura','ar.v.maana']::text[], 'free_answer', 'lesson', 'Que veut dire مَعْنَى ?', array['sens','le sens','signification','la signification','un sens']::text[], 'مَعْنَى : م + a, ع sans voyelle, ن + a long final (fatha + ى). Le sens d''un mot.', 3, '{"id": "ar.l24.e24", "unitIds": ["ar.g24.ta_marbuta_alif_maqsura", "ar.v.maana"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire مَعْنَى ?", "promptLanguage": "fr", "answer": "sens", "acceptedAnswers": ["sens", "le sens", "signification", "la signification", "un sens"], "explanation": "مَعْنَى : م + a, ع sans voyelle, ن + a long final (fatha + ى). Le sens d''un mot.", "tip": "Fatha + ى : a long.", "extraExample": {"text": "مَعْنَى كَلِمَة آمِين.", "translation": "Le sens du mot amen."}, "errorPatterns": [{"equals": "souvenir", "category": "word_confusion", "feedback": "Le souvenir est ذِكْرَى."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e01', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''une syllabe ?', array['une consonne + une voyelle']::text[], 'Une syllabe est un petit paquet : une consonne + une voyelle, comme مَا ou بِي. C''est ce que ton œil doit reconnaître d''un coup.', 1, '{"id": "ar.l25.e01", "type": "mcq", "unitIds": ["ar.g25.syllabes"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qu''une syllabe ?", "promptLanguage": "fr", "options": ["deux consonnes sans voyelle", "une consonne + une voyelle", "une lettre seule sans point", "un mot entier"], "answer": "une consonne + une voyelle", "acceptedAnswers": ["une consonne + une voyelle"], "explanation": "Une syllabe est un petit paquet : une consonne + une voyelle, comme مَا ou بِي. C''est ce que ton œil doit reconnaître d''un coup.", "tip": "Pense à pa-pa ou ma-ma : deux paquets identiques.", "extraExample": {"text": "ماما", "translation": "maman : deux paquets ما | ما"}, "errorPatterns": [{"equals": "deux consonnes sans voyelle", "category": "word_confusion", "feedback": "Une syllabe a toujours une voyelle : sans elle, on ne peut pas la dire."}, {"equals": "un mot entier", "category": "word_confusion", "feedback": "Un mot est fait d''une ou plusieurs syllabes ; une syllabe n''est qu''un paquet du mot."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e02', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.alif','ar.v.waw','ar.v.ya']::text[], 'mcq', 'lesson', 'Quelles lettres écrivent toujours une voyelle longue ?', array['ا و ي']::text[], 'ا, و et ي sont les lettres de voyelle longue : elles restent écrites même sans harakat. Toutes les autres sont des consonnes.', 1, '{"id": "ar.l25.e02", "type": "mcq", "unitIds": ["ar.g25.syllabes", "ar.v.alif", "ar.v.waw", "ar.v.ya"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles lettres écrivent toujours une voyelle longue ?", "promptLanguage": "fr", "options": ["ب ت ث", "س ش ص", "م ن ل", "ا و ي"], "answer": "ا و ي", "acceptedAnswers": ["ا و ي"], "explanation": "ا, و et ي sont les lettres de voyelle longue : elles restent écrites même sans harakat. Toutes les autres sont des consonnes.", "tip": "Retiens la trilogie ا و ي : ce sont tes balises.", "extraExample": {"text": "موز", "translation": "banane : le و donne le paquet مو"}, "errorPatterns": [{"equals": "ب ت ث", "category": "word_confusion", "feedback": "ب ت ث sont des consonnes : les trois sœurs de la barque."}, {"equals": "س ش ص", "category": "word_confusion", "feedback": "س ش ص sont des consonnes à dents ou à boucle, pas des voyelles."}, {"equals": "م ن ل", "category": "word_confusion", "feedback": "م ن ل sont des consonnes aussi."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e03', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.mama']::text[], 'mcq', 'lesson', 'ماما', array['maman']::text[], 'م + ا, puis م + ا : deux paquets ما | ما, « maman ». La première lettre م n''a aucun point.', 1, '{"id": "ar.l25.e03", "type": "mcq", "unitIds": ["ar.g25.syllabes", "ar.v.mama"], "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "ماما", "promptLanguage": "ar", "options": ["papa", "maman", "mamie", "banane"], "answer": "maman", "acceptedAnswers": ["maman"], "explanation": "م + ا, puis م + ا : deux paquets ما | ما, « maman ». La première lettre م n''a aucun point.", "tip": "م = boule sans point ; ب = barque avec un point dessous.", "extraExample": {"text": "ماما عايزة شاي.", "translation": "Maman veut du thé."}, "errorPatterns": [{"equals": "papa", "category": "word_confusion", "feedback": "« papa » s''écrit بابا : il commence par ب, avec 1 point dessous. Ici, la première lettre est م, sans point."}, {"equals": "mamie", "category": "word_confusion", "feedback": "« mamie » s''écrit تيتة, avec deux ت. Ici tu lis ما | ما."}, {"equals": "banane", "category": "word_confusion", "feedback": "« banane » s''écrit موز. Ici tu lis ما | ما : deux paquets identiques."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e04', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.teta']::text[], 'mcq', 'lesson', 'تيتة', array['mamie']::text[], 'تي | تة : le ي est la balise du premier paquet, et le ة termine le mot. Deux paquets, « mamie ».', 1, '{"id": "ar.l25.e04", "type": "mcq", "unitIds": ["ar.g25.syllabes", "ar.v.teta"], "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "تيتة", "promptLanguage": "ar", "options": ["maman", "papa", "chat", "mamie"], "answer": "mamie", "acceptedAnswers": ["mamie"], "explanation": "تي | تة : le ي est la balise du premier paquet, et le ة termine le mot. Deux paquets, « mamie ».", "tip": "Deux ت de chaque côté du ي : le mot sonne comme un petit refrain.", "extraExample": {"text": "تيتة في البيت.", "translation": "Mamie est à la maison."}, "errorPatterns": [{"equals": "maman", "category": "word_confusion", "feedback": "« maman » ne correspond pas : relis تيتة paquet par paquet. Ici, le sens est « mamie »."}, {"equals": "papa", "category": "word_confusion", "feedback": "« papa » ne correspond pas : relis تيتة paquet par paquet. Ici, le sens est « mamie »."}, {"equals": "chat", "category": "word_confusion", "feedback": "« chat » ne correspond pas : relis تيتة paquet par paquet. Ici, le sens est « mamie »."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e05', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.mooz']::text[], 'mcq', 'lesson', 'موز', array['banane']::text[], 'Le و est une balise : مو est un paquet long, puis vient le ز. Ensemble : موز, « banane ».', 2, '{"id": "ar.l25.e05", "type": "mcq", "unitIds": ["ar.g25.syllabes", "ar.v.mooz"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "موز", "promptLanguage": "ar", "options": ["sel", "banane", "lumière", "poisson"], "answer": "banane", "acceptedAnswers": ["banane"], "explanation": "Le و est une balise : مو est un paquet long, puis vient le ز. Ensemble : موز, « banane ».", "tip": "Un و au milieu fait un paquet long : مو.", "extraExample": {"text": "الموز حلو.", "translation": "Les bananes sont bonnes."}, "errorPatterns": [{"equals": "sel", "category": "word_confusion", "feedback": "« sel » ne correspond pas : relis موز paquet par paquet. Ici, le sens est « banane »."}, {"equals": "lumière", "category": "word_confusion", "feedback": "« lumière » ne correspond pas : relis موز paquet par paquet. Ici, le sens est « banane »."}, {"equals": "poisson", "category": "word_confusion", "feedback": "« poisson » ne correspond pas : relis موز paquet par paquet. Ici, le sens est « banane »."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e06', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.teta']::text[], 'mcq', 'lesson', 'Dans quel mot vois-tu la voyelle longue ي ?', array['تيتة']::text[], 'Seul تيتة contient un ي. Les mots ملح, سمك et جمل n''ont que des consonnes écrites : leurs voyelles sont courtes, donc invisibles.', 2, '{"id": "ar.l25.e06", "type": "mcq", "unitIds": ["ar.g25.syllabes", "ar.v.teta"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quel mot vois-tu la voyelle longue ي ?", "promptLanguage": "fr", "options": ["ملح", "سمك", "جمل", "تيتة"], "answer": "تيتة", "acceptedAnswers": ["تيتة"], "explanation": "Seul تيتة contient un ي. Les mots ملح, سمك et جمل n''ont que des consonnes écrites : leurs voyelles sont courtes, donc invisibles.", "tip": "Cherche d''abord les balises ا و ي.", "extraExample": {"text": "بيت", "translation": "maison : le ي est la balise"}, "errorPatterns": [{"equals": "ملح", "category": "word_confusion", "feedback": "« ملح » ne contient ni ا ni و ni ي : ses voyelles sont courtes, donc invisibles."}, {"equals": "سمك", "category": "word_confusion", "feedback": "« سمك » ne contient ni ا ni و ni ي : ses voyelles sont courtes, donc invisibles."}, {"equals": "جمل", "category": "word_confusion", "feedback": "« جمل » ne contient ni ا ni و ni ي : ses voyelles sont courtes, donc invisibles."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e07', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.teta']::text[], 'mcq', 'lesson', 'Comment coupe-t-on تيتة en paquets ?', array['تي | تة']::text[], 'Le ي prolonge la voyelle du premier ت : تي est un paquet. Le reste, تة, forme le second paquet.', 2, '{"id": "ar.l25.e07", "type": "mcq", "unitIds": ["ar.g25.syllabes", "ar.v.teta"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment coupe-t-on تيتة en paquets ?", "promptLanguage": "fr", "options": ["ت | يتة", "تي | تة", "تيت | ة", "ت | يت | ة"], "answer": "تي | تة", "acceptedAnswers": ["تي | تة"], "explanation": "Le ي prolonge la voyelle du premier ت : تي est un paquet. Le reste, تة, forme le second paquet.", "tip": "Une balise reste toujours collée à la consonne qui la précède.", "extraExample": {"text": "ماما", "translation": "ما | ما : deux paquets"}, "errorPatterns": [{"equals": "ت | يتة", "category": "spelling", "feedback": "Couper en « ت | يتة » sépare la balise ي de sa consonne : ce n''est pas un paquet."}, {"equals": "تيت | ة", "category": "spelling", "feedback": "Couper en « تيت | ة » sépare la balise ي de sa consonne : ce n''est pas un paquet."}, {"equals": "ت | يت | ة", "category": "spelling", "feedback": "Couper en « ت | يت | ة » sépare la balise ي de sa consonne : ce n''est pas un paquet."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e08', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.nur']::text[], 'mcq', 'lesson', 'Quel mot se dit en un seul paquet ?', array['نور']::text[], 'نور se dit d''un seul souffle : نو + ر forment un seul paquet long. ماما, تيتة et سمك ont chacun deux paquets.', 3, '{"id": "ar.l25.e08", "type": "mcq", "unitIds": ["ar.g25.syllabes", "ar.v.nur"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel mot se dit en un seul paquet ?", "promptLanguage": "fr", "options": ["ماما", "تيتة", "سمك", "نور"], "answer": "نور", "acceptedAnswers": ["نور"], "explanation": "نور se dit d''un seul souffle : نو + ر forment un seul paquet long. ماما, تيتة et سمك ont chacun deux paquets.", "tip": "Compte les voyelles : une voyelle, un paquet.", "extraExample": {"text": "موز", "translation": "banane : un seul paquet aussi"}, "errorPatterns": [{"equals": "ماما", "category": "word_confusion", "feedback": "« ماما » se dit en deux paquets, pas en un seul."}, {"equals": "تيتة", "category": "word_confusion", "feedback": "« تيتة » se dit en deux paquets, pas en un seul."}, {"equals": "سمك", "category": "word_confusion", "feedback": "« سمك » se dit en deux paquets, pas en un seul."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e09', 'ar', 'ar.l25', 'ar.v.baba', array['ar.v.baba','ar.g25.syllabes']::text[], 'mcq', 'lesson', 'Lis vite : بابا', array['papa']::text[], 'ب + ا, puis ب + ا : بابا, « papa ». Même forme que ماما, mais la barque ب a un point dessous, la boule م n''en a pas.', 2, '{"id": "ar.l25.e09", "type": "mcq", "unitIds": ["ar.v.baba", "ar.g25.syllabes"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "Lis vite : بابا", "promptLanguage": "ar", "options": ["maman", "papa", "mamie", "porte"], "answer": "papa", "acceptedAnswers": ["papa"], "explanation": "ب + ا, puis ب + ا : بابا, « papa ». Même forme que ماما, mais la barque ب a un point dessous, la boule م n''en a pas.", "tip": "ب (point dessous) = b ; م (aucun point) = m.", "extraExample": {"text": "بابا في الكنيسة.", "translation": "Papa est à l''église."}, "errorPatterns": [{"equals": "maman", "category": "word_confusion", "feedback": "ماما commence par م, sans point. Ici la première lettre est ب, avec 1 point dessous : c''est « papa »."}, {"equals": "mamie", "category": "word_confusion", "feedback": "« mamie » s''écrit تيتة. Ici tu lis ب + ا, puis ب + ا."}, {"equals": "porte", "category": "word_confusion", "feedback": "« porte » s''écrit باب, un seul paquet. Ici le mot a deux ا."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e10', 'ar', 'ar.l25', 'ar.v.alif', array['ar.v.alif','ar.g25.syllabes']::text[], 'mcq', 'lesson', 'Quelle lettre est un bâton droit, sans point, qui donne un a long ?', array['ا']::text[], 'ا (alif) est le bâton droit sans point : la balise du a long. ل a aussi un bâton, mais avec un pied qui tourne.', 1, '{"id": "ar.l25.e10", "type": "mcq", "unitIds": ["ar.v.alif", "ar.g25.syllabes"], "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un bâton droit, sans point, qui donne un a long ?", "promptLanguage": "fr", "options": ["ل", "ب", "ر", "ا"], "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "ا (alif) est le bâton droit sans point : la balise du a long. ل a aussi un bâton, mais avec un pied qui tourne.", "tip": "Alif = un poteau planté sur la ligne.", "extraExample": {"text": "باب", "translation": "porte : le ا au milieu"}, "errorPatterns": [{"equals": "ل", "category": "spelling", "feedback": "ل a un bâton, mais avec un pied courbé vers la gauche."}, {"equals": "ب", "category": "spelling", "feedback": "ب est la barque avec un point dessous."}, {"equals": "ر", "category": "spelling", "feedback": "ر est un petit crochet qui descend sous la ligne."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e11', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.mama','ar.v.nur','ar.v.mooz','ar.v.milh']::text[], 'match', 'lesson', 'Relie chaque mot à son sens : la maison et la cuisine.', '{}'::text[], 'ماما (ما | ما), نور (un paquet long), موز (مو + ز) et ملح (trois consonnes) : coupe chaque mot en paquets avant de choisir.', 2, '{"id": "ar.l25.e11", "type": "match", "unitIds": ["ar.g25.syllabes", "ar.v.mama", "ar.v.nur", "ar.v.mooz", "ar.v.milh"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot à son sens : la maison et la cuisine.", "promptLanguage": "fr", "pairs": [{"left": "ماما", "right": "maman"}, {"left": "نور", "right": "lumière"}, {"left": "موز", "right": "banane"}, {"left": "ملح", "right": "sel"}], "acceptedAnswers": [], "answer": "ماما = maman ; نور = lumière ; موز = banane ; ملح = sel", "explanation": "ماما (ما | ما), نور (un paquet long), موز (مو + ز) et ملح (trois consonnes) : coupe chaque mot en paquets avant de choisir.", "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e12', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.samak','ar.v.gamal','ar.v.otta','ar.v.walad']::text[], 'match', 'lesson', 'Relie chaque mot à son sens : les animaux et les gens.', '{}'::text[], 'سمك, جمل et قطة ont deux paquets ; dans ولد, le و est une consonne. Le sens te dit comment le lire.', 2, '{"id": "ar.l25.e12", "type": "match", "unitIds": ["ar.g25.syllabes", "ar.v.samak", "ar.v.gamal", "ar.v.otta", "ar.v.walad"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot à son sens : les animaux et les gens.", "promptLanguage": "fr", "pairs": [{"left": "سمك", "right": "poisson"}, {"left": "جمل", "right": "chameau"}, {"left": "قطة", "right": "chat"}, {"left": "ولد", "right": "garçon"}], "acceptedAnswers": [], "answer": "سمك = poisson ; جمل = chameau ; قطة = chat ; ولد = garçon", "explanation": "سمك, جمل et قطة ont deux paquets ; dans ولد, le و est une consonne. Le sens te dit comment le lire.", "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e13', 'ar', 'ar.l25', 'ar.v.bab', array['ar.v.bab','ar.v.bayt','ar.v.kanisa','ar.v.baba','ar.g25.syllabes']::text[], 'match', 'lesson', 'Relie chaque mot du module 2 à son sens.', '{}'::text[], 'باب et بيت sont des paquets uniques, بابا en a deux, كنيسة en a trois : les balises ا et ي t''aident à les reconnaître.', 2, '{"id": "ar.l25.e13", "type": "match", "unitIds": ["ar.v.bab", "ar.v.bayt", "ar.v.kanisa", "ar.v.baba", "ar.g25.syllabes"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot du module 2 à son sens.", "promptLanguage": "fr", "pairs": [{"left": "باب", "right": "porte"}, {"left": "بيت", "right": "maison"}, {"left": "كنيسة", "right": "église"}, {"left": "بابا", "right": "papa"}], "acceptedAnswers": [], "answer": "باب = porte ; بيت = maison ; كنيسة = église ; بابا = papa", "explanation": "باب et بيت sont des paquets uniques, بابا en a deux, كنيسة en a trois : les balises ا et ي t''aident à les reconnaître.", "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e14', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.mooz']::text[], 'fill_blank', 'lesson', 'م___ز (banane)', array['و']::text[], 'Dans موز, la voyelle longue est un و : il donne le paquet مو. Sans lui, le mot ne se lit plus.', 2, '{"id": "ar.l25.e14", "type": "fill_blank", "unitIds": ["ar.g25.syllabes", "ar.v.mooz"], "difficulty": 2, "instruction": "Complète la voyelle longue manquante.", "prompt": "م___ز (banane)", "promptLanguage": "ar", "options": ["ا", "ي", "ن", "و"], "answer": "و", "acceptedAnswers": ["و"], "explanation": "Dans موز, la voyelle longue est un و : il donne le paquet مو. Sans lui, le mot ne se lit plus.", "tip": "Cherche la balise qui manque : ا, و ou ي.", "extraExample": {"text": "نور", "translation": "lumière : un و aussi"}, "errorPatterns": [{"equals": "ا", "category": "spelling", "feedback": "م ا ز ne donne aucun mot connu : « banane » s''écrit avec un و."}, {"equals": "ي", "category": "spelling", "feedback": "م ي ز n''est pas « banane » : le mot contient un و."}, {"equals": "ن", "category": "spelling", "feedback": "ن est une consonne, alors qu''il manque une voyelle longue."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e15', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.teta']::text[], 'fill_blank', 'lesson', 'ت___تة (mamie)', array['ي']::text[], 'تيتة a un ي pour balise : تي | تة. Avec ا ou و, on lirait un autre mot.', 2, '{"id": "ar.l25.e15", "type": "fill_blank", "unitIds": ["ar.g25.syllabes", "ar.v.teta"], "difficulty": 2, "instruction": "Complète la voyelle longue manquante.", "prompt": "ت___تة (mamie)", "promptLanguage": "ar", "options": ["ا", "ي", "و", "م"], "answer": "ي", "acceptedAnswers": ["ي"], "explanation": "تيتة a un ي pour balise : تي | تة. Avec ا ou و, on lirait un autre mot.", "tip": "Le ي de تيتة est entouré de deux ت.", "extraExample": {"text": "بيت", "translation": "maison : encore un ي au milieu"}, "errorPatterns": [{"equals": "ا", "category": "spelling", "feedback": "ت ا ت ة ne veut rien dire : « mamie » contient un ي."}, {"equals": "و", "category": "spelling", "feedback": "ت و ت ة n''est pas « mamie » : cherche le ي."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e16', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.samak']::text[], 'fill_blank', 'lesson', 'س___ك (poisson)', array['م']::text[], 'Le poisson s''écrit س م ك : trois consonnes, aucune voyelle visible. Le م est la boule fermée, sans point.', 3, '{"id": "ar.l25.e16", "type": "fill_blank", "unitIds": ["ar.g25.syllabes", "ar.v.samak"], "difficulty": 3, "instruction": "Complète la consonne manquante.", "prompt": "س___ك (poisson)", "promptLanguage": "ar", "options": ["ن", "ل", "ب", "م"], "answer": "م", "acceptedAnswers": ["م"], "explanation": "Le poisson s''écrit س م ك : trois consonnes, aucune voyelle visible. Le م est la boule fermée, sans point.", "tip": "Dis le mot dans ta tête : ton oreille retrouve la consonne du milieu.", "extraExample": {"text": "السمك طازة.", "translation": "Le poisson est frais."}, "errorPatterns": [{"equals": "ن", "category": "spelling", "feedback": "ن a un point dessus ; « poisson » s''écrit avec un م, sans point."}, {"equals": "ب", "category": "spelling", "feedback": "ب a un point dessous ; « poisson » s''écrit avec un م, sans point."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e17', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.otta']::text[], 'fill_blank', 'lesson', 'ق___ة (chat)', array['ط']::text[], 'قطة s''écrit ق ط ة : la lettre du milieu est le ط lourd (une boucle et son bâton), pas le ت.', 3, '{"id": "ar.l25.e17", "type": "fill_blank", "unitIds": ["ar.g25.syllabes", "ar.v.otta"], "difficulty": 3, "instruction": "Complète la consonne manquante.", "prompt": "ق___ة (chat)", "promptLanguage": "ar", "options": ["ت", "ط", "د", "ض"], "answer": "ط", "acceptedAnswers": ["ط"], "explanation": "قطة s''écrit ق ط ة : la lettre du milieu est le ط lourd (une boucle et son bâton), pas le ت.", "tip": "Le ط a un bâton qui monte au-dessus de sa boucle.", "extraExample": {"text": "القطة بتشرب لبن.", "translation": "Le chat boit du lait."}, "errorPatterns": [{"equals": "ت", "category": "spelling", "feedback": "ت n''a pas de bâton, mais 2 points dessus. « chat » s''écrit avec un ط."}, {"equals": "ض", "category": "spelling", "feedback": "ض a un point dessus ; ici la lettre n''a aucun point."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e18', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.milh']::text[], 'translation', 'lesson', 'ملح', array['sel','le sel','du sel']::text[], 'ملح = م + ل + ح : trois consonnes, un seul paquet. C''est le « sel ».', 2, '{"id": "ar.l25.e18", "type": "translation", "unitIds": ["ar.g25.syllabes", "ar.v.milh"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "ملح", "promptLanguage": "ar", "answer": "sel", "acceptedAnswers": ["sel", "le sel", "du sel"], "explanation": "ملح = م + ل + ح : trois consonnes, un seul paquet. C''est le « sel ».", "tip": "Boule, bâton, crochet : م ل ح.", "extraExample": {"text": "حط ملح شوية.", "translation": "Mets un peu de sel."}, "errorPatterns": [{"equals": "sucre", "category": "vocabulary", "feedback": "« sucre » s''écrit سكر (module 2). Ici le mot commence par م."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e19', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.gamal']::text[], 'translation', 'lesson', 'جمل', array['chameau','le chameau','un chameau','dromadaire']::text[], 'جمل = ج + م + ل : trois consonnes, deux paquets quand on le dit. C''est le « chameau ».', 3, '{"id": "ar.l25.e19", "type": "translation", "unitIds": ["ar.g25.syllabes", "ar.v.gamal"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "جمل", "promptLanguage": "ar", "answer": "chameau", "acceptedAnswers": ["chameau", "le chameau", "un chameau", "dromadaire"], "explanation": "جمل = ج + م + ل : trois consonnes, deux paquets quand on le dit. C''est le « chameau ».", "tip": "Le ج se dit g au Caire, comme dans gâteau.", "extraExample": {"text": "ركبت جمل جنب الأهرامات.", "translation": "J''ai monté un chameau près des pyramides."}, "pool": "lesson", "lessonId": "ar.l25", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e20', 'ar', 'ar.l25', 'ar.v.kanisa', array['ar.v.kanisa','ar.g25.syllabes']::text[], 'translation', 'lesson', 'كنيسة', array['église','l''église','une église','eglise','l''eglise']::text[], 'كنيسة = كَ | نِي | سَة : trois paquets, avec le ي pour balise. C''est l''« église ».', 2, '{"id": "ar.l25.e20", "type": "translation", "unitIds": ["ar.v.kanisa", "ar.g25.syllabes"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "كنيسة", "promptLanguage": "ar", "answer": "église", "acceptedAnswers": ["église", "l''église", "une église", "eglise", "l''eglise"], "explanation": "كنيسة = كَ | نِي | سَة : trois paquets, avec le ي pour balise. C''est l''« église ».", "tip": "Un ة à la fin signale souvent un mot féminin.", "extraExample": {"text": "الكنيسة كبيرة.", "translation": "L''église est grande."}, "pool": "lesson", "lessonId": "ar.l25", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e21', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.mama']::text[], 'free_answer', 'lesson', 'Combien de paquets compte ماما ?', array['deux','2','deux paquets','2 paquets']::text[], 'ماما = ما | ما : chaque ا prolonge la voyelle de son م. Deux ا, deux paquets.', 2, '{"id": "ar.l25.e21", "type": "free_answer", "unitIds": ["ar.g25.syllabes", "ar.v.mama"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Combien de paquets compte ماما ?", "promptLanguage": "fr", "answer": "deux", "acceptedAnswers": ["deux", "2", "deux paquets", "2 paquets"], "explanation": "ماما = ما | ما : chaque ا prolonge la voyelle de son م. Deux ا, deux paquets.", "tip": "Autant de voyelles, autant de paquets.", "extraExample": {"text": "بابا", "translation": "با | با : deux paquets aussi"}, "errorPatterns": [{"equals": "un", "category": "vocabulary", "feedback": "Il y a deux ا, donc deux paquets : ما | ما."}, {"equals": "1", "category": "vocabulary", "feedback": "Il y a deux ا, donc deux paquets : ما | ما."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e22', 'ar', 'ar.l25', 'ar.g25.syllabes', array['ar.g25.syllabes','ar.v.nur']::text[], 'free_answer', 'lesson', 'Que veut dire نور ?', array['lumière','la lumière','une lumière']::text[], 'نور = نو + ر, un seul paquet long. Le mot veut dire « lumière ».', 2, '{"id": "ar.l25.e22", "type": "free_answer", "unitIds": ["ar.g25.syllabes", "ar.v.nur"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire نور ?", "promptLanguage": "fr", "answer": "lumière", "acceptedAnswers": ["lumière", "la lumière", "une lumière"], "explanation": "نور = نو + ر, un seul paquet long. Le mot veut dire « lumière ».", "tip": "Le و fait le paquet long نو.", "extraExample": {"text": "افتح النور.", "translation": "Allume la lumière."}, "errorPatterns": [{"equals": "fleurs", "category": "vocabulary", "feedback": "« fleurs » s''écrit ورد (module 2). Ici la première lettre est ن."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e23', 'ar', 'ar.l25', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.qalam','ar.g25.syllabes']::text[], 'mcq', 'lesson', 'قَلَم', array['stylo']::text[], 'Avec les harakat, chaque voyelle est écrite : قَلَم est « stylo ». Sans harakat, on écrirait قلم : les mêmes trois consonnes, le même mot, que ton oreille complète.', 2, '{"id": "ar.l25.e23", "type": "mcq", "unitIds": ["ar.g17.short_vowels", "ar.v.qalam", "ar.g25.syllabes"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "قَلَم", "promptLanguage": "ar", "options": ["lune", "stylo", "montagne", "agneau"], "answer": "stylo", "acceptedAnswers": ["stylo"], "explanation": "Avec les harakat, chaque voyelle est écrite : قَلَم est « stylo ». Sans harakat, on écrirait قلم : les mêmes trois consonnes, le même mot, que ton oreille complète.", "tip": "Les harakat sont des aides : ôte-les par la pensée et lis les trois consonnes.", "extraExample": {"text": "قلم", "translation": "stylo : le même mot, sans voyelles écrites"}, "errorPatterns": [{"equals": "lune", "category": "word_confusion", "feedback": "« lune » s''écrit قَمَر, avec un ر à la fin. Ici le mot finit par م."}, {"equals": "montagne", "category": "word_confusion", "feedback": "« montagne » s''écrit جَبَل : il commence par ج."}, {"equals": "agneau", "category": "word_confusion", "feedback": "« agneau » s''écrit حَمَل : il commence par ح."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e01', 'ar', 'ar.l26', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.g26.long_words']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''un bloc ?', array['une suite de lettres attachées']::text[], 'Un bloc est une suite de lettres attachées. Un mot long est fait de plusieurs blocs qu''on lit un par un.', 1, '{"id": "ar.l26.e01", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.g26.long_words"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qu''un bloc ?", "promptLanguage": "fr", "options": ["une voyelle courte", "une suite de lettres attachées", "un mot entier", "un point sous une lettre"], "answer": "une suite de lettres attachées", "acceptedAnswers": ["une suite de lettres attachées"], "explanation": "Un bloc est une suite de lettres attachées. Un mot long est fait de plusieurs blocs qu''on lit un par un.", "tip": "Un bloc finit quand une lettre ne s''attache pas à la suivante.", "extraExample": {"text": "باب", "translation": "با | ب : deux blocs"}, "errorPatterns": [{"equals": "un mot entier", "category": "word_confusion", "feedback": "Un mot peut contenir plusieurs blocs : باب en a deux (با | ب)."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e02', 'ar', 'ar.l26', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.g26.long_words']::text[], 'mcq', 'lesson', 'Quelles lettres ferment un bloc ?', array['ا د ذ ر ز و']::text[], 'Les lettres ا د ذ ر ز و ne s''attachent pas à la suivante : elles terminent le bloc. Toutes les autres s''accrochent.', 1, '{"id": "ar.l26.e02", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.g26.long_words"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles lettres ferment un bloc ?", "promptLanguage": "fr", "options": ["ب ت ث ن ي", "س ش ص ض", "ف ق ك ل", "ا د ذ ر ز و"], "answer": "ا د ذ ر ز و", "acceptedAnswers": ["ا د ذ ر ز و"], "explanation": "Les lettres ا د ذ ر ز و ne s''attachent pas à la suivante : elles terminent le bloc. Toutes les autres s''accrochent.", "tip": "Les six lettres qui lâchent la main.", "extraExample": {"text": "ورد", "translation": "و | ر | د : trois blocs"}, "errorPatterns": [{"equals": "ب ت ث ن ي", "category": "word_confusion", "feedback": "« ب ت ث ن ي » : ces lettres s''attachent à la suivante, elles ne ferment pas de bloc."}, {"equals": "س ش ص ض", "category": "word_confusion", "feedback": "« س ش ص ض » : ces lettres s''attachent à la suivante, elles ne ferment pas de bloc."}, {"equals": "ف ق ك ل", "category": "word_confusion", "feedback": "« ف ق ك ل » : ces lettres s''attachent à la suivante, elles ne ferment pas de bloc."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e03', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.telifun']::text[], 'mcq', 'lesson', 'En combien de blocs se coupe تليفون ?', array['deux']::text[], 'Le و ferme le premier bloc : تليفو | ن. Il reste le ن seul : deux blocs.', 2, '{"id": "ar.l26.e03", "type": "mcq", "unitIds": ["ar.g26.long_words", "ar.v.telifun"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "En combien de blocs se coupe تليفون ?", "promptLanguage": "fr", "options": ["un", "deux", "trois", "quatre"], "answer": "deux", "acceptedAnswers": ["deux"], "explanation": "Le و ferme le premier bloc : تليفو | ن. Il reste le ن seul : deux blocs.", "tip": "Compte les ا د ذ ر ز و : chacun ferme un bloc.", "extraExample": {"text": "جامعة", "translation": "جا | معة : deux blocs"}, "errorPatterns": [{"equals": "un", "category": "spelling", "feedback": "Le و ferme un bloc au milieu du mot : il y en a donc plus d''un."}, {"equals": "trois", "category": "spelling", "feedback": "Il n''y a qu''une coupure, après le و : تليفو | ن, deux blocs."}, {"equals": "quatre", "category": "spelling", "feedback": "Il n''y a qu''une coupure, après le و : تليفو | ن, deux blocs."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e04', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.gamia']::text[], 'mcq', 'lesson', 'Où coupe-t-on جامعة ?', array['جا | معة']::text[], 'Le ا ferme le premier bloc, donc la coupure vient juste après lui : جا | معة. Le ة reste attaché au ع.', 2, '{"id": "ar.l26.e04", "type": "mcq", "unitIds": ["ar.g26.long_words", "ar.v.gamia"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où coupe-t-on جامعة ?", "promptLanguage": "fr", "options": ["ج | امعة", "جامع | ة", "جام | عة", "جا | معة"], "answer": "جا | معة", "acceptedAnswers": ["جا | معة"], "explanation": "Le ا ferme le premier bloc, donc la coupure vient juste après lui : جا | معة. Le ة reste attaché au ع.", "tip": "La coupure vient après la lettre ا, jamais avant.", "extraExample": {"text": "باب", "translation": "با | ب"}, "errorPatterns": [{"equals": "ج | امعة", "category": "spelling", "feedback": "Couper en « ج | امعة » ne respecte pas la règle : on coupe juste après le ا."}, {"equals": "جامع | ة", "category": "spelling", "feedback": "Couper en « جامع | ة » ne respecte pas la règle : on coupe juste après le ا."}, {"equals": "جام | عة", "category": "spelling", "feedback": "Couper en « جام | عة » ne respecte pas la règle : on coupe juste après le ا."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e05', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.mobail']::text[], 'mcq', 'lesson', 'موبايل', array['portable']::text[], 'مو | با | يل : trois blocs, car le و et le ا ferment les deux premiers. Ensemble : موبايل, « portable ».', 2, '{"id": "ar.l26.e05", "type": "mcq", "unitIds": ["ar.g26.long_words", "ar.v.mobail"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "موبايل", "promptLanguage": "ar", "options": ["bus", "portable", "hôpital", "école"], "answer": "portable", "acceptedAnswers": ["portable"], "explanation": "مو | با | يل : trois blocs, car le و et le ا ferment les deux premiers. Ensemble : موبايل, « portable ».", "tip": "Dis-le comme dans la rue : tu le connais par cœur.", "extraExample": {"text": "عندي موبايل جديد.", "translation": "J''ai un nouveau portable."}, "errorPatterns": [{"equals": "bus", "category": "word_confusion", "feedback": "« bus » ne correspond pas : relis موبايل bloc par bloc. Ici, le sens est « portable »."}, {"equals": "hôpital", "category": "word_confusion", "feedback": "« hôpital » ne correspond pas : relis موبايل bloc par bloc. Ici, le sens est « portable »."}, {"equals": "école", "category": "word_confusion", "feedback": "« école » ne correspond pas : relis موبايل bloc par bloc. Ici, le sens est « portable »."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e06', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.mustashfa']::text[], 'mcq', 'lesson', 'Quel mot veut dire « hôpital » ?', array['مستشفى']::text[], 'مستشفى est un seul long bloc, qu''on lit en paquets : مس | تش | فى. Le ى final est sa dernière lettre.', 2, '{"id": "ar.l26.e06", "type": "mcq", "unitIds": ["ar.g26.long_words", "ar.v.mustashfa"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « hôpital » ?", "promptLanguage": "fr", "options": ["مدرسة", "جامعة", "مطعم", "مستشفى"], "answer": "مستشفى", "acceptedAnswers": ["مستشفى"], "explanation": "مستشفى est un seul long bloc, qu''on lit en paquets : مس | تش | فى. Le ى final est sa dernière lettre.", "tip": "Cherche les dents س ش et le ى final.", "extraExample": {"text": "المستشفى قريب.", "translation": "L''hôpital est près d''ici."}, "errorPatterns": [{"equals": "مدرسة", "category": "word_confusion", "feedback": "« مدرسة » est un autre lieu : l''hôpital s''écrit مستشفى."}, {"equals": "جامعة", "category": "word_confusion", "feedback": "« جامعة » est un autre lieu : l''hôpital s''écrit مستشفى."}, {"equals": "مطعم", "category": "word_confusion", "feedback": "« مطعم » est un autre lieu : l''hôpital s''écrit مستشفى."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e07', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words']::text[], 'mcq', 'lesson', 'Que veut dire ال au début d''un mot ?', array['le ou la']::text[], 'ال se lit « le » ou « la » : on le lit d''un coup, puis on lit le reste du mot.', 3, '{"id": "ar.l26.e07", "type": "mcq", "unitIds": ["ar.g26.long_words"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire ال au début d''un mot ?", "promptLanguage": "fr", "options": ["et", "le ou la", "notre", "dans"], "answer": "le ou la", "acceptedAnswers": ["le ou la"], "explanation": "ال se lit « le » ou « la » : on le lit d''un coup, puis on lit le reste du mot.", "tip": "Cherche ال en premier : il s''écarte tout seul.", "extraExample": {"text": "الكنيسة", "translation": "l''église"}, "errorPatterns": [{"equals": "et", "category": "word_confusion", "feedback": "« et » s''écrit و, seul devant le mot suivant."}, {"equals": "notre", "category": "word_confusion", "feedback": "« notre » s''écrit ـنا, à la fin du mot."}, {"equals": "dans", "category": "word_confusion", "feedback": "« dans » est un autre petit mot, que tu verras à la leçon 30."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e08', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words']::text[], 'mcq', 'lesson', 'Dans « بابا وماما », que veut dire le و ?', array['et']::text[], 'Un و seul devant un mot veut dire « et » : بابا وماما = papa et maman.', 3, '{"id": "ar.l26.e08", "type": "mcq", "unitIds": ["ar.g26.long_words"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans « بابا وماما », que veut dire le و ?", "promptLanguage": "fr", "options": ["notre", "moi", "dans", "et"], "answer": "et", "acceptedAnswers": ["et"], "explanation": "Un و seul devant un mot veut dire « et » : بابا وماما = papa et maman.", "tip": "Un و qui reste seul devant le mot suivant est le petit mot « et ».", "extraExample": {"text": "شاي وعيش", "translation": "du thé et du pain"}, "errorPatterns": [{"equals": "notre", "category": "word_confusion", "feedback": "« notre » s''écrit ـنا, à la fin d''un mot."}, {"equals": "moi", "category": "word_confusion", "feedback": "« moi » s''écrit أنا (leçon 27)."}, {"equals": "dans", "category": "word_confusion", "feedback": "« dans » est un autre petit mot (leçon 30)."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e09', 'ar', 'ar.l26', 'ar.v.rabbina', array['ar.v.rabbina','ar.v.abouna','ar.g26.long_words']::text[], 'mcq', 'lesson', 'Quelle fin de mot veut dire « notre » ?', array['ـنا']::text[], 'ـنا veut dire « notre » : ربنا = رب + نا (notre Seigneur), أبونا = أبو + نا (notre père).', 3, '{"id": "ar.l26.e09", "type": "mcq", "unitIds": ["ar.v.rabbina", "ar.v.abouna", "ar.g26.long_words"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle fin de mot veut dire « notre » ?", "promptLanguage": "fr", "options": ["ـة", "ـنا", "ال", "و"], "answer": "ـنا", "acceptedAnswers": ["ـنا"], "explanation": "ـنا veut dire « notre » : ربنا = رب + نا (notre Seigneur), أبونا = أبو + نا (notre père).", "tip": "ـنا : notre.", "extraExample": {"text": "ربنا", "translation": "notre Seigneur : رب + نا"}, "errorPatterns": [{"equals": "ـة", "category": "word_confusion", "feedback": "ـة termine beaucoup de mots féminins, mais ne veut pas dire « notre »."}, {"equals": "ال", "category": "word_confusion", "feedback": "ال est au début du mot et veut dire « le » ou « la »."}, {"equals": "و", "category": "word_confusion", "feedback": "و seul devant un mot veut dire « et »."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e10', 'ar', 'ar.l26', 'ar.v.kanisa', array['ar.v.kanisa','ar.g26.long_words']::text[], 'mcq', 'lesson', 'الكنيسة', array['l''église']::text[], 'ال + كنيسة : ال veut dire « le » ou « la », كنيسة est l''église. Ensemble : « l''église ».', 2, '{"id": "ar.l26.e10", "type": "mcq", "unitIds": ["ar.v.kanisa", "ar.g26.long_words"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "الكنيسة", "promptLanguage": "ar", "options": ["une école", "la maison", "la porte", "l''église"], "answer": "l''église", "acceptedAnswers": ["l''église"], "explanation": "ال + كنيسة : ال veut dire « le » ou « la », كنيسة est l''église. Ensemble : « l''église ».", "tip": "Enlève ال, lis le reste, puis remets-le.", "extraExample": {"text": "الكنيسة كبيرة.", "translation": "L''église est grande."}, "errorPatterns": [{"equals": "une école", "category": "word_confusion", "feedback": "« une école » ne correspond pas : relis الكنيسة bloc par bloc. Ici, le sens est « l''église »."}, {"equals": "la maison", "category": "word_confusion", "feedback": "« la maison » ne correspond pas : relis الكنيسة bloc par bloc. Ici, le sens est « l''église »."}, {"equals": "la porte", "category": "word_confusion", "feedback": "« la porte » ne correspond pas : relis الكنيسة bloc par bloc. Ici, le sens est « l''église »."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e11', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.madrasa','ar.v.mustashfa','ar.v.gamia','ar.v.matam']::text[], 'match', 'lesson', 'Relie chaque lieu à son sens.', '{}'::text[], 'Quatre lieux de la ville : مدرسة (3 blocs), مستشفى (1 bloc), جامعة (2 blocs) et مطعم (1 bloc). Coupe, lis, recolle.', 2, '{"id": "ar.l26.e11", "type": "match", "unitIds": ["ar.g26.long_words", "ar.v.madrasa", "ar.v.mustashfa", "ar.v.gamia", "ar.v.matam"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque lieu à son sens.", "promptLanguage": "fr", "pairs": [{"left": "مدرسة", "right": "école"}, {"left": "مستشفى", "right": "hôpital"}, {"left": "جامعة", "right": "université"}, {"left": "مطعم", "right": "restaurant"}], "acceptedAnswers": [], "answer": "مدرسة = école ; مستشفى = hôpital ; جامعة = université ; مطعم = restaurant", "explanation": "Quatre lieux de la ville : مدرسة (3 blocs), مستشفى (1 bloc), جامعة (2 blocs) et مطعم (1 bloc). Coupe, lis, recolle.", "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e12', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.mobail','ar.v.utobis','ar.v.telifun','ar.v.al_qahira']::text[], 'match', 'lesson', 'Relie chaque mot à son sens : la ville et la rue.', '{}'::text[], 'Des mots de tous les jours, écrits comme on les dit : موبايل, أتوبيس et تليفون viennent de l''étranger, القاهرة est ال + قاهرة.', 2, '{"id": "ar.l26.e12", "type": "match", "unitIds": ["ar.g26.long_words", "ar.v.mobail", "ar.v.utobis", "ar.v.telifun", "ar.v.al_qahira"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot à son sens : la ville et la rue.", "promptLanguage": "fr", "pairs": [{"left": "موبايل", "right": "portable"}, {"left": "أتوبيس", "right": "bus"}, {"left": "تليفون", "right": "téléphone"}, {"left": "القاهرة", "right": "Le Caire"}], "acceptedAnswers": [], "answer": "موبايل = portable ; أتوبيس = bus ; تليفون = téléphone ; القاهرة = Le Caire", "explanation": "Des mots de tous les jours, écrits comme on les dit : موبايل, أتوبيس et تليفون viennent de l''étranger, القاهرة est ال + قاهرة.", "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e13', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.telifun','ar.v.gamia','ar.v.madrasa','ar.v.mobail']::text[], 'match', 'lesson', 'Relie chaque mot à ses blocs.', '{}'::text[], 'On coupe après chaque ا د ذ ر ز و : تليفو | ن (le و), جا | معة (le ا), مد | ر | سة (le د et le ر), مو | با | يل (le و et le ا).', 3, '{"id": "ar.l26.e13", "type": "match", "unitIds": ["ar.g26.long_words", "ar.v.telifun", "ar.v.gamia", "ar.v.madrasa", "ar.v.mobail"], "difficulty": 3, "instruction": "Relie chaque mot à sa coupure en blocs.", "prompt": "Relie chaque mot à ses blocs.", "promptLanguage": "fr", "pairs": [{"left": "تليفون", "right": "تليفو | ن"}, {"left": "جامعة", "right": "جا | معة"}, {"left": "مدرسة", "right": "مد | ر | سة"}, {"left": "موبايل", "right": "مو | با | يل"}], "acceptedAnswers": [], "answer": "تليفون = تليفو | ن ; جامعة = جا | معة ; مدرسة = مد | ر | سة ; موبايل = مو | با | يل", "explanation": "On coupe après chaque ا د ذ ر ز و : تليفو | ن (le و), جا | معة (le ا), مد | ر | سة (le د et le ر), مو | با | يل (le و et le ا).", "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e14', 'ar', 'ar.l26', 'ar.v.mama', array['ar.v.mama','ar.v.walad','ar.v.otta','ar.v.milh','ar.g26.long_words']::text[], 'match', 'lesson', 'Relie chaque mot de la leçon 25 à son sens.', '{}'::text[], 'Retour aux mots courts : ماما (ما | ما), ولد (le و est une consonne), قطة (ق ط ة) et ملح (trois consonnes).', 2, '{"id": "ar.l26.e14", "type": "match", "unitIds": ["ar.v.mama", "ar.v.walad", "ar.v.otta", "ar.v.milh", "ar.g26.long_words"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot de la leçon 25 à son sens.", "promptLanguage": "fr", "pairs": [{"left": "ماما", "right": "maman"}, {"left": "ولد", "right": "garçon"}, {"left": "قطة", "right": "chat"}, {"left": "ملح", "right": "sel"}], "acceptedAnswers": [], "answer": "ماما = maman ; ولد = garçon ; قطة = chat ; ملح = sel", "explanation": "Retour aux mots courts : ماما (ما | ما), ولد (le و est une consonne), قطة (ق ط ة) et ملح (trois consonnes).", "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e15', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.telifun']::text[], 'fill_blank', 'lesson', 'تليفو | ___ (téléphone)', array['ن']::text[], 'تليفون se coupe après le و : تليفو | ن. Le dernier bloc est le ن tout seul.', 2, '{"id": "ar.l26.e15", "type": "fill_blank", "unitIds": ["ar.g26.long_words", "ar.v.telifun"], "difficulty": 2, "instruction": "Complète le dernier bloc.", "prompt": "تليفو | ___ (téléphone)", "promptLanguage": "ar", "options": ["ل", "ن", "م", "ب"], "answer": "ن", "acceptedAnswers": ["ن"], "explanation": "تليفون se coupe après le و : تليفو | ن. Le dernier bloc est le ن tout seul.", "tip": "Le dernier bloc d''un mot peut être une seule lettre.", "extraExample": {"text": "جامعة", "translation": "جا | معة"}, "errorPatterns": [{"equals": "ل", "category": "spelling", "feedback": "Le dernier bloc de « téléphone » est un ن, avec 1 point dessus."}, {"equals": "م", "category": "spelling", "feedback": "م est une boule sans point ; ici la lettre a 1 point dessus."}, {"equals": "ب", "category": "spelling", "feedback": "ب a 1 point dessous ; ici le point est dessus."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e16', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.mobail']::text[], 'fill_blank', 'lesson', 'مو | با | ___ (portable)', array['يل']::text[], 'موبايل se coupe en مو | با | يل : le ا ferme le deuxième bloc, il reste le ي et le ل.', 2, '{"id": "ar.l26.e16", "type": "fill_blank", "unitIds": ["ar.g26.long_words", "ar.v.mobail"], "difficulty": 2, "instruction": "Complète le dernier bloc.", "prompt": "مو | با | ___ (portable)", "promptLanguage": "ar", "options": ["ين", "بل", "ول", "يل"], "answer": "يل", "acceptedAnswers": ["يل"], "explanation": "موبايل se coupe en مو | با | يل : le ا ferme le deuxième bloc, il reste le ي et le ل.", "tip": "Après un ا, le bloc suivant repart à neuf.", "extraExample": {"text": "موبايل جديد", "translation": "un portable neuf"}, "errorPatterns": [{"equals": "ين", "category": "spelling", "feedback": "« ين » ne finit pas موبايل : le mot finit par ي + ل."}, {"equals": "بل", "category": "spelling", "feedback": "« بل » ne finit pas موبايل : le mot finit par ي + ل."}, {"equals": "ول", "category": "spelling", "feedback": "« ول » ne finit pas موبايل : le mot finit par ي + ل."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e17', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.al_qahira']::text[], 'fill_blank', 'lesson', 'ا | لقا | هر | ___ (Le Caire)', array['ة']::text[], 'القاهرة finit par le ة, qui reste seul dans son bloc parce que le ر ne s''attache pas. Il a 2 points dessus.', 3, '{"id": "ar.l26.e17", "type": "fill_blank", "unitIds": ["ar.g26.long_words", "ar.v.al_qahira"], "difficulty": 3, "instruction": "Complète le dernier bloc.", "prompt": "ا | لقا | هر | ___ (Le Caire)", "promptLanguage": "ar", "options": ["ه", "ة", "ى", "ا"], "answer": "ة", "acceptedAnswers": ["ة"], "explanation": "القاهرة finit par le ة, qui reste seul dans son bloc parce que le ر ne s''attache pas. Il a 2 points dessus.", "tip": "ة a toujours 2 points dessus.", "extraExample": {"text": "مدرسة", "translation": "مد | ر | سة"}, "errorPatterns": [{"equals": "ه", "category": "spelling", "feedback": "ه n''a aucun point ; la fin de القاهرة porte 2 points : c''est ة."}, {"equals": "ى", "category": "spelling", "feedback": "ى finit les mots en a long, mais ici il y a 2 points dessus : c''est ة."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e18', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.mustashfa']::text[], 'translation', 'lesson', 'مستشفى', array['hôpital','l''hôpital','un hôpital','hopital']::text[], 'مستشفى est un seul bloc de six lettres, lu en paquets مس | تش | فى : « hôpital ».', 2, '{"id": "ar.l26.e18", "type": "translation", "unitIds": ["ar.g26.long_words", "ar.v.mustashfa"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "مستشفى", "promptLanguage": "ar", "answer": "hôpital", "acceptedAnswers": ["hôpital", "l''hôpital", "un hôpital", "hopital"], "explanation": "مستشفى est un seul bloc de six lettres, lu en paquets مس | تش | فى : « hôpital ».", "tip": "Pense aux dents س ش au milieu.", "extraExample": {"text": "المستشفى قريب.", "translation": "L''hôpital est près d''ici."}, "pool": "lesson", "lessonId": "ar.l26", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e19', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.telifun']::text[], 'translation', 'lesson', 'تليفون', array['téléphone','le téléphone','un téléphone','telephone']::text[], 'تليفو | ن : le mot qu''on entend partout, écrit comme on le dit.', 2, '{"id": "ar.l26.e19", "type": "translation", "unitIds": ["ar.g26.long_words", "ar.v.telifun"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "تليفون", "promptLanguage": "ar", "answer": "téléphone", "acceptedAnswers": ["téléphone", "le téléphone", "un téléphone", "telephone"], "explanation": "تليفو | ن : le mot qu''on entend partout, écrit comme on le dit.", "tip": "Coupe après le و.", "extraExample": {"text": "التليفون بيرن.", "translation": "Le téléphone sonne."}, "pool": "lesson", "lessonId": "ar.l26", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e20', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.al_katidraiya']::text[], 'translation', 'lesson', 'الكاتدرائية', array['cathédrale','la cathédrale','une cathédrale','cathedrale','la cathedrale']::text[], 'ا | لكا | تد | ر | ا | ئية : six blocs. On met ال de côté et on lit كاتدرائية : « cathédrale ».', 3, '{"id": "ar.l26.e20", "type": "translation", "unitIds": ["ar.g26.long_words", "ar.v.al_katidraiya"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "الكاتدرائية", "promptLanguage": "ar", "answer": "cathédrale", "acceptedAnswers": ["cathédrale", "la cathédrale", "une cathédrale", "cathedrale", "la cathedrale"], "explanation": "ا | لكا | تد | ر | ا | ئية : six blocs. On met ال de côté et on lit كاتدرائية : « cathédrale ».", "tip": "Lis ال, puis avance bloc par bloc.", "extraExample": {"text": "الكاتدرائية كبيرة.", "translation": "La cathédrale est grande."}, "pool": "lesson", "lessonId": "ar.l26", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e21', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.al_katidraiya']::text[], 'free_answer', 'lesson', 'Combien de blocs compte الكاتدرائية ?', array['six','6','six blocs','6 blocs']::text[], 'Chaque ا, د, ر ferme un bloc, et le dernier bloc ئية termine le mot : ا | لكا | تد | ر | ا | ئية, six blocs.', 3, '{"id": "ar.l26.e21", "type": "free_answer", "unitIds": ["ar.g26.long_words", "ar.v.al_katidraiya"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Combien de blocs compte الكاتدرائية ?", "promptLanguage": "fr", "answer": "six", "acceptedAnswers": ["six", "6", "six blocs", "6 blocs"], "explanation": "Chaque ا, د, ر ferme un bloc, et le dernier bloc ئية termine le mot : ا | لكا | تد | ر | ا | ئية, six blocs.", "tip": "Pose un trait après chaque ا د ر, puis compte les morceaux.", "extraExample": {"text": "القاهرة", "translation": "ا | لقا | هر | ة : quatre blocs"}, "errorPatterns": [{"equals": "cinq", "category": "vocabulary", "feedback": "Tu as oublié le dernier bloc ئية : il y en a six."}, {"equals": "5", "category": "vocabulary", "feedback": "Tu as oublié le dernier bloc ئية : il y en a six."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e22', 'ar', 'ar.l26', 'ar.g26.long_words', array['ar.g26.long_words','ar.v.matam']::text[], 'free_answer', 'lesson', 'Que veut dire مطعم ?', array['restaurant','un restaurant','le restaurant']::text[], 'مطعم = مط | عم, un seul bloc de quatre lettres : « restaurant ».', 2, '{"id": "ar.l26.e22", "type": "free_answer", "unitIds": ["ar.g26.long_words", "ar.v.matam"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire مطعم ?", "promptLanguage": "fr", "answer": "restaurant", "acceptedAnswers": ["restaurant", "un restaurant", "le restaurant"], "explanation": "مطعم = مط | عم, un seul bloc de quatre lettres : « restaurant ».", "tip": "Un seul bloc : coupe-le en deux paquets, مط | عم.", "extraExample": {"text": "المطعم فاتح.", "translation": "Le restaurant est ouvert."}, "pool": "lesson", "lessonId": "ar.l26", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e01', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ezzayyak']::text[], 'mcq', 'lesson', 'إزيك', array['Comment vas-tu ?']::text[], 'إ | ز | يك : trois blocs, إ | ز | يك. C''est la question qu''on pose en premier à quelqu''un.', 1, '{"id": "ar.l27.e01", "type": "mcq", "unitIds": ["ar.g27.short_sentences", "ar.v.ezzayyak"], "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "إزيك", "promptLanguage": "ar", "options": ["Où est l''église ?", "Comment vas-tu ?", "Je veux du thé.", "Merci."], "answer": "Comment vas-tu ?", "acceptedAnswers": ["Comment vas-tu ?"], "explanation": "إ | ز | يك : trois blocs, إ | ز | يك. C''est la question qu''on pose en premier à quelqu''un.", "tip": "Trois blocs : un إ seul, un ز seul, puis يك.", "extraExample": {"text": "إزيك يا مينا؟", "translation": "Comment vas-tu, Mina ?"}, "errorPatterns": [{"equals": "Où est l''église ?", "category": "word_confusion", "feedback": "« Où est l''église ? » ne correspond pas : relis إزيك bloc par bloc. Ici, le sens est « Comment vas-tu ? »."}, {"equals": "Je veux du thé.", "category": "word_confusion", "feedback": "« Je veux du thé. » ne correspond pas : relis إزيك bloc par bloc. Ici, le sens est « Comment vas-tu ? »."}, {"equals": "Merci.", "category": "word_confusion", "feedback": "« Merci. » ne correspond pas : relis إزيك bloc par bloc. Ici, le sens est « Comment vas-tu ? »."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e02', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.kwayyis']::text[], 'mcq', 'lesson', 'كويس', array['bien']::text[], 'كو | يس : le و ferme le premier bloc, puis يس. C''est le mot égyptien pour « bien ».', 1, '{"id": "ar.l27.e02", "type": "mcq", "unitIds": ["ar.g27.short_sentences", "ar.v.kwayyis"], "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "كويس", "promptLanguage": "ar", "options": ["merci", "où", "thé", "bien"], "answer": "bien", "acceptedAnswers": ["bien"], "explanation": "كو | يس : le و ferme le premier bloc, puis يس. C''est le mot égyptien pour « bien ».", "tip": "Le و au milieu de كويس fait un paquet long.", "extraExample": {"text": "الشاي كويس.", "translation": "Le thé est bon."}, "errorPatterns": [{"equals": "merci", "category": "word_confusion", "feedback": "« merci » ne correspond pas : relis كويس bloc par bloc. Ici, le sens est « bien »."}, {"equals": "où", "category": "word_confusion", "feedback": "« où » ne correspond pas : relis كويس bloc par bloc. Ici, le sens est « bien »."}, {"equals": "thé", "category": "word_confusion", "feedback": "« thé » ne correspond pas : relis كويس bloc par bloc. Ici, le sens est « bien »."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e03', 'ar', 'ar.l27', 'ar.v.jaan', array['ar.v.jaan','ar.v.ana','ar.g27.short_sentences']::text[], 'mcq', 'lesson', 'أنا جعان', array['J''ai faim.']::text[], 'أنا veut dire « je » et جعان (module 2) veut dire « affamé ». Sans verbe « être » : « moi affamé », c''est-à-dire « j''ai faim ».', 2, '{"id": "ar.l27.e03", "type": "mcq", "unitIds": ["ar.v.jaan", "ar.v.ana", "ar.g27.short_sentences"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "أنا جعان", "promptLanguage": "ar", "options": ["Je veux du thé.", "J''ai faim.", "Je vais bien, Dieu merci.", "Où est l''église ?"], "answer": "J''ai faim.", "acceptedAnswers": ["J''ai faim."], "explanation": "أنا veut dire « je » et جعان (module 2) veut dire « affamé ». Sans verbe « être » : « moi affamé », c''est-à-dire « j''ai faim ».", "tip": "Deux mots, deux images : أنا + جعان.", "extraExample": {"text": "أنا جعان أوي.", "translation": "J''ai très faim."}, "errorPatterns": [{"equals": "Je veux du thé.", "category": "word_confusion", "feedback": "« Je veux du thé. » ne correspond pas : relis أنا جعان bloc par bloc. Ici, le sens est « J''ai faim. »."}, {"equals": "Je vais bien, Dieu merci.", "category": "word_confusion", "feedback": "« Je vais bien, Dieu merci. » ne correspond pas : relis أنا جعان bloc par bloc. Ici, le sens est « J''ai faim. »."}, {"equals": "Où est l''église ?", "category": "word_confusion", "feedback": "« Où est l''église ? » ne correspond pas : relis أنا جعان bloc par bloc. Ici, le sens est « J''ai faim. »."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e04', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.fin','ar.v.kanisa']::text[], 'mcq', 'lesson', 'فين الكنيسة؟', array['Où est l''église ?']::text[], 'فين (où) ouvre la phrase, puis الكنيسة (ال + كنيسة) : « Où est l''église ? »', 2, '{"id": "ar.l27.e04", "type": "mcq", "unitIds": ["ar.g27.short_sentences", "ar.v.fin", "ar.v.kanisa"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "فين الكنيسة؟", "promptLanguage": "ar", "options": ["Comment vas-tu ?", "J''ai faim.", "Merci.", "Où est l''église ?"], "answer": "Où est l''église ?", "acceptedAnswers": ["Où est l''église ?"], "explanation": "فين (où) ouvre la phrase, puis الكنيسة (ال + كنيسة) : « Où est l''église ? »", "tip": "Le mot de question vient en premier.", "extraExample": {"text": "فين الباب؟", "translation": "Où est la porte ?"}, "errorPatterns": [{"equals": "Comment vas-tu ?", "category": "word_confusion", "feedback": "« Comment vas-tu ? » ne correspond pas : relis فين الكنيسة؟ bloc par bloc. Ici, le sens est « Où est l''église ? »."}, {"equals": "J''ai faim.", "category": "word_confusion", "feedback": "« J''ai faim. » ne correspond pas : relis فين الكنيسة؟ bloc par bloc. Ici, le sens est « Où est l''église ? »."}, {"equals": "Merci.", "category": "word_confusion", "feedback": "« Merci. » ne correspond pas : relis فين الكنيسة؟ bloc par bloc. Ici, le sens est « Où est l''église ? »."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e05', 'ar', 'ar.l27', 'ar.v.ayiz', array['ar.v.ayiz','ar.v.shay','ar.g27.short_sentences']::text[], 'mcq', 'lesson', 'عايز شاي', array['Je veux du thé.']::text[], 'عايز (je veux) et شاي (thé), deux mots du module 2 : « Je veux du thé. » Pas de ـة à عايز : c''est un homme qui parle.', 2, '{"id": "ar.l27.e05", "type": "mcq", "unitIds": ["ar.v.ayiz", "ar.v.shay", "ar.g27.short_sentences"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "عايز شاي", "promptLanguage": "ar", "options": ["J''ai faim.", "Je veux du thé.", "Maman veut du thé.", "Où est le thé ?"], "answer": "Je veux du thé.", "acceptedAnswers": ["Je veux du thé."], "explanation": "عايز (je veux) et شاي (thé), deux mots du module 2 : « Je veux du thé. » Pas de ـة à عايز : c''est un homme qui parle.", "tip": "Un ـة à la fin de عايز signale une femme.", "extraExample": {"text": "عايز عيش.", "translation": "Je veux du pain."}, "errorPatterns": [{"equals": "J''ai faim.", "category": "word_confusion", "feedback": "« J''ai faim. » ne correspond pas : relis عايز شاي bloc par bloc. Ici, le sens est « Je veux du thé. »."}, {"equals": "Maman veut du thé.", "category": "word_confusion", "feedback": "« Maman veut du thé. » ne correspond pas : relis عايز شاي bloc par bloc. Ici, le sens est « Je veux du thé. »."}, {"equals": "Où est le thé ?", "category": "word_confusion", "feedback": "« Où est le thé ? » ne correspond pas : relis عايز شاي bloc par bloc. Ici, le sens est « Je veux du thé. »."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e06', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ezzayyak','ar.v.kwayyis']::text[], 'mcq', 'lesson', 'Quelle phrase répond à إزيك ؟', array['أنا كويس، الحمد لله']::text[], 'À une question de nouvelles, on répond par des nouvelles : أنا كويس، الحمد لله. عايز شاي exprime un souhait et فين الكنيسة؟ pose une autre question.', 2, '{"id": "ar.l27.e06", "type": "mcq", "unitIds": ["ar.g27.short_sentences", "ar.v.ezzayyak", "ar.v.kwayyis"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle phrase répond à إزيك ؟", "promptLanguage": "ar", "options": ["عايز شاي", "فين الكنيسة؟", "شكرا", "أنا كويس، الحمد لله"], "answer": "أنا كويس، الحمد لله", "acceptedAnswers": ["أنا كويس، الحمد لله"], "explanation": "À une question de nouvelles, on répond par des nouvelles : أنا كويس، الحمد لله. عايز شاي exprime un souhait et فين الكنيسة؟ pose une autre question.", "tip": "Question de nouvelles, réponse de nouvelles.", "extraExample": {"text": "إزيك؟ أنا كويس، الحمد لله.", "translation": "— Comment vas-tu ? — Je vais bien, Dieu merci."}, "errorPatterns": [{"equals": "عايز شاي", "category": "vocabulary", "feedback": "عايز شاي veut dire « Je veux du thé. » : ce n''est pas une réponse à des nouvelles."}, {"equals": "فين الكنيسة؟", "category": "vocabulary", "feedback": "فين الكنيسة؟ est une question (« Où est l''église ? »), pas une réponse."}, {"equals": "شكرا", "category": "vocabulary", "feedback": "شكرا veut dire « merci » : on remercie, on ne donne pas de ses nouvelles."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e07', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.sabah_el_kheir','ar.v.nur']::text[], 'mcq', 'lesson', 'Que répond-on à صباح الخير ?', array['صباح النور']::text[], 'On répond à un souhait par un souhait plus beau : صباح النور, « matin de lumière ».', 2, '{"id": "ar.l27.e07", "type": "mcq", "unitIds": ["ar.g27.short_sentences", "ar.v.sabah_el_kheir", "ar.v.nur"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que répond-on à صباح الخير ?", "promptLanguage": "fr", "options": ["شكرا", "صباح النور", "إزيك", "لو سمحت"], "answer": "صباح النور", "acceptedAnswers": ["صباح النور"], "explanation": "On répond à un souhait par un souhait plus beau : صباح النور, « matin de lumière ».", "tip": "Bien → lumière : النور.", "extraExample": {"text": "صباح الخير يا مينا.", "translation": "Bonjour Mina."}, "errorPatterns": [{"equals": "شكرا", "category": "vocabulary", "feedback": "« شكرا » ne répond pas à un salut du matin : on répond صباح النور."}, {"equals": "إزيك", "category": "vocabulary", "feedback": "« إزيك » ne répond pas à un salut du matin : on répond صباح النور."}, {"equals": "لو سمحت", "category": "vocabulary", "feedback": "« لو سمحت » ne répond pas à un salut du matin : on répond صباح النور."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e08', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.law_samaht','ar.v.fin']::text[], 'mcq', 'lesson', 'Pour demander poliment où est l''église, tu dis…', array['لو سمحت، فين الكنيسة؟']::text[], 'لو سمحت (excuse-moi) ouvre la phrase et فين الكنيسة؟ pose la question. لو سمحت، عايز شاي demande du thé, pas l''église.', 3, '{"id": "ar.l27.e08", "type": "mcq", "unitIds": ["ar.g27.short_sentences", "ar.v.law_samaht", "ar.v.fin"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pour demander poliment où est l''église, tu dis…", "promptLanguage": "ar", "options": ["أنا كويس، الحمد لله", "لو سمحت، عايز شاي", "إزيك يا مينا؟", "لو سمحت، فين الكنيسة؟"], "answer": "لو سمحت، فين الكنيسة؟", "acceptedAnswers": ["لو سمحت، فين الكنيسة؟"], "explanation": "لو سمحت (excuse-moi) ouvre la phrase et فين الكنيسة؟ pose la question. لو سمحت، عايز شاي demande du thé, pas l''église.", "tip": "Cherche فين : c''est lui qui veut dire « où ».", "extraExample": {"text": "لو سمحت، فين الباب؟", "translation": "Excuse-moi, où est la porte ?"}, "errorPatterns": [{"equals": "أنا كويس، الحمد لله", "category": "vocabulary", "feedback": "C''est une réponse de nouvelles, pas une question."}, {"equals": "لو سمحت، عايز شاي", "category": "vocabulary", "feedback": "Cette phrase demande du thé : il n''y a pas de فين, donc pas de « où »."}, {"equals": "إزيك يا مينا؟", "category": "vocabulary", "feedback": "C''est une question de nouvelles : « Comment vas-tu, Mina ? »"}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e09', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ya_nida']::text[], 'mcq', 'lesson', 'Quel petit mot sert à appeler quelqu''un, comme dans إزيك يا مينا ؟', array['يا']::text[], 'يا se met devant un prénom pour appeler la personne : يا مينا. Tu le retrouveras dans يا رب.', 3, '{"id": "ar.l27.e09", "type": "mcq", "unitIds": ["ar.g27.short_sentences", "ar.v.ya_nida"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel petit mot sert à appeler quelqu''un, comme dans إزيك يا مينا ؟", "promptLanguage": "fr", "options": ["أنا", "يا", "فين", "كويس"], "answer": "يا", "acceptedAnswers": ["يا"], "explanation": "يا se met devant un prénom pour appeler la personne : يا مينا. Tu le retrouveras dans يا رب.", "tip": "يا + prénom : on s''adresse à quelqu''un.", "extraExample": {"text": "أهلا يا مريم", "translation": "Salut Mariam"}, "errorPatterns": [{"equals": "أنا", "category": "word_confusion", "feedback": "أنا veut dire « je »."}, {"equals": "فين", "category": "word_confusion", "feedback": "فين veut dire « où »."}, {"equals": "كويس", "category": "word_confusion", "feedback": "كويس veut dire « bien »."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e10', 'ar', 'ar.l27', 'ar.v.mama', array['ar.v.mama','ar.v.ayiz','ar.g27.short_sentences']::text[], 'mcq', 'lesson', 'ماما عايزة شاي', array['Maman veut du thé.']::text[], 'ماما (maman, leçon 25) + عايزة (elle veut) + شاي (thé). Le ـة de عايزة montre que c''est une femme qui veut.', 2, '{"id": "ar.l27.e10", "type": "mcq", "unitIds": ["ar.v.mama", "ar.v.ayiz", "ar.g27.short_sentences"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "ماما عايزة شاي", "promptLanguage": "ar", "options": ["Papa veut du thé.", "Maman a faim.", "Mamie veut du thé.", "Maman veut du thé."], "answer": "Maman veut du thé.", "acceptedAnswers": ["Maman veut du thé."], "explanation": "ماما (maman, leçon 25) + عايزة (elle veut) + شاي (thé). Le ـة de عايزة montre que c''est une femme qui veut.", "tip": "عايزة avec ـة : une femme veut.", "extraExample": {"text": "بابا عايز شاي.", "translation": "Papa veut du thé."}, "errorPatterns": [{"equals": "Papa veut du thé.", "category": "word_confusion", "feedback": "« Papa veut du thé. » ne correspond pas : relis ماما عايزة شاي bloc par bloc. Ici, le sens est « Maman veut du thé. »."}, {"equals": "Maman a faim.", "category": "word_confusion", "feedback": "« Maman a faim. » ne correspond pas : relis ماما عايزة شاي bloc par bloc. Ici, le sens est « Maman veut du thé. »."}, {"equals": "Mamie veut du thé.", "category": "word_confusion", "feedback": "« Mamie veut du thé. » ne correspond pas : relis ماما عايزة شاي bloc par bloc. Ici, le sens est « Maman veut du thé. »."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e11', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ana','ar.v.kwayyis','ar.v.fin','ar.v.shokran']::text[], 'match', 'lesson', 'Relie chaque mot à son sens (1).', '{}'::text[], 'Quatre petits mots que tu verras partout : أنا (je), كويس (bien), فين (où, avec son ن final) et شكرا (merci).', 1, '{"id": "ar.l27.e11", "type": "match", "unitIds": ["ar.g27.short_sentences", "ar.v.ana", "ar.v.kwayyis", "ar.v.fin", "ar.v.shokran"], "difficulty": 1, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot à son sens (1).", "promptLanguage": "fr", "pairs": [{"left": "أنا", "right": "je, moi"}, {"left": "كويس", "right": "bien"}, {"left": "فين", "right": "où"}, {"left": "شكرا", "right": "merci"}], "acceptedAnswers": [], "answer": "أنا = je, moi ; كويس = bien ; فين = où ; شكرا = merci", "explanation": "Quatre petits mots que tu verras partout : أنا (je), كويس (bien), فين (où, avec son ن final) et شكرا (merci).", "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e12', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ahlan','ar.v.law_samaht','ar.v.sabah_el_kheir','ar.v.ezzayyak']::text[], 'match', 'lesson', 'Relie chaque mot à son sens (2).', '{}'::text[], 'Quatre mots de politesse : on salue avec أهلا, on demande de l''attention avec لو سمحت, on souhaite le bonjour avec صباح الخير et on prend des nouvelles avec إزيك.', 2, '{"id": "ar.l27.e12", "type": "match", "unitIds": ["ar.g27.short_sentences", "ar.v.ahlan", "ar.v.law_samaht", "ar.v.sabah_el_kheir", "ar.v.ezzayyak"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot à son sens (2).", "promptLanguage": "fr", "pairs": [{"left": "أهلا", "right": "salut, bienvenue"}, {"left": "لو سمحت", "right": "excuse-moi"}, {"left": "صباح الخير", "right": "bonjour (le matin)"}, {"left": "إزيك", "right": "comment vas-tu ?"}], "acceptedAnswers": [], "answer": "أهلا = salut, bienvenue ; لو سمحت = excuse-moi ; صباح الخير = bonjour (le matin) ; إزيك = comment vas-tu ?", "explanation": "Quatre mots de politesse : on salue avec أهلا, on demande de l''attention avec لو سمحت, on souhaite le bonjour avec صباح الخير et on prend des nouvelles avec إزيك.", "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e13', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ezzayyak','ar.v.fin','ar.v.ayiz','ar.v.jaan']::text[], 'match', 'lesson', 'Relie chaque phrase à son sens.', '{}'::text[], 'Quatre phrases de la leçon : une question de nouvelles, une question de lieu, un souhait et un état. Repère le mot clé de chacune : إزيك, فين, عايز, جعان.', 3, '{"id": "ar.l27.e13", "type": "match", "unitIds": ["ar.g27.short_sentences", "ar.v.ezzayyak", "ar.v.fin", "ar.v.ayiz", "ar.v.jaan"], "difficulty": 3, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque phrase à son sens.", "promptLanguage": "fr", "pairs": [{"left": "إزيك؟", "right": "Comment vas-tu ?"}, {"left": "فين الكنيسة؟", "right": "Où est l''église ?"}, {"left": "عايز شاي", "right": "Je veux du thé."}, {"left": "أنا جعان", "right": "J''ai faim."}], "acceptedAnswers": [], "answer": "إزيك؟ = Comment vas-tu ? ; فين الكنيسة؟ = Où est l''église ? ; عايز شاي = Je veux du thé. ; أنا جعان = J''ai faim.", "explanation": "Quatre phrases de la leçon : une question de nouvelles, une question de lieu, un souhait et un état. Repère le mot clé de chacune : إزيك, فين, عايز, جعان.", "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e14', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.kwayyis']::text[], 'fill_blank', 'lesson', 'أنا ___، الحمد لله (Je vais bien, Dieu merci.)', array['كويس']::text[], 'Après أنا، on met l''état : كويس pour « bien ». جعان voudrait dire « j''ai faim ».', 2, '{"id": "ar.l27.e14", "type": "fill_blank", "unitIds": ["ar.g27.short_sentences", "ar.v.kwayyis"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "أنا ___، الحمد لله (Je vais bien, Dieu merci.)", "promptLanguage": "ar", "options": ["جعان", "فين", "شاي", "كويس"], "answer": "كويس", "acceptedAnswers": ["كويس"], "explanation": "Après أنا، on met l''état : كويس pour « bien ». جعان voudrait dire « j''ai faim ».", "tip": "Le mot qui veut dire « bien » est كويس.", "extraExample": {"text": "أنا كويس.", "translation": "Je vais bien."}, "errorPatterns": [{"equals": "جعان", "category": "vocabulary", "feedback": "أنا جعان veut dire « J''ai faim. », pas « Je vais bien. »"}, {"equals": "فين", "category": "vocabulary", "feedback": "فين veut dire « où » : il ne dit pas comment on va."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e15', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.fin']::text[], 'fill_blank', 'lesson', '___ الكنيسة؟ (Où est l''église ?)', array['فين']::text[], 'Pour demander « où », on commence la phrase par فين.', 2, '{"id": "ar.l27.e15", "type": "fill_blank", "unitIds": ["ar.g27.short_sentences", "ar.v.fin"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "___ الكنيسة؟ (Où est l''église ?)", "promptLanguage": "ar", "options": ["أنا", "فين", "كويس", "شكرا"], "answer": "فين", "acceptedAnswers": ["فين"], "explanation": "Pour demander « où », on commence la phrase par فين.", "tip": "فين ouvre la question.", "extraExample": {"text": "فين الباب؟", "translation": "Où est la porte ?"}, "errorPatterns": [{"equals": "أنا", "category": "vocabulary", "feedback": "أنا veut dire « je » : la phrase demande un lieu."}, {"equals": "شكرا", "category": "vocabulary", "feedback": "شكرا veut dire « merci »."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e16', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ya_nida']::text[], 'fill_blank', 'lesson', 'إزيك ___ مينا؟ (Comment vas-tu, Mina ?)', array['يا']::text[], 'يا se place devant le prénom de la personne qu''on appelle : يا مينا.', 3, '{"id": "ar.l27.e16", "type": "fill_blank", "unitIds": ["ar.g27.short_sentences", "ar.v.ya_nida"], "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "إزيك ___ مينا؟ (Comment vas-tu, Mina ?)", "promptLanguage": "ar", "options": ["أنا", "فين", "أهلا", "يا"], "answer": "يا", "acceptedAnswers": ["يا"], "explanation": "يا se place devant le prénom de la personne qu''on appelle : يا مينا.", "tip": "يا + prénom.", "extraExample": {"text": "أهلا يا مينا!", "translation": "Salut Mina !"}, "errorPatterns": [{"equals": "أنا", "category": "vocabulary", "feedback": "إزيك أنا مينا voudrait dire autre chose ; ici on appelle Mina avec يا."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e17', 'ar', 'ar.l27', 'ar.v.shay', array['ar.v.shay','ar.v.eish','ar.v.mayya','ar.v.qahwa','ar.g27.short_sentences']::text[], 'fill_blank', 'lesson', 'عايز ___ (Je veux du thé.)', array['شاي']::text[], 'Le mot « thé » est شاي (ش + ا + ي). عيش est le pain, مية l''eau et قهوة le café.', 3, '{"id": "ar.l27.e17", "type": "fill_blank", "unitIds": ["ar.v.shay", "ar.v.eish", "ar.v.mayya", "ar.v.qahwa", "ar.g27.short_sentences"], "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "عايز ___ (Je veux du thé.)", "promptLanguage": "ar", "options": ["عيش", "شاي", "مية", "قهوة"], "answer": "شاي", "acceptedAnswers": ["شاي"], "explanation": "Le mot « thé » est شاي (ش + ا + ي). عيش est le pain, مية l''eau et قهوة le café.", "tip": "Le thé commence par ش : trois dents, trois points dessus.", "extraExample": {"text": "عايز مية.", "translation": "Je veux de l''eau."}, "errorPatterns": [{"equals": "عيش", "category": "vocabulary", "feedback": "عيش veut dire « pain » : ce n''est pas le thé."}, {"equals": "مية", "category": "vocabulary", "feedback": "مية veut dire « eau »."}, {"equals": "قهوة", "category": "vocabulary", "feedback": "قهوة veut dire « café »."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e18', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ana','ar.v.kwayyis','ar.v.elhamdulillah']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Je vais bien, Dieu merci. »', array['أنا كويس الحمد لله','الحمد لله أنا كويس']::text[], 'On met d''abord أنا, puis كويس, puis الحمد لله : « moi bien, Dieu merci ». Le groupe الحمد لله va ensemble.', 3, '{"id": "ar.l27.e18", "type": "reorder", "unitIds": ["ar.g27.short_sentences", "ar.v.ana", "ar.v.kwayyis", "ar.v.elhamdulillah"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Je vais bien, Dieu merci. »", "promptLanguage": "fr", "tokens": ["الحمد", "كويس", "لله", "أنا"], "answer": "أنا كويس الحمد لله", "acceptedAnswers": ["أنا كويس الحمد لله", "الحمد لله أنا كويس"], "explanation": "On met d''abord أنا, puis كويس, puis الحمد لله : « moi bien, Dieu merci ». Le groupe الحمد لله va ensemble.", "tip": "الحمد لله est un groupe de deux mots inséparables.", "extraExample": {"text": "أنا جعان", "translation": "J''ai faim"}, "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e19', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.law_samaht','ar.v.fin']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Excuse-moi, où est l''église ? »', array['لو سمحت فين الكنيسة','فين الكنيسة لو سمحت']::text[], 'لو سمحت est un groupe de deux mots, puis la question فين الكنيسة. On peut aussi mettre لو سمحت à la fin.', 3, '{"id": "ar.l27.e19", "type": "reorder", "unitIds": ["ar.g27.short_sentences", "ar.v.law_samaht", "ar.v.fin"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Excuse-moi, où est l''église ? »", "promptLanguage": "fr", "tokens": ["الكنيسة", "لو", "فين", "سمحت"], "answer": "لو سمحت فين الكنيسة", "acceptedAnswers": ["لو سمحت فين الكنيسة", "فين الكنيسة لو سمحت"], "explanation": "لو سمحت est un groupe de deux mots, puis la question فين الكنيسة. On peut aussi mettre لو سمحت à la fin.", "tip": "لو سمحت ne se coupe pas : les deux mots vont ensemble.", "extraExample": {"text": "لو سمحت فين الباب", "translation": "Excuse-moi, où est la porte ?"}, "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e20', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ezzayyak','ar.v.ya_nida']::text[], 'translation', 'lesson', 'إزيك يا مينا', array['Comment vas-tu, Mina ?','comment vas-tu mina','comment ça va, mina','comment ça va mina','comment tu vas, mina','salut mina, comment vas-tu','comment vas tu mina']::text[], 'إزيك (comment vas-tu) + يا مينا (on appelle Mina). C''est la façon la plus courante de prendre des nouvelles.', 2, '{"id": "ar.l27.e20", "type": "translation", "unitIds": ["ar.g27.short_sentences", "ar.v.ezzayyak", "ar.v.ya_nida"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "إزيك يا مينا", "promptLanguage": "ar", "answer": "Comment vas-tu, Mina ?", "acceptedAnswers": ["Comment vas-tu, Mina ?", "comment vas-tu mina", "comment ça va, mina", "comment ça va mina", "comment tu vas, mina", "salut mina, comment vas-tu", "comment vas tu mina"], "explanation": "إزيك (comment vas-tu) + يا مينا (on appelle Mina). C''est la façon la plus courante de prendre des nouvelles.", "tip": "يا + prénom = on appelle la personne.", "extraExample": {"text": "إزيك يا تيتة؟", "translation": "Comment vas-tu, mamie ?"}, "pool": "lesson", "lessonId": "ar.l27", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e21', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.ana','ar.v.kwayyis','ar.v.elhamdulillah']::text[], 'translation', 'lesson', 'أنا كويس الحمد لله', array['Je vais bien, Dieu merci.','je vais bien dieu merci','ça va bien, dieu merci','ça va, dieu merci','je suis bien, dieu merci','je vais bien, grâce à dieu','je vais bien grâce à dieu']::text[], 'أنا (je) + كويس (bien) + الحمد لله (Dieu merci). C''est la réponse classique à إزيك.', 3, '{"id": "ar.l27.e21", "type": "translation", "unitIds": ["ar.g27.short_sentences", "ar.v.ana", "ar.v.kwayyis", "ar.v.elhamdulillah"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "أنا كويس الحمد لله", "promptLanguage": "ar", "answer": "Je vais bien, Dieu merci.", "acceptedAnswers": ["Je vais bien, Dieu merci.", "je vais bien dieu merci", "ça va bien, dieu merci", "ça va, dieu merci", "je suis bien, dieu merci", "je vais bien, grâce à dieu", "je vais bien grâce à dieu"], "explanation": "أنا (je) + كويس (bien) + الحمد لله (Dieu merci). C''est la réponse classique à إزيك.", "tip": "Cherche l''ordre : je, bien, Dieu merci.", "extraExample": {"text": "أنا كويس", "translation": "Je vais bien"}, "pool": "lesson", "lessonId": "ar.l27", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e22', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.elhamdulillah']::text[], 'free_answer', 'lesson', 'Que veut dire الحمد لله ?', array['Dieu merci','grâce à dieu','louange à dieu','gloire à dieu','merci mon dieu']::text[], 'الحمد لله veut dire à la lettre « la louange est à Dieu ». Les Égyptiens l''emploient comme « Dieu merci ».', 2, '{"id": "ar.l27.e22", "type": "free_answer", "unitIds": ["ar.g27.short_sentences", "ar.v.elhamdulillah"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire الحمد لله ?", "promptLanguage": "fr", "answer": "Dieu merci", "acceptedAnswers": ["Dieu merci", "grâce à dieu", "louange à dieu", "gloire à dieu", "merci mon dieu"], "explanation": "الحمد لله veut dire à la lettre « la louange est à Dieu ». Les Égyptiens l''emploient comme « Dieu merci ».", "tip": "Deux mots qui se disent toujours ensemble.", "extraExample": {"text": "كويس، الحمد لله.", "translation": "Bien, Dieu merci."}, "pool": "lesson", "lessonId": "ar.l27", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e23', 'ar', 'ar.l27', 'ar.g27.short_sentences', array['ar.g27.short_sentences','ar.v.shokran']::text[], 'free_answer', 'lesson', 'Que veut dire شكرا ?', array['merci','merci beaucoup','merci bien']::text[], 'شكرا est le mot pour remercier. On l''entend dix fois par jour dans la rue.', 2, '{"id": "ar.l27.e23", "type": "free_answer", "unitIds": ["ar.g27.short_sentences", "ar.v.shokran"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire شكرا ?", "promptLanguage": "fr", "answer": "merci", "acceptedAnswers": ["merci", "merci beaucoup", "merci bien"], "explanation": "شكرا est le mot pour remercier. On l''entend dix fois par jour dans la rue.", "tip": "Cinq lettres : ش ك ر ا, avec un ر et un ا qui ne s''attachent pas.", "extraExample": {"text": "شكرا كتير.", "translation": "Merci beaucoup."}, "pool": "lesson", "lessonId": "ar.l27", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e01', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.ya_rab_irham']::text[], 'mcq', 'lesson', 'يا رب ارحم', array['Seigneur, aie pitié']::text[], 'يا (appel) + رب (Seigneur) + ارحم (aie pitié) : c''est le « Seigneur, aie pitié » de la liturgie.', 1, '{"id": "ar.l28.e01", "type": "mcq", "unitIds": ["ar.g28.liturgy", "ar.v.ya_rab_irham"], "difficulty": 1, "instruction": "Lis la phrase et choisis son sens.", "prompt": "يا رب ارحم", "promptLanguage": "ar", "options": ["Gloire à toi, Seigneur", "Seigneur, aie pitié", "La paix à tous", "Et à ton esprit aussi"], "answer": "Seigneur, aie pitié", "acceptedAnswers": ["Seigneur, aie pitié"], "explanation": "يا (appel) + رب (Seigneur) + ارحم (aie pitié) : c''est le « Seigneur, aie pitié » de la liturgie.", "tip": "Cherche رب au milieu : c''est « le Seigneur ».", "extraExample": {"text": "يا رب ارحمنا.", "translation": "Seigneur, aie pitié de nous."}, "errorPatterns": [{"equals": "Gloire à toi, Seigneur", "category": "word_confusion", "feedback": "« Gloire à toi, Seigneur » ne correspond pas : relis يا رب ارحم bloc par bloc. Ici, le sens est « Seigneur, aie pitié »."}, {"equals": "La paix à tous", "category": "word_confusion", "feedback": "« La paix à tous » ne correspond pas : relis يا رب ارحم bloc par bloc. Ici, le sens est « Seigneur, aie pitié »."}, {"equals": "Et à ton esprit aussi", "category": "word_confusion", "feedback": "« Et à ton esprit aussi » ne correspond pas : relis يا رب ارحم bloc par bloc. Ici, le sens est « Seigneur, aie pitié »."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e02', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.salam_likol','ar.v.wi_liruhak_ayan']::text[], 'mcq', 'lesson', 'Le prêtre dit « السلام لكل ». Que répond le peuple ?', array['ولروحك أيضا']::text[], 'Au souhait du prêtre, le peuple répond ولروحك أيضا : « Et à ton esprit aussi ». C''est un dialogue appris par cœur.', 1, '{"id": "ar.l28.e02", "type": "mcq", "unitIds": ["ar.g28.liturgy", "ar.v.salam_likol", "ar.v.wi_liruhak_ayan"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Le prêtre dit « السلام لكل ». Que répond le peuple ?", "promptLanguage": "fr", "options": ["المجد لك يا رب", "يا رب ارحم", "بالحقيقة قام", "ولروحك أيضا"], "answer": "ولروحك أيضا", "acceptedAnswers": ["ولروحك أيضا"], "explanation": "Au souhait du prêtre, le peuple répond ولروحك أيضا : « Et à ton esprit aussi ». C''est un dialogue appris par cœur.", "tip": "Souhait de paix → réponse qui commence par و.", "extraExample": {"text": "السلام لكل. ولروحك أيضا.", "translation": "La paix à tous. Et à ton esprit aussi."}, "errorPatterns": [{"equals": "المجد لك يا رب", "category": "vocabulary", "feedback": "C''est une louange (« Gloire à toi, Seigneur »), pas la réponse au souhait de paix."}, {"equals": "يا رب ارحم", "category": "vocabulary", "feedback": "C''est une demande de pitié, pas la réponse à un souhait de paix."}, {"equals": "بالحقيقة قام", "category": "vocabulary", "feedback": "C''est la réponse à المسيح قام, pendant le temps pascal."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e03', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.magd_lak']::text[], 'mcq', 'lesson', 'المجد لك يا رب', array['Gloire à toi, Seigneur']::text[], 'المجد (ال + مجد : la gloire) + لك (à toi) + يا رب : c''est la louange de l''assemblée.', 2, '{"id": "ar.l28.e03", "type": "mcq", "unitIds": ["ar.g28.liturgy", "ar.v.magd_lak"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "المجد لك يا رب", "promptLanguage": "ar", "options": ["Seigneur, aie pitié", "Gloire à toi, Seigneur", "Et à ton esprit aussi", "Le Christ est ressuscité"], "answer": "Gloire à toi, Seigneur", "acceptedAnswers": ["Gloire à toi, Seigneur"], "explanation": "المجد (ال + مجد : la gloire) + لك (à toi) + يا رب : c''est la louange de l''assemblée.", "tip": "لك finit par ك : « à toi ».", "extraExample": {"text": "المجد لك.", "translation": "Gloire à toi."}, "errorPatterns": [{"equals": "Seigneur, aie pitié", "category": "word_confusion", "feedback": "« Seigneur, aie pitié » ne correspond pas : relis المجد لك يا رب bloc par bloc. Ici, le sens est « Gloire à toi, Seigneur »."}, {"equals": "Et à ton esprit aussi", "category": "word_confusion", "feedback": "« Et à ton esprit aussi » ne correspond pas : relis المجد لك يا رب bloc par bloc. Ici, le sens est « Gloire à toi, Seigneur »."}, {"equals": "Le Christ est ressuscité", "category": "word_confusion", "feedback": "« Le Christ est ressuscité » ne correspond pas : relis المجد لك يا رب bloc par bloc. Ici, le sens est « Gloire à toi, Seigneur »."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e04', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.agbiya']::text[], 'mcq', 'lesson', 'Quel mot désigne le livre des prières des heures ?', array['أجبية']::text[], 'أجبية est le livre des heures : les prières de la journée. تسبحة est un office de louange, مزمور un psaume et نبوات des prophéties.', 2, '{"id": "ar.l28.e04", "type": "mcq", "unitIds": ["ar.g28.liturgy", "ar.v.agbiya"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot désigne le livre des prières des heures ?", "promptLanguage": "fr", "options": ["تسبحة", "مزمور", "نبوات", "أجبية"], "answer": "أجبية", "acceptedAnswers": ["أجبية"], "explanation": "أجبية est le livre des heures : les prières de la journée. تسبحة est un office de louange, مزمور un psaume et نبوات des prophéties.", "tip": "Le livre qu''on garde sur soi : أجبية.", "extraExample": {"text": "الأجبية في الشنطة.", "translation": "Le livre des heures est dans le sac."}, "errorPatterns": [{"equals": "تسبحة", "category": "word_confusion", "feedback": "« تسبحة » ne désigne pas le livre des heures : c''est أجبية."}, {"equals": "مزمور", "category": "word_confusion", "feedback": "« مزمور » ne désigne pas le livre des heures : c''est أجبية."}, {"equals": "نبوات", "category": "word_confusion", "feedback": "« نبوات » ne désigne pas le livre des heures : c''est أجبية."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e05', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.tasbiha']::text[], 'mcq', 'lesson', 'Quel mot désigne l''office de louange avec chants et psaumes ?', array['تسبحة']::text[], 'تسبحة vient de la même idée que « louer » : c''est l''office de louange, fait de chants et de psaumes.', 2, '{"id": "ar.l28.e05", "type": "mcq", "unitIds": ["ar.g28.liturgy", "ar.v.tasbiha"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot désigne l''office de louange avec chants et psaumes ?", "promptLanguage": "fr", "options": ["أجبية", "تسبحة", "قداس", "صلاة"], "answer": "تسبحة", "acceptedAnswers": ["تسبحة"], "explanation": "تسبحة vient de la même idée que « louer » : c''est l''office de louange, fait de chants et de psaumes.", "tip": "ت س ب ح ة : le mot de la louange.", "extraExample": {"text": "التسبحة بتبدأ بدري.", "translation": "L''office de louange commence tôt."}, "errorPatterns": [{"equals": "أجبية", "category": "word_confusion", "feedback": "« أجبية » est un autre mot de la prière : l''office de louange est تسبحة."}, {"equals": "قداس", "category": "word_confusion", "feedback": "« قداس » est un autre mot de la prière : l''office de louange est تسبحة."}, {"equals": "صلاة", "category": "word_confusion", "feedback": "« صلاة » est un autre mot de la prière : l''office de louange est تسبحة."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e06', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.wi_liruhak_ayan']::text[], 'mcq', 'lesson', 'ولروحك أيضا', array['Et à ton esprit aussi']::text[], 'و (et) + لروحك (à ton esprit) + أيضا (aussi) : « Et à ton esprit aussi ». Le ك final veut dire « ton ».', 2, '{"id": "ar.l28.e06", "type": "mcq", "unitIds": ["ar.g28.liturgy", "ar.v.wi_liruhak_ayan"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "ولروحك أيضا", "promptLanguage": "ar", "options": ["La paix à tous", "Gloire à toi, Seigneur", "Le Christ est ressuscité", "Et à ton esprit aussi"], "answer": "Et à ton esprit aussi", "acceptedAnswers": ["Et à ton esprit aussi"], "explanation": "و (et) + لروحك (à ton esprit) + أيضا (aussi) : « Et à ton esprit aussi ». Le ك final veut dire « ton ».", "tip": "Le و du début est le petit mot « et » (leçon 26).", "extraExample": {"text": "السلام لكل. ولروحك أيضا.", "translation": "La paix à tous. Et à ton esprit aussi."}, "errorPatterns": [{"equals": "La paix à tous", "category": "word_confusion", "feedback": "« La paix à tous » ne correspond pas : relis ولروحك أيضا bloc par bloc. Ici, le sens est « Et à ton esprit aussi »."}, {"equals": "Gloire à toi, Seigneur", "category": "word_confusion", "feedback": "« Gloire à toi, Seigneur » ne correspond pas : relis ولروحك أيضا bloc par bloc. Ici, le sens est « Et à ton esprit aussi »."}, {"equals": "Le Christ est ressuscité", "category": "word_confusion", "feedback": "« Le Christ est ressuscité » ne correspond pas : relis ولروحك أيضا bloc par bloc. Ici, le sens est « Et à ton esprit aussi »."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e07', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.wi_liruhak_ayan']::text[], 'mcq', 'lesson', 'Quel est le sens du ك à la fin de ولروحك ?', array['ton']::text[], 'Le ك final veut dire « toi » ou « ton » : ولروحك = et à ton esprit, لك = à toi.', 3, '{"id": "ar.l28.e07", "type": "mcq", "unitIds": ["ar.g28.liturgy", "ar.v.wi_liruhak_ayan"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le sens du ك à la fin de ولروحك ?", "promptLanguage": "fr", "options": ["notre", "ton", "mon", "et"], "answer": "ton", "acceptedAnswers": ["ton"], "explanation": "Le ك final veut dire « toi » ou « ton » : ولروحك = et à ton esprit, لك = à toi.", "tip": "ك = toi ; ـنا = notre.", "extraExample": {"text": "المجد لك", "translation": "Gloire à toi"}, "errorPatterns": [{"equals": "notre", "category": "word_confusion", "feedback": "« notre » s''écrit ـنا (leçon 26)."}, {"equals": "mon", "category": "word_confusion", "feedback": "« mon » s''écrit avec une autre fin, pas avec ك."}, {"equals": "et", "category": "word_confusion", "feedback": "« et » est le و du début, pas la lettre de la fin."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e08', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.masih_qam']::text[], 'mcq', 'lesson', 'Que répond-on à المسيح قام ?', array['بالحقيقة قام']::text[], 'On répond à المسيح قام par بالحقيقة قام : « Il est vraiment ressuscité ». Les deux phrases se terminent par قام.', 2, '{"id": "ar.l28.e08", "type": "mcq", "unitIds": ["ar.g28.liturgy", "ar.v.masih_qam"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que répond-on à المسيح قام ?", "promptLanguage": "fr", "options": ["ولروحك أيضا", "يا رب ارحم", "المجد لك يا رب", "بالحقيقة قام"], "answer": "بالحقيقة قام", "acceptedAnswers": ["بالحقيقة قام"], "explanation": "On répond à المسيح قام par بالحقيقة قام : « Il est vraiment ressuscité ». Les deux phrases se terminent par قام.", "tip": "Les deux phrases finissent par le même mot : قام.", "extraExample": {"text": "بالحقيقة قام!", "translation": "Il est vraiment ressuscité !"}, "errorPatterns": [{"equals": "ولروحك أيضا", "category": "vocabulary", "feedback": "« ولروحك أيضا » est une autre réponse de la liturgie, pas celle du temps pascal."}, {"equals": "يا رب ارحم", "category": "vocabulary", "feedback": "« يا رب ارحم » est une autre réponse de la liturgie, pas celle du temps pascal."}, {"equals": "المجد لك يا رب", "category": "vocabulary", "feedback": "« المجد لك يا رب » est une autre réponse de la liturgie, pas celle du temps pascal."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e09', 'ar', 'ar.l28', 'ar.v.masih', array['ar.v.masih','ar.v.masih_qam','ar.g28.liturgy']::text[], 'mcq', 'lesson', 'المسيح قام', array['Le Christ est ressuscité']::text[], 'المسيح (le Christ, module 2) + قام (il est ressuscité, à la lettre « il s''est levé »). Le premier mot est celui du module 2.', 3, '{"id": "ar.l28.e09", "type": "mcq", "unitIds": ["ar.v.masih", "ar.v.masih_qam", "ar.g28.liturgy"], "difficulty": 3, "instruction": "Lis la phrase et choisis son sens.", "prompt": "المسيح قام", "promptLanguage": "ar", "options": ["Il est vraiment ressuscité", "Le Christ est ressuscité", "Gloire à toi, Seigneur", "Seigneur, aie pitié"], "answer": "Le Christ est ressuscité", "acceptedAnswers": ["Le Christ est ressuscité"], "explanation": "المسيح (le Christ, module 2) + قام (il est ressuscité, à la lettre « il s''est levé »). Le premier mot est celui du module 2.", "tip": "Commence par le mot que tu connais : المسيح.", "extraExample": {"text": "هللويا، المسيح قام.", "translation": "Alléluia, le Christ est ressuscité."}, "errorPatterns": [{"equals": "Il est vraiment ressuscité", "category": "word_confusion", "feedback": "« Il est vraiment ressuscité » ne correspond pas : relis المسيح قام bloc par bloc. Ici, le sens est « Le Christ est ressuscité »."}, {"equals": "Gloire à toi, Seigneur", "category": "word_confusion", "feedback": "« Gloire à toi, Seigneur » ne correspond pas : relis المسيح قام bloc par bloc. Ici, le sens est « Le Christ est ressuscité »."}, {"equals": "Seigneur, aie pitié", "category": "word_confusion", "feedback": "« Seigneur, aie pitié » ne correspond pas : relis المسيح قام bloc par bloc. Ici, le sens est « Le Christ est ressuscité »."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e10', 'ar', 'ar.l28', 'ar.v.quddas', array['ar.v.quddas','ar.g28.liturgy']::text[], 'mcq', 'lesson', 'Parmi ces mots, lequel veut dire « liturgie » ?', array['قداس']::text[], 'قداس est la liturgie, la grande prière de l''église. صلاة est la prière en général, مزمور un psaume, نبوات les prophéties.', 3, '{"id": "ar.l28.e10", "type": "mcq", "unitIds": ["ar.v.quddas", "ar.g28.liturgy"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Parmi ces mots, lequel veut dire « liturgie » ?", "promptLanguage": "fr", "options": ["صلاة", "مزمور", "نبوات", "قداس"], "answer": "قداس", "acceptedAnswers": ["قداس"], "explanation": "قداس est la liturgie, la grande prière de l''église. صلاة est la prière en général, مزمور un psaume, نبوات les prophéties.", "tip": "Le dimanche, on va au قداس.", "extraExample": {"text": "قداس الأحد", "translation": "la liturgie du dimanche"}, "errorPatterns": [{"equals": "صلاة", "category": "word_confusion", "feedback": "« صلاة » est un autre mot de l''église : la liturgie s''écrit قداس."}, {"equals": "مزمور", "category": "word_confusion", "feedback": "« مزمور » est un autre mot de l''église : la liturgie s''écrit قداس."}, {"equals": "نبوات", "category": "word_confusion", "feedback": "« نبوات » est un autre mot de l''église : la liturgie s''écrit قداس."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e11', 'ar', 'ar.l28', 'ar.g26.long_words', array['ar.g26.long_words','ar.g28.liturgy']::text[], 'mcq', 'lesson', 'Dans « المجد لك يا رب », quel mot commence par ال ?', array['المجد']::text[], 'ال se lit « le » ou « la » : المجد = ال + مجد, « la gloire ». Les autres mots n''ont pas de ال.', 3, '{"id": "ar.l28.e11", "type": "mcq", "unitIds": ["ar.g26.long_words", "ar.g28.liturgy"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans « المجد لك يا رب », quel mot commence par ال ?", "promptLanguage": "fr", "options": ["لك", "المجد", "يا", "رب"], "answer": "المجد", "acceptedAnswers": ["المجد"], "explanation": "ال se lit « le » ou « la » : المجد = ال + مجد, « la gloire ». Les autres mots n''ont pas de ال.", "tip": "Cherche le ا suivi d''un ل au début du mot.", "extraExample": {"text": "الكنيسة", "translation": "l''église"}, "errorPatterns": [{"equals": "لك", "category": "spelling", "feedback": "« لك » n''a pas de ال au début."}, {"equals": "يا", "category": "spelling", "feedback": "« يا » n''a pas de ال au début."}, {"equals": "رب", "category": "spelling", "feedback": "« رب » n''a pas de ال au début."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e12', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.ya_rab_irham','ar.v.salam_likol','ar.v.magd_lak','ar.v.masih_qam']::text[], 'match', 'lesson', 'Relie chaque réponse à son sens.', '{}'::text[], 'Quatre phrases de la liturgie : la demande de pitié, le souhait de paix, la louange et le salut de Pâques.', 2, '{"id": "ar.l28.e12", "type": "match", "unitIds": ["ar.g28.liturgy", "ar.v.ya_rab_irham", "ar.v.salam_likol", "ar.v.magd_lak", "ar.v.masih_qam"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque réponse à son sens.", "promptLanguage": "fr", "pairs": [{"left": "يا رب ارحم", "right": "Seigneur, aie pitié"}, {"left": "السلام لكل", "right": "La paix à tous"}, {"left": "المجد لك يا رب", "right": "Gloire à toi, Seigneur"}, {"left": "المسيح قام", "right": "Le Christ est ressuscité"}], "acceptedAnswers": [], "answer": "يا رب ارحم = Seigneur, aie pitié ; السلام لكل = La paix à tous ; المجد لك يا رب = Gloire à toi, Seigneur ; المسيح قام = Le Christ est ressuscité", "explanation": "Quatre phrases de la liturgie : la demande de pitié, le souhait de paix, la louange et le salut de Pâques.", "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e13', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.tasbiha','ar.v.agbiya','ar.v.halleluya','ar.v.quddus']::text[], 'match', 'lesson', 'Relie chaque mot de l''église à son sens.', '{}'::text[], 'تسبحة est l''office de louange, أجبية le livre des heures, هللويا le cri de louange et قدوس veut dire « saint ».', 2, '{"id": "ar.l28.e13", "type": "match", "unitIds": ["ar.g28.liturgy", "ar.v.tasbiha", "ar.v.agbiya", "ar.v.halleluya", "ar.v.quddus"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot de l''église à son sens.", "promptLanguage": "fr", "pairs": [{"left": "تسبحة", "right": "office de louange"}, {"left": "أجبية", "right": "livre des heures"}, {"left": "هللويا", "right": "alléluia"}, {"left": "قدوس", "right": "saint"}], "acceptedAnswers": [], "answer": "تسبحة = office de louange ; أجبية = livre des heures ; هللويا = alléluia ; قدوس = saint", "explanation": "تسبحة est l''office de louange, أجبية le livre des heures, هللويا le cri de louange et قدوس veut dire « saint ».", "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e14', 'ar', 'ar.l28', 'ar.v.quddas', array['ar.v.quddas','ar.v.mazmur','ar.v.nabawat','ar.v.amin','ar.v.salat','ar.g28.liturgy']::text[], 'match', 'lesson', 'Retrouve les mots de la leçon 16 : relie chaque mot à son sens.', '{}'::text[], 'Cinq mots d''église déjà vus : قداس (liturgie), مزمور (psaume), نبوات (prophéties), آمين (amen) et صلاة (prière).', 3, '{"id": "ar.l28.e14", "type": "match", "unitIds": ["ar.v.quddas", "ar.v.mazmur", "ar.v.nabawat", "ar.v.amin", "ar.v.salat", "ar.g28.liturgy"], "difficulty": 3, "instruction": "Relie chaque élément à son sens.", "prompt": "Retrouve les mots de la leçon 16 : relie chaque mot à son sens.", "promptLanguage": "fr", "pairs": [{"left": "قداس", "right": "liturgie"}, {"left": "مزمور", "right": "psaume"}, {"left": "نبوات", "right": "prophéties"}, {"left": "آمين", "right": "amen"}, {"left": "صلاة", "right": "prière"}], "acceptedAnswers": [], "answer": "قداس = liturgie ; مزمور = psaume ; نبوات = prophéties ; آمين = amen ; صلاة = prière", "explanation": "Cinq mots d''église déjà vus : قداس (liturgie), مزمور (psaume), نبوات (prophéties), آمين (amen) et صلاة (prière).", "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e15', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.salam_likol']::text[], 'fill_blank', 'lesson', 'السلام ___ (La paix à tous)', array['لكل']::text[], 'Le souhait complet est السلام لكل : « la paix à tous ». لك voudrait dire « à toi ».', 2, '{"id": "ar.l28.e15", "type": "fill_blank", "unitIds": ["ar.g28.liturgy", "ar.v.salam_likol"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "السلام ___ (La paix à tous)", "promptLanguage": "ar", "options": ["لك", "لكل", "رب", "أيضا"], "answer": "لكل", "acceptedAnswers": ["لكل"], "explanation": "Le souhait complet est السلام لكل : « la paix à tous ». لك voudrait dire « à toi ».", "tip": "لكل a un ل de plus que لك.", "extraExample": {"text": "السلام لكل.", "translation": "La paix à tous."}, "errorPatterns": [{"equals": "لك", "category": "vocabulary", "feedback": "لك veut dire « à toi » ; ici il faut « à tous » : لكل."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e16', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.magd_lak']::text[], 'fill_blank', 'lesson', 'المجد لك يا ___ (Gloire à toi, Seigneur)', array['رب']::text[], 'Le groupe يا رب veut dire « Seigneur » : المجد لك يا رب. روح, نور et قام ont d''autres sens.', 2, '{"id": "ar.l28.e16", "type": "fill_blank", "unitIds": ["ar.g28.liturgy", "ar.v.magd_lak"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "المجد لك يا ___ (Gloire à toi, Seigneur)", "promptLanguage": "ar", "options": ["روح", "نور", "قام", "رب"], "answer": "رب", "acceptedAnswers": ["رب"], "explanation": "Le groupe يا رب veut dire « Seigneur » : المجد لك يا رب. روح, نور et قام ont d''autres sens.", "tip": "يا + رب : on appelle le Seigneur.", "extraExample": {"text": "يا رب ارحم", "translation": "Seigneur, aie pitié"}, "errorPatterns": [{"equals": "روح", "category": "vocabulary", "feedback": "روح veut dire « esprit » : on l''a vu dans ولروحك."}, {"equals": "نور", "category": "vocabulary", "feedback": "نور veut dire « lumière »."}, {"equals": "قام", "category": "vocabulary", "feedback": "قام veut dire « il est ressuscité »."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e17', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.wi_liruhak_ayan']::text[], 'fill_blank', 'lesson', 'ولروحك ___ (Et à ton esprit aussi)', array['أيضا']::text[], 'La réponse complète est ولروحك أيضا : « et à ton esprit aussi ». لكل appartient au souhait du prêtre.', 3, '{"id": "ar.l28.e17", "type": "fill_blank", "unitIds": ["ar.g28.liturgy", "ar.v.wi_liruhak_ayan"], "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "ولروحك ___ (Et à ton esprit aussi)", "promptLanguage": "ar", "options": ["لكل", "أيضا", "رب", "قام"], "answer": "أيضا", "acceptedAnswers": ["أيضا"], "explanation": "La réponse complète est ولروحك أيضا : « et à ton esprit aussi ». لكل appartient au souhait du prêtre.", "tip": "أيضا veut dire « aussi ».", "extraExample": {"text": "السلام لكل. ولروحك أيضا.", "translation": "La paix à tous. Et à ton esprit aussi."}, "errorPatterns": [{"equals": "لكل", "category": "vocabulary", "feedback": "لكل vient du souhait du prêtre (السلام لكل), pas de la réponse."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e18', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.ya_rab_irham']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Seigneur, aie pitié »', array['يا رب ارحم']::text[], 'On appelle d''abord le Seigneur (يا رب), puis on demande la pitié (ارحم).', 2, '{"id": "ar.l28.e18", "type": "reorder", "unitIds": ["ar.g28.liturgy", "ar.v.ya_rab_irham"], "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Seigneur, aie pitié »", "promptLanguage": "fr", "tokens": ["ارحم", "رب", "يا"], "answer": "يا رب ارحم", "acceptedAnswers": ["يا رب ارحم"], "explanation": "On appelle d''abord le Seigneur (يا رب), puis on demande la pitié (ارحم).", "tip": "يا ouvre toujours : on appelle avant de demander.", "extraExample": {"text": "يا رب ارحمنا", "translation": "Seigneur, aie pitié de nous"}, "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e19', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.magd_lak']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Gloire à toi, Seigneur »', array['المجد لك يا رب']::text[], 'La gloire (المجد) d''abord, puis à qui elle revient : لك, puis l''appel يا رب.', 3, '{"id": "ar.l28.e19", "type": "reorder", "unitIds": ["ar.g28.liturgy", "ar.v.magd_lak"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Gloire à toi, Seigneur »", "promptLanguage": "fr", "tokens": ["يا", "لك", "المجد", "رب"], "answer": "المجد لك يا رب", "acceptedAnswers": ["المجد لك يا رب"], "explanation": "La gloire (المجد) d''abord, puis à qui elle revient : لك, puis l''appel يا رب.", "tip": "Le groupe يا رب va toujours ensemble, à la fin.", "extraExample": {"text": "المجد لك", "translation": "Gloire à toi"}, "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
