insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e21', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.halleluya','ar.v.masih_qam']::text[], 'translation', 'lesson', 'هللويا، المسيح قام', array['Alléluia, le Christ est ressuscité.','alléluia, le christ est ressuscité','alléluia le christ est ressuscité','alleluia, le christ est ressuscité','alléluia, christ est ressuscité']::text[], 'هللويا (alléluia) + المسيح قام (le Christ est ressuscité) : la joie de Pâques.', 3, '{"id": "ar.l28.e21", "type": "translation", "unitIds": ["ar.g28.liturgy", "ar.v.halleluya", "ar.v.masih_qam"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "هللويا، المسيح قام", "promptLanguage": "ar", "answer": "Alléluia, le Christ est ressuscité.", "acceptedAnswers": ["Alléluia, le Christ est ressuscité.", "alléluia, le christ est ressuscité", "alléluia le christ est ressuscité", "alleluia, le christ est ressuscité", "alléluia, christ est ressuscité"], "explanation": "هللويا (alléluia) + المسيح قام (le Christ est ressuscité) : la joie de Pâques.", "tip": "Deux phrases de joie, un seul souffle.", "extraExample": {"text": "بالحقيقة قام!", "translation": "Il est vraiment ressuscité !"}, "pool": "lesson", "lessonId": "ar.l28", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e22', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.halleluya']::text[], 'free_answer', 'lesson', 'Que veut dire هللويا ?', array['alléluia','alleluia','louez le seigneur','louange au seigneur']::text[], 'هللويا est un cri de joie qui vient de l''hébreu : « louez le Seigneur ».', 2, '{"id": "ar.l28.e22", "type": "free_answer", "unitIds": ["ar.g28.liturgy", "ar.v.halleluya"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire هللويا ?", "promptLanguage": "fr", "answer": "alléluia", "acceptedAnswers": ["alléluia", "alleluia", "louez le seigneur", "louange au seigneur"], "explanation": "هللويا est un cri de joie qui vient de l''hébreu : « louez le Seigneur ».", "tip": "Il se termine par ويا : tu l''as entendu mille fois.", "extraExample": {"text": "هللويا!", "translation": "Alléluia !"}, "pool": "lesson", "lessonId": "ar.l28", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e23', 'ar', 'ar.l28', 'ar.g28.liturgy', array['ar.g28.liturgy','ar.v.quddus']::text[], 'free_answer', 'lesson', 'Que veut dire قدوس ?', array['saint','sainte','le saint']::text[], 'قدوس veut dire « saint ». On l''entend dans l''hymne qui commence par قدوس الله, « Saint Dieu ».', 2, '{"id": "ar.l28.e23", "type": "free_answer", "unitIds": ["ar.g28.liturgy", "ar.v.quddus"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire قدوس ?", "promptLanguage": "fr", "answer": "saint", "acceptedAnswers": ["saint", "sainte", "le saint"], "explanation": "قدوس veut dire « saint ». On l''entend dans l''hymne qui commence par قدوس الله, « Saint Dieu ».", "tip": "ق د و س : deux lettres qui ne s''attachent pas, le د et le و.", "extraExample": {"text": "قدوس الله", "translation": "Saint Dieu"}, "pool": "lesson", "lessonId": "ar.l28", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e24', 'ar', 'ar.l28', 'ar.v.rabb', array['ar.v.rabb','ar.g28.liturgy']::text[], 'mcq', 'lesson', 'Dans يا رب ارحم, que veut dire رب ?', array['Seigneur']::text[], 'رب veut dire « Seigneur ». Avec les harakat, on le voit écrit رَبّ, avec une chadda sur le ب ; dans les livres de prières, la chadda est souvent écrite.', 2, '{"id": "ar.l28.e24", "type": "mcq", "unitIds": ["ar.v.rabb", "ar.g28.liturgy"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans يا رب ارحم, que veut dire رب ?", "promptLanguage": "ar", "options": ["Père", "Dieu merci", "Jésus", "Seigneur"], "answer": "Seigneur", "acceptedAnswers": ["Seigneur"], "explanation": "رب veut dire « Seigneur ». Avec les harakat, on le voit écrit رَبّ, avec une chadda sur le ب ; dans les livres de prières, la chadda est souvent écrite.", "tip": "يا رب : « ô Seigneur », l''appel qui ouvre tant de prières.", "extraExample": {"text": "المجد لك يا رب", "translation": "Gloire à toi, Seigneur"}, "errorPatterns": [{"equals": "Père", "category": "word_confusion", "feedback": "« Père » se dit أب ; رب veut dire « Seigneur »."}, {"equals": "Dieu merci", "category": "word_confusion", "feedback": "« Dieu merci » se dit الحمد لله."}, {"equals": "Jésus", "category": "word_confusion", "feedback": "رب est un titre, « Seigneur », pas un nom."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
