insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e03', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.kutub_katab','ar.v.gawab']::text[], 'mcq', 'lesson', 'بابا كتب جواب', array['Papa a écrit une lettre.']::text[], 'Après بابا, on attend une action : كتب veut dire « il a écrit », et جواب est la lettre.', 2, '{"id": "ar.l29.e03", "type": "mcq", "unitIds": ["ar.g29.read_with_meaning", "ar.v.kutub_katab", "ar.v.gawab"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "بابا كتب جواب", "promptLanguage": "ar", "options": ["J''ai beaucoup de livres.", "Papa a écrit une lettre.", "Papa a mangé du poisson.", "Papa a beaucoup de livres."], "answer": "Papa a écrit une lettre.", "acceptedAnswers": ["Papa a écrit une lettre."], "explanation": "Après بابا, on attend une action : كتب veut dire « il a écrit », et جواب est la lettre.", "tip": "Quand le mot suit une personne, cherche l''action.", "extraExample": {"text": "ماما كتبت جواب.", "translation": "Maman a écrit une lettre."}, "errorPatterns": [{"equals": "J''ai beaucoup de livres.", "category": "word_confusion", "feedback": "« J''ai beaucoup de livres. » ne correspond pas : relis بابا كتب جواب bloc par bloc. Ici, le sens est « Papa a écrit une lettre. »."}, {"equals": "Papa a mangé du poisson.", "category": "word_confusion", "feedback": "« Papa a mangé du poisson. » ne correspond pas : relis بابا كتب جواب bloc par bloc. Ici, le sens est « Papa a écrit une lettre. »."}, {"equals": "Papa a beaucoup de livres.", "category": "word_confusion", "feedback": "« Papa a beaucoup de livres. » ne correspond pas : relis بابا كتب جواب bloc par bloc. Ici, le sens est « Papa a écrit une lettre. »."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update 