insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e04', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.alam_ilm','ar.v.masr']::text[], 'mcq', 'lesson', 'Dans « علم مصر », que veut dire علم ?', array['drapeau']::text[], 'علم مصر, c''est « le drapeau de l''Égypte » : un pays a un drapeau. La science n''irait pas avec le nom d''un pays.', 2, '{"id": "ar.l29.e04", "type": "mcq", "unitIds": ["ar.g29.read_with_meaning", "ar.v.alam_ilm", "ar.v.masr"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans « علم مصر », que veut dire علم ?", "promptLanguage": "fr", "options": ["science", "nourriture", "livres", "drapeau"], "answer": "drapeau", "acceptedAnswers": ["drapeau"], "explanation": "علم مصر, c''est « le drapeau de l''Égypte » : un pays a un drapeau. La science n''irait pas avec le nom d''un pays.", "tip": "Un nom de pays derrière : pense au drapeau.", "extraExample": {"text": "علم مصر.", "translation": "Le drapeau de l''Égypte."}, "errorPatterns": [{"equals": "science", "category": "word_confusion", "feedback": "« science » ne va pas avec le nom d''un pays : علم مصر est « le drapeau de l''Égypte »."}, {"equals": "nourriture", "category": "word_confusion", "feedback": "« nourriture » ne va pas avec le nom d''un pays : علم مصر est « le drapeau de l''Égypte »."}, {"equals": "livres", "category": "word_confusion", "feedback": "« livres » ne va pas avec le nom d''un pays : علم مصر est « le drapeau de l''Égypte »."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e05', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.alam_ilm','ar.v.nur']::text[], 'mcq', 'lesson', 'Dans « العلم نور », que veut dire العلم ?', array['la science']::text[], 'Une lumière (نور), c''est l''image du savoir : العلم نور = « La science est une lumière. »', 2, '{"id": "ar.l29.e05", "type": "mcq", "unitIds": ["ar.g29.read_with_meaning", "ar.v.alam_ilm", "ar.v.nur"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans « العلم نور », que veut dire العلم ?", "promptLanguage": "fr", "options": ["le drapeau", "la science", "la nourriture", "le livre"], "answer": "la science", "acceptedAnswers": ["la science"], "explanation": "Une lumière (نور), c''est l''image du savoir : العلم نور = « La science est une lumière. »", "tip": "Le sens de نور (lumière) oriente vers la science.", "extraExample": {"text": "العلم مهم.", "translation": "La science est importante."}, "errorPatterns": [{"equals": "le drapeau", "category": "word_confusion", "feedback": "« Le drapeau est une lumière » n''a pas de sens : ici on parle de la science."}, {"equals": "la nourriture", "category": "word_confusion", "feedback": "On ne dit pas que la nourriture est une lumière : le mot est العلم, la science."}, {"equals": "le livre", "category": "word_confusion", "feedback": "Le livre se dit كتاب : ici le mot est العلم."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = 