insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e06', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.akl_akal','ar.v.samak']::text[], 'mcq', 'lesson', 'بابا أكل سمك', array['Papa a mangé du poisson.']::text[], 'Après بابا (une personne), أكل est une action : « il a mangé ». Le poisson (سمك) est celui de la leçon 25.', 2, '{"id": "ar.l29.e06", "type": "mcq", "unitIds": ["ar.g29.read_with_meaning", "ar.v.akl_akal", "ar.v.samak"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "بابا أكل سمك", "promptLanguage": "ar", "options": ["Papa a du poisson.", "Papa veut de la nourriture.", "Maman a mangé du poisson.", "Papa a mangé du poisson."], "answer": "Papa a mangé du poisson.", "acceptedAnswers": ["Papa a mangé du poisson."], "explanation": "Après بابا (une personne), أكل est une action : « il a mangé ». Le poisson (سمك) est celui de la leçon 25.", "tip": "Une personne devant le mot : c''est une action.", "extraExample": {"text": "ماما أكلت موز.", "translation": "Maman a mangé une banane."}, "errorPatterns": [{"equals": "Papa a du poisson.", "category": "word_confusion", "feedback": "« Papa a du poisson. » ne correspond pas : relis بابا أكل سمك bloc par bloc. Ici, le sens est « Papa a mangé du poisson. »."}, {"equals": "Papa veut de la nourriture.", "category": "word_confusion", "feedback": "« Papa veut de la nourriture. » ne correspond pas : relis بابا أكل سمك bloc par bloc. Ici, le sens est « Papa a mangé du poisson. »."}, {"equals": "Maman a mangé du poisson.", "category": "word_confusion", "feedback": "« Maman a mangé du poisson. » ne correspond pas : relis بابا أكل سمك bloc par bloc. Ici, le sens est « Papa a mangé du poisson. »."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e07', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.akl_akal']::text[], 'mcq', 'lesson', 'Que veut dire الأكل ?', array['la nourriture']::text[], 'Avec ال devant, c''est un nom : الأكل = « la nourriture ». Une action ne prend pas ال.', 2, '{"id": "ar.l29.e07", "type": "mcq", "unitIds": ["ar.g29.read_with_meaning", "ar.v.akl_akal"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire الأكل ?", "promptLanguage": "fr", "options": ["il a mangé", "la nourriture", "le drapeau", "la lettre"], "answer": "la nourriture", "acceptedAnswers": ["la nourriture"], "explanation": "Avec ال devant, c''est un nom : الأكل = « la nourriture ». Une action ne prend pas ال.", "tip": "ال annonce un nom.", "extraExample": {"text": "الأكل حلو.", "translation": "La nourriture est bonne."}, "errorPatterns": [{"equals": "il a mangé", "category": "word_confusion", "feedback": "« Il a mangé » est une action : elle ne prend pas ال. الأكل est le nom, « la nourriture »."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e08', 'ar', 'ar.l29', 'ar.g17.short_vowels', array['ar.g17.short_vowels','ar.v.kutub_katab','ar.g29.read_with_meaning']::text[], 'mcq', 'lesson', 'Avec les voyelles, lequel de ces mots veut dire « livres » (plusieurs livres) ?', array['كُتُب']::text[], 'كُتُب est le pluriel : « livres ». كَتَب veut dire « il a écrit », كِتَاب est un seul livre et كُتَّاب veut dire « écrivains ».', 3, '{"id": "ar.l29.e08", "type": "mcq", "unitIds": ["ar.g17.short_vowels", "ar.v.kutub_katab", "ar.g29.read_with_meaning"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Avec les voyelles, lequel de ces mots veut dire « livres » (plusieurs livres) ?", "promptLanguage": "ar", "options": ["كَتَب", "كِتَاب", "كُتَّاب", "كُتُب"], "answer": "كُتُب", "acceptedAnswers": ["كُتُب"], "explanation": "كُتُب est le pluriel : « livres ». كَتَب veut dire « il a écrit », كِتَاب est un seul livre et كُتَّاب veut dire « écrivains ».", "tip": "Les voyelles écrites lèvent tous les doutes, mais on ne les écrit presque jamais.", "extraExample": {"text": "عندي كتب كتير.", "translation": "J''ai beaucoup de livres."}, "errorPatterns": [{"equals": "كَتَب", "category": "word_confusion", "feedback": "كَتَب (il a écrit) est le verbe : le deuxième sens de كتب."}, {"equals": "كِتَاب", "category": "word_confusion", "feedback": "كِتَاب est un seul livre (avec un ا long) ; ici on veut « livres », au pluriel."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e09', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.madrasa']::text[], 'mcq', 'lesson', 'Quelle graphie est une autre façon d''écrire مدرسة ?', array['مدرسه']::text[], 'Beaucoup d''Égyptiens écrivent un ه au lieu du ة : مدرسه = مدرسة. Les autres mots sont un pluriel ou une forme avec « mon ».', 3, '{"id": "ar.l29.e09", "type": "mcq", "unitIds": ["ar.g29.read_with_meaning", "ar.v.madrasa"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle graphie est une autre façon d''écrire مدرسة ?", "promptLanguage": "fr", "options": ["مدارس", "مدرسه", "مدرسين", "مدرسي"], "answer": "مدرسه", "acceptedAnswers": ["مدرسه"], "explanation": "Beaucoup d''Égyptiens écrivent un ه au lieu du ة : مدرسه = مدرسة. Les autres mots sont un pluriel ou une forme avec « mon ».", "tip": "Même forme d''ensemble, seule la fin change : ة ou ه.", "extraExample": {"text": "المدرسه", "translation": "l''école"}, "errorPatterns": [{"equals": "مدارس", "category": "spelling", "feedback": "مدارس est un pluriel (des écoles) : il a un ا de plus au milieu."}, {"equals": "مدرسين", "category": "spelling", "feedback": "مدرسين finit par ين : ce n''est pas le même mot."}, {"equals": "مدرسي", "category": "spelling", "feedback": "مدرسي finit par ي : ce n''est pas le même mot."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e10', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning']::text[], 'mcq', 'lesson', 'Quelle graphie est une autre façon d''écrire على ?', array['علي']::text[], 'Beaucoup d''Égyptiens écrivent ي au lieu de ى à la fin de على. Les autres sont d''autres mots : عيل (enfant), عالي (haut), علم (drapeau, science).', 3, '{"id": "ar.l29.e10", "type": "mcq", "unitIds": ["ar.g29.read_with_meaning"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle graphie est une autre façon d''écrire على ?", "promptLanguage": "fr", "options": ["عيل", "عالي", "علم", "علي"], "answer": "علي", "acceptedAnswers": ["علي"], "explanation": "Beaucoup d''Égyptiens écrivent ي au lieu de ى à la fin de على. Les autres sont d''autres mots : عيل (enfant), عالي (haut), علم (drapeau, science).", "tip": "Un ى final peut s''écrire ي : même mot.", "extraExample": {"text": "على الترابيزة", "translation": "sur la table"}, "errorPatterns": [{"equals": "عيل", "category": "spelling", "feedback": "عيل a un ي au milieu : c''est un autre mot."}, {"equals": "عالي", "category": "spelling", "feedback": "عالي a un ا au milieu : c''est un autre mot."}, {"equals": "علم", "category": "spelling", "feedback": "علم finit par م : c''est un autre mot."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e11', 'ar', 'ar.l29', 'ar.v.gamia', array['ar.v.gamia','ar.g29.read_with_meaning']::text[], 'mcq', 'lesson', 'جامعة', array['université']::text[], 'جا | معة : le ا ferme le premier bloc. Ces cinq lettres donnent l''« université ».', 2, '{"id": "ar.l29.e11", "type": "mcq", "unitIds": ["ar.v.gamia", "ar.g29.read_with_meaning"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "جامعة", "promptLanguage": "ar", "options": ["école", "université", "hôpital", "restaurant"], "answer": "université", "acceptedAnswers": ["université"], "explanation": "جا | معة : le ا ferme le premier bloc. Ces cinq lettres donnent l''« université ».", "tip": "Coupe après le ا, puis lis معة.", "extraExample": {"text": "الجامعة كبيرة.", "translation": "L''université est grande."}, "errorPatterns": [{"equals": "école", "category": "word_confusion", "feedback": "« école » ne correspond pas : relis جامعة bloc par bloc. Ici, le sens est « université »."}, {"equals": "hôpital", "category": "word_confusion", "feedback": "« hôpital » ne correspond pas : relis جامعة bloc par bloc. Ici, le sens est « université »."}, {"equals": "restaurant", "category": "word_confusion", "feedback": "« restaurant » ne correspond pas : relis جامعة bloc par bloc. Ici, le sens est « université »."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e12', 'ar', 'ar.l29', 'ar.v.salat', array['ar.v.salat','ar.g29.read_with_meaning']::text[], 'mcq', 'lesson', 'Quel mot veut dire « prière » ?', array['صلاة']::text[], 'صلاة veut dire « prière » en général. قداس est la liturgie, مزمور un psaume et تسبحة un office de louange.', 2, '{"id": "ar.l29.e12", "type": "mcq", "unitIds": ["ar.v.salat", "ar.g29.read_with_meaning"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « prière » ?", "promptLanguage": "fr", "options": ["قداس", "مزمور", "تسبحة", "صلاة"], "answer": "صلاة", "acceptedAnswers": ["صلاة"], "explanation": "صلاة veut dire « prière » en général. قداس est la liturgie, مزمور un psaume et تسبحة un office de louange.", "tip": "La ligature لا au milieu de صلاة : ص + لا + ة.", "extraExample": {"text": "صلاة الصبح", "translation": "la prière du matin"}, "errorPatterns": [{"equals": "قداس", "category": "word_confusion", "feedback": "« قداس » est un autre mot de l''église : la prière s''écrit صلاة."}, {"equals": "مزمور", "category": "word_confusion", "feedback": "« مزمور » est un autre mot de l''église : la prière s''écrit صلاة."}, {"equals": "تسبحة", "category": "word_confusion", "feedback": "« تسبحة » est un autre mot de l''église : la prière s''écrit صلاة."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e13', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.kutub_katab','ar.v.alam_ilm','ar.v.akl_akal','ar.v.andi']::text[], 'match', 'lesson', 'Retour aux phrases de tous les jours : relie chaque phrase à son sens.', '{}'::text[], 'Dans chaque phrase, le mot d''avant décide : après عندي un nom (livres), après بابا une action (a écrit, a mangé), et علم مصر nomme le drapeau d''un pays.', 3, '{"id": "ar.l29.e13", "type": "match", "unitIds": ["ar.g29.read_with_meaning", "ar.v.kutub_katab", "ar.v.alam_ilm", "ar.v.akl_akal", "ar.v.andi"], "difficulty": 3, "instruction": "Relie chaque élément à son sens.", "prompt": "Retour aux phrases de tous les jours : relie chaque phrase à son sens.", "promptLanguage": "fr", "pairs": [{"left": "عندي كتب كتير", "right": "J''ai beaucoup de livres."}, {"left": "بابا كتب جواب", "right": "Papa a écrit une lettre."}, {"left": "علم مصر", "right": "le drapeau de l''Égypte"}, {"left": "بابا أكل سمك", "right": "Papa a mangé du poisson."}], "acceptedAnswers": [], "answer": "عندي كتب كتير = J''ai beaucoup de livres. ; بابا كتب جواب = Papa a écrit une lettre. ; علم مصر = le drapeau de l''Égypte ; بابا أكل سمك = Papa a mangé du poisson.", "explanation": "Dans chaque phrase, le mot d''avant décide : après عندي un nom (livres), après بابا une action (a écrit, a mangé), et علم مصر nomme le drapeau d''un pays.", "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e14', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.andi','ar.v.kitir','ar.v.gawab','ar.v.masr']::text[], 'match', 'lesson', 'Relie chaque mot à son sens.', '{}'::text[], 'Quatre mots de la leçon : عندي (à la lettre « chez moi »), كتير, جواب et مصر.', 1, '{"id": "ar.l29.e14", "type": "match", "unitIds": ["ar.g29.read_with_meaning", "ar.v.andi", "ar.v.kitir", "ar.v.gawab", "ar.v.masr"], "difficulty": 1, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot à son sens.", "promptLanguage": "fr", "pairs": [{"left": "عندي", "right": "j''ai"}, {"left": "كتير", "right": "beaucoup"}, {"left": "جواب", "right": "lettre"}, {"left": "مصر", "right": "Égypte"}], "acceptedAnswers": [], "answer": "عندي = j''ai ; كتير = beaucoup ; جواب = lettre ; مصر = Égypte", "explanation": "Quatre mots de la leçon : عندي (à la lettre « chez moi »), كتير, جواب et مصر.", "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e15', 'ar', 'ar.l29', 'ar.v.madrasa', array['ar.v.madrasa','ar.v.shokran','ar.v.agbiya','ar.v.al_qahira','ar.g29.read_with_meaning']::text[], 'match', 'lesson', 'Relie chaque mot des leçons 26 à 28 à son sens.', '{}'::text[], 'Retour en arrière : مدرسة (école, 3 blocs), شكرا (merci), أجبية (livre des heures) et القاهرة (Le Caire, avec ال).', 3, '{"id": "ar.l29.e15", "type": "match", "unitIds": ["ar.v.madrasa", "ar.v.shokran", "ar.v.agbiya", "ar.v.al_qahira", "ar.g29.read_with_meaning"], "difficulty": 3, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot des leçons 26 à 28 à son sens.", "promptLanguage": "fr", "pairs": [{"left": "مدرسة", "right": "école"}, {"left": "شكرا", "right": "merci"}, {"left": "أجبية", "right": "livre des heures"}, {"left": "القاهرة", "right": "Le Caire"}], "acceptedAnswers": [], "answer": "مدرسة = école ; شكرا = merci ; أجبية = livre des heures ; القاهرة = Le Caire", "explanation": "Retour en arrière : مدرسة (école, 3 blocs), شكرا (merci), أجبية (livre des heures) et القاهرة (Le Caire, avec ال).", "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e16', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.kutub_katab']::text[], 'fill_blank', 'lesson', 'عندي ___ كتير (livres)', array['كتب']::text[], 'Après عندي on attend une chose, et le sens « livres » donne كتب. جواب est une lettre, مصر l''Égypte.', 2, '{"id": "ar.l29.e16", "type": "fill_blank", "unitIds": ["ar.g29.read_with_meaning", "ar.v.kutub_katab"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "عندي ___ كتير (livres)", "promptLanguage": "ar", "options": ["جواب", "مصر", "علم", "كتب"], "answer": "كتب", "acceptedAnswers": ["كتب"], "explanation": "Après عندي on attend une chose, et le sens « livres » donne كتب. جواب est une lettre, مصر l''Égypte.", "tip": "Ici كتب est un nom : « des livres ».", "extraExample": {"text": "عندي كتب.", "translation": "J''ai des livres."}, "errorPatterns": [{"equals": "جواب", "category": "vocabulary", "feedback": "جواب veut dire « lettre », pas « livres »."}, {"equals": "علم", "category": "vocabulary", "feedback": "علم veut dire « drapeau » ou « science », pas « livres »."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e17', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.gawab']::text[], 'fill_blank', 'lesson', 'بابا كتب ___ (Papa a écrit une lettre.)', array['جواب']::text[], 'Papa a écrit… quoi ? Une lettre : جواب. كتير veut dire « beaucoup » et مصر « Égypte ».', 2, '{"id": "ar.l29.e17", "type": "fill_blank", "unitIds": ["ar.g29.read_with_meaning", "ar.v.gawab"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "بابا كتب ___ (Papa a écrit une lettre.)", "promptLanguage": "ar", "options": ["كتير", "جواب", "مصر", "علم"], "answer": "جواب", "acceptedAnswers": ["جواب"], "explanation": "Papa a écrit… quoi ? Une lettre : جواب. كتير veut dire « beaucoup » et مصر « Égypte ».", "tip": "Après un verbe d''écriture, cherche l''objet : جواب.", "extraExample": {"text": "كتبت جواب.", "translation": "J''ai écrit une lettre."}, "errorPatterns": [{"equals": "كتير", "category": "vocabulary", "feedback": "كتير veut dire « beaucoup » : on n''écrit pas « beaucoup »."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e18', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.akl_akal']::text[], 'fill_blank', 'lesson', 'بابا ___ سمك (Papa a mangé du poisson.)', array['أكل']::text[], 'Après بابا, l''action est أكل (il a mangé) : « Papa a mangé du poisson. »', 3, '{"id": "ar.l29.e18", "type": "fill_blank", "unitIds": ["ar.g29.read_with_meaning", "ar.v.akl_akal"], "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "بابا ___ سمك (Papa a mangé du poisson.)", "promptLanguage": "ar", "options": ["علم", "كتير", "عندي", "أكل"], "answer": "أكل", "acceptedAnswers": ["أكل"], "explanation": "Après بابا, l''action est أكل (il a mangé) : « Papa a mangé du poisson. »", "tip": "Une personne + une action + un complément.", "extraExample": {"text": "ماما أكلت موز.", "translation": "Maman a mangé une banane."}, "errorPatterns": [{"equals": "عندي", "category": "vocabulary", "feedback": "عندي veut dire « j''ai » : il ne va pas après بابا."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e19', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.kutub_katab','ar.v.gawab']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Papa a écrit une lettre. »', array['بابا كتب جواب']::text[], 'Qui ? بابا. Il a fait quoi ? كتب. Quoi ? جواب. L''ordre est : personne, action, chose.', 3, '{"id": "ar.l29.e19", "type": "reorder", "unitIds": ["ar.g29.read_with_meaning", "ar.v.kutub_katab", "ar.v.gawab"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Papa a écrit une lettre. »", "promptLanguage": "fr", "tokens": ["جواب", "بابا", "كتب"], "answer": "بابا كتب جواب", "acceptedAnswers": ["بابا كتب جواب"], "explanation": "Qui ? بابا. Il a fait quoi ? كتب. Quoi ? جواب. L''ordre est : personne, action, chose.", "tip": "Qui, fait quoi, quoi : personne, action, chose.", "extraExample": {"text": "بابا أكل سمك", "translation": "Papa a mangé du poisson"}, "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e20', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.andi','ar.v.kitir','ar.v.kutub_katab']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « J''ai beaucoup de livres. »', array['عندي كتب كتير']::text[], 'عندي (j''ai) vient d''abord, puis la chose (كتب), puis la quantité (كتير).', 3, '{"id": "ar.l29.e20", "type": "reorder", "unitIds": ["ar.g29.read_with_meaning", "ar.v.andi", "ar.v.kitir", "ar.v.kutub_katab"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « J''ai beaucoup de livres. »", "promptLanguage": "fr", "tokens": ["كتير", "عندي", "كتب"], "answer": "عندي كتب كتير", "acceptedAnswers": ["عندي كتب كتير"], "explanation": "عندي (j''ai) vient d''abord, puis la chose (كتب), puis la quantité (كتير).", "tip": "Chose d''abord, quantité ensuite : كتب كتير.", "extraExample": {"text": "عندي موبايل", "translation": "J''ai un portable"}, "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e21', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.andi','ar.v.gawab']::text[], 'translation', 'lesson', 'عندي جواب', array['J''ai une lettre.','j''ai une lettre','j''ai un courrier','j''ai une réponse']::text[], 'عندي (j''ai) + جواب (une lettre). Le mot عندي veut dire à la lettre « chez moi ».', 2, '{"id": "ar.l29.e21", "type": "translation", "unitIds": ["ar.g29.read_with_meaning", "ar.v.andi", "ar.v.gawab"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "عندي جواب", "promptLanguage": "ar", "answer": "J''ai une lettre.", "acceptedAnswers": ["J''ai une lettre.", "j''ai une lettre", "j''ai un courrier", "j''ai une réponse"], "explanation": "عندي (j''ai) + جواب (une lettre). Le mot عندي veut dire à la lettre « chez moi ».", "tip": "عندي + un nom = j''ai quelque chose.", "extraExample": {"text": "عندي موبايل.", "translation": "J''ai un portable."}, "pool": "lesson", "lessonId": "ar.l29", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e22', 'ar', 'ar.l29', 'ar.v.shokran', array['ar.v.shokran','ar.v.kitir','ar.g29.read_with_meaning']::text[], 'translation', 'lesson', 'شكرا كتير', array['Merci beaucoup.','merci beaucoup','merci bien','merci énormément']::text[], 'شكرا (merci) + كتير (beaucoup) : la formule la plus courante pour remercier chaleureusement.', 2, '{"id": "ar.l29.e22", "type": "translation", "unitIds": ["ar.v.shokran", "ar.v.kitir", "ar.g29.read_with_meaning"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "شكرا كتير", "promptLanguage": "ar", "answer": "Merci beaucoup.", "acceptedAnswers": ["Merci beaucoup.", "merci beaucoup", "merci bien", "merci énormément"], "explanation": "شكرا (merci) + كتير (beaucoup) : la formule la plus courante pour remercier chaleureusement.", "tip": "كتير se place après ce qu''il renforce.", "extraExample": {"text": "شكرا.", "translation": "Merci."}, "pool": "lesson", "lessonId": "ar.l29", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e23', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.kitir']::text[], 'free_answer', 'lesson', 'Que veut dire كتير ?', array['beaucoup','plein','énormément']::text[], 'كتير veut dire « beaucoup » ; on l''entend dans شكرا كتير.', 2, '{"id": "ar.l29.e23", "type": "free_answer", "unitIds": ["ar.g29.read_with_meaning", "ar.v.kitir"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire كتير ?", "promptLanguage": "fr", "answer": "beaucoup", "acceptedAnswers": ["beaucoup", "plein", "énormément"], "explanation": "كتير veut dire « beaucoup » ; on l''entend dans شكرا كتير.", "tip": "Il se place après le mot qu''il renforce.", "extraExample": {"text": "عندي كتب كتير.", "translation": "J''ai beaucoup de livres."}, "pool": "lesson", "lessonId": "ar.l29", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e24', 'ar', 'ar.l29', 'ar.g29.read_with_meaning', array['ar.g29.read_with_meaning','ar.v.masr']::text[], 'free_answer', 'lesson', 'Que veut dire مصر ?', array['Égypte','egypte','l''égypte','l''egypte']::text[], 'مصر est le nom du pays : م ص ر, trois lettres, avec un ر final qui reste seul.', 2, '{"id": "ar.l29.e24", "type": "free_answer", "unitIds": ["ar.g29.read_with_meaning", "ar.v.masr"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire مصر ?", "promptLanguage": "fr", "answer": "Égypte", "acceptedAnswers": ["Égypte", "egypte", "l''égypte", "l''egypte"], "explanation": "مصر est le nom du pays : م ص ر, trois lettres, avec un ر final qui reste seul.", "tip": "Tu le vois sur le drapeau : علم مصر.", "extraExample": {"text": "أنا من مصر.", "translation": "Je suis d''Égypte."}, "pool": "lesson", "lessonId": "ar.l29", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e01', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.da','ar.v.bayt']::text[], 'mcq', 'lesson', 'ده بيت', array['C''est une maison.']::text[], 'ده (ça, masculin) + بيت (maison, module 2) : « C''est une maison. »', 1, '{"id": "ar.l30.e01", "type": "mcq", "unitIds": ["ar.g30.little_words", "ar.v.da", "ar.v.bayt"], "difficulty": 1, "instruction": "Lis la phrase et choisis son sens.", "prompt": "ده بيت", "promptLanguage": "ar", "options": ["C''est une église.", "C''est une maison.", "Où est la maison ?", "C''est une porte."], "answer": "C''est une maison.", "acceptedAnswers": ["C''est une maison."], "explanation": "ده (ça, masculin) + بيت (maison, module 2) : « C''est une maison. »", "tip": "ده est masculin, comme بيت.", "extraExample": {"text": "ده باب.", "translation": "C''est une porte."}, "errorPatterns": [{"equals": "C''est une église.", "category": "word_confusion", "feedback": "« C''est une église. » ne correspond pas : relis ده بيت bloc par bloc. Ici, le sens est « C''est une maison. »."}, {"equals": "Où est la maison ?", "category": "word_confusion", "feedback": "« Où est la maison ? » ne correspond pas : relis ده بيت bloc par bloc. Ici, le sens est « C''est une maison. »."}, {"equals": "C''est une porte.", "category": "word_confusion", "feedback": "« C''est une porte. » ne correspond pas : relis ده بيت bloc par bloc. Ici, le sens est « C''est une maison. »."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e02', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.di','ar.v.kanisa']::text[], 'mcq', 'lesson', 'دي كنيسة', array['C''est une église.']::text[], 'دي (ça, féminin) + كنيسة : « C''est une église ». كنيسة est un mot féminin : il finit par ة.', 2, '{"id": "ar.l30.e02", "type": "mcq", "unitIds": ["ar.g30.little_words", "ar.v.di", "ar.v.kanisa"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "دي كنيسة", "promptLanguage": "ar", "options": ["C''est une maison.", "Ce sont des garçons.", "Où est l''église ?", "C''est une église."], "answer": "C''est une église.", "acceptedAnswers": ["C''est une église."], "explanation": "دي (ça, féminin) + كنيسة : « C''est une église ». كنيسة est un mot féminin : il finit par ة.", "tip": "Un ة à la fin du nom : pense à دي.", "extraExample": {"text": "دي مدرسة.", "translation": "C''est une école."}, "errorPatterns": [{"equals": "C''est une maison.", "category": "word_confusion", "feedback": "« C''est une maison. » ne correspond pas : relis دي كنيسة bloc par bloc. Ici, le sens est « C''est une église. »."}, {"equals": "Ce sont des garçons.", "category": "word_confusion", "feedback": "« Ce sont des garçons. » ne correspond pas : relis دي كنيسة bloc par bloc. Ici, le sens est « C''est une église. »."}, {"equals": "Où est l''église ?", "category": "word_confusion", "feedback": "« Où est l''église ? » ne correspond pas : relis دي كنيسة bloc par bloc. Ici, le sens est « C''est une église. »."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e03', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.dol','ar.v.walad']::text[], 'mcq', 'lesson', 'دول ولاد', array['Ce sont des garçons.']::text[], 'دول sert pour plusieurs personnes ou choses : « Ce sont… ». ولاد est le pluriel de ولد (garçon, leçon 25).', 2, '{"id": "ar.l30.e03", "type": "mcq", "unitIds": ["ar.g30.little_words", "ar.v.dol", "ar.v.walad"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "دول ولاد", "promptLanguage": "ar", "options": ["C''est un garçon.", "Ce sont des garçons.", "Ce sont des filles.", "C''est une maison."], "answer": "Ce sont des garçons.", "acceptedAnswers": ["Ce sont des garçons."], "explanation": "دول sert pour plusieurs personnes ou choses : « Ce sont… ». ولاد est le pluriel de ولد (garçon, leçon 25).", "tip": "دول : plus d''un.", "extraExample": {"text": "دول كتب.", "translation": "Ce sont des livres."}, "errorPatterns": [{"equals": "C''est un garçon.", "category": "word_confusion", "feedback": "« C''est un garçon. » ne correspond pas : relis دول ولاد bloc par bloc. Ici, le sens est « Ce sont des garçons. »."}, {"equals": "Ce sont des filles.", "category": "word_confusion", "feedback": "« Ce sont des filles. » ne correspond pas : relis دول ولاد bloc par bloc. Ici, le sens est « Ce sont des garçons. »."}, {"equals": "C''est une maison.", "category": "word_confusion", "feedback": "« C''est une maison. » ne correspond pas : relis دول ولاد bloc par bloc. Ici, le sens est « Ce sont des garçons. »."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e04', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.fi','ar.v.kanisa']::text[], 'mcq', 'lesson', 'Que veut dire في الكنيسة ?', array['dans l''église']::text[], 'في veut dire « dans » : في الكنيسة = dans l''église. Pour « sur », on aurait على.', 2, '{"id": "ar.l30.e04", "type": "mcq", "unitIds": ["ar.g30.little_words", "ar.v.fi", "ar.v.kanisa"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire في الكنيسة ?", "promptLanguage": "fr", "options": ["sur l''église", "où est l''église", "l''église n''est pas ici", "dans l''église"], "answer": "dans l''église", "acceptedAnswers": ["dans l''église"], "explanation": "في veut dire « dans » : في الكنيسة = dans l''église. Pour « sur », on aurait على.", "tip": "في : deux lettres, un ف et un ي.", "extraExample": {"text": "في البيت", "translation": "dans la maison"}, "errorPatterns": [{"equals": "sur l''église", "category": "word_confusion", "feedback": "« Sur » se dit على ; ici le mot est في, « dans »."}, {"equals": "où est l''église", "category": "word_confusion", "feedback": "« Où » se dit فين, avec un ن final ; ici le mot est في."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e05', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.ala','ar.v.kitab','ar.v.tarabeza']::text[], 'mcq', 'lesson', 'Que veut dire الكتاب على الترابيزة ?', array['Le livre est sur la table.']::text[], 'على veut dire « sur » : le livre (الكتاب) est sur la table (الترابيزة). On lit dans l''ordre : le livre d''abord, puis où il est.', 2, '{"id": "ar.l30.e05", "type": "mcq", "unitIds": ["ar.g30.little_words", "ar.v.ala", "ar.v.kitab", "ar.v.tarabeza"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire الكتاب على الترابيزة ?", "promptLanguage": "ar", "options": ["Le livre est dans la table.", "Le livre est sur la table.", "La table est sur le livre.", "Où est le livre ?"], "answer": "Le livre est sur la table.", "acceptedAnswers": ["Le livre est sur la table."], "explanation": "على veut dire « sur » : le livre (الكتاب) est sur la table (الترابيزة). On lit dans l''ordre : le livre d''abord, puis où il est.", "tip": "Lis l''ordre des mots : ce qui est posé vient avant على.", "extraExample": {"text": "الموبايل على الكرسي.", "translation": "Le portable est sur la chaise."}, "errorPatterns": [{"equals": "Le livre est dans la table.", "category": "word_confusion", "feedback": "« Dans » se dit في ; ici le mot est على, « sur »."}, {"equals": "La table est sur le livre.", "category": "word_confusion", "feedback": "L''ordre est inversé : le livre est le premier mot, c''est lui qui est posé."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e06', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.min']::text[], 'mcq', 'lesson', 'Quel mot veut dire « qui » ?', array['مين']::text[], 'مين veut dire « qui ». إيه veut dire « quoi », ليه « pourquoi », إمتى « quand ».', 1, '{"id": "ar.l30.e06", "type": "mcq", "unitIds": ["ar.g30.little_words", "ar.v.min"], "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « qui » ?", "promptLanguage": "fr", "options": ["إيه", "ليه", "إمتى", "مين"], "answer": "مين", "acceptedAnswers": ["مين"], "explanation": "مين veut dire « qui ». إيه veut dire « quoi », ليه « pourquoi », إمتى « quand ».", "tip": "Cinq questions, cinq images : apprends-les par cœur.", "extraExample": {"text": "مين ده؟", "translation": "C''est qui ?"}, "errorPatterns": [{"equals": "إيه", "category": "word_confusion", "feedback": "« إيه » n''est pas « qui » : relis la liste des cinq questions."}, {"equals": "ليه", "category": "word_confusion", "feedback": "« ليه » n''est pas « qui » : relis la liste des cinq questions."}, {"equals": "إمتى", "category": "word_confusion", "feedback": "« إمتى » n''est pas « qui » : relis la liste des cinq questions."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e07', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.eh','ar.v.da']::text[], 'mcq', 'lesson', 'إيه ده؟', array['C''est quoi ?']::text[], 'إيه (quoi) + ده (ça) : « C''est quoi ? » Le mot de question donne le ton de la phrase.', 2, '{"id": "ar.l30.e07", "type": "mcq", "unitIds": ["ar.g30.little_words", "ar.v.eh", "ar.v.da"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "إيه ده؟", "promptLanguage": "ar", "options": ["C''est qui ?", "C''est quoi ?", "Pourquoi ?", "Quand est-ce ?"], "answer": "C''est quoi ?", "acceptedAnswers": ["C''est quoi ?"], "explanation": "إيه (quoi) + ده (ça) : « C''est quoi ? » Le mot de question donne le ton de la phrase.", "tip": "Le mot de question vient en premier ou en dernier.", "extraExample": {"text": "ده إيه؟", "translation": "C''est quoi ?"}, "errorPatterns": [{"equals": "C''est qui ?", "category": "word_confusion", "feedback": "« C''est qui ? » ne correspond pas : relis إيه ده؟ bloc par bloc. Ici, le sens est « C''est quoi ? »."}, {"equals": "Pourquoi ?", "category": "word_confusion", "feedback": "« Pourquoi ? » ne correspond pas : relis إيه ده؟ bloc par bloc. Ici, le sens est « C''est quoi ? »."}, {"equals": "Quand est-ce ?", "category": "word_confusion", "feedback": "« Quand est-ce ? » ne correspond pas : relis إيه ده؟ bloc par bloc. Ici, le sens est « C''est quoi ? »."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e08', 'ar', 'ar.l30', 'ar.v.fin', array['ar.v.fin','ar.g30.little_words']::text[], 'mcq', 'lesson', 'Quel petit mot veut dire « où » ?', array['فين']::text[], 'فين (où) finit par un ن ; في (dans) n''en a pas ; مين (qui) commence par م.', 3, '{"id": "ar.l30.e08", "type": "mcq", "unitIds": ["ar.v.fin", "ar.g30.little_words"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel petit mot veut dire « où » ?", "promptLanguage": "fr", "options": ["في", "مين", "ليه", "فين"], "answer": "فين", "acceptedAnswers": ["فين"], "explanation": "فين (où) finit par un ن ; في (dans) n''en a pas ; مين (qui) commence par م.", "tip": "Regarde le début et la fin : ف…ن = où.", "extraExample": {"text": "فين الباب؟", "translation": "Où est la porte ?"}, "errorPatterns": [{"equals": "في", "category": "word_confusion", "feedback": "في (dans) n''a pas de ن final : « où » s''écrit فين."}, {"equals": "مين", "category": "word_confusion", "feedback": "مين commence par م : c''est « qui »."}, {"equals": "ليه", "category": "word_confusion", "feedback": "ليه commence par ل : c''est « pourquoi »."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e09', 'ar', 'ar.l30', 'ar.v.mish', array['ar.v.mish','ar.v.kwayyis','ar.g30.little_words']::text[], 'mcq', 'lesson', 'مش كويس', array['pas bien']::text[], 'مش (ne… pas) + كويس (bien) : « pas bien ». مش devant un mot le nie.', 2, '{"id": "ar.l30.e09", "type": "mcq", "unitIds": ["ar.v.mish", "ar.v.kwayyis", "ar.g30.little_words"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "مش كويس", "promptLanguage": "ar", "options": ["très bien", "pas bien", "Dieu merci", "pas de thé"], "answer": "pas bien", "acceptedAnswers": ["pas bien"], "explanation": "مش (ne… pas) + كويس (bien) : « pas bien ». مش devant un mot le nie.", "tip": "مش nie le mot qui le suit.", "extraExample": {"text": "مش عايز.", "translation": "Je ne veux pas."}, "errorPatterns": [{"equals": "très bien", "category": "word_confusion", "feedback": "« très bien » ne correspond pas : relis مش كويس bloc par bloc. Ici, le sens est « pas bien »."}, {"equals": "Dieu merci", "category": "word_confusion", "feedback": "« Dieu merci » ne correspond pas : relis مش كويس bloc par bloc. Ici, le sens est « pas bien »."}, {"equals": "pas de thé", "category": "word_confusion", "feedback": "« pas de thé » ne correspond pas : relis مش كويس bloc par bloc. Ici, le sens est « pas bien »."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = 