insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e10', 'ar', 'ar.l30', 'ar.v.kitir', array['ar.v.kitir','ar.g30.little_words']::text[], 'mcq', 'lesson', 'Quel mot veut dire « beaucoup » ?', array['كتير']::text[], 'كتير veut dire « beaucoup ». كتب veut dire « livres » ou « il a écrit », عندي « j''ai », جواب « lettre ».', 2, '{"id": "ar.l30.e10", "type": "mcq", "unitIds": ["ar.v.kitir", "ar.g30.little_words"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « beaucoup » ?", "promptLanguage": "fr", "options": ["كتب", "عندي", "جواب", "كتير"], "answer": "كتير", "acceptedAnswers": ["كتير"], "explanation": "كتير veut dire « beaucoup ». كتب veut dire « livres » ou « il a écrit », عندي « j''ai », جواب « lettre ».", "tip": "كتير finit par ير, comme شكرا كتير.", "extraExample": {"text": "شكرا كتير.", "translation": "Merci beaucoup."}, "errorPatterns": [{"equals": "كتب", "category": "word_confusion", "feedback": "« كتب » a un autre sens : « beaucoup » se dit كتير."}, {"equals": "عندي", "category": "word_confusion", "feedback": "« عندي » a un autre sens : « beaucoup » se dit كتير."}, {"equals": "جواب", "category": "word_confusion", "feedback": "« جواب » a un autre sens : « beaucoup » se dit كتير."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e11', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.da','ar.v.di','ar.v.dol']::text[], 'match', 'lesson', 'Relie chaque petit mot à son genre.', '{}'::text[], 'ده pour un masculin, دي pour un féminin, دول pour plusieurs. Le dernier caractère fait la différence.', 1, '{"id": "ar.l30.e11", "type": "match", "unitIds": ["ar.g30.little_words", "ar.v.da", "ar.v.di", "ar.v.dol"], "difficulty": 1, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque petit mot à son genre.", "promptLanguage": "fr", "pairs": [{"left": "ده", "right": "masculin"}, {"left": "دي", "right": "féminin"}, {"left": "دول", "right": "pluriel"}], "acceptedAnswers": [], "answer": "ده = masculin ; دي = féminin ; دول = pluriel", "explanation": "ده pour un masculin, دي pour un féminin, دول pour plusieurs. Le dernier caractère fait la différence.", "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e12', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.fi','ar.v.ala','ar.v.mish','ar.v.fin']::text[], 'match', 'lesson', 'Relie chaque petit mot à son sens.', '{}'::text[], 'في (dans), على (sur), مش (ne… pas) et فين (où) : quatre petits mots qu''on voit dans presque chaque phrase.', 2, '{"id": "ar.l30.e12", "type": "match", "unitIds": ["ar.g30.little_words", "ar.v.fi", "ar.v.ala", "ar.v.mish", "ar.v.fin"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque petit mot à son sens.", "promptLanguage": "fr", "pairs": [{"left": "في", "right": "dans"}, {"left": "على", "right": "sur"}, {"left": "مش", "right": "ne… pas"}, {"left": "فين", "right": "où"}], "acceptedAnswers": [], "answer": "في = dans ; على = sur ; مش = ne… pas ; فين = où", "explanation": "في (dans), على (sur), مش (ne… pas) et فين (où) : quatre petits mots qu''on voit dans presque chaque phrase.", "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e13', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.eh','ar.v.min','ar.v.leh','ar.v.imta']::text[], 'match', 'lesson', 'Relie chaque mot de question à son sens.', '{}'::text[], 'Quatre questions : إيه (quoi), مين (qui), ليه (pourquoi) et إمتى (quand). Le cinquième mot, فين, veut dire « où ».', 2, '{"id": "ar.l30.e13", "type": "match", "unitIds": ["ar.g30.little_words", "ar.v.eh", "ar.v.min", "ar.v.leh", "ar.v.imta"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot de question à son sens.", "promptLanguage": "fr", "pairs": [{"left": "إيه", "right": "quoi"}, {"left": "مين", "right": "qui"}, {"left": "ليه", "right": "pourquoi"}, {"left": "إمتى", "right": "quand"}], "acceptedAnswers": [], "answer": "إيه = quoi ; مين = qui ; ليه = pourquoi ; إمتى = quand", "explanation": "Quatre questions : إيه (quoi), مين (qui), ليه (pourquoi) et إمتى (quand). Le cinquième mot, فين, veut dire « où ».", "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e14', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.leh','ar.v.imta','ar.v.min','ar.v.fin']::text[], 'match', 'lesson', 'Relie chaque question à son sens.', '{}'::text[], 'Repère le mot de question de chaque phrase : ليه (pourquoi), إمتى (quand), مين (qui), فين (où).', 3, '{"id": "ar.l30.e14", "type": "match", "unitIds": ["ar.g30.little_words", "ar.v.leh", "ar.v.imta", "ar.v.min", "ar.v.fin"], "difficulty": 3, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque question à son sens.", "promptLanguage": "fr", "pairs": [{"left": "ليه مش عايز؟", "right": "Pourquoi tu ne veux pas ?"}, {"left": "إمتى القداس؟", "right": "Quand est la liturgie ?"}, {"left": "مين ده؟", "right": "C''est qui ?"}, {"left": "فين الباب؟", "right": "Où est la porte ?"}], "acceptedAnswers": [], "answer": "ليه مش عايز؟ = Pourquoi tu ne veux pas ? ; إمتى القداس؟ = Quand est la liturgie ? ; مين ده؟ = C''est qui ? ; فين الباب؟ = Où est la porte ?", "explanation": "Repère le mot de question de chaque phrase : ليه (pourquoi), إمتى (quand), مين (qui), فين (où).", "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e15', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.da']::text[], 'fill_blank', 'lesson', '___ بيت (C''est une maison.)', array['ده']::text[], 'بيت est un mot masculin, donc on dit ده بيت. دي serait pour un féminin et دول pour un pluriel.', 2, '{"id": "ar.l30.e15", "type": "fill_blank", "unitIds": ["ar.g30.little_words", "ar.v.da"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "___ بيت (C''est une maison.)", "promptLanguage": "ar", "options": ["دي", "ده", "دول", "في"], "answer": "ده", "acceptedAnswers": ["ده"], "explanation": "بيت est un mot masculin, donc on dit ده بيت. دي serait pour un féminin et دول pour un pluriel.", "tip": "Mot féminin ou masculin : cherche le ة.", "extraExample": {"text": "ده باب.", "translation": "C''est une porte."}, "errorPatterns": [{"equals": "دي", "category": "vocabulary", "feedback": "دي est pour un féminin ; بيت est masculin."}, {"equals": "دول", "category": "vocabulary", "feedback": "دول est pour un pluriel ; ici il n''y a qu''une maison."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e16', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.ala']::text[], 'fill_blank', 'lesson', 'الكتاب ___ الترابيزة (Le livre est sur la table.)', array['على']::text[], 'Le livre est posé sur la table : le petit mot est على, « sur ». في voudrait dire « dans ».', 2, '{"id": "ar.l30.e16", "type": "fill_blank", "unitIds": ["ar.g30.little_words", "ar.v.ala"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "الكتاب ___ الترابيزة (Le livre est sur la table.)", "promptLanguage": "ar", "options": ["في", "مش", "فين", "على"], "answer": "على", "acceptedAnswers": ["على"], "explanation": "Le livre est posé sur la table : le petit mot est على, « sur ». في voudrait dire « dans ».", "tip": "Posé dessus : على.", "extraExample": {"text": "الموبايل على الكرسي.", "translation": "Le portable est sur la chaise."}, "errorPatterns": [{"equals": "في", "category": "vocabulary", "feedback": "في veut dire « dans » : ici le livre est dessus."}, {"equals": "فين", "category": "vocabulary", "feedback": "فين veut dire « où »."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e17', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.imta']::text[], 'fill_blank', 'lesson', '___ القداس؟ (Quand est la liturgie ?)', array['إمتى']::text[], 'Pour demander « quand », on commence par إمتى. مين (qui), ليه (pourquoi) et إيه (quoi) posent d''autres questions.', 3, '{"id": "ar.l30.e17", "type": "fill_blank", "unitIds": ["ar.g30.little_words", "ar.v.imta"], "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "___ القداس؟ (Quand est la liturgie ?)", "promptLanguage": "ar", "options": ["مين", "إمتى", "ليه", "إيه"], "answer": "إمتى", "acceptedAnswers": ["إمتى"], "explanation": "Pour demander « quand », on commence par إمتى. مين (qui), ليه (pourquoi) et إيه (quoi) posent d''autres questions.", "tip": "إمتى : le seul de la liste qui commence par إ + م.", "extraExample": {"text": "إمتى هتيجي؟", "translation": "Quand viendras-tu ?"}, "errorPatterns": [{"equals": "مين", "category": "vocabulary", "feedback": "« مين » pose une autre question que « quand »."}, {"equals": "ليه", "category": "vocabulary", "feedback": "« ليه » pose une autre question que « quand »."}, {"equals": "إيه", "category": "vocabulary", "feedback": "« إيه » pose une autre question que « quand »."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e18', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.leh','ar.v.mish']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Pourquoi tu ne veux pas de thé ? »', array['ليه مش عايز شاي','مش عايز شاي ليه']::text[], 'Le mot de question ليه ouvre la phrase, puis مش عايز (je ne veux pas) et شاي. On peut aussi le mettre à la fin.', 3, '{"id": "ar.l30.e18", "type": "reorder", "unitIds": ["ar.g30.little_words", "ar.v.leh", "ar.v.mish"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Pourquoi tu ne veux pas de thé ? »", "promptLanguage": "fr", "tokens": ["شاي", "عايز", "ليه", "مش"], "answer": "ليه مش عايز شاي", "acceptedAnswers": ["ليه مش عايز شاي", "مش عايز شاي ليه"], "explanation": "Le mot de question ليه ouvre la phrase, puis مش عايز (je ne veux pas) et شاي. On peut aussi le mettre à la fin.", "tip": "ليه au début, ou tout à la fin.", "extraExample": {"text": "ليه مش عايز؟", "translation": "Pourquoi tu ne veux pas ?"}, "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e19', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.ala']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Le livre est sur la table. »', array['الكتاب على الترابيزة']::text[], 'On nomme d''abord ce qui est posé (الكتاب), puis على (sur), puis l''endroit (الترابيزة).', 3, '{"id": "ar.l30.e19", "type": "reorder", "unitIds": ["ar.g30.little_words", "ar.v.ala"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Le livre est sur la table. »", "promptLanguage": "fr", "tokens": ["الترابيزة", "الكتاب", "على"], "answer": "الكتاب على الترابيزة", "acceptedAnswers": ["الكتاب على الترابيزة"], "explanation": "On nomme d''abord ce qui est posé (الكتاب), puis على (sur), puis l''endroit (الترابيزة).", "tip": "Chose posée, على, endroit.", "extraExample": {"text": "الموبايل على الكرسي", "translation": "Le portable est sur la chaise"}, "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e20', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.imta','ar.v.quddas']::text[], 'translation', 'lesson', 'إمتى القداس', array['Quand est la liturgie ?','quand est la liturgie','quand a lieu la liturgie','quand est la messe','c''est quand la liturgie']::text[], 'إمتى (quand) + القداس (la liturgie) : « Quand est la liturgie ? »', 2, '{"id": "ar.l30.e20", "type": "translation", "unitIds": ["ar.g30.little_words", "ar.v.imta", "ar.v.quddas"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "إمتى القداس", "promptLanguage": "ar", "answer": "Quand est la liturgie ?", "acceptedAnswers": ["Quand est la liturgie ?", "quand est la liturgie", "quand a lieu la liturgie", "quand est la messe", "c''est quand la liturgie"], "explanation": "إمتى (quand) + القداس (la liturgie) : « Quand est la liturgie ? »", "tip": "Le mot de question vient en premier.", "extraExample": {"text": "إمتى التسبحة؟", "translation": "Quand est l''office de louange ?"}, "pool": "lesson", "lessonId": "ar.l30", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e21', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.leh']::text[], 'free_answer', 'lesson', 'Que veut dire ليه ?', array['pourquoi','pourquoi ?']::text[], 'ليه veut dire « pourquoi ». On l''entend à chaque « pourquoi pas ? » en égyptien.', 2, '{"id": "ar.l30.e21", "type": "free_answer", "unitIds": ["ar.g30.little_words", "ar.v.leh"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire ليه ?", "promptLanguage": "fr", "answer": "pourquoi", "acceptedAnswers": ["pourquoi", "pourquoi ?"], "explanation": "ليه veut dire « pourquoi ». On l''entend à chaque « pourquoi pas ? » en égyptien.", "tip": "ليه ouvre la question.", "extraExample": {"text": "ليه مش عايز؟", "translation": "Pourquoi tu ne veux pas ?"}, "pool": "lesson", "lessonId": "ar.l30", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e22', 'ar', 'ar.l30', 'ar.g30.little_words', array['ar.g30.little_words','ar.v.ala']::text[], 'free_answer', 'lesson', 'Que veut dire على ?', array['sur','sur le','sur la']::text[], 'على veut dire « sur ». On le trouve aussi écrit علي.', 2, '{"id": "ar.l30.e22", "type": "free_answer", "unitIds": ["ar.g30.little_words", "ar.v.ala"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire على ?", "promptLanguage": "fr", "answer": "sur", "acceptedAnswers": ["sur", "sur le", "sur la"], "explanation": "على veut dire « sur ». On le trouve aussi écrit علي.", "tip": "Pense à ce qui est posé dessus.", "extraExample": {"text": "الكتاب على الترابيزة.", "translation": "Le livre est sur la table."}, "pool": "lesson", "lessonId": "ar.l30", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e23', 'ar', 'ar.l30', 'ar.v.kwayyis', array['ar.v.kwayyis','ar.g30.little_words']::text[], 'free_answer', 'lesson', 'Que veut dire كويس ?', array['bien','bon']::text[], 'كويس veut dire « bien » ou « bon ». C''est le mot de la leçon 27.', 2, '{"id": "ar.l30.e23", "type": "free_answer", "unitIds": ["ar.v.kwayyis", "ar.g30.little_words"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire كويس ?", "promptLanguage": "fr", "answer": "bien", "acceptedAnswers": ["bien", "bon"], "explanation": "كويس veut dire « bien » ou « bon ». C''est le mot de la leçon 27.", "tip": "Le و au milieu fait un paquet long : كو.", "extraExample": {"text": "الشاي كويس.", "translation": "Le thé est bon."}, "pool": "lesson", "lessonId": "ar.l30", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e01', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.rayeh','ar.v.naharda','ar.v.kanisa']::text[], 'mcq', 'lesson', 'أنا رايح الكنيسة النهارده', array['Je vais à l''église aujourd''hui.']::text[], 'أنا رايح (je vais) | الكنيسة (à l''église) | النهارده (aujourd''hui) : trois groupes de sens à enchaîner.', 2, '{"id": "ar.l31.e01", "type": "mcq", "unitIds": ["ar.g31.sentence_flow", "ar.v.rayeh", "ar.v.naharda", "ar.v.kanisa"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "أنا رايح الكنيسة النهارده", "promptLanguage": "ar", "options": ["Je veux du thé maintenant.", "Je vais à l''église aujourd''hui.", "Où est l''église aujourd''hui ?", "Maman va à l''université aujourd''hui."], "answer": "Je vais à l''église aujourd''hui.", "acceptedAnswers": ["Je vais à l''église aujourd''hui."], "explanation": "أنا رايح (je vais) | الكنيسة (à l''église) | النهارده (aujourd''hui) : trois groupes de sens à enchaîner.", "tip": "Qui ? fait quoi ? où ? quand ?", "extraExample": {"text": "أنا رايح الجامعة النهارده.", "translation": "Je vais à l''université aujourd''hui."}, "errorPatterns": [{"equals": "Je veux du thé maintenant.", "category": "word_confusion", "feedback": "« Je veux du thé maintenant. » ne correspond pas : relis أنا رايح الكنيسة النهارده bloc par bloc. Ici, le sens est « Je vais à l''église aujourd''hui. »."}, {"equals": "Où est l''église aujourd''hui ?", "category": "word_confusion", "feedback": "« Où est l''église aujourd''hui ? » ne correspond pas : relis أنا رايح الكنيسة النهارده bloc par bloc. Ici, le sens est « Je vais à l''église aujourd''hui. »."}, {"equals": "Maman va à l''université aujourd''hui.", "category": "word_confusion", "feedback": "« Maman va à l''université aujourd''hui. » ne correspond pas : relis أنا رايح الكنيسة النهارده bloc par bloc. Ici, le sens est « Je vais à l''église aujourd''hui. »."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e02', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.delwaqti','ar.v.ayiz','ar.v.shay']::text[], 'mcq', 'lesson', 'بابا عايز شاي دلوقتي', array['Papa veut du thé maintenant.']::text[], 'بابا (qui) | عايز شاي (veut du thé) | دلوقتي (maintenant) : le « quand » est à la fin.', 2, '{"id": "ar.l31.e02", "type": "mcq", "unitIds": ["ar.g31.sentence_flow", "ar.v.delwaqti", "ar.v.ayiz", "ar.v.shay"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "بابا عايز شاي دلوقتي", "promptLanguage": "ar", "options": ["Papa a faim maintenant.", "Papa va à l''église aujourd''hui.", "Maman veut du thé maintenant.", "Papa veut du thé maintenant."], "answer": "Papa veut du thé maintenant.", "acceptedAnswers": ["Papa veut du thé maintenant."], "explanation": "بابا (qui) | عايز شاي (veut du thé) | دلوقتي (maintenant) : le « quand » est à la fin.", "tip": "Le dernier groupe donne le « quand ».", "extraExample": {"text": "بابا عايز عيش دلوقتي.", "translation": "Papa veut du pain maintenant."}, "errorPatterns": [{"equals": "Papa a faim maintenant.", "category": "word_confusion", "feedback": "« Papa a faim maintenant. » ne correspond pas : relis بابا عايز شاي دلوقتي bloc par bloc. Ici, le sens est « Papa veut du thé maintenant. »."}, {"equals": "Papa va à l''église aujourd''hui.", "category": "word_confusion", "feedback": "« Papa va à l''église aujourd''hui. » ne correspond pas : relis بابا عايز شاي دلوقتي bloc par bloc. Ici, le sens est « Papa veut du thé maintenant. »."}, {"equals": "Maman veut du thé maintenant.", "category": "word_confusion", "feedback": "« Maman veut du thé maintenant. » ne correspond pas : relis بابا عايز شاي دلوقتي bloc par bloc. Ici, le sens est « Papa veut du thé maintenant. »."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e03', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.rayeh','ar.v.gamia','ar.v.naharda']::text[], 'mcq', 'lesson', 'ماما رايحة الجامعة النهارده', array['Maman va à l''université aujourd''hui.']::text[], 'ماما رايحة (maman va, avec ـة : une femme) | الجامعة (à l''université) | النهارده (aujourd''hui).', 2, '{"id": "ar.l31.e03", "type": "mcq", "unitIds": ["ar.g31.sentence_flow", "ar.v.rayeh", "ar.v.gamia", "ar.v.naharda"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "ماما رايحة الجامعة النهارده", "promptLanguage": "ar", "options": ["Maman va à l''école aujourd''hui.", "Maman va à l''université aujourd''hui.", "Papa va à l''université aujourd''hui.", "Maman veut de l''eau maintenant."], "answer": "Maman va à l''université aujourd''hui.", "acceptedAnswers": ["Maman va à l''université aujourd''hui."], "explanation": "ماما رايحة (maman va, avec ـة : une femme) | الجامعة (à l''université) | النهارده (aujourd''hui).", "tip": "Le ـة de رايحة annonce une femme.", "extraExample": {"text": "ماما رايحة الكنيسة.", "translation": "Maman va à l''église."}, "errorPatterns": [{"equals": "Maman va à l''école aujourd''hui.", "category": "word_confusion", "feedback": "« Maman va à l''école aujourd''hui. » ne correspond pas : relis ماما رايحة الجامعة النهارده bloc par bloc. Ici, le sens est « Maman va à l''université aujourd''hui. »."}, {"equals": "Papa va à l''université aujourd''hui.", "category": "word_confusion", "feedback": "« Papa va à l''université aujourd''hui. » ne correspond pas : relis ماما رايحة الجامعة النهارده bloc par bloc. Ici, le sens est « Maman va à l''université aujourd''hui. »."}, {"equals": "Maman veut de l''eau maintenant.", "category": "word_confusion", "feedback": "« Maman veut de l''eau maintenant. » ne correspond pas : relis ماما رايحة الجامعة النهارده bloc par bloc. Ici, le sens est « Maman va à l''université aujourd''hui. »."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e04', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.awi','ar.v.jaan']::text[], 'mcq', 'lesson', 'أنا جعان أوي', array['J''ai très faim.']::text[], 'أنا جعان (j''ai faim) + أوي (très) : أوي renforce le mot qui le précède.', 2, '{"id": "ar.l31.e04", "type": "mcq", "unitIds": ["ar.g31.sentence_flow", "ar.v.awi", "ar.v.jaan"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "أنا جعان أوي", "promptLanguage": "ar", "options": ["J''ai un peu faim.", "Je veux du thé.", "Je vais bien, Dieu merci.", "J''ai très faim."], "answer": "J''ai très faim.", "acceptedAnswers": ["J''ai très faim."], "explanation": "أنا جعان (j''ai faim) + أوي (très) : أوي renforce le mot qui le précède.", "tip": "أوي se met après le mot qu''il renforce.", "extraExample": {"text": "الأكل حلو أوي.", "translation": "La nourriture est très bonne."}, "errorPatterns": [{"equals": "J''ai un peu faim.", "category": "word_confusion", "feedback": "« J''ai un peu faim. » ne correspond pas : relis أنا جعان أوي bloc par bloc. Ici, le sens est « J''ai très faim. »."}, {"equals": "Je veux du thé.", "category": "word_confusion", "feedback": "« Je veux du thé. » ne correspond pas : relis أنا جعان أوي bloc par bloc. Ici, le sens est « J''ai très faim. »."}, {"equals": "Je vais bien, Dieu merci.", "category": "word_confusion", "feedback": "« Je vais bien, Dieu merci. » ne correspond pas : relis أنا جعان أوي bloc par bloc. Ici, le sens est « J''ai très faim. »."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e05', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.kaman','ar.v.ayiz','ar.v.eish']::text[], 'mcq', 'lesson', 'عايز عيش كمان', array['Je veux encore du pain.']::text[], 'عايز عيش (je veux du pain) + كمان (encore). كمان se place après ce qu''il complète.', 2, '{"id": "ar.l31.e05", "type": "mcq", "unitIds": ["ar.g31.sentence_flow", "ar.v.kaman", "ar.v.ayiz", "ar.v.eish"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "عايز عيش كمان", "promptLanguage": "ar", "options": ["Je veux du pain maintenant.", "Je veux encore du pain.", "Je ne veux pas de pain.", "Papa veut du pain."], "answer": "Je veux encore du pain.", "acceptedAnswers": ["Je veux encore du pain."], "explanation": "عايز عيش (je veux du pain) + كمان (encore). كمان se place après ce qu''il complète.", "tip": "كمان : encore, aussi.", "extraExample": {"text": "عايز شاي كمان.", "translation": "Je veux encore du thé."}, "errorPatterns": [{"equals": "Je veux du pain maintenant.", "category": "word_confusion", "feedback": "« Je veux du pain maintenant. » ne correspond pas : relis عايز عيش كمان bloc par bloc. Ici, le sens est « Je veux encore du pain. »."}, {"equals": "Je ne veux pas de pain.", "category": "word_confusion", "feedback": "« Je ne veux pas de pain. » ne correspond pas : relis عايز عيش كمان bloc par bloc. Ici, le sens est « Je veux encore du pain. »."}, {"equals": "Papa veut du pain.", "category": "word_confusion", "feedback": "« Papa veut du pain. » ne correspond pas : relis عايز عيش كمان bloc par bloc. Ici, le sens est « Je veux encore du pain. »."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e06', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.tamam','ar.v.shokran','ar.v.awi']::text[], 'mcq', 'lesson', 'تمام شكرا أوي', array['Parfait, merci beaucoup.']::text[], 'تمام (parfait) + شكرا (merci) + أوي (très) : « Parfait, merci beaucoup. »', 3, '{"id": "ar.l31.e06", "type": "mcq", "unitIds": ["ar.g31.sentence_flow", "ar.v.tamam", "ar.v.shokran", "ar.v.awi"], "difficulty": 3, "instruction": "Lis la phrase et choisis son sens.", "prompt": "تمام شكرا أوي", "promptLanguage": "ar", "options": ["Allez, merci beaucoup.", "D''accord, merci.", "Parfait, c''est fini.", "Parfait, merci beaucoup."], "answer": "Parfait, merci beaucoup.", "acceptedAnswers": ["Parfait, merci beaucoup."], "explanation": "تمام (parfait) + شكرا (merci) + أوي (très) : « Parfait, merci beaucoup. »", "tip": "Trois mots courts qui se lisent d''un coup.", "extraExample": {"text": "تمام، كله كويس.", "translation": "Parfait, tout est bien."}, "errorPatterns": [{"equals": "Allez, merci beaucoup.", "category": "word_confusion", "feedback": "« Allez, merci beaucoup. » ne correspond pas : relis تمام شكرا أوي bloc par bloc. Ici, le sens est « Parfait, merci beaucoup. »."}, {"equals": "D''accord, merci.", "category": "word_confusion", "feedback": "« D''accord, merci. » ne correspond pas : relis تمام شكرا أوي bloc par bloc. Ici, le sens est « Parfait, merci beaucoup. »."}, {"equals": "Parfait, c''est fini.", "category": "word_confusion", "feedback": "« Parfait, c''est fini. » ne correspond pas : relis تمام شكرا أوي bloc par bloc. Ici, le sens est « Parfait, merci beaucoup. »."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e07', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.rayeh']::text[], 'mcq', 'lesson', 'Qui parle dans « أنا رايحة الكنيسة » ?', array['une femme']::text[], 'Le ـة de رايحة montre qu''une femme parle ; un homme dirait رايح.', 3, '{"id": "ar.l31.e07", "type": "mcq", "unitIds": ["ar.g31.sentence_flow", "ar.v.rayeh"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui parle dans « أنا رايحة الكنيسة » ?", "promptLanguage": "fr", "options": ["un homme", "une femme", "plusieurs personnes"], "answer": "une femme", "acceptedAnswers": ["une femme"], "explanation": "Le ـة de رايحة montre qu''une femme parle ; un homme dirait رايح.", "tip": "Regarde la fin du mot : ـة = une femme.", "extraExample": {"text": "ماما رايحة الجامعة.", "translation": "Maman va à l''université."}, "errorPatterns": [{"equals": "un homme", "category": "grammar", "feedback": "Un homme dirait رايح, sans ـة."}, {"equals": "plusieurs personnes", "category": "grammar", "feedback": "Plusieurs personnes diraient رايحين, avec ـين."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e08', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.delwaqti']::text[], 'mcq', 'lesson', 'Dans « بابا عايز شاي دلوقتي », quel mot dit « quand » ?', array['دلوقتي']::text[], 'Le « quand » est le dernier groupe : دلوقتي (maintenant). بابا est le qui, عايز شاي le « veut du thé ».', 2, '{"id": "ar.l31.e08", "type": "mcq", "unitIds": ["ar.g31.sentence_flow", "ar.v.delwaqti"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans « بابا عايز شاي دلوقتي », quel mot dit « quand » ?", "promptLanguage": "fr", "options": ["بابا", "عايز", "شاي", "دلوقتي"], "answer": "دلوقتي", "acceptedAnswers": ["دلوقتي"], "explanation": "Le « quand » est le dernier groupe : دلوقتي (maintenant). بابا est le qui, عايز شاي le « veut du thé ».", "tip": "Cherche le « quand » à la fin de la phrase.", "extraExample": {"text": "أنا رايح النهارده.", "translation": "Je vais aujourd''hui."}, "errorPatterns": [{"equals": "بابا", "category": "grammar", "feedback": "« بابا » ne dit pas quand : le « quand » est le dernier mot, دلوقتي."}, {"equals": "عايز", "category": "grammar", "feedback": "« عايز » ne dit pas quand : le « quand » est le dernier mot, دلوقتي."}, {"equals": "شاي", "category": "grammar", "feedback": "« شاي » ne dit pas quand : le « quand » est le dernier mot, دلوقتي."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e09', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.yalla']::text[], 'mcq', 'lesson', 'Quel mot veut dire « allez ! » ?', array['يلا']::text[], 'يلا sert à encourager ou à partir : « allez ! ». خلاص veut dire « c''est fini », ماشي « d''accord » et كده « comme ça ».', 1, '{"id": "ar.l31.e09", "type": "mcq", "unitIds": ["ar.g31.sentence_flow", "ar.v.yalla"], "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « allez ! » ?", "promptLanguage": "fr", "options": ["خلاص", "يلا", "ماشي", "كده"], "answer": "يلا", "acceptedAnswers": ["يلا"], "explanation": "يلا sert à encourager ou à partir : « allez ! ». خلاص veut dire « c''est fini », ماشي « d''accord » et كده « comme ça ».", "tip": "يلا lance l''action : on y va.", "extraExample": {"text": "يلا يا مينا", "translation": "Allez, Mina !"}, "errorPatterns": [{"equals": "خلاص", "category": "word_confusion", "feedback": "« خلاص » a un autre sens que « allez ! » : relis la leçon."}, {"equals": "ماشي", "category": "word_confusion", "feedback": "« ماشي » a un autre sens que « allez ! » : relis la leçon."}, {"equals": "كده", "category": "word_confusion", "feedback": "« كده » a un autre sens que « allez ! » : relis la leçon."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e10', 'ar', 'ar.l31', 'ar.v.ala', array['ar.v.ala','ar.g31.sentence_flow']::text[], 'mcq', 'lesson', 'Quel petit mot veut dire « sur » ?', array['على']::text[], 'على veut dire « sur ». في veut dire « dans », مش « ne… pas » et فين « où ».', 2, '{"id": "ar.l31.e10", "type": "mcq", "unitIds": ["ar.v.ala", "ar.g31.sentence_flow"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel petit mot veut dire « sur » ?", "promptLanguage": "fr", "options": ["في", "مش", "فين", "على"], "answer": "على", "acceptedAnswers": ["على"], "explanation": "على veut dire « sur ». في veut dire « dans », مش « ne… pas » et فين « où ».", "tip": "على : posé dessus.", "extraExample": {"text": "الكتاب على الترابيزة.", "translation": "Le livre est sur la table."}, "errorPatterns": [{"equals": "في", "category": "word_confusion", "feedback": "« في » a un autre sens que « sur » : relis les petits mots de la leçon 30."}, {"equals": "مش", "category": "word_confusion", "feedback": "« مش » a un autre sens que « sur » : relis les petits mots de la leçon 30."}, {"equals": "فين", "category": "word_confusion", "feedback": "« فين » a un autre sens que « sur » : relis les petits mots de la leçon 30."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e11', 'ar', 'ar.l31', 'ar.v.leh', array['ar.v.leh','ar.g31.sentence_flow']::text[], 'mcq', 'lesson', 'Quel mot de question veut dire « pourquoi » ?', array['ليه']::text[], 'ليه veut dire « pourquoi ». مين veut dire « qui », إمتى « quand » et فين « où ».', 2, '{"id": "ar.l31.e11", "type": "mcq", "unitIds": ["ar.v.leh", "ar.g31.sentence_flow"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot de question veut dire « pourquoi » ?", "promptLanguage": "fr", "options": ["مين", "ليه", "إمتى", "فين"], "answer": "ليه", "acceptedAnswers": ["ليه"], "explanation": "ليه veut dire « pourquoi ». مين veut dire « qui », إمتى « quand » et فين « où ».", "tip": "ليه ouvre une question qui cherche la raison.", "extraExample": {"text": "ليه مش عايز؟", "translation": "Pourquoi tu ne veux pas ?"}, "errorPatterns": [{"equals": "مين", "category": "word_confusion", "feedback": "« مين » pose une autre question que « pourquoi »."}, {"equals": "إمتى", "category": "word_confusion", "feedback": "« إمتى » pose une autre question que « pourquoi »."}, {"equals": "فين", "category": "word_confusion", "feedback": "« فين » pose une autre question que « pourquoi »."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e12', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.naharda','ar.v.delwaqti','ar.v.kaman','ar.v.awi']::text[], 'match', 'lesson', 'Relie chaque mot de la rue à son sens (1).', '{}'::text[], 'Quatre mots de tous les jours : النهارده (aujourd''hui), دلوقتي (maintenant), كمان (encore) et أوي (très).', 2, '{"id": "ar.l31.e12", "type": "match", "unitIds": ["ar.g31.sentence_flow", "ar.v.naharda", "ar.v.delwaqti", "ar.v.kaman", "ar.v.awi"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot de la rue à son sens (1).", "promptLanguage": "fr", "pairs": [{"left": "النهارده", "right": "aujourd''hui"}, {"left": "دلوقتي", "right": "maintenant"}, {"left": "كمان", "right": "encore"}, {"left": "أوي", "right": "très"}], "acceptedAnswers": [], "answer": "النهارده = aujourd''hui ; دلوقتي = maintenant ; كمان = encore ; أوي = très", "explanation": "Quatre mots de tous les jours : النهارده (aujourd''hui), دلوقتي (maintenant), كمان (encore) et أوي (très).", "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e13', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.khalas','ar.v.yalla','ar.v.mashi','ar.v.keda']::text[], 'match', 'lesson', 'Relie chaque mot de la rue à son sens (2).', '{}'::text[], 'Des mots de conversation : خلاص (c''est fini), يلا (allez), ماشي (d''accord) et كده (comme ça).', 2, '{"id": "ar.l31.e13", "type": "match", "unitIds": ["ar.g31.sentence_flow", "ar.v.khalas", "ar.v.yalla", "ar.v.mashi", "ar.v.keda"], "difficulty": 2, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque mot de la rue à son sens (2).", "promptLanguage": "fr", "pairs": [{"left": "خلاص", "right": "ça y est"}, {"left": "يلا", "right": "allez"}, {"left": "ماشي", "right": "d''accord"}, {"left": "كده", "right": "comme ça"}], "acceptedAnswers": [], "answer": "خلاص = ça y est ; يلا = allez ; ماشي = d''accord ; كده = comme ça", "explanation": "Des mots de conversation : خلاص (c''est fini), يلا (allez), ماشي (d''accord) et كده (comme ça).", "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e14', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.rayeh']::text[], 'match', 'lesson', 'Relie chaque forme à celui qui parle.', '{}'::text[], 'رايح (sans ـة) pour un homme, رايحة (avec ـة) pour une femme, رايحين (avec ـين) pour plusieurs personnes.', 3, '{"id": "ar.l31.e14", "type": "match", "unitIds": ["ar.g31.sentence_flow", "ar.v.rayeh"], "difficulty": 3, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque forme à celui qui parle.", "promptLanguage": "fr", "pairs": [{"left": "رايح", "right": "un homme"}, {"left": "رايحة", "right": "une femme"}, {"left": "رايحين", "right": "plusieurs personnes"}], "acceptedAnswers": [], "answer": "رايح = un homme ; رايحة = une femme ; رايحين = plusieurs personnes", "explanation": "رايح (sans ـة) pour un homme, رايحة (avec ـة) pour une femme, رايحين (avec ـين) pour plusieurs personnes.", "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e15', 'ar', 'ar.l31', 'ar.v.ya_rab_irham', array['ar.v.ya_rab_irham','ar.v.salam_likol','ar.v.magd_lak','ar.v.masih_qam','ar.g31.sentence_flow']::text[], 'match', 'lesson', 'Retour à l''église : relie chaque réponse à son sens.', '{}'::text[], 'Quatre réponses de la liturgie : tu les connais par cœur, ton œil doit les reconnaître d''un trait.', 3, '{"id": "ar.l31.e15", "type": "match", "unitIds": ["ar.v.ya_rab_irham", "ar.v.salam_likol", "ar.v.magd_lak", "ar.v.masih_qam", "ar.g31.sentence_flow"], "difficulty": 3, "instruction": "Relie chaque élément à son sens.", "prompt": "Retour à l''église : relie chaque réponse à son sens.", "promptLanguage": "fr", "pairs": [{"left": "يا رب ارحم", "right": "Seigneur, aie pitié"}, {"left": "السلام لكل", "right": "La paix à tous"}, {"left": "المجد لك يا رب", "right": "Gloire à toi, Seigneur"}, {"left": "المسيح قام", "right": "Le Christ est ressuscité"}], "acceptedAnswers": [], "answer": "يا رب ارحم = Seigneur, aie pitié ; السلام لكل = La paix à tous ; المجد لك يا رب = Gloire à toi, Seigneur ; المسيح قام = Le Christ est ressuscité", "explanation": "Quatre réponses de la liturgie : tu les connais par cœur, ton œil doit les reconnaître d''un trait.", "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e16', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.rayeh']::text[], 'fill_blank', 'lesson', 'أنا ___ الكنيسة النهارده (Je vais à l''église aujourd''hui.)', array['رايح']::text[], 'Pour dire où l''on va, on emploie رايح. جعان (affamé) et كويس (bien) ne vont pas avec un lieu.', 2, '{"id": "ar.l31.e16", "type": "fill_blank", "unitIds": ["ar.g31.sentence_flow", "ar.v.rayeh"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "أنا ___ الكنيسة النهارده (Je vais à l''église aujourd''hui.)", "promptLanguage": "ar", "options": ["جعان", "عايز", "كويس", "رايح"], "answer": "رايح", "acceptedAnswers": ["رايح"], "explanation": "Pour dire où l''on va, on emploie رايح. جعان (affamé) et كويس (bien) ne vont pas avec un lieu.", "tip": "رايح + un lieu : je vais quelque part.", "extraExample": {"text": "أنا رايح الجامعة.", "translation": "Je vais à l''université."}, "errorPatterns": [{"equals": "جعان", "category": "vocabulary", "feedback": "أنا جعان الكنيسة n''a pas de sens : جعان veut dire « affamé »."}, {"equals": "كويس", "category": "vocabulary", "feedback": "أنا كويس الكنيسة n''a pas de sens : كويس veut dire « bien »."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e17', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.delwaqti']::text[], 'fill_blank', 'lesson', 'بابا عايز شاي ___ (Papa veut du thé maintenant.)', array['دلوقتي']::text[], 'Le mot qui veut dire « maintenant » est دلوقتي ; il se met à la fin de la phrase.', 2, '{"id": "ar.l31.e17", "type": "fill_blank", "unitIds": ["ar.g31.sentence_flow", "ar.v.delwaqti"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "بابا عايز شاي ___ (Papa veut du thé maintenant.)", "promptLanguage": "ar", "options": ["أوي", "دلوقتي", "كمان", "كده"], "answer": "دلوقتي", "acceptedAnswers": ["دلوقتي"], "explanation": "Le mot qui veut dire « maintenant » est دلوقتي ; il se met à la fin de la phrase.", "tip": "دلوقتي : maintenant, tout de suite.", "extraExample": {"text": "خلاص دلوقتي.", "translation": "C''est fini maintenant."}, "errorPatterns": [{"equals": "أوي", "category": "vocabulary", "feedback": "« أوي » ne veut pas dire « maintenant » : c''est دلوقتي."}, {"equals": "كمان", "category": "vocabulary", "feedback": "« كمان » ne veut pas dire « maintenant » : c''est دلوقتي."}, {"equals": "كده", "category": "vocabulary", "feedback": "« كده » ne veut pas dire « maintenant » : c''est دلوقتي."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e18', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.rayeh']::text[], 'fill_blank', 'lesson', 'ماما ___ الجامعة النهارده (Maman va à l''université aujourd''hui.)', array['رايحة']::text[], 'Maman est une femme : le mot prend ـة, رايحة. رايح est pour un homme, رايحين pour plusieurs personnes.', 3, '{"id": "ar.l31.e18", "type": "fill_blank", "unitIds": ["ar.g31.sentence_flow", "ar.v.rayeh"], "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "ماما ___ الجامعة النهارده (Maman va à l''université aujourd''hui.)", "promptLanguage": "ar", "options": ["رايح", "رايحين", "عايزة", "رايحة"], "answer": "رايحة", "acceptedAnswers": ["رايحة"], "explanation": "Maman est une femme : le mot prend ـة, رايحة. رايح est pour un homme, رايحين pour plusieurs personnes.", "tip": "ـة à la fin : une femme.", "extraExample": {"text": "تيتة رايحة الكنيسة.", "translation": "Mamie va à l''église."}, "errorPatterns": [{"equals": "رايح", "category": "grammar", "feedback": "رايح est pour un homme ; ماما est une femme."}, {"equals": "رايحين", "category": "grammar", "feedback": "رايحين est pour plusieurs personnes."}, {"equals": "عايزة", "category": "grammar", "feedback": "عايزة veut dire « elle veut » : ici il faut dire qu''elle va."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e19', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.rayeh','ar.v.naharda']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Je vais à l''église aujourd''hui. »', array['أنا رايح الكنيسة النهارده','النهارده أنا رايح الكنيسة']::text[], 'Qui (أنا), fait quoi (رايح), où (الكنيسة), quand (النهارده). On peut aussi mettre le « quand » en premier.', 3, '{"id": "ar.l31.e19", "type": "reorder", "unitIds": ["ar.g31.sentence_flow", "ar.v.rayeh", "ar.v.naharda"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Je vais à l''église aujourd''hui. »", "promptLanguage": "fr", "tokens": ["النهارده", "أنا", "الكنيسة", "رايح"], "answer": "أنا رايح الكنيسة النهارده", "acceptedAnswers": ["أنا رايح الكنيسة النهارده", "النهارده أنا رايح الكنيسة"], "explanation": "Qui (أنا), fait quoi (رايح), où (الكنيسة), quand (النهارده). On peut aussi mettre le « quand » en premier.", "tip": "Qui, fait quoi, où, quand.", "extraExample": {"text": "أنا رايح الجامعة النهارده", "translation": "Je vais à l''université aujourd''hui"}, "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e20', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.delwaqti']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Papa veut du thé maintenant. »', array['بابا عايز شاي دلوقتي','دلوقتي بابا عايز شاي']::text[], 'Qui (بابا), fait quoi (عايز شاي), quand (دلوقتي). Le « quand » peut aussi ouvrir la phrase.', 3, '{"id": "ar.l31.e20", "type": "reorder", "unitIds": ["ar.g31.sentence_flow", "ar.v.delwaqti"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Papa veut du thé maintenant. »", "promptLanguage": "fr", "tokens": ["دلوقتي", "شاي", "بابا", "عايز"], "answer": "بابا عايز شاي دلوقتي", "acceptedAnswers": ["بابا عايز شاي دلوقتي", "دلوقتي بابا عايز شاي"], "explanation": "Qui (بابا), fait quoi (عايز شاي), quand (دلوقتي). Le « quand » peut aussi ouvrir la phrase.", "tip": "Le « quand » va à la fin ou au début.", "extraExample": {"text": "ماما عايزة شاي دلوقتي", "translation": "Maman veut du thé maintenant"}, "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e21', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.yalla','ar.v.ya_nida']::text[], 'translation', 'lesson', 'يلا يا مينا', array['Allez, Mina !','allez mina','allons-y mina','on y va mina','allez, mina']::text[], 'يلا (allez) + يا مينا (on appelle Mina) : on l''encourage à se lancer ou à venir.', 2, '{"id": "ar.l31.e21", "type": "translation", "unitIds": ["ar.g31.sentence_flow", "ar.v.yalla", "ar.v.ya_nida"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "يلا يا مينا", "promptLanguage": "ar", "answer": "Allez, Mina !", "acceptedAnswers": ["Allez, Mina !", "allez mina", "allons-y mina", "on y va mina", "allez, mina"], "explanation": "يلا (allez) + يا مينا (on appelle Mina) : on l''encourage à se lancer ou à venir.", "tip": "يا + prénom : on appelle quelqu''un.", "extraExample": {"text": "يلا يا بابا", "translation": "Allez, papa !"}, "pool": "lesson", "lessonId": "ar.l31", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e22', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.keda','ar.v.kwayyis']::text[], 'translation', 'lesson', 'كده كويس', array['Comme ça, c''est bien ?','comme ça, c''est bien','comme ça c''est bien','c''est bien comme ça','c''est bien comme ça ?','comme ça c''est bon']::text[], 'كده (comme ça) + كويس (bien) : on demande si c''est bon ainsi.', 3, '{"id": "ar.l31.e22", "type": "translation", "unitIds": ["ar.g31.sentence_flow", "ar.v.keda", "ar.v.kwayyis"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "كده كويس", "promptLanguage": "ar", "answer": "Comme ça, c''est bien ?", "acceptedAnswers": ["Comme ça, c''est bien ?", "comme ça, c''est bien", "comme ça c''est bien", "c''est bien comme ça", "c''est bien comme ça ?", "comme ça c''est bon"], "explanation": "كده (comme ça) + كويس (bien) : on demande si c''est bon ainsi.", "tip": "Deux petits mots qui reviennent partout.", "extraExample": {"text": "كده تمام؟", "translation": "Comme ça, c''est parfait ?"}, "pool": "lesson", "lessonId": "ar.l31", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e23', 'ar', 'ar.l31', 'ar.v.min', array['ar.v.min','ar.g31.sentence_flow']::text[], 'free_answer', 'lesson', 'Que veut dire مين ?', array['qui','qui ?']::text[], 'مين veut dire « qui ». C''est un des cinq mots de question de la leçon 30.', 2, '{"id": "ar.l31.e23", "type": "free_answer", "unitIds": ["ar.v.min", "ar.g31.sentence_flow"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire مين ?", "promptLanguage": "fr", "answer": "qui", "acceptedAnswers": ["qui", "qui ?"], "explanation": "مين veut dire « qui ». C''est un des cinq mots de question de la leçon 30.", "tip": "Ne le confonds pas avec مش (ne… pas).", "extraExample": {"text": "مين ده؟", "translation": "C''est qui ?"}, "pool": "lesson", "lessonId": "ar.l31", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e24', 'ar', 'ar.l31', 'ar.g31.sentence_flow', array['ar.g31.sentence_flow','ar.v.mashi']::text[], 'free_answer', 'lesson', 'Que veut dire ماشي ?', array['d''accord','ok','okay','ça marche','dac']::text[], 'ماشي veut dire « d''accord » : on le dit pour accepter une proposition.', 2, '{"id": "ar.l31.e24", "type": "free_answer", "unitIds": ["ar.g31.sentence_flow", "ar.v.mashi"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire ماشي ?", "promptLanguage": "fr", "answer": "d''accord", "acceptedAnswers": ["d''accord", "ok", "okay", "ça marche", "dac"], "explanation": "ماشي veut dire « d''accord » : on le dit pour accepter une proposition.", "tip": "Tu le dis toi-même vingt fois par jour.", "extraExample": {"text": "ماشي، هاجي.", "translation": "D''accord, je viens."}, "pool": "lesson", "lessonId": "ar.l31", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e01', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.makhrag']::text[], 'mcq', 'lesson', 'مخرج', array['sortie']::text[], 'مخر | ج : deux blocs, le ر ferme le premier. C''est le panneau « sortie ».', 1, '{"id": "ar.l32.e01", "type": "mcq", "unitIds": ["ar.g32.reading_review", "ar.v.makhrag"], "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "مخرج", "promptLanguage": "ar", "options": ["entrée", "sortie", "interdit", "rue"], "answer": "sortie", "acceptedAnswers": ["sortie"], "explanation": "مخر | ج : deux blocs, le ر ferme le premier. C''est le panneau « sortie ».", "tip": "Pense à la porte verte au-dessus de la sortie.", "extraExample": {"text": "مخرج الطوارئ.", "translation": "La sortie de secours."}, "errorPatterns": [{"equals": "entrée", "category": "word_confusion", "feedback": "« entrée » ne correspond pas : relis مخرج bloc par bloc. Ici, le sens est « sortie »."}, {"equals": "interdit", "category": "word_confusion", "feedback": "« interdit » ne correspond pas : relis مخرج bloc par bloc. Ici, le sens est « sortie »."}, {"equals": "rue", "category": "word_confusion", "feedback": "« rue » ne correspond pas : relis مخرج bloc par bloc. Ici, le sens est « sortie »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e02', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.mamnu']::text[], 'mcq', 'lesson', 'ممنوع', array['interdit']::text[], 'ممنو | ع : deux blocs, le و ferme le premier. Deux م au début : c''est le panneau « interdit ».', 1, '{"id": "ar.l32.e02", "type": "mcq", "unitIds": ["ar.g32.reading_review", "ar.v.mamnu"], "difficulty": 1, "instruction": "Lis le mot et choisis son sens.", "prompt": "ممنوع", "promptLanguage": "ar", "options": ["sortie", "pharmacie", "station", "interdit"], "answer": "interdit", "acceptedAnswers": ["interdit"], "explanation": "ممنو | ع : deux blocs, le و ferme le premier. Deux م au début : c''est le panneau « interdit ».", "tip": "Deux م qui se répondent : c''est le panneau qui t''arrête.", "extraExample": {"text": "ممنوع الدخول.", "translation": "Entrée interdite."}, "errorPatterns": [{"equals": "sortie", "category": "word_confusion", "feedback": "« sortie » ne correspond pas : relis ممنوع bloc par bloc. Ici, le sens est « interdit »."}, {"equals": "pharmacie", "category": "word_confusion", "feedback": "« pharmacie » ne correspond pas : relis ممنوع bloc par bloc. Ici, le sens est « interdit »."}, {"equals": "station", "category": "word_confusion", "feedback": "« station » ne correspond pas : relis ممنوع bloc par bloc. Ici, le sens est « interdit »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e03', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.saydaliya']::text[], 'mcq', 'lesson', 'صيدلية', array['pharmacie']::text[], 'صيد | لية : deux blocs, le د ferme le premier. C''est la « pharmacie ».', 2, '{"id": "ar.l32.e03", "type": "mcq", "unitIds": ["ar.g32.reading_review", "ar.v.saydaliya"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "صيدلية", "promptLanguage": "ar", "options": ["hôpital", "pharmacie", "restaurant", "école"], "answer": "pharmacie", "acceptedAnswers": ["pharmacie"], "explanation": "صيد | لية : deux blocs, le د ferme le premier. C''est la « pharmacie ».", "tip": "Une croix verte et le mot صيدلية.", "extraExample": {"text": "الصيدلية فاتحة.", "translation": "La pharmacie est ouverte."}, "errorPatterns": [{"equals": "hôpital", "category": "word_confusion", "feedback": "« hôpital » ne correspond pas : relis صيدلية bloc par bloc. Ici, le sens est « pharmacie »."}, {"equals": "restaurant", "category": "word_confusion", "feedback": "« restaurant » ne correspond pas : relis صيدلية bloc par bloc. Ici, le sens est « pharmacie »."}, {"equals": "école", "category": "word_confusion", "feedback": "« école » ne correspond pas : relis صيدلية bloc par bloc. Ici, le sens est « pharmacie »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e04', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.mahatta','ar.v.metro','ar.v.law_samaht','ar.v.fin']::text[], 'mcq', 'lesson', 'لو سمحت، فين محطة المترو؟', array['Excuse-moi, où est la station de métro ?']::text[], 'لو سمحت (excuse-moi) + فين (où) + محطة المترو (la station de métro) : une demande de chemin complète.', 2, '{"id": "ar.l32.e04", "type": "mcq", "unitIds": ["ar.g32.reading_review", "ar.v.mahatta", "ar.v.metro", "ar.v.law_samaht", "ar.v.fin"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "لو سمحت، فين محطة المترو؟", "promptLanguage": "ar", "options": ["Excuse-moi, où est l''église ?", "Merci, la station de métro est ici.", "Où est le métro, Mina ?", "Excuse-moi, où est la station de métro ?"], "answer": "Excuse-moi, où est la station de métro ?", "acceptedAnswers": ["Excuse-moi, où est la station de métro ?"], "explanation": "لو سمحت (excuse-moi) + فين (où) + محطة المترو (la station de métro) : une demande de chemin complète.", "tip": "Cherche فين : c''est le mot de question.", "extraExample": {"text": "لو سمحت، فين الصيدلية؟", "translation": "Excuse-moi, où est la pharmacie ?"}, "errorPatterns": [{"equals": "Excuse-moi, où est l''église ?", "category": "word_confusion", "feedback": "« Excuse-moi, où est l''église ? » ne correspond pas : relis لو سمحت، فين محطة المترو؟ bloc par bloc. Ici, le sens est « Excuse-moi, où est la station de métro ? »."}, {"equals": "Merci, la station de métro est ici.", "category": "word_confusion", "feedback": "« Merci, la station de métro est ici. » ne correspond pas : relis لو سمحت، فين محطة المترو؟ bloc par bloc. Ici, le sens est « Excuse-moi, où est la station de métro ? »."}, {"equals": "Où est le métro, Mina ?", "category": "word_confusion", "feedback": "« Où est le métro, Mina ? » ne correspond pas : relis لو سمحت، فين محطة المترو؟ bloc par bloc. Ici, le sens est « Excuse-moi, où est la station de métro ? »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e05', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.el_ahad','ar.v.quddas']::text[], 'mcq', 'lesson', 'قداس الأحد', array['la liturgie du dimanche']::text[], 'قداس (liturgie, module 2) + الأحد (dimanche) : « la liturgie du dimanche ».', 2, '{"id": "ar.l32.e05", "type": "mcq", "unitIds": ["ar.g32.reading_review", "ar.v.el_ahad", "ar.v.quddas"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "قداس الأحد", "promptLanguage": "ar", "options": ["l''école du dimanche", "la liturgie du dimanche", "l''office de louange du dimanche", "le psaume du dimanche"], "answer": "la liturgie du dimanche", "acceptedAnswers": ["la liturgie du dimanche"], "explanation": "قداس (liturgie, module 2) + الأحد (dimanche) : « la liturgie du dimanche ».", "tip": "الأحد = ال + أحد.", "extraExample": {"text": "قداس النهارده.", "translation": "La liturgie, c''est aujourd''hui."}, "errorPatterns": [{"equals": "l''école du dimanche", "category": "word_confusion", "feedback": "« l''école du dimanche » ne correspond pas : relis قداس الأحد bloc par bloc. Ici, le sens est « la liturgie du dimanche »."}, {"equals": "l''office de louange du dimanche", "category": "word_confusion", "feedback": "« l''office de louange du dimanche » ne correspond pas : relis قداس الأحد bloc par bloc. Ici, le sens est « la liturgie du dimanche »."}, {"equals": "le psaume du dimanche", "category": "word_confusion", "feedback": "« le psaume du dimanche » ne correspond pas : relis قداس الأحد bloc par bloc. Ici, le sens est « la liturgie du dimanche »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = 