insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e06', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.madares_el_ahad']::text[], 'mcq', 'lesson', 'مدارس الأحد', array['l''école du dimanche']::text[], 'مدارس est le pluriel de مدرسة (école) ; avec الأحد : « l''école du dimanche ».', 2, '{"id": "ar.l32.e06", "type": "mcq", "unitIds": ["ar.g32.reading_review", "ar.v.madares_el_ahad"], "difficulty": 2, "instruction": "Lis la phrase et choisis son sens.", "prompt": "مدارس الأحد", "promptLanguage": "ar", "options": ["la liturgie du dimanche", "le livre des heures", "l''église du dimanche", "l''école du dimanche"], "answer": "l''école du dimanche", "acceptedAnswers": ["l''école du dimanche"], "explanation": "مدارس est le pluriel de مدرسة (école) ; avec الأحد : « l''école du dimanche ».", "tip": "Reconnais مدرسة dans مدارس.", "extraExample": {"text": "أنا رايح مدارس الأحد.", "translation": "Je vais à l''école du dimanche."}, "errorPatterns": [{"equals": "la liturgie du dimanche", "category": "word_confusion", "feedback": "« la liturgie du dimanche » ne correspond pas : relis مدارس الأحد bloc par bloc. Ici, le sens est « l''école du dimanche »."}, {"equals": "le livre des heures", "category": "word_confusion", "feedback": "« le livre des heures » ne correspond pas : relis مدارس الأحد bloc par bloc. Ici, le sens est « l''école du dimanche »."}, {"equals": "l''église du dimanche", "category": "word_confusion", "feedback": "« l''église du dimanche » ne correspond pas : relis مدارس الأحد bloc par bloc. Ici, le sens est « l''école du dimanche »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e07', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.share']::text[], 'mcq', 'lesson', 'شارع', array['rue']::text[], 'شا | ر | ع : trois blocs, car le ا et le ر ferment chacun un bloc. C''est la « rue ».', 2, '{"id": "ar.l32.e07", "type": "mcq", "unitIds": ["ar.g32.reading_review", "ar.v.share"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "شارع", "promptLanguage": "ar", "options": ["station", "rue", "métro", "sortie"], "answer": "rue", "acceptedAnswers": ["rue"], "explanation": "شا | ر | ع : trois blocs, car le ا et le ر ferment chacun un bloc. C''est la « rue ».", "tip": "ش | ا | ر | ع : cherche les coupures du ا et du ر.", "extraExample": {"text": "الشارع زحمة.", "translation": "La rue est bondée."}, "errorPatterns": [{"equals": "station", "category": "word_confusion", "feedback": "« station » ne correspond pas : relis شارع bloc par bloc. Ici, le sens est « rue »."}, {"equals": "métro", "category": "word_confusion", "feedback": "« métro » ne correspond pas : relis شارع bloc par bloc. Ici, le sens est « rue »."}, {"equals": "sortie", "category": "word_confusion", "feedback": "« sortie » ne correspond pas : relis شارع bloc par bloc. Ici, le sens est « rue »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e08', 'ar', 'ar.l32', 'ar.v.fi', array['ar.v.fi','ar.g32.reading_review']::text[], 'mcq', 'lesson', 'Lequel de ces petits mots veut dire « dans » ?', array['في']::text[], 'في (dans) est le plus court : deux lettres. فين (où) et مين (qui) ont un ن final ; على veut dire « sur ».', 3, '{"id": "ar.l32.e08", "type": "mcq", "unitIds": ["ar.v.fi", "ar.g32.reading_review"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces petits mots veut dire « dans » ?", "promptLanguage": "fr", "options": ["فين", "مين", "على", "في"], "answer": "في", "acceptedAnswers": ["في"], "explanation": "في (dans) est le plus court : deux lettres. فين (où) et مين (qui) ont un ن final ; على veut dire « sur ».", "tip": "Compte les lettres : في n''en a que deux.", "extraExample": {"text": "في الكنيسة", "translation": "dans l''église"}, "errorPatterns": [{"equals": "فين", "category": "word_confusion", "feedback": "فين veut dire « où » : il a un ن final de plus."}, {"equals": "مين", "category": "word_confusion", "feedback": "مين veut dire « qui »."}, {"equals": "على", "category": "word_confusion", "feedback": "على veut dire « sur »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e09', 'ar', 'ar.l32', 'ar.v.kitir', array['ar.v.kitir','ar.g32.reading_review']::text[], 'mcq', 'lesson', 'Dans « شكرا كتير », que veut dire كتير ?', array['beaucoup']::text[], 'كتير veut dire « beaucoup » : شكرا كتير = « merci beaucoup ». « Très » se dit أوي.', 3, '{"id": "ar.l32.e09", "type": "mcq", "unitIds": ["ar.v.kitir", "ar.g32.reading_review"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans « شكرا كتير », que veut dire كتير ?", "promptLanguage": "fr", "options": ["très", "beaucoup", "livres", "aussi"], "answer": "beaucoup", "acceptedAnswers": ["beaucoup"], "explanation": "كتير veut dire « beaucoup » : شكرا كتير = « merci beaucoup ». « Très » se dit أوي.", "tip": "Ne le confonds pas avec كتب (livres).", "extraExample": {"text": "عندي كتب كتير.", "translation": "J''ai beaucoup de livres."}, "errorPatterns": [{"equals": "très", "category": "word_confusion", "feedback": "« Très » se dit أوي ; كتير veut dire « beaucoup »."}, {"equals": "livres", "category": "word_confusion", "feedback": "« Livres » se dit كتب, avec un ب à la fin."}, {"equals": "aussi", "category": "word_confusion", "feedback": "« Aussi » se dit كمان."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e10', 'ar', 'ar.l32', 'ar.v.delwaqti', array['ar.v.delwaqti','ar.g32.reading_review']::text[], 'mcq', 'lesson', 'Quel mot veut dire « maintenant » ?', array['دلوقتي']::text[], 'دلوقتي veut dire « maintenant ». النهارده veut dire « aujourd''hui », كمان « aussi, encore » et كده « comme ça ».', 3, '{"id": "ar.l32.e10", "type": "mcq", "unitIds": ["ar.v.delwaqti", "ar.g32.reading_review"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « maintenant » ?", "promptLanguage": "fr", "options": ["النهارده", "كمان", "كده", "دلوقتي"], "answer": "دلوقتي", "acceptedAnswers": ["دلوقتي"], "explanation": "دلوقتي veut dire « maintenant ». النهارده veut dire « aujourd''hui », كمان « aussi, encore » et كده « comme ça ».", "tip": "Le « quand » est souvent à la fin de la phrase.", "extraExample": {"text": "بابا عايز شاي دلوقتي.", "translation": "Papa veut du thé maintenant."}, "errorPatterns": [{"equals": "النهارده", "category": "word_confusion", "feedback": "« النهارده » a un autre sens que « maintenant »."}, {"equals": "كمان", "category": "word_confusion", "feedback": "« كمان » a un autre sens que « maintenant »."}, {"equals": "كده", "category": "word_confusion", "feedback": "« كده » a un autre sens que « maintenant »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e11', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.saydaliya','ar.v.makhrag','ar.v.mamnu','ar.v.metro']::text[], 'match', 'lesson', 'Relie chaque panneau à son sens.', '{}'::text[], 'Quatre mots de la rue : صيدلية (pharmacie), مخرج (sortie), ممنوع (interdit) et مترو (métro).', 1, '{"id": "ar.l32.e11", "type": "match", "unitIds": ["ar.g32.reading_review", "ar.v.saydaliya", "ar.v.makhrag", "ar.v.mamnu", "ar.v.metro"], "difficulty": 1, "instruction": "Relie chaque élément à son sens.", "prompt": "Relie chaque panneau à son sens.", "promptLanguage": "fr", "pairs": [{"left": "صيدلية", "right": "pharmacie"}, {"left": "مخرج", "right": "sortie"}, {"left": "ممنوع", "right": "interdit"}, {"left": "مترو", "right": "métro"}], "acceptedAnswers": [], "answer": "صيدلية = pharmacie ; مخرج = sortie ; ممنوع = interdit ; مترو = métro", "explanation": "Quatre mots de la rue : صيدلية (pharmacie), مخرج (sortie), ممنوع (interdit) et مترو (métro).", "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
