insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e14', 'ar', 'ar.l32', 'ar.v.mobail', array['ar.v.mobail','ar.v.utobis','ar.v.walad','ar.v.samak','ar.g32.reading_review']::text[], 'match', 'lesson', 'Retour aux premières leçons : relie chaque mot à son sens.', '{}'::text[], 'موبايل (3 blocs), أتوبيس (3 blocs), ولد (le و est une consonne) et سمك (trois consonnes) : coupe, lis, recolle.', 3, '{"id": "ar.l32.e14", "type": "match", "unitIds": ["ar.v.mobail", "ar.v.utobis", "ar.v.walad", "ar.v.samak", "ar.g32.reading_review"], "difficulty": 3, "instruction": "Relie chaque élément à son sens.", "prompt": "Retour aux premières leçons : relie chaque mot à son sens.", "promptLanguage": "fr", "pairs": [{"left": "موبايل", "right": "portable"}, {"left": "أتوبيس", "right": "bus"}, {"left": "ولد", "right": "garçon"}, {"left": "سمك", "right": "poisson"}], "acceptedAnswers": [], "answer": "موبايل = portable ; أتوبيس = bus ; ولد = garçon ; سمك = poisson", "explanation": "موبايل (3 blocs), أتوبيس (3 blocs), ولد (le و est une consonne) et سمك (trois consonnes) : coupe, lis, recolle.", "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e15', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.el_ahad']::text[], 'fill_blank', 'lesson', 'قداس ___ (la liturgie du dimanche)', array['الأحد']::text[], 'Le dimanche se dit الأحد : قداس الأحد = « la liturgie du dimanche ». النهارده veut dire « aujourd''hui » et بكرة « demain ».', 2, '{"id": "ar.l32.e15", "type": "fill_blank", "unitIds": ["ar.g32.reading_review", "ar.v.el_ahad"], "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "قداس ___ (la liturgie du dimanche)", "promptLanguage": "ar", "options": ["الكنيسة", "الأحد", "النهارده", "بكرة"], "answer": "الأحد", "acceptedAnswers": ["الأحد"], "explanation": "Le dimanche se dit الأحد : قداس الأحد = « la liturgie du dimanche ». النهارده veut dire « aujourd''hui » et بكرة « demain ».", "tip": "الأحد = ال + أحد : trois blocs.", "extraExample": {"text": "الأحد الجاي.", "translation": "Dimanche prochain."}, "errorPatterns": [{"equals": "النهارده", "category": "vocabulary", "feedback": "النهارده veut dire « aujourd''hui », pas « dimanche »."}, {"equals": "بكرة", "category": "vocabulary", "feedback": "بكرة veut dire « demain »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e16', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.fin','ar.v.mahatta']::text[], 'fill_blank', 'lesson', 'لو سمحت، ___ محطة المترو؟ (Excuse-moi, où est la station de métro ?)', array['فين']::text[], 'Pour demander un lieu, on emploie فين (où). مين veut dire « qui », في « dans » et إيه « quoi ».', 3, '{"id": "ar.l32.e16", "type": "fill_blank", "unitIds": ["ar.g32.reading_review", "ar.v.fin", "ar.v.mahatta"], "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "لو سمحت، ___ محطة المترو؟ (Excuse-moi, où est la station de métro ?)", "promptLanguage": "ar", "options": ["مين", "في", "إيه", "فين"], "answer": "فين", "acceptedAnswers": ["فين"], "explanation": "Pour demander un lieu, on emploie فين (où). مين veut dire « qui », في « dans » et إيه « quoi ».", "tip": "فين : un ن final, comme dans « où ».", "extraExample": {"text": "لو سمحت، فين الباب؟", "translation": "Excuse-moi, où est la porte ?"}, "errorPatterns": [{"equals": "مين", "category": "vocabulary", "feedback": "مين veut dire « qui »."}, {"equals": "في", "category": "vocabulary", "feedback": "في (dans) n''a pas de ن final ; pour « où », il faut فين."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e17', 'ar', 'ar.l32', 'ar.v.ahlan', array['ar.v.ahlan','ar.g32.reading_review']::text[], 'fill_blank', 'lesson', '___ يا مينا، إزيك؟ (Salut Mina, comment vas-tu ?)', array['أهلا']::text[], 'Pour saluer quelqu''un, on commence par أهلا. شكرا veut dire « merci », ممنوع « interdit » et مخرج « sortie ».', 3, '{"id": "ar.l32.e17", "type": "fill_blank", "unitIds": ["ar.v.ahlan", "ar.g32.reading_review"], "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "___ يا مينا، إزيك؟ (Salut Mina, comment vas-tu ?)", "promptLanguage": "ar", "options": ["شكرا", "أهلا", "ممنوع", "مخرج"], "answer": "أهلا", "acceptedAnswers": ["أهلا"], "explanation": "Pour saluer quelqu''un, on commence par أهلا. شكرا veut dire « merci », ممنوع « interdit » et مخرج « sortie ».", "tip": "أهلا ouvre la conversation.", "extraExample": {"text": "أهلا يا مريم!", "translation": "Salut Mariam !"}, "errorPatterns": [{"equals": "شكرا", "category": "vocabulary", "feedback": "شكرا veut dire « merci » : on ne remercie pas avant de saluer."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e18', 'ar', 'ar.l32', 'ar.v.wi_liruhak_ayan', array['ar.v.wi_liruhak_ayan','ar.v.salam_likol','ar.g32.reading_review']::text[], 'fill_blank', 'lesson', 'السلام لكل — ___ (Et à ton esprit aussi.)', array['ولروحك أيضا']::text[], 'Au souhait du prêtre السلام لكل, le peuple répond ولروحك أيضا. Les autres phrases sont d''autres moments de la liturgie.', 3, '{"id": "ar.l32.e18", "type": "fill_blank", "unitIds": ["ar.v.wi_liruhak_ayan", "ar.v.salam_likol", "ar.g32.reading_review"], "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "السلام لكل — ___ (Et à ton esprit aussi.)", "promptLanguage": "ar", "options": ["المجد لك يا رب", "يا رب ارحم", "آمين", "ولروحك أيضا"], "answer": "ولروحك أيضا", "acceptedAnswers": ["ولروحك أيضا"], "explanation": "Au souhait du prêtre السلام لكل, le peuple répond ولروحك أيضا. Les autres phrases sont d''autres moments de la liturgie.", "tip": "Souhait de paix → réponse qui commence par و.", "extraExample": {"text": "ولروحك أيضا.", "translation": "Et à ton esprit aussi."}, "errorPatterns": [{"equals": "المجد لك يا رب", "category": "vocabulary", "feedback": "C''est une louange, pas la réponse au souhait de paix."}, {"equals": "يا رب ارحم", "category": "vocabulary", "feedback": "C''est une demande de pitié."}, {"equals": "آمين", "category": "vocabulary", "feedback": "آمين veut dire « amen » : il conclut une prière, il ne répond pas à ce souhait."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e19', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.mahatta','ar.v.metro']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Excuse-moi, où est la station de métro ? »', array['لو سمحت فين محطة المترو','فين محطة المترو لو سمحت']::text[], 'لو سمحت est un groupe de deux mots, puis la question فين محطة المترو. On peut aussi mettre لو سمحت à la fin.', 3, '{"id": "ar.l32.e19", "type": "reorder", "unitIds": ["ar.g32.reading_review", "ar.v.mahatta", "ar.v.metro"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Excuse-moi, où est la station de métro ? »", "promptLanguage": "fr", "tokens": ["المترو", "فين", "لو", "محطة", "سمحت"], "answer": "لو سمحت فين محطة المترو", "acceptedAnswers": ["لو سمحت فين محطة المترو", "فين محطة المترو لو سمحت"], "explanation": "لو سمحت est un groupe de deux mots, puis la question فين محطة المترو. On peut aussi mettre لو سمحت à la fin.", "tip": "لو سمحت ne se coupe pas.", "extraExample": {"text": "لو سمحت فين الصيدلية", "translation": "Excuse-moi, où est la pharmacie ?"}, "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e20', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.madares_el_ahad','ar.v.rayeh']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « Je vais à l''école du dimanche. »', array['أنا رايح مدارس الأحد']::text[], 'Qui (أنا), fait quoi (رايح), où (مدارس الأحد). Le groupe مدارس الأحد ne se coupe pas.', 3, '{"id": "ar.l32.e20", "type": "reorder", "unitIds": ["ar.g32.reading_review", "ar.v.madares_el_ahad", "ar.v.rayeh"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Remets dans l''ordre : « Je vais à l''école du dimanche. »", "promptLanguage": "fr", "tokens": ["الأحد", "أنا", "مدارس", "رايح"], "answer": "أنا رايح مدارس الأحد", "acceptedAnswers": ["أنا رايح مدارس الأحد"], "explanation": "Qui (أنا), fait quoi (رايح), où (مدارس الأحد). Le groupe مدارس الأحد ne se coupe pas.", "tip": "Qui, fait quoi, où.", "extraExample": {"text": "أنا رايح الكنيسة", "translation": "Je vais à l''église"}, "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e21', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.mahatta']::text[], 'translation', 'lesson', 'محطة', array['station','la station','gare','arrêt']::text[], 'محطة est un seul bloc de quatre lettres : « station » (de métro, de bus ou de train).', 2, '{"id": "ar.l32.e21", "type": "translation", "unitIds": ["ar.g32.reading_review", "ar.v.mahatta"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "محطة", "promptLanguage": "ar", "answer": "station", "acceptedAnswers": ["station", "la station", "gare", "arrêt"], "explanation": "محطة est un seul bloc de quatre lettres : « station » (de métro, de bus ou de train).", "tip": "Coupe en deux paquets : مح | طة.", "extraExample": {"text": "المحطة الجاية.", "translation": "La prochaine station."}, "pool": "lesson", "lessonId": "ar.l32", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e22', 'ar', 'ar.l32', 'ar.v.shokran', array['ar.v.shokran','ar.v.awi','ar.g32.reading_review']::text[], 'translation', 'lesson', 'شكرا أوي', array['Merci beaucoup.','merci beaucoup','merci bien','merci énormément']::text[], 'شكرا (merci) + أوي (très) : la façon courante de remercier chaleureusement.', 2, '{"id": "ar.l32.e22", "type": "translation", "unitIds": ["ar.v.shokran", "ar.v.awi", "ar.g32.reading_review"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "شكرا أوي", "promptLanguage": "ar", "answer": "Merci beaucoup.", "acceptedAnswers": ["Merci beaucoup.", "merci beaucoup", "merci bien", "merci énormément"], "explanation": "شكرا (merci) + أوي (très) : la façon courante de remercier chaleureusement.", "tip": "أوي renforce le mot qui le précède.", "extraExample": {"text": "شكرا كتير.", "translation": "Merci beaucoup."}, "pool": "lesson", "lessonId": "ar.l32", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e23', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.el_ahad']::text[], 'free_answer', 'lesson', 'Que veut dire الأحد ?', array['dimanche','le dimanche']::text[], 'الأحد veut dire « dimanche » : ال + أحد. C''est le jour de la liturgie.', 2, '{"id": "ar.l32.e23", "type": "free_answer", "unitIds": ["ar.g32.reading_review", "ar.v.el_ahad"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire الأحد ?", "promptLanguage": "fr", "answer": "dimanche", "acceptedAnswers": ["dimanche", "le dimanche"], "explanation": "الأحد veut dire « dimanche » : ال + أحد. C''est le jour de la liturgie.", "tip": "ال + أحد : le premier jour.", "extraExample": {"text": "القداس يوم الأحد.", "translation": "La liturgie est le dimanche."}, "pool": "lesson", "lessonId": "ar.l32", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e24', 'ar', 'ar.l32', 'ar.g32.reading_review', array['ar.g32.reading_review','ar.v.metro']::text[], 'free_answer', 'lesson', 'Que veut dire مترو ?', array['métro','le métro','metro']::text[], 'مترو est le mot « métro » écrit comme on le dit : م + ت + رو.', 2, '{"id": "ar.l32.e24", "type": "free_answer", "unitIds": ["ar.g32.reading_review", "ar.v.metro"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire مترو ?", "promptLanguage": "fr", "answer": "métro", "acceptedAnswers": ["métro", "le métro", "metro"], "explanation": "مترو est le mot « métro » écrit comme on le dit : م + ت + رو.", "tip": "Il vient du français : dis-le à voix haute.", "extraExample": {"text": "المترو سريع.", "translation": "Le métro est rapide."}, "pool": "lesson", "lessonId": "ar.l32", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e01', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.mesa_el_kheir']::text[], 'mcq', 'lesson', 'Quelle salutation veut dire « bonsoir » ?', array['مساء الخير']::text[], 'مساء veut dire « soir » : مساء الخير = bonsoir (carte « Le soir »).', 1, '{"id": "ar.l33.e01", "unitIds": ["ar.g33.salutations_politesse", "ar.v.mesa_el_kheir"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne salutation.", "prompt": "Quelle salutation veut dire « bonsoir » ?", "promptLanguage": "fr", "answer": "مساء الخير", "acceptedAnswers": ["مساء الخير"], "explanation": "مساء veut dire « soir » : مساء الخير = bonsoir (carte « Le soir »).", "tip": "مساء commence par م et finit par la hamza ء.", "extraExample": {"text": "مساء الخير يا أبونا", "translation": "Bonsoir, notre père"}, "options": ["معلش", "صباح النور", "صباح الخير", "مساء الخير"], "errorPatterns": [{"equals": "صباح الخير", "category": "word_confusion", "feedback": "صباح est le matin ; le soir on dit مساء."}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e02', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.sabah_el_nur']::text[], 'mcq', 'lesson', 'Quelqu''un te dit صباح الخير. Que réponds-tu ?', array['صباح النور']::text[], 'On répond à صباح الخير par صباح النور, « matin de lumière » : le bien appelle la lumière.', 1, '{"id": "ar.l33.e02", "unitIds": ["ar.g33.salutations_politesse", "ar.v.sabah_el_nur"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelqu''un te dit صباح الخير. Que réponds-tu ?", "promptLanguage": "fr", "answer": "صباح النور", "acceptedAnswers": ["صباح النور"], "explanation": "On répond à صباح الخير par صباح النور, « matin de lumière » : le bien appelle la lumière.", "tip": "Même mot, mais الخير devient النور.", "extraExample": {"text": "صباح النور يا مينا", "translation": "Bonjour (réponse), Mina"}, "options": ["مع السلامة", "مساء النور", "العفو", "صباح النور"], "errorPatterns": [{"equals": "مساء النور", "category": "word_confusion", "feedback": "C''est la réponse du soir ; ici il s''agit du matin."}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e03', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.mesa_el_nur']::text[], 'mcq', 'lesson', 'Quelqu''un te dit مساء الخير. Que réponds-tu ?', array['مساء النور']::text[], 'À مساء الخير on répond مساء النور, « soir de lumière » (carte « Le soir »).', 2, '{"id": "ar.l33.e03", "unitIds": ["ar.g33.salutations_politesse", "ar.v.mesa_el_nur"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelqu''un te dit مساء الخير. Que réponds-tu ?", "promptLanguage": "fr", "answer": "مساء النور", "acceptedAnswers": ["مساء النور"], "explanation": "À مساء الخير on répond مساء النور, « soir de lumière » (carte « Le soir »).", "tip": "Matin ↔ matin, soir ↔ soir : on garde le même premier mot.", "extraExample": {"text": "مساء النور يا مريم", "translation": "Bonsoir (réponse), Mariam"}, "options": ["العفو", "صباح النور", "مساء النور", "مع السلامة"], "errorPatterns": [{"equals": "صباح النور", "category": "word_confusion", "feedback": "C''est la réponse du matin."}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e04', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.amel_eih']::text[], 'mcq', 'lesson', 'Tu demandes à une femme « comment ça va ? ». Que dis-tu ?', array['عاملة إيه']::text[], 'À une femme, on ajoute ة : عاملة إيه (carte « Une 2e façon de demander »).', 3, '{"id": "ar.l33.e04", "unitIds": ["ar.g33.salutations_politesse", "ar.v.amel_eih"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "prompt": "Tu demandes à une femme « comment ça va ? ». Que dis-tu ?", "promptLanguage": "fr", "answer": "عاملة إيه", "acceptedAnswers": ["عاملة إيه"], "explanation": "À une femme, on ajoute ة : عاملة إيه (carte « Une 2e façon de demander »).", "tip": "Féminin = ة à la fin.", "extraExample": {"text": "عاملة إيه يا ماما؟", "translation": "Comment ça va, maman ?"}, "options": ["مساء الخير", "عامل إيه", "شكرا", "عاملة إيه"], "errorPatterns": [{"equals": "عامل إيه", "category": "word_confusion", "feedback": "C''est la forme pour un homme ; à une femme on dit عاملة."}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e05', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.afw']::text[], 'mcq', 'lesson', 'Quelqu''un te dit شكرا. Que réponds-tu ?', array['العفو']::text[], 'À un merci on répond العفو, « de rien » (carte « Merci et de rien »).', 1, '{"id": "ar.l33.e05", "unitIds": ["ar.g33.salutations_politesse", "ar.v.afw"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelqu''un te dit شكرا. Que réponds-tu ?", "promptLanguage": "fr", "answer": "العفو", "acceptedAnswers": ["العفو"], "explanation": "À un merci on répond العفو, « de rien » (carte « Merci et de rien »).", "tip": "شكرا ← العفو.", "extraExample": {"text": "شكرا يا مينا — العفو", "translation": "Merci, Mina — De rien"}, "options": ["يلا", "ماشي", "معلش", "العفو"], "errorPatterns": [{"equals": "معلش", "category": "word_confusion", "feedback": "معلش sert à s''excuser, pas à répondre à un merci."}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e06', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.alf_shokran']::text[], 'mcq', 'lesson', 'Ton ami t''écrit : « ألف شكر ! ». Que veut-il dire ?', array['mille mercis']::text[], 'ألف شكر veut dire « mille mercis » : un merci chaleureux (carte « Merci et de rien »).', 2, '{"id": "ar.l33.e06", "unitIds": ["ar.g33.salutations_politesse", "ar.v.alf_shokran"], "type": "mcq", "difficulty": 2, "instruction": "Lis et choisis le sens.", "prompt": "Ton ami t''écrit : « ألف شكر ! ». Que veut-il dire ?", "promptLanguage": "fr", "answer": "mille mercis", "acceptedAnswers": ["mille mercis"], "explanation": "ألف شكر veut dire « mille mercis » : un merci chaleureux (carte « Merci et de rien »).", "tip": "ألف = mille ; شكر = merci.", "extraExample": {"text": "ألف شكر يا بابا", "translation": "Mille mercis, papa"}, "options": ["au revoir", "bonsoir", "s''il te plaît", "mille mercis"], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e07', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.an_eznak']::text[], 'mcq', 'lesson', 'Quelle expression veut dire « avec ta permission » (quand on passe ou qu''on part) ?', array['عن إذنك']::text[], 'عن إذنك veut dire « avec ta permission » : on le dit en passant ou en partant (carte « Demander poliment »).', 3, '{"id": "ar.l33.e07", "unitIds": ["ar.g33.salutations_politesse", "ar.v.an_eznak"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne formule.", "prompt": "Quelle expression veut dire « avec ta permission » (quand on passe ou qu''on part) ?", "promptLanguage": "fr", "answer": "عن إذنك", "acceptedAnswers": ["عن إذنك"], "explanation": "عن إذنك veut dire « avec ta permission » : on le dit en passant ou en partant (carte « Demander poliment »).", "tip": "إذنك = ta permission.", "extraExample": {"text": "عن إذنك يا أستاذ", "translation": "Avec votre permission, monsieur"}, "options": ["عن إذنك", "من فضلك", "معلش", "لو سمحت"], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e08', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.maa_salama']::text[], 'mcq', 'lesson', 'Tu quittes ton ami. Que lui dis-tu ?', array['مع السلامة']::text[], 'مع السلامة veut dire « au revoir », littéralement « avec la paix ».', 1, '{"id": "ar.l33.e08", "unitIds": ["ar.g33.salutations_politesse", "ar.v.maa_salama"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne formule.", "prompt": "Tu quittes ton ami. Que lui dis-tu ?", "promptLanguage": "fr", "answer": "مع السلامة", "acceptedAnswers": ["مع السلامة"], "explanation": "مع السلامة veut dire « au revoir », littéralement « avec la paix ».", "tip": "مع السلامة = au revoir.", "extraExample": {"text": "مع السلامة يا حبيبي", "translation": "Au revoir, mon chéri"}, "options": ["العفو", "صباح النور", "مع السلامة", "أهلا"], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e09', 'ar', 'ar.l33', 'ar.v.elhamdulillah', array['ar.v.elhamdulillah']::text[], 'mcq', 'lesson', 'Ton ami te demande إزيك ? Quelle est la réponse la plus courante ?', array['الحمد لله']::text[], 'الحمد لله veut dire « Dieu merci » : c''est la réponse habituelle à إزيك.', 1, '{"id": "ar.l33.e09", "unitIds": ["ar.v.elhamdulillah"], "type": "mcq", "difficulty": 1, "instruction": "Rappel du module précédent.", "prompt": "Ton ami te demande إزيك ? Quelle est la réponse la plus courante ?", "promptLanguage": "fr", "answer": "الحمد لله", "acceptedAnswers": ["الحمد لله"], "explanation": "الحمد لله veut dire « Dieu merci » : c''est la réponse habituelle à إزيك.", "tip": "إزيك ← الحمد لله.", "extraExample": {"text": "إزيك يا مينا — الحمد لله", "translation": "Comment vas-tu, Mina ? — Dieu merci"}, "options": ["الحمد لله", "صباح النور", "العفو", "مع السلامة"], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e10', 'ar', 'ar.l33', 'ar.v.sad', array['ar.v.sad']::text[], 'mcq', 'lesson', 'Le mot صباح s''ouvre par une lettre « lourde ». Laquelle ?', array['ص']::text[], 'ص est le s lourd (leçon des lettres lourdes) ; س est le s léger, ش le ch.', 2, '{"id": "ar.l33.e10", "unitIds": ["ar.v.sad"], "type": "mcq", "difficulty": 2, "instruction": "Rappel des lettres.", "prompt": "Le mot صباح s''ouvre par une lettre « lourde ». Laquelle ?", "promptLanguage": "fr", "answer": "ص", "acceptedAnswers": ["ص"], "explanation": "ص est le s lourd (leçon des lettres lourdes) ; س est le s léger, ش le ch.", "tip": "ص a une boucle fermée ; س a seulement des dents.", "extraExample": {"text": "صباح الخير", "translation": "Bonjour"}, "options": ["س", "ض", "ص", "ش"], "errorPatterns": [{"equals": "س", "category": "word_confusion", "feedback": "س est le s léger ; ici c''est la boucle de ص."}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e11', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.mesa_el_kheir','ar.v.amel_eih','ar.v.afw','ar.v.men_fadlak','ar.v.maa_salama']::text[], 'match', 'lesson', 'Associe chaque expression à son sens.', '{}'::text[], 'Ce sont les expressions de cette leçon : le soir, les nouvelles, le merci, la demande et l''adieu.', 1, '{"id": "ar.l33.e11", "unitIds": ["ar.g33.salutations_politesse", "ar.v.mesa_el_kheir", "ar.v.amel_eih", "ar.v.afw", "ar.v.men_fadlak", "ar.v.maa_salama"], "type": "match", "difficulty": 1, "instruction": "Associe chaque expression à son sens.", "prompt": "Associe chaque expression à son sens.", "promptLanguage": "fr", "answer": "مساء الخير = bonsoir ; عامل إيه = comment ça va ? ; العفو = de rien ; من فضلك = s''il te plaît ; مع السلامة = au revoir", "acceptedAnswers": [], "explanation": "Ce sont les expressions de cette leçon : le soir, les nouvelles, le merci, la demande et l''adieu.", "pairs": [{"left": "مساء الخير", "right": "bonsoir"}, {"left": "عامل إيه", "right": "comment ça va ?"}, {"left": "العفو", "right": "de rien"}, {"left": "من فضلك", "right": "s''il te plaît"}, {"left": "مع السلامة", "right": "au revoir"}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e12', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.sabah_el_nur','ar.v.mesa_el_nur']::text[], 'match', 'lesson', 'Associe chaque phrase à sa réponse.', '{}'::text[], 'Une salutation appelle toujours sa réponse : le bien appelle la lumière, et le merci appelle « de rien ».', 2, '{"id": "ar.l33.e12", "unitIds": ["ar.g33.salutations_politesse", "ar.v.sabah_el_nur", "ar.v.mesa_el_nur"], "type": "match", "difficulty": 2, "instruction": "Associe chaque phrase à sa réponse.", "prompt": "Associe chaque phrase à sa réponse.", "promptLanguage": "fr", "answer": "صباح الخير = صباح النور ; مساء الخير = مساء النور ; شكرا = العفو ; إزيك = الحمد لله", "acceptedAnswers": [], "explanation": "Une salutation appelle toujours sa réponse : le bien appelle la lumière, et le merci appelle « de rien ».", "pairs": [{"left": "صباح الخير", "right": "صباح النور"}, {"left": "مساء الخير", "right": "مساء النور"}, {"left": "شكرا", "right": "العفو"}, {"left": "إزيك", "right": "الحمد لله"}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e13', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.maalesh','ar.v.an_eznak','ar.v.alf_shokran','ar.v.law_samaht','ar.v.mashi']::text[], 'match', 'lesson', 'Associe ces expressions de politesse à leur sens.', '{}'::text[], 'Trois expressions nouvelles, et deux du module précédent (لو سمحت, ماشي).', 2, '{"id": "ar.l33.e13", "unitIds": ["ar.g33.salutations_politesse", "ar.v.maalesh", "ar.v.an_eznak", "ar.v.alf_shokran", "ar.v.law_samaht", "ar.v.mashi"], "type": "match", "difficulty": 2, "instruction": "Associe chaque expression à son sens.", "prompt": "Associe ces expressions de politesse à leur sens.", "promptLanguage": "fr", "answer": "معلش = pardon, ce n''est pas grave ; عن إذنك = avec ta permission ; ألف شكر = mille mercis ; لو سمحت = excuse-moi (pour interpeller) ; ماشي = d''accord, OK", "acceptedAnswers": [], "explanation": "Trois expressions nouvelles, et deux du module précédent (لو سمحت, ماشي).", "pairs": [{"left": "معلش", "right": "pardon, ce n''est pas grave"}, {"left": "عن إذنك", "right": "avec ta permission"}, {"left": "ألف شكر", "right": "mille mercis"}, {"left": "لو سمحت", "right": "excuse-moi (pour interpeller)"}, {"left": "ماشي", "right": "d''accord, OK"}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e14', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.mesa_el_kheir']::text[], 'fill_blank', 'lesson', 'مساء ___  (bonsoir)', array['الخير']::text[], '« Bonsoir » se dit مساء الخير : seul le premier mot change entre matin et soir.', 1, '{"id": "ar.l33.e14", "unitIds": ["ar.g33.salutations_politesse", "ar.v.mesa_el_kheir"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la salutation.", "prompt": "مساء ___  (bonsoir)", "promptLanguage": "ar", "answer": "الخير", "acceptedAnswers": ["الخير"], "explanation": "« Bonsoir » se dit مساء الخير : seul le premier mot change entre matin et soir.", "tip": "الخير = le bien.", "extraExample": {"text": "مساء الخير يا ماما", "translation": "Bonsoir, maman"}, "options": ["الخير", "العفو", "السلامة", "إذنك"], "pool": "lesson", "lessonId": "ar.l33", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
