insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e16', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.maa_salama']::text[], 'fill_blank', 'lesson', 'مع ___  (au revoir)', array['السلامة']::text[], 'On dit مع السلامة pour « au revoir » (carte « Se quitter »).', 2, '{"id": "ar.l33.e16", "unitIds": ["ar.g33.salutations_politesse", "ar.v.maa_salama"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la formule d''adieu.", "prompt": "مع ___  (au revoir)", "promptLanguage": "ar", "answer": "السلامة", "acceptedAnswers": ["السلامة"], "explanation": "On dit مع السلامة pour « au revoir » (carte « Se quitter »).", "tip": "Pense à « avec la paix ».", "extraExample": {"text": "مع السلامة يا مينا", "translation": "Au revoir, Mina"}, "options": ["النور", "السلامة", "الخير", "فضلك"], "pool": "lesson", "lessonId": "ar.l33", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e17', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.men_fadlak']::text[], 'fill_blank', 'lesson', 'من ___ ، عايز شاي  (s''il te plaît, je veux un thé)', array['فضلك']::text[], 'من فضلك veut dire « s''il te plaît » : on l''ajoute à la demande.', 2, '{"id": "ar.l33.e17", "unitIds": ["ar.g33.salutations_politesse", "ar.v.men_fadlak"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la demande polie.", "prompt": "من ___ ، عايز شاي  (s''il te plaît, je veux un thé)", "promptLanguage": "ar", "answer": "فضلك", "acceptedAnswers": ["فضلك"], "explanation": "من فضلك veut dire « s''il te plaît » : on l''ajoute à la demande.", "tip": "من + فضلك = de ta faveur.", "extraExample": {"text": "من فضلك، عايز عيش", "translation": "S''il te plaît, je veux du pain"}, "options": ["إذنك", "فضلك", "سمحت", "شكرا"], "errorPatterns": [{"equals": "سمحت", "category": "word_confusion", "feedback": "سمحت va avec لو (لو سمحت), pas avec من."}], "pool": "lesson", "lessonId": "ar.l33", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e18', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.alf_shokran']::text[], 'translation', 'lesson', 'ألف شكر يا أبونا', array['mille mercis notre père','mille mercis mon père','mille mercis père','mille mercis le père','mille mercis au prêtre','un grand merci notre père']::text[], 'ألف شكر = mille mercis, et يا أبونا = « notre père » en s''adressant au prêtre.', 2, '{"id": "ar.l33.e18", "unitIds": ["ar.g33.salutations_politesse", "ar.v.alf_shokran"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "ألف شكر يا أبونا", "promptLanguage": "ar", "answer": "mille mercis notre père", "acceptedAnswers": ["mille mercis notre père", "mille mercis mon père", "mille mercis père", "mille mercis le père", "mille mercis au prêtre", "un grand merci notre père"], "explanation": "ألف شكر = mille mercis, et يا أبونا = « notre père » en s''adressant au prêtre.", "tip": "يا + nom = on appelle quelqu''un.", "extraExample": {"text": "ألف شكر يا مريم", "translation": "Mille mercis, Mariam"}, "pool": "lesson", "lessonId": "ar.l33", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e19', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.maalesh']::text[], 'translation', 'lesson', 'معلش', array['pardon','désolé','ce n''est pas grave','pas grave','tant pis','excuse-moi','excuse moi','désolée']::text[], 'معلش couvre « pardon », « ce n''est pas grave » et « tant pis ».', 2, '{"id": "ar.l33.e19", "unitIds": ["ar.g33.salutations_politesse", "ar.v.maalesh"], "type": "translation", "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "معلش", "promptLanguage": "ar", "answer": "pardon", "acceptedAnswers": ["pardon", "désolé", "ce n''est pas grave", "pas grave", "tant pis", "excuse-moi", "excuse moi", "désolée"], "explanation": "معلش couvre « pardon », « ce n''est pas grave » et « tant pis ».", "tip": "Le contexte décide du sens.", "extraExample": {"text": "معلش يا ماما", "translation": "Pardon, maman"}, "pool": "lesson", "lessonId": "ar.l33", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e20', 'ar', 'ar.l33', 'ar.v.ayiz', array['ar.v.ayiz','ar.v.shay','ar.v.sukkar']::text[], 'translation', 'lesson', 'عايز شاي وسكر', array['je veux du thé et du sucre','je veux un thé et du sucre','je veux le thé et le sucre','veux du thé et du sucre','je voudrais du thé et du sucre','je voudrais un thé avec du sucre','je veux du thé avec du sucre','je veux un thé avec du sucre']::text[], 'عايز = je veux, شاي = thé, و collé = et, سكر = sucre : des mots vus dans les lettres dans les mots.', 3, '{"id": "ar.l33.e20", "unitIds": ["ar.v.ayiz", "ar.v.shay", "ar.v.sukkar"], "type": "translation", "difficulty": 3, "instruction": "Rappel : écris le sens en français.", "prompt": "عايز شاي وسكر", "promptLanguage": "ar", "answer": "je veux du thé et du sucre", "acceptedAnswers": ["je veux du thé et du sucre", "je veux un thé et du sucre", "je veux le thé et le sucre", "veux du thé et du sucre", "je voudrais du thé et du sucre", "je voudrais un thé avec du sucre", "je veux du thé avec du sucre", "je veux un thé avec du sucre"], "explanation": "عايز = je veux, شاي = thé, و collé = et, سكر = sucre : des mots vus dans les lettres dans les mots.", "tip": "Sans voyelles, عايز peut être je/tu/il : le contexte tranche.", "extraExample": {"text": "عايز عيش وشاي", "translation": "Je veux du pain et du thé"}, "pool": "lesson", "lessonId": "ar.l33", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e21', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.an_eznak']::text[], 'free_answer', 'lesson', 'Que veut dire عن إذنك quand quelqu''un se lève pour partir ?', array['avec ta permission','avec votre permission','avec ta permission je pars','excuse-moi','excusez-moi','avec ton autorisation','permets-moi']::text[], 'عن إذنك veut dire « avec ta permission » : une formule polie pour passer ou partir.', 3, '{"id": "ar.l33.e21", "unitIds": ["ar.g33.salutations_politesse", "ar.v.an_eznak"], "type": "free_answer", "difficulty": 3, "instruction": "Réponds en français.", "prompt": "Que veut dire عن إذنك quand quelqu''un se lève pour partir ?", "promptLanguage": "fr", "answer": "avec ta permission", "acceptedAnswers": ["avec ta permission", "avec votre permission", "avec ta permission je pars", "excuse-moi", "excusez-moi", "avec ton autorisation", "permets-moi"], "explanation": "عن إذنك veut dire « avec ta permission » : une formule polie pour passer ou partir.", "tip": "إذن = permission.", "extraExample": {"text": "عن إذنك يا أستاذ", "translation": "Avec votre permission, monsieur"}, "pool": "lesson", "lessonId": "ar.l33", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e22', 'ar', 'ar.l33', 'ar.v.habibi', array['ar.v.habibi']::text[], 'free_answer', 'lesson', 'Ta mère te dit : « معلش يا حبيبي ». Que veut dire حبيبي ?', array['mon chéri','mon cheri','chéri','cheri','mon cher','mon amour','mon chou','ma chérie']::text[], 'حبيبي est un mot affectueux : « mon chéri » (mot vu dans la leçon sur ج ح خ).', 1, '{"id": "ar.l33.e22", "unitIds": ["ar.v.habibi"], "type": "free_answer", "difficulty": 1, "instruction": "Rappel : réponds en français.", "prompt": "Ta mère te dit : « معلش يا حبيبي ». Que veut dire حبيبي ?", "promptLanguage": "fr", "answer": "mon chéri", "acceptedAnswers": ["mon chéri", "mon cheri", "chéri", "cheri", "mon cher", "mon amour", "mon chou", "ma chérie"], "explanation": "حبيبي est un mot affectueux : « mon chéri » (mot vu dans la leçon sur ج ح خ).", "tip": "Se dit à un enfant, un ami, un proche.", "extraExample": {"text": "إزيك يا حبيبي", "translation": "Comment vas-tu, mon chéri ?"}, "pool": "lesson", "lessonId": "ar.l33", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l33.e23', 'ar', 'ar.l33', 'ar.g33.salutations_politesse', array['ar.g33.salutations_politesse','ar.v.maa_salama']::text[], 'reorder', 'lesson', 'Forme la phrase : « Au revoir, notre père ».', array['مع السلامة يا أبونا']::text[], 'On commence par la formule, puis يا et la personne qu''on appelle.', 2, '{"id": "ar.l33.e23", "unitIds": ["ar.g33.salutations_politesse", "ar.v.maa_salama"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Forme la phrase : « Au revoir, notre père ».", "promptLanguage": "fr", "answer": "مع السلامة يا أبونا", "acceptedAnswers": ["مع السلامة يا أبونا"], "explanation": "On commence par la formule, puis يا et la personne qu''on appelle.", "tip": "Formule d''abord, يا + nom à la fin.", "extraExample": {"text": "مساء الخير يا أبونا", "translation": "Bonsoir, notre père"}, "tokens": ["السلامة", "أبونا", "مع", "يا"], "pool": "lesson", "lessonId": "ar.l33", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l34.e01', 'ar', 'ar.l34', 'ar.g34.la_famille', array['ar.g34.la_famille','ar.v.mama']::text[], 'mcq', 'lesson', 'Quel mot veut dire « maman » ?', array['ماما']::text[], 'ماما est le jumeau de بابا : seule la première lettre change (carte « Papa et maman »).', 1, '{"id": "ar.l34.e01", "unitIds": ["ar.g34.la_famille", "ar.v.mama"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « maman » ?", "promptLanguage": "fr", "answer": "ماما", "acceptedAnswers": ["ماما"], "explanation": "ماما est le jumeau de بابا : seule la première lettre change (carte « Papa et maman »).", "tip": "م comme dans ماما et مريم.", "extraExample": {"text": "ماما في البيت", "translation": "Maman est à la maison"}, "options": ["بابا", "تيتة", "جدو", "ماما"], "errorPatterns": [{"equals": "بابا", "category": "word_confusion", "feedback": "بابا est papa ; maman commence par م."}], "pool": "lesson", "lessonId": "ar.l34", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l34.e02', 'ar', 'ar.l34', 'ar.g34.la_famille', array['ar.g34.la_famille','ar.v.ibni']::text[], 'mcq', 'lesson', 'Que veut dire le ي collé à la fin de ابني ?', array['mon / ma']::text[], 'Un ي final veut dire « mon / ma » : ابن + ي = ابني, « mon fils » (carte « Le secret »).', 1, '{"id": "ar.l34.e02", "unitIds": ["ar.g34.la_famille", "ar.v.ibni"], "type": "mcq", "difficulty": 1, "instruction": "Comprends la règle.", "prompt": "Que veut dire le ي collé à la fin de ابني ?", "promptLanguage": "fr", "answer": "mon / ma", "acceptedAnswers": ["mon / ma"], "explanation": "Un ي final veut dire « mon / ma » : ابن + ي = ابني, « mon fils » (carte « Le secret »).", "tip": "ـي = mon / ma ; ـنا = notre.", "extraExample": {"text": "بنتي مريم", "translation": "Ma fille Mariam"}, "options": ["ton", "mon / ma", "notre", "ils"], "errorPatterns": [{"equals": "notre", "category": "word_confusion", "feedback": "« notre » c''est ـنا, comme dans أبونا."}], "pool": "lesson", "lessonId": "ar.l34", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l34.e03', 'ar', 'ar.l34', 'ar.g34.la_famille', array['ar.g34.la_famille','ar.v.ibni']::text[], 'mcq', 'lesson', 'Lis : ابني. Que veut dire ce mot ?', array['mon fils']::text[], 'ابني = ابن (fils) + ي (mon) : mon fils.', 1, '{"id": "ar.l34.e03", "unitIds": ["ar.g34.la_famille", "ar.v.ibni"], "type": "mcq", "difficulty": 1, "instruction": "Lis et choisis le sens.", "prompt": "Lis : ابني. Que veut dire ce mot ?", "promptLanguage": "fr", "answer": "mon fils", "acceptedAnswers": ["mon fils"], "explanation": "ابني = ابن (fils) + ي (mon) : mon fils.", "tip": "ابن = fils, بنت = fille.", "extraExample": {"text": "ابني مينا", "translation": "Mon fils Mina"}, "options": ["ma fille", "mon frère", "mon fils", "mon mari"], "errorPatterns": [{"equals": "ma fille", "category": "word_confusion", "feedback": "Ma fille se dit بنتي."}], "pool": "lesson", "lessonId": "ar.l34", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l34.e04', 'ar', 'ar.l34', 'ar.g34.la_famille', array['ar.g34.la_famille','ar.v.akhuya']::text[], 'mcq', 'lesson', 'Lis : أخويا. Que veut dire ce mot ?', array['mon frère']::text[], 'أخويا veut dire « mon frère » : le ـي de « mon » s''écrit ـيا (carte « Frère et sœur »).', 2, '{"id": "ar.l34.e04", "unitIds": ["ar.g34.la_famille", "ar.v.akhuya"], "type": "mcq", "difficulty": 2, "instruction": "Lis et choisis le sens.", "prompt": "Lis : أخويا. Que veut dire ce mot ?", "promptLanguage": "fr", "answer": "mon frère", "acceptedAnswers": ["mon frère"], "explanation": "أخويا veut dire « mon frère » : le ـي de « mon » s''écrit ـيا (carte « Frère et sœur »).", "tip": "أخويا = أخو + يا.", "extraExample": {"text": "أخويا مينا", "translation": "Mon frère Mina"}, "options": ["mon frère", "mon fils", "mon mari", "mon oncle"], "pool": "lesson", "lessonId": "ar.l34", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l34.e05', 'ar', 'ar.l34', 'ar.g34.la_famille', array['ar.g34.la_famille','ar.v.okhti']::text[], 'mcq', 'lesson', 'Quel mot veut dire « ma sœur » ?', array['أختي']::text[], 'أختي = أخت (sœur) + ي (ma).', 1, '{"id": "ar.l34.e05", "unitIds": ["ar.g34.la_famille", "ar.v.okhti"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « ma sœur » ?", "promptLanguage": "fr", "answer": "أختي", "acceptedAnswers": ["أختي"], "explanation": "أختي = أخت (sœur) + ي (ma).", "tip": "أختي contient la lettre ت.", "extraExample": {"text": "أختي مريم", "translation": "Ma sœur Mariam"}, "options": ["بنتي", "مراتي", "أخويا", "أختي"], "errorPatterns": [{"equals": "أخويا", "category": "word_confusion", "feedback": "أخويا est le frère."}], "pool": "lesson", "lessonId": "ar.l34", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l34.e06', 'ar', 'ar.l34', 'ar.g34.la_famille', array['ar.g34.la_famille','ar.v.khaltu']::text[], 'mcq', 'lesson', 'Un enfant appelle la sœur de sa mère. Quel mot dit-il ?', array['خالتو']::text[], 'خالتو est la sœur de la mère ; عمو est le frère du père (carte « Grands-parents, oncle, tante »).', 2, '{"id": "ar.l34.e06", "unitIds": ["ar.g34.la_famille", "ar.v.khaltu"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Un enfant appelle la sœur de sa mère. Quel mot dit-il ?", "promptLanguage": "fr", "answer": "خالتو", "acceptedAnswers": ["خالتو"], "explanation": "خالتو est la sœur de la mère ; عمو est le frère du père (carte « Grands-parents, oncle, tante »).", "tip": "خال... = côté maternel.", "extraExample": {"text": "خالتو مريم", "translation": "Tante Mariam"}, "options": ["تيتة", "عمو", "ماما", "خالتو"], "errorPatterns": [{"equals": "عمو", "category": "word_confusion", "feedback": "عمو est l''oncle, pas la tante."}], "pool": "lesson", "lessonId": "ar.l34", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l34.e07', 'ar', 'ar.l34', 'ar.g34.la_famille', array['ar.g34.la_famille','ar.v.ammu']::text[], 'mcq', 'lesson', 'Quel mot veut dire « oncle » ?', array['عمو']::text[], 'عمو est l''oncle, le frère du père ; les enfants le disent aussi à un adulte qu''ils aiment bien.', 2, '{"id": "ar.l34.e07", "unitIds": ["ar.g34.la_famille", "ar.v.ammu"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « oncle » ?", "promptLanguage": "fr", "answer": "عمو", "acceptedAnswers": ["عمو"], "explanation": "عمو est l''oncle, le frère du père ; les enfants le disent aussi à un adulte qu''ils aiment bien.", "tip": "عمو = oncle.", "extraExample": {"text": "صباح الخير يا عمو", "translation": "Bonjour, oncle"}, "options": ["خالتو", "أخويا", "جدو", "عمو"], "pool": "lesson", "lessonId": "ar.l34", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
