insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l34.e10', 'ar', 'ar.l34', 'ar.v.jiddu', array['ar.v.jiddu']::text[], 'mcq', 'lesson', 'Le père de ton père, que tu appelles جدو, c''est ton…', array['papy']::text[], 'جدو veut dire « papy » (vu avec la lettre ج) ; il va avec تيتة, « mamie ».', 1, '{"id": "ar.l34.e10", "unitIds": ["ar.v.jiddu"], "type": "mcq", "difficulty": 1, "instruction": "Rappel du vocabulaire.", "prompt": "Le père de ton père, que tu appelles جدو, c''est ton…", "promptLanguage": "fr", "answer": "papy", "acceptedAnswers": ["papy"], "explanation": "جدو veut dire « papy » (vu avec la lettre ج) ; il va avec تيتة, « mamie ».", "tip": "جدو + تيتة = les grands-parents.", "extraExample": {"text": "جدو في البيت", "translation": "Papy est à la maison"}, "options": ["mari", "oncle", "fils", "papy"], "pool": "lesson", "lessonId": "ar.l34", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
