insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l36.e02', 'ar', 'ar.l36', 'ar.g36.la_nourriture', array['ar.g36.la_nourriture','ar.v.koshary']::text[], 'mcq', 'lesson', 'Quel plat mélange riz, pâtes et lentilles avec une sauce tomate ?', array['كشري']::text[], 'كشري est le plat national : riz, pâtes, lentilles et sauce de طماطم.', 1, '{"id": "ar.l36.e02", "unitIds": ["ar.g36.la_nourriture", "ar.v.koshary"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon plat.", "prompt": "Quel plat mélange riz, pâtes et lentilles avec une sauce tomate ?", "promptLanguage": "fr", "answer": "كشري", "acceptedAnswers": ["كشري"], "explanation": "كشري est le plat national : riz, pâtes, lentilles et sauce de طماطم.", "tip": "كشري = tout dans la même assiette.", "extraExample": {"text": "عايز طبق كشري", "translation": "Je veux une assiette de riz, pâtes et lentilles"}, "options": ["كشري", "فراخ", "طعمية", "بيض"], "errorPatterns": [{"equals": "طعمية", "category": "word_confusion", "feedback": "طعمية est une croquette de fèves, pas un mélange de riz et de pâtes."}], "pool": "lesson", "lessonId": "ar.l36", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l36.e03', 'ar', 'ar.l36', 'ar.g36.la_nourriture', array['ar.g36.la_nourriture','ar.v.molokheya']::text[], 'mcq', 'lesson', 'Lis : ملوخية. Qu''est-ce que c''est ?', array['une soupe verte']::text[], 'ملوخية est une soupe verte, qu''on mange avec رز et فراخ (carte « ملوخية et فراخ »).', 2, '{"id": "ar.l36.e03", "unitIds": ["ar.g36.la_nourriture", "ar.v.molokheya"], "type": "mcq", "difficulty": 2, "instruction": "Lis et choisis le sens.", "prompt": "Lis : ملوخية. Qu''est-ce que c''est ?", "promptLanguage": "fr", "answer": "une soupe verte", "acceptedAnswers": ["une soupe verte"], "explanation": "ملوخية est une soupe verte, qu''on mange avec رز et فراخ (carte « ملوخية et فراخ »).", "tip": "ملوخية : le plat vert du déjeuner.", "extraExample": {"text": "ملوخية بالفراخ", "translation": "Soupe verte au poulet"}, "options": ["une soupe verte", "un dessert", "un fromage", "un jus"], "pool": "lesson", "lessonId": "ar.l36", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l36.e04', 'ar', 'ar.l36', 'ar.g36.la_nourriture', array['ar.g36.la_nourriture','ar.v.ferakh']::text[], 'mcq', 'lesson', 'Quel mot veut dire « poulet » ?', array['فراخ']::text[], 'فراخ est le poulet ; لحمة est la viande de bœuf ou d''agneau.', 1, '{"id": "ar.l36.e04", "unitIds": ["ar.g36.la_nourriture", "ar.v.ferakh"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « poulet » ?", "promptLanguage": "fr", "answer": "فراخ", "acceptedAnswers": ["فراخ"], "explanation": "فراخ est le poulet ; لحمة est la viande de bœuf ou d''agneau.", "tip": "فراخ = volaille.", "extraExample": {"text": "رز وفراخ", "translation": "Du riz et du poulet"}, "options": ["بيض", "جبنة", "لحمة", "فراخ"], "errorPatterns": [{"equals": "لحمة", "category": "word_confusion", "feedback": "لحمة est la viande rouge ; le poulet se dit فراخ."}], "pool": "lesson", "lessonId": "ar.l36", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l36.e05', 'ar', 'ar.l36', 'ar.g36.la_nourriture', array['ar.g36.la_nourriture','ar.v.beid']::text[], 'mcq', 'lesson', 'Quel mot veut dire « des œufs » (en général, plusieurs) ?', array['بيض']::text[], 'بيض désigne les œufs en général ; avec ة, بيضة n''en désigne qu''un seul.', 2, '{"id": "ar.l36.e05", "unitIds": ["ar.g36.la_nourriture", "ar.v.beid"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « des œufs » (en général, plusieurs) ?", "promptLanguage": "fr", "answer": "بيض", "acceptedAnswers": ["بيض"], "explanation": "بيض désigne les œufs en général ; avec ة, بيضة n''en désigne qu''un seul.", "tip": "Sans ة : le groupe.", "extraExample": {"text": "بيض وجبنة", "translation": "Des œufs et du fromage"}, "options": ["بيض", "جبنة", "بيضة", "عصير"], "errorPatterns": [{"equals": "بيضة", "category": "word_confusion", "feedback": "بيضة est un seul œuf."}], "pool": "lesson", "lessonId": "ar.l36", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l36.e06', 'ar', 'ar.l36', 'ar.g36.la_nourriture', array['ar.g36.la_nourriture','ar.v.beid']::text[], 'mcq', 'lesson', 'Tu veux UN seul œuf. Quel mot dis-tu ?', array['بيضة']::text[], 'Le ة final désigne une seule pièce : بيض (des œufs) devient بيضة (un œuf).', 3, '{"id": "ar.l36.e06", "unitIds": ["ar.g36.la_nourriture", "ar.v.beid"], "type": "mcq", "difficulty": 3, "instruction": "Applique la règle du ة.", "prompt": "Tu veux UN seul œuf. Quel mot dis-tu ?", "promptLanguage": "fr", "answer": "بيضة", "acceptedAnswers": ["بيضة"], "explanation": "Le ة final désigne une seule pièce : بيض (des œufs) devient بيضة (un œuf).", "tip": "ة = une seule pièce.", "extraExample": {"text": "موز → موزة", "translation": "des bananes → une banane"}, "options": ["بيض", "فراخ", "بيضة", "جبنة"], "errorPatterns": [{"equals": "بيض", "category": "word_confusion", "feedback": "بيض désigne plusieurs œufs ; pour un seul on ajoute ة."}], "pool": "lesson", "lessonId": "ar.l36", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
