insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l36.e15', 'ar', 'ar.l36', 'ar.g36.la_nourriture', array['ar.g36.la_nourriture','ar.v.molokheya']::text[], 'fill_blank', 'lesson', '___ ورز وفراخ  (la soupe verte, du riz et du poulet)', array['ملوخية']::text[], 'La ملوخية se mange avec du رز et de la فراخ (carte « ملوخية et فراخ »).', 2, '{"id": "ar.l36.e15", "unitIds": ["ar.g36.la_nourriture", "ar.v.molokheya"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le menu.", "prompt": "___ ورز وفراخ  (la soupe verte, du riz et du poulet)", "promptLanguage": "ar", "answer": "ملوخية", "acceptedAnswers": ["ملوخية"], "explanation": "La ملوخية se mange avec du رز et de la فراخ (carte « ملوخية et فراخ »).", "tip": "Soupe verte + riz + poulet.", "extraExample": {"text": "ملوخية بالفراخ", "translation": "Soupe verte au poulet"}, "options": ["طعمية", "جبنة", "ملوخية", "كشري"], "pool": "lesson", "lessonId": "ar.l36", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
