insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l36.e21', 'ar', 'ar.l36', 'ar.g36.la_nourriture', array['ar.g36.la_nourriture','ar.v.molokheya']::text[], 'free_answer', 'lesson', 'Sur un menu, tu lis « ملوخية ». Quel genre de plat est-ce ?', array['une soupe verte','soupe verte','une soupe','soupe','un plat vert','de la soupe','soupe de corète','une soupe d''herbes']::text[], 'ملوخية est une soupe verte faite de feuilles hachées (carte « ملوخية et فراخ »).', 2, '{"id": "ar.l36.e21", "unitIds": ["ar.g36.la_nourriture", "ar.v.molokheya"], "type": "free_answer", "difficulty": 2, "instruction": "Réponds en français.", "prompt": "Sur un menu, tu lis « ملوخية ». Quel genre de plat est-ce ?", "promptLanguage": "fr", "answer": "une soupe verte", "acceptedAnswers": ["une soupe verte", "soupe verte", "une soupe", "soupe", "un plat vert", "de la soupe", "soupe de corète", "une soupe d''herbes"], "explanation": "ملوخية est une soupe verte faite de feuilles hachées (carte « ملوخية et فراخ »).", "tip": "Elle se sert avec du رز.", "extraExample": {"text": "ملوخية ورز", "translation": "De la soupe verte et du riz"}, "pool": "lesson", "lessonId": "ar.l36", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l36.e22', 'ar', 'ar.l36', 'ar.g36.la_nourriture', array['ar.g36.la_nourriture','ar.v.ferakh']::text[], 'free_answer', 'lesson', 'Tu lis sur un menu « رز وفراخ ». Qu''est-ce que tu vas manger ?', array['du riz et du poulet','riz et poulet','du riz avec du poulet','riz avec poulet','riz poulet','du riz et de la volaille']::text[], 'رز = riz, و = et, فراخ = poulet.', 2, '{"id": "ar.l36.e22", "unitIds": ["ar.g36.la_nourriture", "ar.v.ferakh"], "type": "free_answer", "difficulty": 2, "instruction": "Réponds en français.", "prompt": "Tu lis sur un menu « رز وفراخ ». Qu''est-ce que tu vas manger ?", "promptLanguage": "fr", "answer": "du riz et du poulet", "acceptedAnswers": ["du riz et du poulet", "riz et poulet", "du riz avec du poulet", "riz avec poulet", "riz poulet", "du riz et de la volaille"], "explanation": "رز = riz, و = et, فراخ = poulet.", "tip": "و collé au mot suivant = et.", "extraExample": {"text": "رز وسمك", "translation": "Du riz et du poisson"}, "pool": "lesson", "lessonId": "ar.l36", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
