insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l37.e01', 'ar', 'ar.l37', 'ar.g37.cafe_et_marche', array['ar.g37.cafe_et_marche','ar.v.ayiz']::text[], 'mcq', 'lesson', 'Tu veux commander un thé. Quel mot dis-tu avant « شاي » ?', array['عايز']::text[], 'عايز veut dire « je veux » : on le met avant ce qu''on commande (carte « Au café »).', 1, '{"id": "ar.l37.e01", "unitIds": ["ar.g37.cafe_et_marche", "ar.v.ayiz"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Tu veux commander un thé. Quel mot dis-tu avant « شاي » ?", "promptLanguage": "fr", "answer": "عايز", "acceptedAnswers": ["عايز"], "explanation": "عايز veut dire « je veux » : on le met avant ce qu''on commande (carte « Au café »).", "tip": "عايز + chose.", "extraExample": {"text": "عايز قهوة", "translation": "Je veux un café"}, "options": ["الحساب", "فلوس", "عايز", "غالي"], "errorPatterns": [{"equals": "غالي", "category": "word_confusion", "feedback": "غالي veut dire « cher »."}], "pool": "lesson", "lessonId": "ar.l37", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l37.e02', 'ar', 'ar.l37', 'ar.g37.cafe_et_marche', array['ar.g37.cafe_et_marche','ar.v.ayiz']::text[], 'mcq', 'lesson', 'Une femme commande un thé. Que dit-elle ?', array['عايزة']::text[], 'Une femme ajoute ة : عايزة (carte « Au café »).', 2, '{"id": "ar.l37.e02", "unitIds": ["ar.g37.cafe_et_marche", "ar.v.ayiz"], "type": "mcq", "difficulty": 2, "instruction": "Applique la règle du féminin.", "prompt": "Une femme commande un thé. Que dit-elle ?", "promptLanguage": "fr", "answer": "عايزة", "acceptedAnswers": ["عايزة"], "explanation": "Une femme ajoute ة : عايزة (carte « Au café »).", "tip": "Féminin = ة.", "extraExample": {"text": "عايزة قهوة", "translation": "Je voudrais un café (une femme)"}, "options": ["غالية", "عايزة", "عايز", "رخيصة"], "errorPatterns": [{"equals": "عايز", "category": "word_confusion", "feedback": "C''est la forme de l''homme ; une femme ajoute ة."}], "pool": "lesson", "lessonId": "ar.l37", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l37.e03', 'ar', 'ar.l37', 'ar.g37.cafe_et_marche', array['ar.g37.cafe_et_marche','ar.v.el_hisab']::text[], 'mcq', 'lesson', 'Quel mot veut dire « l''addition » ?', array['الحساب']::text[], 'الحساب est l''addition ; on le demande avec لو سمحت (carte « Payer »).', 1, '{"id": "ar.l37.e03", "unitIds": ["ar.g37.cafe_et_marche", "ar.v.el_hisab"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « l''addition » ?", "promptLanguage": "fr", "answer": "الحساب", "acceptedAnswers": ["الحساب"], "explanation": "الحساب est l''addition ; on le demande avec لو سمحت (carte « Payer »).", "tip": "الحساب لو سمحت.", "extraExample": {"text": "الحساب عليا", "translation": "C''est moi qui paie"}, "options": ["فلوس", "حاجة", "الحساب", "سوق"], "pool": "lesson", "lessonId": "ar.l37", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l37.e04', 'ar', 'ar.l37', 'ar.g37.cafe_et_marche', array['ar.g37.cafe_et_marche','ar.v.guneh']::text[], 'mcq', 'lesson', 'Quelle est la monnaie de l''Égypte ?', array['جنيه']::text[], 'جنيه est la livre égyptienne ; فلوس est l''argent en général (carte « L''argent »).', 2, '{"id": "ar.l37.e04", "unitIds": ["ar.g37.cafe_et_marche", "ar.v.guneh"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quelle est la monnaie de l''Égypte ?", "promptLanguage": "fr", "answer": "جنيه", "acceptedAnswers": ["جنيه"], "explanation": "جنيه est la livre égyptienne ; فلوس est l''argent en général (carte « L''argent »).", "tip": "جنيه : le ج se lit g.", "extraExample": {"text": "جنيه واحد", "translation": "Une livre"}, "options": ["حاجة", "جنيه", "فلوس", "كباية"], "errorPatterns": [{"equals": "فلوس", "category": "word_confusion", "feedback": "فلوس est l''argent en général, pas la monnaie."}], "pool": "lesson", "lessonId": "ar.l37", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l37.e05', 'ar', 'ar.l37', 'ar.g37.cafe_et_marche', array['ar.g37.cafe_et_marche','ar.v.bikam']::text[], 'mcq', 'lesson', 'Pour demander le prix d''un objet, quel mot dis-tu devant ده ?', array['بكام']::text[], 'بكام veut dire « combien ça coûte ? » (carte « Demander le prix »).', 1, '{"id": "ar.l37.e05", "unitIds": ["ar.g37.cafe_et_marche", "ar.v.bikam"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Pour demander le prix d''un objet, quel mot dis-tu devant ده ?", "promptLanguage": "fr", "answer": "بكام", "acceptedAnswers": ["بكام"], "explanation": "بكام veut dire « combien ça coûte ? » (carte « Demander le prix »).", "tip": "بكام = ب + كام.", "extraExample": {"text": "بكام الكيلو؟", "translation": "Combien le kilo ?"}, "options": ["بكام", "الحساب", "عايز", "غالي"], "errorPatterns": [{"equals": "غالي", "category": "word_confusion", "feedback": "غالي est la réponse (« cher »), pas la question."}], "pool": "lesson", "lessonId": "ar.l37", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l37.e06', 'ar', 'ar.l37', 'ar.g37.cafe_et_marche', array['ar.g37.cafe_et_marche','ar.v.ghali']::text[], 'mcq', 'lesson', 'Le vendeur annonce un prix trop haut. Que dis-tu au souk ?', array['غالي']::text[], 'غالي veut dire « cher » : au souk, on commence presque toujours par là (carte « Le souk »).', 2, '{"id": "ar.l37.e06", "unitIds": ["ar.g37.cafe_et_marche", "ar.v.ghali"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réaction.", "prompt": "Le vendeur annonce un prix trop haut. Que dis-tu au souk ?", "promptLanguage": "fr", "answer": "غالي", "acceptedAnswers": ["غالي"], "explanation": "غالي veut dire « cher » : au souk, on commence presque toujours par là (carte « Le souk »).", "tip": "غالي = cher.", "extraExample": {"text": "غالي أوي!", "translation": "Très cher !"}, "options": ["الحساب", "معلش", "غالي", "رخيص"], "errorPatterns": [{"equals": "رخيص", "category": "word_confusion", "feedback": "رخيص veut dire « bon marché »."}], "pool": "lesson", "lessonId": "ar.l37", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l37.e07', 'ar', 'ar.l37', 'ar.g37.cafe_et_marche', array['ar.g37.cafe_et_marche','ar.v.souq']::text[], 'mcq', 'lesson', 'Tu lis : « رايح السوق ». Où va la personne ?', array['au marché']::text[], 'سوق est le marché ; رايح veut dire « je vais » (mot vu dans les phrases).', 1, '{"id": "ar.l37.e07", "unitIds": ["ar.g37.cafe_et_marche", "ar.v.souq"], "type": "mcq", "difficulty": 1, "instruction": "Lis et choisis le sens.", "prompt": "Tu lis : « رايح السوق ». Où va la personne ?", "promptLanguage": "fr", "answer": "au marché", "acceptedAnswers": ["au marché"], "explanation": "سوق est le marché ; رايح veut dire « je vais » (mot vu dans les phrases).", "tip": "السوق = le souk.", "extraExample": {"text": "السوق زحمة", "translation": "Le marché est bondé"}, "options": ["à l''église", "au marché", "à l''école", "au café"], "pool": "lesson", "lessonId": "ar.l37", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l37.e08', 'ar', 'ar.l37', 'ar.g37.cafe_et_marche', array['ar.g37.cafe_et_marche','ar.v.mumken']::text[], 'mcq', 'lesson', 'Pour demander doucement « je peux avoir un café ? », quel mot places-tu devant قهوة ?', array['ممكن']::text[], 'ممكن veut dire « est-ce possible ? » : ممكن قهوة ؟ est la façon douce de commander (carte « ممكن et حاجة »).', 2, '{"id": "ar.l37.e08", "unitIds": ["ar.g37.cafe_et_marche", "ar.v.mumken"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Pour demander doucement « je peux avoir un café ? », quel mot places-tu devant قهوة ?", "promptLanguage": "fr", "answer": "ممكن", "acceptedAnswers": ["ممكن"], "explanation": "ممكن veut dire « est-ce possible ? » : ممكن قهوة ؟ est la façon douce de commander (carte « ممكن et حاجة »).", "tip": "ممكن + chose ?", "extraExample": {"text": "ممكن الحساب؟", "translation": "Je peux avoir l''addition ?"}, "options": ["رخيص", "كام", "ممكن", "الحساب"], "errorPatterns": [{"equals": "كام", "category": "word_confusion", "feedback": "كام veut dire « combien »."}], "pool": "lesson", "lessonId": "ar.l37", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l37.e09', 'ar', 'ar.l37', 'ar.v.men_fadlak', array['ar.v.men_fadlak']::text[], 'mcq', 'lesson', 'Quelle expression veut dire « s''il te plaît » ?', array['من فضلك']::text[], 'من فضلك veut dire « s''il te plaît » ; معلش est « pardon ».', 1, '{"id": "ar.l37.e09", "unitIds": ["ar.v.men_fadlak"], "type": "mcq", "difficulty": 1, "instruction": "Rappel de la politesse.", "prompt": "Quelle expression veut dire « s''il te plaît » ?", "promptLanguage": "fr", "answer": "من فضلك", "acceptedAnswers": ["من فضلك"], "explanation": "من فضلك veut dire « s''il te plaît » ; معلش est « pardon ».", "tip": "من فضلك accompagne la commande.", "extraExample": {"text": "من فضلك، عايز عصير", "translation": "S''il te plaît, je veux un jus"}, "options": ["معلش", "مع السلامة", "العفو", "من فضلك"], "errorPatterns": [{"equals": "معلش", "category": "word_confusion", "feedback": "معلش veut dire « pardon »."}], "pool": "lesson", "lessonId": "ar.l37", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
