insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l38.e23', 'ar', 'ar.l38', 'ar.g38.nombres_et_prix', array['ar.g38.nombres_et_prix','ar.v.itnen']::text[], 'reorder', 'lesson', 'Forme la phrase : « Deux thés, s''il te plaît ».', array['اتنين شاي من فضلك']::text[], 'Le nombre vient avant l''objet, et من فضلك termine la demande polie.', 2, '{"id": "ar.l38.e23", "unitIds": ["ar.g38.nombres_et_prix", "ar.v.itnen"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Forme la phrase : « Deux thés, s''il te plaît ».", "promptLanguage": "fr", "answer": "اتنين شاي من فضلك", "acceptedAnswers": ["اتنين شاي من فضلك"], "explanation": "Le nombre vient avant l''objet, et من فضلك termine la demande polie.", "tip": "Nombre + objet + من فضلك.", "extraExample": {"text": "تلاتة شاي من فضلك", "translation": "Trois thés, s''il te plaît"}, "tokens": ["من", "فضلك", "اتنين", "شاي"], "pool": "lesson", "lessonId": "ar.l38", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e01', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.embareh']::text[], 'mcq', 'lesson', 'Quel mot veut dire « hier » ?', array['امبارح']::text[], 'امبارح est hier ; il complète la ligne du temps امبارح — النهارده — بكرة.', 1, '{"id": "ar.l39.e01", "unitIds": ["ar.g39.le_temps", "ar.v.embareh"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « hier » ?", "promptLanguage": "fr", "answer": "امبارح", "acceptedAnswers": ["امبارح"], "explanation": "امبارح est hier ; il complète la ligne du temps امبارح — النهارده — بكرة.", "tip": "امبارح commence par ا.", "extraExample": {"text": "امبارح بالليل", "translation": "Hier soir"}, "options": ["بكرة", "النهارده", "امبارح", "دلوقتي"], "errorPatterns": [{"equals": "بكرة", "category": "word_confusion", "feedback": "بكرة veut dire « demain »."}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e02', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.bellayl']::text[], 'mcq', 'lesson', 'Tu entends « بالليل بنصلي ». Quand prie-t-on ?', array['la nuit']::text[], 'بالليل = ب + الليل : « la nuit » (carte « Les moments de la journée »).', 2, '{"id": "ar.l39.e02", "unitIds": ["ar.g39.le_temps", "ar.v.bellayl"], "type": "mcq", "difficulty": 2, "instruction": "Lis et choisis le sens.", "prompt": "Tu entends « بالليل بنصلي ». Quand prie-t-on ?", "promptLanguage": "fr", "answer": "la nuit", "acceptedAnswers": ["la nuit"], "explanation": "بالليل = ب + الليل : « la nuit » (carte « Les moments de la journée »).", "tip": "ب = pendant, à.", "extraExample": {"text": "بالليل الجو حلو", "translation": "La nuit, il fait bon"}, "options": ["le matin", "à midi", "la nuit", "hier"], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e03', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.el_subh']::text[], 'mcq', 'lesson', 'Quel mot veut dire « le matin » dans un emploi du temps ?', array['الصبح']::text[], 'الصبح est le matin ; tu connais sa famille dans صباح الخير.', 1, '{"id": "ar.l39.e03", "unitIds": ["ar.g39.le_temps", "ar.v.el_subh"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « le matin » dans un emploi du temps ?", "promptLanguage": "fr", "answer": "الصبح", "acceptedAnswers": ["الصبح"], "explanation": "الصبح est le matin ; tu connais sa famille dans صباح الخير.", "tip": "الصبح ↔ صباح.", "extraExample": {"text": "الصبح في الكنيسة", "translation": "Le matin à l''église"}, "options": ["الصبح", "بالليل", "بعدين", "الضهر"], "errorPatterns": [{"equals": "الضهر", "category": "word_confusion", "feedback": "الضهر est midi."}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e04', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.baadein']::text[], 'mcq', 'lesson', 'Quel mot veut dire « plus tard, ensuite » ?', array['بعدين']::text[], 'بعدين est « plus tard » ; il s''oppose à دلوقتي, « maintenant ».', 1, '{"id": "ar.l39.e04", "unitIds": ["ar.g39.le_temps", "ar.v.baadein"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « plus tard, ensuite » ?", "promptLanguage": "fr", "answer": "بعدين", "acceptedAnswers": ["بعدين"], "explanation": "بعدين est « plus tard » ; il s''oppose à دلوقتي, « maintenant ».", "tip": "بعدين ≠ دلوقتي.", "extraExample": {"text": "ماشي، بعدين", "translation": "D''accord, plus tard"}, "options": ["دلوقتي", "امبارح", "بعدين", "بكرة"], "errorPatterns": [{"equals": "دلوقتي", "category": "word_confusion", "feedback": "دلوقتي veut dire « maintenant »."}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e05', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.el_sa_kam']::text[], 'mcq', 'lesson', 'Quelle question demande l''heure ?', array['الساعة كام؟']::text[], 'الساعة كام ؟ demande l''heure ; بكام ده؟ demande un prix.', 2, '{"id": "ar.l39.e05", "unitIds": ["ar.g39.le_temps", "ar.v.el_sa_kam"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne question.", "prompt": "Quelle question demande l''heure ?", "promptLanguage": "fr", "answer": "الساعة كام؟", "acceptedAnswers": ["الساعة كام؟"], "explanation": "الساعة كام ؟ demande l''heure ; بكام ده؟ demande un prix.", "tip": "كام est dans les deux : regarde le mot avant.", "extraExample": {"text": "الساعة كام دلوقتي؟", "translation": "Quelle heure est-il maintenant ?"}, "options": ["عامل إيه؟", "بكام ده؟", "فين السوق؟", "الساعة كام؟"], "errorPatterns": [{"equals": "بكام ده؟", "category": "word_confusion", "feedback": "بكام demande un prix, pas l''heure."}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e06', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.rob']::text[], 'mcq', 'lesson', 'Tu lis : « الساعة تلاتة ونص ». Quelle heure est-ce ?', array['3 h 30']::text[], 'ونص veut dire « et demie » : 3 h 30. Pour 3 h 15, on dirait وربع (carte « Quelle heure est-il ? »).', 3, '{"id": "ar.l39.e06", "unitIds": ["ar.g39.le_temps", "ar.v.rob"], "type": "mcq", "difficulty": 3, "instruction": "Lis l''heure.", "prompt": "Tu lis : « الساعة تلاتة ونص ». Quelle heure est-ce ?", "promptLanguage": "fr", "answer": "3 h 30", "acceptedAnswers": ["3 h 30"], "explanation": "ونص veut dire « et demie » : 3 h 30. Pour 3 h 15, on dirait وربع (carte « Quelle heure est-il ? »).", "tip": "نص = moitié, ربع = quart.", "extraExample": {"text": "الساعة اتنين ونص", "translation": "Il est deux heures et demie"}, "options": ["3 h 30", "3 h 15", "3 h 45", "2 h 30"], "errorPatterns": [{"equals": "3 h 15", "category": "word_confusion", "feedback": "3 h 15 se dit تلاتة وربع."}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e07', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.el_itnen']::text[], 'mcq', 'lesson', 'Si الأحد est le premier jour, quel jour est الاتنين ?', array['lundi']::text[], 'الاتنين vient de « deux » : c''est le deuxième jour, le lundi (carte « La semaine suit les nombres »).', 2, '{"id": "ar.l39.e07", "unitIds": ["ar.g39.le_temps", "ar.v.el_itnen"], "type": "mcq", "difficulty": 2, "instruction": "Comprends la semaine.", "prompt": "Si الأحد est le premier jour, quel jour est الاتنين ?", "promptLanguage": "fr", "answer": "lundi", "acceptedAnswers": ["lundi"], "explanation": "الاتنين vient de « deux » : c''est le deuxième jour, le lundi (carte « La semaine suit les nombres »).", "tip": "الأحد = 1, الاتنين = 2.", "extraExample": {"text": "يوم الاتنين", "translation": "Le lundi"}, "options": ["vendredi", "lundi", "mardi", "samedi"], "errorPatterns": [{"equals": "mardi", "category": "word_confusion", "feedback": "Mardi est التلات (trois)."}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
