insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e09', 'ar', 'ar.l39', 'ar.v.sawm', array['ar.v.sawm']::text[], 'mcq', 'lesson', 'Quels jours de la semaine les coptes orthodoxes jeûnent-ils (صوم) ?', array['mercredi et vendredi']::text[], 'Les coptes jeûnent chaque mercredi (الأربع) et vendredi (الجمعة).', 2, '{"id": "ar.l39.e09", "unitIds": ["ar.v.sawm"], "type": "mcq", "difficulty": 2, "instruction": "Rappel : les jours de jeûne.", "prompt": "Quels jours de la semaine les coptes orthodoxes jeûnent-ils (صوم) ?", "promptLanguage": "fr", "answer": "mercredi et vendredi", "acceptedAnswers": ["mercredi et vendredi"], "explanation": "Les coptes jeûnent chaque mercredi (الأربع) et vendredi (الجمعة).", "tip": "الأربع والجمعة صوم.", "extraExample": {"text": "الجمعة صوم", "translation": "Le vendredi est un jour de jeûne"}, "options": ["samedi et dimanche", "jeudi et samedi", "lundi et mardi", "mercredi et vendredi"], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e10', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.inshallah']::text[], 'mcq', 'lesson', 'On te dit « بكرة إن شاء الله ». Que veut dire إن شاء الله ?', array['si Dieu le veut']::text[], 'إن شاء الله veut dire « si Dieu le veut » : un réflexe pour parler du futur.', 1, '{"id": "ar.l39.e10", "unitIds": ["ar.g39.le_temps", "ar.v.inshallah"], "type": "mcq", "difficulty": 1, "instruction": "Lis et choisis le sens.", "prompt": "On te dit « بكرة إن شاء الله ». Que veut dire إن شاء الله ?", "promptLanguage": "fr", "answer": "si Dieu le veut", "acceptedAnswers": ["si Dieu le veut"], "explanation": "إن شاء الله veut dire « si Dieu le veut » : un réflexe pour parler du futur.", "tip": "Futur → إن شاء الله.", "extraExample": {"text": "هنتقابل إن شاء الله", "translation": "On se verra, si Dieu le veut"}, "options": ["à tout de suite", "merci beaucoup", "au revoir", "si Dieu le veut"], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e11', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.embareh','ar.v.baadein','ar.v.el_subh','ar.v.el_dohr','ar.v.bellayl']::text[], 'match', 'lesson', 'Associe chaque mot de temps à son sens.', '{}'::text[], 'Le passé proche, le « plus tard » et les trois moments de la journée.', 1, '{"id": "ar.l39.e11", "unitIds": ["ar.g39.le_temps", "ar.v.embareh", "ar.v.baadein", "ar.v.el_subh", "ar.v.el_dohr", "ar.v.bellayl"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à son sens.", "prompt": "Associe chaque mot de temps à son sens.", "promptLanguage": "fr", "answer": "امبارح = hier ; بعدين = plus tard, ensuite ; الصبح = le matin ; الضهر = midi, l''après-midi ; بالليل = la nuit", "acceptedAnswers": [], "explanation": "Le passé proche, le « plus tard » et les trois moments de la journée.", "pairs": [{"left": "امبارح", "right": "hier"}, {"left": "بعدين", "right": "plus tard, ensuite"}, {"left": "الصبح", "right": "le matin"}, {"left": "الضهر", "right": "midi, l''après-midi"}, {"left": "بالليل", "right": "la nuit"}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e12', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.el_sa_kam','ar.v.rob','ar.v.el_itnen','ar.v.el_gomaa','ar.v.inshallah']::text[], 'match', 'lesson', 'Associe l''heure, la semaine et le réflexe du futur à leur sens.', '{}'::text[], 'L''heure, le quart, deux jours et l''expression du futur.', 2, '{"id": "ar.l39.e12", "unitIds": ["ar.g39.le_temps", "ar.v.el_sa_kam", "ar.v.rob", "ar.v.el_itnen", "ar.v.el_gomaa", "ar.v.inshallah"], "type": "match", "difficulty": 2, "instruction": "Associe chaque expression à son sens.", "prompt": "Associe l''heure, la semaine et le réflexe du futur à leur sens.", "promptLanguage": "fr", "answer": "الساعة كام = quelle heure est-il ? ; ربع = un quart ; الاتنين = lundi ; الجمعة = vendredi ; إن شاء الله = si Dieu le veut", "acceptedAnswers": [], "explanation": "L''heure, le quart, deux jours et l''expression du futur.", "pairs": [{"left": "الساعة كام", "right": "quelle heure est-il ?"}, {"left": "ربع", "right": "un quart"}, {"left": "الاتنين", "right": "lundi"}, {"left": "الجمعة", "right": "vendredi"}, {"left": "إن شاء الله", "right": "si Dieu le veut"}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e13', 'ar', 'ar.l39', 'ar.v.naharda', array['ar.v.naharda','ar.v.bukra','ar.v.delwaqti','ar.v.el_ahad','ar.v.sabt']::text[], 'match', 'lesson', 'Revois les mots du temps déjà lus dans les modules précédents.', '{}'::text[], 'Ces mots viennent des lettres et des phrases de tous les jours : tu les retrouves sur ta ligne du temps.', 1, '{"id": "ar.l39.e13", "unitIds": ["ar.v.naharda", "ar.v.bukra", "ar.v.delwaqti", "ar.v.el_ahad", "ar.v.sabt"], "type": "match", "difficulty": 1, "instruction": "Rappel : associe chaque mot à son sens.", "prompt": "Revois les mots du temps déjà lus dans les modules précédents.", "promptLanguage": "fr", "answer": "النهارده = aujourd''hui ; بكرة = demain ; دلوقتي = maintenant ; الأحد = dimanche ; سبت = samedi", "acceptedAnswers": [], "explanation": "Ces mots viennent des lettres et des phrases de tous les jours : tu les retrouves sur ta ligne du temps.", "pairs": [{"left": "النهارده", "right": "aujourd''hui"}, {"left": "بكرة", "right": "demain"}, {"left": "دلوقتي", "right": "maintenant"}, {"left": "الأحد", "right": "dimanche"}, {"left": "سبت", "right": "samedi"}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e14', 'ar', 'ar.l39', 'ar.v.bukra', array['ar.v.bukra','ar.g39.le_temps']::text[], 'fill_blank', 'lesson', '___ رايح القداس  (demain, je vais à la liturgie)', array['بكرة']::text[], 'بكرة veut dire « demain » ; رايح veut dire « je vais ».', 2, '{"id": "ar.l39.e14", "unitIds": ["ar.v.bukra", "ar.g39.le_temps"], "type": "fill_blank", "difficulty": 2, "instruction": "Rappel : complète la phrase.", "prompt": "___ رايح القداس  (demain, je vais à la liturgie)", "promptLanguage": "ar", "answer": "بكرة", "acceptedAnswers": ["بكرة"], "explanation": "بكرة veut dire « demain » ; رايح veut dire « je vais ».", "tip": "بكرة = demain.", "extraExample": {"text": "بكرة الصبح", "translation": "Demain matin"}, "options": ["بكرة", "الضهر", "بعدين", "امبارح"], "errorPatterns": [{"equals": "امبارح", "category": "word_confusion", "feedback": "امبارح veut dire « hier » : on ne dit pas « hier je vais »."}], "pool": "lesson", "lessonId": "ar.l39", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
