insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e20', 'ar', 'ar.l39', 'ar.v.naharda', array['ar.v.naharda','ar.v.el_ahad']::text[], 'translation', 'lesson', 'النهارده الأحد', array['aujourd''hui c''est dimanche','aujourd''hui, c''est dimanche','aujourd''hui dimanche','aujourd''hui, dimanche','on est dimanche aujourd''hui','nous sommes dimanche']::text[], 'النهارده = aujourd''hui, الأحد = dimanche.', 2, '{"id": "ar.l39.e20", "unitIds": ["ar.v.naharda", "ar.v.el_ahad"], "type": "translation", "difficulty": 2, "instruction": "Rappel : écris le sens en français.", "prompt": "النهارده الأحد", "promptLanguage": "ar", "answer": "aujourd''hui c''est dimanche", "acceptedAnswers": ["aujourd''hui c''est dimanche", "aujourd''hui, c''est dimanche", "aujourd''hui dimanche", "aujourd''hui, dimanche", "on est dimanche aujourd''hui", "nous sommes dimanche"], "explanation": "النهارده = aujourd''hui, الأحد = dimanche.", "tip": "Pas de verbe « être » : deux mots suffisent.", "extraExample": {"text": "النهارده الجمعة", "translation": "Aujourd''hui c''est vendredi"}, "pool": "lesson", "lessonId": "ar.l39", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
