insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e22', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.el_sa_kam']::text[], 'free_answer', 'lesson', 'Que veut dire la question « الساعة كام ؟ » ?', array['quelle heure est-il','quelle heure est il','quelle heure est-il ?','il est quelle heure','quelle heure','c''est quelle heure','l''heure']::text[], 'الساعة كام ؟ demande l''heure (carte « Quelle heure est-il ? »).', 2, '{"id": "ar.l39.e22", "unitIds": ["ar.g39.le_temps", "ar.v.el_sa_kam"], "type": "free_answer", "difficulty": 2, "instruction": "Réponds en français.", "prompt": "Que veut dire la question « الساعة كام ؟ » ?", "promptLanguage": "fr", "answer": "quelle heure est-il", "acceptedAnswers": ["quelle heure est-il", "quelle heure est il", "quelle heure est-il ?", "il est quelle heure", "quelle heure", "c''est quelle heure", "l''heure"], "explanation": "الساعة كام ؟ demande l''heure (carte « Quelle heure est-il ? »).", "tip": "كام = combien, الساعة = l''heure.", "extraExample": {"text": "القداس الساعة كام؟", "translation": "À quelle heure est la liturgie ?"}, "pool": "lesson", "lessonId": "ar.l39", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l39.e23', 'ar', 'ar.l39', 'ar.g39.le_temps', array['ar.g39.le_temps','ar.v.el_sa_kam']::text[], 'reorder', 'lesson', 'Dis : « Il est trois heures et demie ».', array['الساعة تلاتة ونص']::text[], 'On commence par الساعة, puis le nombre, puis ونص pour la demie.', 2, '{"id": "ar.l39.e23", "unitIds": ["ar.g39.le_temps", "ar.v.el_sa_kam"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Dis : « Il est trois heures et demie ».", "promptLanguage": "fr", "answer": "الساعة تلاتة ونص", "acceptedAnswers": ["الساعة تلاتة ونص"], "explanation": "On commence par الساعة, puis le nombre, puis ونص pour la demie.", "tip": "الساعة + nombre + ونص.", "extraExample": {"text": "الساعة اتنين وربع", "translation": "Il est deux heures et quart"}, "tokens": ["تلاتة", "ونص", "الساعة"], "pool": "lesson", "lessonId": "ar.l39", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l40.e01', 'ar', 'ar.l40', 'ar.g40.a_l_eglise', array['ar.g40.a_l_eglise','ar.v.haykal']::text[], 'mcq', 'lesson', 'Quel mot veut dire « sanctuaire » (la partie de l''église où se trouve l''autel) ?', array['هيكل']::text[], 'الهيكل est le sanctuaire ; كنيسة est l''église entière (carte « Dans l''église »).', 1, '{"id": "ar.l40.e01", "unitIds": ["ar.g40.a_l_eglise", "ar.v.haykal"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « sanctuaire » (la partie de l''église où se trouve l''autel) ?", "promptLanguage": "fr", "answer": "هيكل", "acceptedAnswers": ["هيكل"], "explanation": "الهيكل est le sanctuaire ; كنيسة est l''église entière (carte « Dans l''église »).", "tip": "هيكل = là où est le مذبح.", "extraExample": {"text": "أبونا في الهيكل", "translation": "Notre père est dans le sanctuaire"}, "options": ["جرس", "هيكل", "كنيسة", "أيقونة"], "errorPatterns": [{"equals": "كنيسة", "category": "word_confusion", "feedback": "كنيسة est l''église entière, pas seulement le sanctuaire."}], "pool": "lesson", "lessonId": "ar.l40", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
