insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l40.e03', 'ar', 'ar.l40', 'ar.g40.a_l_eglise', array['ar.g40.a_l_eglise','ar.v.ayqona']::text[], 'mcq', 'lesson', 'Quel mot veut dire « icône » (une image sainte peinte) ?', array['أيقونة']::text[], 'أيقونة est l''icône ; صليب est la croix, إنجيل l''Évangile, مزمور le psaume.', 1, '{"id": "ar.l40.e03", "unitIds": ["ar.g40.a_l_eglise", "ar.v.ayqona"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « icône » (une image sainte peinte) ?", "promptLanguage": "fr", "answer": "أيقونة", "acceptedAnswers": ["أيقونة"], "explanation": "أيقونة est l''icône ; صليب est la croix, إنجيل l''Évangile, مزمور le psaume.", "tip": "أيقونة : أ + ي + ق.", "extraExample": {"text": "الأيقونة في الكنيسة", "translation": "L''icône est dans l''église"}, "options": ["مزمور", "إنجيل", "صليب", "أيقونة"], "pool": "lesson", "lessonId": "ar.l40", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
