insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l40.e05', 'ar', 'ar.l40', 'ar.g40.a_l_eglise', array['ar.g40.a_l_eglise','ar.v.el_qiddisin']::text[], 'mcq', 'lesson', 'Que veut dire القديسين ?', array['les saints']::text[], 'القديسين est le pluriel de قديس : le ـين final marque le pluriel des personnes.', 2, '{"id": "ar.l40.e05", "unitIds": ["ar.g40.a_l_eglise", "ar.v.el_qiddisin"], "type": "mcq", "difficulty": 2, "instruction": "Lis et choisis le sens.", "prompt": "Que veut dire القديسين ?", "promptLanguage": "fr", "answer": "les saints", "acceptedAnswers": ["les saints"], "explanation": "القديسين est le pluriel de قديس : le ـين final marque le pluriel des personnes.", "tip": "ـين = plusieurs personnes.", "extraExample": {"text": "صلوات القديسين", "translation": "Les prières des saints"}, "options": ["les saints", "le saint", "les prêtres", "les anges"], "errorPatterns": [{"equals": "le saint", "category": "word_confusion", "feedback": "Le singulier est قديس, sans ـين."}], "pool": "lesson", "lessonId": "ar.l40", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l40.e06', 'ar', 'ar.l40', 'ar.g40.a_l_eglise', array['ar.g40.a_l_eglise','ar.v.el_qiddisin']::text[], 'mcq', 'lesson', 'Quelle expression veut dire « notre mère la Vierge » ?', array['أمنا العدرا']::text[], 'ـنا veut dire « notre » : أم + نا = أمنا, comme أبونا (notre père) et ربنا (notre Seigneur).', 3, '{"id": "ar.l40.e06", "unitIds": ["ar.g40.a_l_eglise", "ar.v.el_qiddisin"], "type": "mcq", "difficulty": 3, "instruction": "Applique la règle de ـنا.", "prompt": "Quelle expression veut dire « notre mère la Vierge » ?", "promptLanguage": "fr", "answer": "أمنا العدرا", "acceptedAnswers": ["أمنا العدرا"], "explanation": "ـنا veut dire « notre » : أم + نا = أمنا, comme أبونا (notre père) et ربنا (notre Seigneur).", "tip": "ـنا = notre.", "extraExample": {"text": "أمنا العدرا", "translation": "Notre mère la Vierge"}, "options": ["أبونا العدرا", "ربنا العدرا", "أمنا العدرا", "أخويا العدرا"], "errorPatterns": [{"equals": "أبونا العدرا", "category": "word_confusion", "feedback": "أبونا est « notre père » ; la Vierge est une mère : أمنا."}], "pool": "lesson", "lessonId": "ar.l40", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
