insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l40.e10', 'ar', 'ar.l40', 'ar.v.injil', array['ar.v.injil']::text[], 'mcq', 'lesson', 'Quel mot arabe désigne le livre de la Bonne Nouvelle lu à la liturgie ?', array['إنجيل']::text[], 'إنجيل est l''Évangile ; مزمور est un psaume, نبوات les prophéties, أجبية le livre des heures.', 1, '{"id": "ar.l40.e10", "unitIds": ["ar.v.injil"], "type": "mcq", "difficulty": 1, "instruction": "Rappel : le livre de la liturgie.", "prompt": "Quel mot arabe désigne le livre de la Bonne Nouvelle lu à la liturgie ?", "promptLanguage": "fr", "answer": "إنجيل", "acceptedAnswers": ["إنجيل"], "explanation": "إنجيل est l''Évangile ; مزمور est un psaume, نبوات les prophéties, أجبية le livre des heures.", "tip": "إنجيل : le livre de la Bonne Nouvelle.", "extraExample": {"text": "الإنجيل في القداس", "translation": "L''Évangile est lu à la liturgie"}, "options": ["نبوات", "مزمور", "أجبية", "إنجيل"], "pool": "lesson", "lessonId": "ar.l40", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l40.e11', 'ar', 'ar.l40', 'ar.g40.a_l_eglise', array['ar.g40.a_l_eglise','ar.v.haykal','ar.v.madbah','ar.v.ayqona','ar.v.el_qiddisin','ar.v.margirgis']::text[], 'match', 'lesson', 'Associe chaque mot de l''église à son sens.', '{}'::text[], 'Le lieu (هيكل, مذبح, أيقونة) et les saints (القديسين, مارجرجس).', 1, '{"id": "ar.l40.e11", "unitIds": ["ar.g40.a_l_eglise", "ar.v.haykal", "ar.v.madbah", "ar.v.ayqona", "ar.v.el_qiddisin", "ar.v.margirgis"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à son sens.", "prompt": "Associe chaque mot de l''église à son sens.", "promptLanguage": "fr", "answer": "هيكل = sanctuaire ; مذبح = autel ; أيقونة = icône ; القديسين = les saints ; مارجرجس = saint Georges", "acceptedAnswers": [], "explanation": "Le lieu (هيكل, مذبح, أيقونة) et les saints (القديسين, مارجرجس).", "pairs": [{"left": "هيكل", "right": "sanctuaire"}, {"left": "مذبح", "right": "autel"}, {"left": "أيقونة", "right": "icône"}, {"left": "القديسين", "right": "les saints"}, {"left": "مارجرجس", "right": "saint Georges"}], "pool": "lesson", "lessonId": "ar.l40", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
