insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.rahib', 'ar', 'رَاهِب', 'moine', 'Le moine, qui vit dans un monastère (دَيْر), comme ceux du désert d''Égypte.', '[{"text": "رَاهِب فِي الدَّيْر.", "translation": "Un moine dans le monastère."}, {"text": "الرُّهْبَان.", "translation": "Les moines."}]'::jsonb, null, '{"id": "ar.d.rahib", "word": "رَاهِب", "translation": "moine", "partOfSpeech": "noun", "explanation": "Le moine, qui vit dans un monastère (دَيْر), comme ceux du désert d''Égypte.", "examples": [{"text": "رَاهِب فِي الدَّيْر.", "translation": "Un moine dans le monastère."}, {"text": "الرُّهْبَان.", "translation": "Les moines."}], "unitId": "ar.v.rahib", "forms": {"plural": "رُهْبَان"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
