insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kubbaya', 'ar', 'كُبَّايَة', 'verre (à boire)', 'Le verre dans lequel on boit ; on l''écrit souvent كوباية, mais on dit كُبَّايَة avec un ب doublé.', '[{"text": "كُبَّايَة مَيَّة.", "translation": "Un verre d''eau."}, {"text": "كُبَّايَة شَاي.", "translation": "Un verre de thé."}]'::jsonb, null, '{"id": "ar.d.kubbaya", "word": "كُبَّايَة", "translation": "verre (à boire)", "partOfSpeech": "noun", "explanation": "Le verre dans lequel on boit ; on l''écrit souvent كوباية, mais on dit كُبَّايَة avec un ب doublé.", "examples": [{"text": "كُبَّايَة مَيَّة.", "translation": "Un verre d''eau."}, {"text": "كُبَّايَة شَاي.", "translation": "Un verre de thé."}], "unitId": "ar.v.kubbaya", "forms": {"plural": "كُبَّايَات"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
