insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kull', 'ar', 'كُلّ', 'tout, chaque', 'Tout, chaque : كُلّ يَوْم, chaque jour.', '[{"text": "كُلّ يَوْم.", "translation": "Chaque jour."}, {"text": "كُلّ سَنَة وَإِنْتَ طَيِّب.", "translation": "Bonne fête ! (littéralement : chaque année et tu vas bien)"}]'::jsonb, null, '{"id": "ar.d.kull", "word": "كُلّ", "translation": "tout, chaque", "partOfSpeech": "noun", "explanation": "Tout, chaque : كُلّ يَوْم, chaque jour.", "examples": [{"text": "كُلّ يَوْم.", "translation": "Chaque jour."}, {"text": "كُلّ سَنَة وَإِنْتَ طَيِّب.", "translation": "Bonne fête ! (littéralement : chaque année et tu vas bien)"}], "unitId": "ar.v.kull"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
