insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.muallim', 'ar', 'مُعَلِّم', 'maître, patron', 'Le maître, le patron d''un atelier ou d''un café ; dans l''Évangile, on appelle Jésus « Maître ».', '[{"text": "يَا مُعَلِّم!", "translation": "Patron ! (pour appeler le chef d''un café)"}, {"text": "أَيُّهَا الْمُعَلِّم الصَّالِح.", "translation": "Bon Maître."}]'::jsonb, null, '{"id": "ar.d.muallim", "word": "مُعَلِّم", "translation": "maître, patron", "partOfSpeech": "noun", "explanation": "Le maître, le patron d''un atelier ou d''un café ; dans l''Évangile, on appelle Jésus « Maître ».", "examples": [{"text": "يَا مُعَلِّم!", "translation": "Patron ! (pour appeler le chef d''un café)"}, {"text": "أَيُّهَا الْمُعَلِّم الصَّالِح.", "translation": "Bon Maître."}], "unitId": "ar.v.muallim"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
