insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sayyid', 'ar', 'سَيِّد', 'monsieur, seigneur', 'Monsieur, ou le Seigneur ; السَّيِّد الْمَسِيح est une façon respectueuse de dire le Christ.', '[{"text": "السَّيِّد الْمَسِيح.", "translation": "Le Seigneur le Christ."}, {"text": "سَيِّد مُحْتَرَم.", "translation": "Un monsieur respecté."}]'::jsonb, null, '{"id": "ar.d.sayyid", "word": "سَيِّد", "translation": "monsieur, seigneur", "partOfSpeech": "noun", "explanation": "Monsieur, ou le Seigneur ; السَّيِّد الْمَسِيح est une façon respectueuse de dire le Christ.", "examples": [{"text": "السَّيِّد الْمَسِيح.", "translation": "Le Seigneur le Christ."}, {"text": "سَيِّد مُحْتَرَم.", "translation": "Un monsieur respecté."}], "unitId": "ar.v.sayyid"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
