insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.afwan', 'ar', 'عَفْوًا', 'de rien, pardon', 'Ce qu''on répond à un merci, ou pour s''excuser : « pardon ».', '[{"text": "شُكْرًا. - عَفْوًا.", "translation": "Merci. - De rien."}, {"text": "عَفْوًا، فِين الْمَحَطَّة؟", "translation": "Pardon, où est la gare ?"}]'::jsonb, null, '{"id": "ar.d.afwan", "word": "عَفْوًا", "translation": "de rien, pardon", "partOfSpeech": "expression", "explanation": "Ce qu''on répond à un merci, ou pour s''excuser : « pardon ».", "examples": [{"text": "شُكْرًا. - عَفْوًا.", "translation": "Merci. - De rien."}, {"text": "عَفْوًا، فِين الْمَحَطَّة؟", "translation": "Pardon, où est la gare ?"}], "unitId": "ar.v.afwan"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
