insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.musa', 'ar', 'مُوسَى', 'Moïse', 'Moïse, le prophète de l''Exode ; ى donne un a long.', '[{"text": "مُوسَى النَّبِي.", "translation": "Moïse le prophète."}, {"text": "جَبَل مُوسَى.", "translation": "Le mont de Moïse."}]'::jsonb, null, '{"id": "ar.d.musa", "word": "مُوسَى", "translation": "Moïse", "partOfSpeech": "noun", "explanation": "Moïse, le prophète de l''Exode ; ى donne un a long.", "examples": [{"text": "مُوسَى النَّبِي.", "translation": "Moïse le prophète."}, {"text": "جَبَل مُوسَى.", "translation": "Le mont de Moïse."}], "unitId": "ar.v.musa"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.matta', 'ar', 'مَتَّى', 'Matthieu', 'Matthieu, apôtre et auteur du premier Évangile ; ت est doublé, et ى donne un a long.', '[{"text": "إِنْجِيل مَتَّى.", "translation": "L''Évangile selon Matthieu."}, {"text": "مَتَّى الرَّسُول.", "translation": "Matthieu l''apôtre."}]'::jsonb, null, '{"id": "ar.d.matta", "word": "مَتَّى", "translation": "Matthieu", "partOfSpeech": "noun", "explanation": "Matthieu, apôtre et auteur du premier Évangile ; ت est doublé, et ى donne un a long.", "examples": [{"text": "إِنْجِيل مَتَّى.", "translation": "L''Évangile selon Matthieu."}, {"text": "مَتَّى الرَّسُول.", "translation": "Matthieu l''apôtre."}], "unitId": "ar.v.matta"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
