insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.maana', 'ar', 'مَعْنَى', 'sens, signification', 'Le sens d''un mot ou d''une phrase.', '[{"text": "إِيه مَعْنَى الْكَلِمَة؟", "translation": "Que veut dire ce mot ?"}, {"text": "مَعْنَى كَلِمَة آمِين.", "translation": "Le sens du mot amen."}]'::jsonb, null, '{"id": "ar.d.maana", "word": "مَعْنَى", "translation": "sens, signification", "partOfSpeech": "noun", "explanation": "Le sens d''un mot ou d''une phrase.", "examples": [{"text": "إِيه مَعْنَى الْكَلِمَة؟", "translation": "Que veut dire ce mot ?"}, {"text": "مَعْنَى كَلِمَة آمِين.", "translation": "Le sens du mot amen."}], "unitId": "ar.v.maana"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.yohanna', 'ar', 'يُوحَنَّا', 'Jean', 'Jean, l''apôtre bien-aimé ; le a long final s''écrit ici avec un ا, et non un ى.', '[{"text": "إِنْجِيل يُوحَنَّا.", "translation": "L''Évangile selon Jean."}, {"text": "يُوحَنَّا الْحَبِيب.", "translation": "Jean le bien-aimé."}]'::jsonb, null, '{"id": "ar.d.yohanna", "word": "يُوحَنَّا", "translation": "Jean", "partOfSpeech": "noun", "explanation": "Jean, l''apôtre bien-aimé ; le a long final s''écrit ici avec un ا, et non un ى.", "examples": [{"text": "إِنْجِيل يُوحَنَّا.", "translation": "L''Évangile selon Jean."}, {"text": "يُوحَنَّا الْحَبِيب.", "translation": "Jean le bien-aimé."}], "unitId": "ar.v.yohanna"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mama', 'ar', 'ماما', 'maman', 'Le mot des enfants pour leur mère, formé de deux paquets identiques ما | ما.', '[{"text": "ماما عايزة شاي.", "translation": "Maman veut du thé."}, {"text": "بابا وماما في الكنيسة.", "translation": "Papa et maman sont à l''église."}]'::jsonb, null, '{"id": "ar.d.mama", "word": "ماما", "translation": "maman", "partOfSpeech": "noun", "explanation": "Le mot des enfants pour leur mère, formé de deux paquets identiques ما | ما.", "examples": [{"text": "ماما عايزة شاي.", "translation": "Maman veut du thé."}, {"text": "بابا وماما في الكنيسة.", "translation": "Papa et maman sont à l''église."}], "unitId": "ar.v.mama", "confusions": [{"word": "بابا", "note": "بابا (papa) a la même forme, mais commence par ب, avec un point dessous."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.teta', 'ar', 'تيتة', 'mamie', 'Le mot affectueux pour la grand-mère. Le ي au milieu est la balise : تي | تة.', '[{"text": "تيتة بتحب الشاي.", "translation": "Mamie adore le thé."}, {"text": "تيتة في البيت.", "translation": "Mamie est à la maison."}]'::jsonb, null, '{"id": "ar.d.teta", "word": "تيتة", "translation": "mamie", "partOfSpeech": "noun", "explanation": "Le mot affectueux pour la grand-mère. Le ي au milieu est la balise : تي | تة.", "examples": [{"text": "تيتة بتحب الشاي.", "translation": "Mamie adore le thé."}, {"text": "تيتة في البيت.", "translation": "Mamie est à la maison."}], "unitId": "ar.v.teta"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nur', 'ar', 'نور', 'lumière', 'La lumière ; c''est aussi un prénom. Un seul paquet long : نو + ر.', '[{"text": "افتح النور.", "translation": "Allume la lumière."}, {"text": "العلم نور.", "translation": "Le savoir est une lumière."}]'::jsonb, null, '{"id": "ar.d.nur", "word": "نور", "translation": "lumière", "partOfSpeech": "noun", "explanation": "La lumière ; c''est aussi un prénom. Un seul paquet long : نو + ر.", "examples": [{"text": "افتح النور.", "translation": "Allume la lumière."}, {"text": "العلم نور.", "translation": "Le savoir est une lumière."}], "unitId": "ar.v.nur", "confusions": [{"word": "ورد", "note": "ورد (fleurs) se lit presque pareil : regarde la première lettre, ن ou و."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mooz', 'ar', 'موز', 'banane', 'La banane. Le و est la balise du paquet long مو.', '[{"text": "أنا باكل موز.", "translation": "Je mange une banane."}, {"text": "الموز حلو.", "translation": "Les bananes sont bonnes."}]'::jsonb, null, '{"id": "ar.d.mooz", "word": "موز", "translation": "banane", "partOfSpeech": "noun", "explanation": "La banane. Le و est la balise du paquet long مو.", "examples": [{"text": "أنا باكل موز.", "translation": "Je mange une banane."}, {"text": "الموز حلو.", "translation": "Les bananes sont bonnes."}], "unitId": "ar.v.mooz"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.milh', 'ar', 'ملح', 'sel', 'Le sel : trois consonnes, aucune voyelle visible, un seul paquet.', '[{"text": "حط ملح شوية.", "translation": "Mets un peu de sel."}, {"text": "الأكل محتاج ملح.", "translation": "La cuisine a besoin de sel."}]'::jsonb, null, '{"id": "ar.d.milh", "word": "ملح", "translation": "sel", "partOfSpeech": "noun", "explanation": "Le sel : trois consonnes, aucune voyelle visible, un seul paquet.", "examples": [{"text": "حط ملح شوية.", "translation": "Mets un peu de sel."}, {"text": "الأكل محتاج ملح.", "translation": "La cuisine a besoin de sel."}], "unitId": "ar.v.milh", "confusions": [{"word": "سكر", "note": "سكر (sucre) a aussi trois consonnes, mais ce ne sont pas les mêmes."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.samak', 'ar', 'سمك', 'poisson', 'Le poisson, au singulier collectif : on dit السمك pour « le poisson » en général.', '[{"text": "السمك طازة.", "translation": "Le poisson est frais."}, {"text": "بحب السمك المشوي.", "translation": "J''aime le poisson grillé."}]'::jsonb, null, '{"id": "ar.d.samak", "word": "سمك", "translation": "poisson", "partOfSpeech": "noun", "explanation": "Le poisson, au singulier collectif : on dit السمك pour « le poisson » en général.", "examples": [{"text": "السمك طازة.", "translation": "Le poisson est frais."}, {"text": "بحب السمك المشوي.", "translation": "J''aime le poisson grillé."}], "unitId": "ar.v.samak", "forms": {"plural": "أسماك"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.gamal', 'ar', 'جمل', 'chameau', 'Le chameau. Le ج se dit g au Caire, comme dans gâteau.', '[{"text": "الجمل في الصحرا.", "translation": "Le chameau est dans le désert."}, {"text": "ركبت جمل جنب الأهرامات.", "translation": "J''ai monté un chameau près des pyramides."}]'::jsonb, null, '{"id": "ar.d.gamal", "word": "جمل", "translation": "chameau", "partOfSpeech": "noun", "explanation": "Le chameau. Le ج se dit g au Caire, comme dans gâteau.", "examples": [{"text": "الجمل في الصحرا.", "translation": "Le chameau est dans le désert."}, {"text": "ركبت جمل جنب الأهرامات.", "translation": "J''ai monté un chameau près des pyramides."}], "unitId": "ar.v.gamal", "forms": {"plural": "جمال"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.otta', 'ar', 'قطة', 'chat (chatte)', 'Le chat ou la chatte : le mot est féminin. Au Caire, le ق se dit comme un petit coup de gorge.', '[{"text": "القطة بتشرب لبن.", "translation": "Le chat boit du lait."}, {"text": "عندي قطة صغيرة.", "translation": "J''ai une petite chatte."}]'::jsonb, null, '{"id": "ar.d.otta", "word": "قطة", "translation": "chat (chatte)", "partOfSpeech": "noun", "explanation": "Le chat ou la chatte : le mot est féminin. Au Caire, le ق se dit comme un petit coup de gorge.", "examples": [{"text": "القطة بتشرب لبن.", "translation": "Le chat boit du lait."}, {"text": "عندي قطة صغيرة.", "translation": "J''ai une petite chatte."}], "unitId": "ar.v.otta", "forms": {"plural": "قطط"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.walad', 'ar', 'ولد', 'garçon', 'Un garçon. Le و du début est une consonne (le w de week-end), pas une voyelle longue.', '[{"text": "الولد بيلعب.", "translation": "Le garçon joue."}, {"text": "عندي ولد وبنت.", "translation": "J''ai un garçon et une fille."}]'::jsonb, null, '{"id": "ar.d.walad", "word": "ولد", "translation": "garçon", "partOfSpeech": "noun", "explanation": "Un garçon. Le و du début est une consonne (le w de week-end), pas une voyelle longue.", "examples": [{"text": "الولد بيلعب.", "translation": "Le garçon joue."}, {"text": "عندي ولد وبنت.", "translation": "J''ai un garçon et une fille."}], "unitId": "ar.v.walad", "forms": {"plural": "ولاد"}, "confusions": [{"word": "ورد", "note": "ولد et ورد (fleurs) ne diffèrent que par la deuxième lettre."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.madrasa', 'ar', 'مدرسة', 'école', 'L''école. مد | ر | سة : trois blocs, car le د et le ر ferment chacun un bloc.', '[{"text": "المدرسة قريبة من البيت.", "translation": "L''école est près de la maison."}, {"text": "أنا رايح المدرسة.", "translation": "Je vais à l''école."}]'::jsonb, null, '{"id": "ar.d.madrasa", "word": "مدرسة", "translation": "école", "partOfSpeech": "noun", "explanation": "L''école. مد | ر | سة : trois blocs, car le د et le ر ferment chacun un bloc.", "examples": [{"text": "المدرسة قريبة من البيت.", "translation": "L''école est près de la maison."}, {"text": "أنا رايح المدرسة.", "translation": "Je vais à l''école."}], "unitId": "ar.v.madrasa", "forms": {"plural": "مدارس"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mustashfa', 'ar', 'مستشفى', 'hôpital', 'L''hôpital. Un seul bloc de six lettres, à lire en paquets : مس | تش | فى.', '[{"text": "المستشفى قدام الجامعة.", "translation": "L''hôpital est en face de l''université."}, {"text": "تيتة في المستشفى.", "translation": "Mamie est à l''hôpital."}]'::jsonb, null, '{"id": "ar.d.mustashfa", "word": "مستشفى", "translation": "hôpital", "partOfSpeech": "noun", "explanation": "L''hôpital. Un seul bloc de six lettres, à lire en paquets : مس | تش | فى.", "examples": [{"text": "المستشفى قدام الجامعة.", "translation": "L''hôpital est en face de l''université."}, {"text": "تيتة في المستشفى.", "translation": "Mamie est à l''hôpital."}], "unitId": "ar.v.mustashfa", "forms": {"plural": "مستشفيات"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mobail', 'ar', 'موبايل', 'portable', 'Le téléphone portable. مو | با | يل : trois blocs.', '[{"text": "عندي موبايل جديد.", "translation": "J''ai un nouveau portable."}, {"text": "الموبايل فين؟", "translation": "Où est le portable ?"}]'::jsonb, null, '{"id": "ar.d.mobail", "word": "موبايل", "translation": "portable", "partOfSpeech": "noun", "explanation": "Le téléphone portable. مو | با | يل : trois blocs.", "examples": [{"text": "عندي موبايل جديد.", "translation": "J''ai un nouveau portable."}, {"text": "الموبايل فين؟", "translation": "Où est le portable ?"}], "unitId": "ar.v.mobail", "forms": {"plural": "موبايلات"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.utobis', 'ar', 'أتوبيس', 'bus', 'Le bus. أ | تو | بيس : le أ du début ferme son bloc tout seul.', '[{"text": "الأتوبيس اتأخر.", "translation": "Le bus est en retard."}, {"text": "بروح الشغل بالأتوبيس.", "translation": "Je vais au travail en bus."}]'::jsonb, null, '{"id": "ar.d.utobis", "word": "أتوبيس", "translation": "bus", "partOfSpeech": "noun", "explanation": "Le bus. أ | تو | بيس : le أ du début ferme son bloc tout seul.", "examples": [{"text": "الأتوبيس اتأخر.", "translation": "Le bus est en retard."}, {"text": "بروح الشغل بالأتوبيس.", "translation": "Je vais au travail en bus."}], "unitId": "ar.v.utobis", "forms": {"plural": "أتوبيسات"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.telifun', 'ar', 'تليفون', 'téléphone', 'Le téléphone. تليفو | ن : deux blocs, le و ferme le premier.', '[{"text": "التليفون بيرن.", "translation": "Le téléphone sonne."}, {"text": "رقم التليفون ده غلط.", "translation": "Ce numéro de téléphone est faux."}]'::jsonb, null, '{"id": "ar.d.telifun", "word": "تليفون", "translation": "téléphone", "partOfSpeech": "noun", "explanation": "Le téléphone. تليفو | ن : deux blocs, le و ferme le premier.", "examples": [{"text": "التليفون بيرن.", "translation": "Le téléphone sonne."}, {"text": "رقم التليفون ده غلط.", "translation": "Ce numéro de téléphone est faux."}], "unitId": "ar.v.telifun", "confusions": [{"word": "موبايل", "note": "موبايل désigne le portable ; تليفون est le mot pour le téléphone en général."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.gamia', 'ar', 'جامعة', 'université', 'L''université. جا | معة : deux blocs, le ا ferme le premier.', '[{"text": "أخويا في الجامعة.", "translation": "Mon frère est à l''université."}, {"text": "جامعة القاهرة قديمة.", "translation": "L''université du Caire est ancienne."}]'::jsonb, null, '{"id": "ar.d.gamia", "word": "جامعة", "translation": "université", "partOfSpeech": "noun", "explanation": "L''université. جا | معة : deux blocs, le ا ferme le premier.", "examples": [{"text": "أخويا في الجامعة.", "translation": "Mon frère est à l''université."}, {"text": "جامعة القاهرة قديمة.", "translation": "L''université du Caire est ancienne."}], "unitId": "ar.v.gamia", "forms": {"plural": "جامعات"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.matam', 'ar', 'مطعم', 'restaurant', 'Le restaurant. Un seul bloc de quatre lettres, à lire en deux paquets : مط | عم.', '[{"text": "المطعم فاتح.", "translation": "Le restaurant est ouvert."}, {"text": "هنتغدى في مطعم.", "translation": "Nous allons déjeuner au restaurant."}]'::jsonb, null, '{"id": "ar.d.matam", "word": "مطعم", "translation": "restaurant", "partOfSpeech": "noun", "explanation": "Le restaurant. Un seul bloc de quatre lettres, à lire en deux paquets : مط | عم.", "examples": [{"text": "المطعم فاتح.", "translation": "Le restaurant est ouvert."}, {"text": "هنتغدى في مطعم.", "translation": "Nous allons déjeuner au restaurant."}], "unitId": "ar.v.matam", "forms": {"plural": "مطاعم"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.al_qahira', 'ar', 'القاهرة', 'Le Caire', 'La capitale de l''Égypte. ال + قاهرة : ا | لقا | هر | ة, quatre blocs.', '[{"text": "أنا ساكن في القاهرة.", "translation": "J''habite au Caire."}, {"text": "القاهرة زحمة.", "translation": "Le Caire est bondé."}]'::jsonb, null, '{"id": "ar.d.al_qahira", "word": "القاهرة", "translation": "Le Caire", "partOfSpeech": "noun", "explanation": "La capitale de l''Égypte. ال + قاهرة : ا | لقا | هر | ة, quatre blocs.", "examples": [{"text": "أنا ساكن في القاهرة.", "translation": "J''habite au Caire."}, {"text": "القاهرة زحمة.", "translation": "Le Caire est bondé."}], "unitId": "ar.v.al_qahira"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.al_katidraiya', 'ar', 'الكاتدرائية', 'la cathédrale', 'La cathédrale. ا | لكا | تد | ر | ا | ئية : six blocs, le plus long mot de la leçon.', '[{"text": "الكاتدرائية المرقسية في القاهرة.", "translation": "La cathédrale Saint-Marc est au Caire."}, {"text": "رحنا الكاتدرائية في العيد.", "translation": "Nous sommes allés à la cathédrale pour la fête."}]'::jsonb, null, '{"id": "ar.d.al_katidraiya", "word": "الكاتدرائية", "translation": "la cathédrale", "partOfSpeech": "noun", "explanation": "La cathédrale. ا | لكا | تد | ر | ا | ئية : six blocs, le plus long mot de la leçon.", "examples": [{"text": "الكاتدرائية المرقسية في القاهرة.", "translation": "La cathédrale Saint-Marc est au Caire."}, {"text": "رحنا الكاتدرائية في العيد.", "translation": "Nous sommes allés à la cathédrale pour la fête."}], "unitId": "ar.v.al_katidraiya"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ana', 'ar', 'أنا', 'je, moi', 'Le pronom « je » ou « moi ». Il ouvre la plupart des phrases.', '[{"text": "أنا من مصر.", "translation": "Je suis d''Égypte."}, {"text": "أنا جعان.", "translation": "J''ai faim."}]'::jsonb, null, '{"id": "ar.d.ana", "word": "أنا", "translation": "je, moi", "partOfSpeech": "pronoun", "explanation": "Le pronom « je » ou « moi ». Il ouvre la plupart des phrases.", "examples": [{"text": "أنا من مصر.", "translation": "Je suis d''Égypte."}, {"text": "أنا جعان.", "translation": "J''ai faim."}], "unitId": "ar.v.ana"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ezzayyak', 'ar', 'إزيك', 'comment vas-tu ?', 'La question qu''on pose en premier à quelqu''un. إ | ز | يك : trois blocs. Elle se prononce un peu autrement pour un homme et pour une femme, mais elle s''écrit pareil.', '[{"text": "إزيك يا مينا؟", "translation": "Comment vas-tu, Mina ?"}, {"text": "إزيك يا تيتة؟", "translation": "Comment vas-tu, mamie ?"}]'::jsonb, null, '{"id": "ar.d.ezzayyak", "word": "إزيك", "translation": "comment vas-tu ?", "partOfSpeech": "expression", "explanation": "La question qu''on pose en premier à quelqu''un. إ | ز | يك : trois blocs. Elle se prononce un peu autrement pour un homme et pour une femme, mais elle s''écrit pareil.", "examples": [{"text": "إزيك يا مينا؟", "translation": "Comment vas-tu, Mina ?"}, {"text": "إزيك يا تيتة؟", "translation": "Comment vas-tu, mamie ?"}], "unitId": "ar.v.ezzayyak"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kwayyis', 'ar', 'كويس', 'bien', 'Le mot de tous les jours pour dire « bien, bon ». Il s''accorde : كويسة pour une femme ou une chose féminine.', '[{"text": "أنا كويس.", "translation": "Je vais bien."}, {"text": "الشاي كويس.", "translation": "Le thé est bon."}]'::jsonb, null, '{"id": "ar.d.kwayyis", "word": "كويس", "translation": "bien", "partOfSpeech": "adjective", "explanation": "Le mot de tous les jours pour dire « bien, bon ». Il s''accorde : كويسة pour une femme ou une chose féminine.", "examples": [{"text": "أنا كويس.", "translation": "Je vais bien."}, {"text": "الشاي كويس.", "translation": "Le thé est bon."}], "unitId": "ar.v.kwayyis", "forms": {"feminine": "كويسة", "plural": "كويسين"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.elhamdulillah', 'ar', 'الحمد لله', 'Dieu merci', 'À la lettre « la louange est à Dieu ». Les Égyptiens l''ajoutent presque toujours quand ils disent qu''ils vont bien.', '[{"text": "كويس، الحمد لله.", "translation": "Bien, Dieu merci."}, {"text": "خلصت الشغل، الحمد لله.", "translation": "J''ai fini le travail, Dieu merci."}]'::jsonb, null, '{"id": "ar.d.elhamdulillah", "word": "الحمد لله", "translation": "Dieu merci", "partOfSpeech": "expression", "explanation": "À la lettre « la louange est à Dieu ». Les Égyptiens l''ajoutent presque toujours quand ils disent qu''ils vont bien.", "examples": [{"text": "كويس، الحمد لله.", "translation": "Bien, Dieu merci."}, {"text": "خلصت الشغل، الحمد لله.", "translation": "J''ai fini le travail, Dieu merci."}], "unitId": "ar.v.elhamdulillah"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.fin', 'ar', 'فين', 'où', 'Le mot pour demander un lieu. Il se place presque toujours au début de la phrase.', '[{"text": "فين الباب؟", "translation": "Où est la porte ?"}, {"text": "إنت فين؟", "translation": "Tu es où ?"}]'::jsonb, null, '{"id": "ar.d.fin", "word": "فين", "translation": "où", "partOfSpeech": "adverb", "explanation": "Le mot pour demander un lieu. Il se place presque toujours au début de la phrase.", "examples": [{"text": "فين الباب؟", "translation": "Où est la porte ?"}, {"text": "إنت فين؟", "translation": "Tu es où ?"}], "unitId": "ar.v.fin", "confusions": [{"word": "في", "note": "في (dans) ne diffère de فين que par le ن final."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ahlan', 'ar', 'أهلا', 'salut, bienvenue', 'Un salut chaleureux : « salut » ou « bienvenue ».', '[{"text": "أهلا يا مينا!", "translation": "Salut Mina !"}, {"text": "أهلا وسهلا.", "translation": "Bienvenue."}]'::jsonb, null, '{"id": "ar.d.ahlan", "word": "أهلا", "translation": "salut, bienvenue", "partOfSpeech": "interjection", "explanation": "Un salut chaleureux : « salut » ou « bienvenue ».", "examples": [{"text": "أهلا يا مينا!", "translation": "Salut Mina !"}, {"text": "أهلا وسهلا.", "translation": "Bienvenue."}], "unitId": "ar.v.ahlan"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.shokran', 'ar', 'شكرا', 'merci', 'Merci. On peut ajouter كتير ou أوي pour dire « merci beaucoup ».', '[{"text": "شكرا يا مينا.", "translation": "Merci, Mina."}, {"text": "شكرا كتير.", "translation": "Merci beaucoup."}]'::jsonb, null, '{"id": "ar.d.shokran", "word": "شكرا", "translation": "merci", "partOfSpeech": "interjection", "explanation": "Merci. On peut ajouter كتير ou أوي pour dire « merci beaucoup ».", "examples": [{"text": "شكرا يا مينا.", "translation": "Merci, Mina."}, {"text": "شكرا كتير.", "translation": "Merci beaucoup."}], "unitId": "ar.v.shokran"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.law_samaht', 'ar', 'لو سمحت', 'excuse-moi (pour interpeller)', 'À la lettre « si tu permets ». On l''emploie pour attirer l''attention de quelqu''un ou demander poliment.', '[{"text": "لو سمحت، فين الكنيسة؟", "translation": "Excuse-moi, où est l''église ?"}, {"text": "لو سمحت، كوباية مية.", "translation": "S''il te plaît, un verre d''eau."}]'::jsonb, null, '{"id": "ar.d.law_samaht", "word": "لو سمحت", "translation": "excuse-moi (pour interpeller)", "partOfSpeech": "expression", "explanation": "À la lettre « si tu permets ». On l''emploie pour attirer l''attention de quelqu''un ou demander poliment.", "examples": [{"text": "لو سمحت، فين الكنيسة؟", "translation": "Excuse-moi, où est l''église ?"}, {"text": "لو سمحت، كوباية مية.", "translation": "S''il te plaît, un verre d''eau."}], "unitId": "ar.v.law_samaht"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sabah_el_kheir', 'ar', 'صباح الخير', 'bonjour (le matin)', 'Le salut du matin, à la lettre « matin du bien ». On répond صباح النور.', '[{"text": "صباح الخير يا تيتة.", "translation": "Bonjour mamie."}, {"text": "صباح النور!", "translation": "Bonjour ! (en réponse)"}]'::jsonb, null, '{"id": "ar.d.sabah_el_kheir", "word": "صباح الخير", "translation": "bonjour (le matin)", "partOfSpeech": "expression", "explanation": "Le salut du matin, à la lettre « matin du bien ». On répond صباح النور.", "examples": [{"text": "صباح الخير يا تيتة.", "translation": "Bonjour mamie."}, {"text": "صباح النور!", "translation": "Bonjour ! (en réponse)"}], "unitId": "ar.v.sabah_el_kheir"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ya_nida', 'ar', 'يا', 'ô (pour appeler quelqu''un)', 'Petit mot placé devant un prénom ou un titre pour appeler la personne. On le retrouve dans يا رب (Seigneur).', '[{"text": "يا مينا!", "translation": "Mina !"}, {"text": "يا رب ارحم.", "translation": "Seigneur, aie pitié."}]'::jsonb, null, '{"id": "ar.d.ya_nida", "word": "يا", "translation": "ô (pour appeler quelqu''un)", "partOfSpeech": "particle", "explanation": "Petit mot placé devant un prénom ou un titre pour appeler la personne. On le retrouve dans يا رب (Seigneur).", "examples": [{"text": "يا مينا!", "translation": "Mina !"}, {"text": "يا رب ارحم.", "translation": "Seigneur, aie pitié."}], "unitId": "ar.v.ya_nida"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ya_rab_irham', 'ar', 'يا رب ارحم', 'Seigneur, aie pitié', 'La réponse la plus répétée de la liturgie. Le mot ارحم s''écrit parfois إرحم avec une petite hamza : c''est le même mot.', '[{"text": "يا رب ارحم.", "translation": "Seigneur, aie pitié."}, {"text": "يا رب ارحمنا.", "translation": "Seigneur, aie pitié de nous."}]'::jsonb, null, '{"id": "ar.d.ya_rab_irham", "word": "يا رب ارحم", "translation": "Seigneur, aie pitié", "partOfSpeech": "expression", "explanation": "La réponse la plus répétée de la liturgie. Le mot ارحم s''écrit parfois إرحم avec une petite hamza : c''est le même mot.", "examples": [{"text": "يا رب ارحم.", "translation": "Seigneur, aie pitié."}, {"text": "يا رب ارحمنا.", "translation": "Seigneur, aie pitié de nous."}], "unitId": "ar.v.ya_rab_irham"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.salam_likol', 'ar', 'السلام لكل', 'la paix à tous', 'Le souhait du prêtre à l''assemblée. On le trouve aussi écrit السلام للكل : c''est le même souhait.', '[{"text": "السلام لكل.", "translation": "La paix à tous."}, {"text": "السلام لكل. ولروحك أيضا.", "translation": "La paix à tous. Et à ton esprit aussi."}]'::jsonb, null, '{"id": "ar.d.salam_likol", "word": "السلام لكل", "translation": "la paix à tous", "partOfSpeech": "expression", "explanation": "Le souhait du prêtre à l''assemblée. On le trouve aussi écrit السلام للكل : c''est le même souhait.", "examples": [{"text": "السلام لكل.", "translation": "La paix à tous."}, {"text": "السلام لكل. ولروحك أيضا.", "translation": "La paix à tous. Et à ton esprit aussi."}], "unitId": "ar.v.salam_likol", "confusions": [{"word": "لك", "note": "لك veut dire « à toi » ; لكل veut dire « à tous »."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.wi_liruhak_ayan', 'ar', 'ولروحك أيضا', 'et à ton esprit aussi', 'La réponse du peuple à السلام لكل. Selon les livres, on écrit أيضا ou أيضًا avec un signe.', '[{"text": "ولروحك أيضا.", "translation": "Et à ton esprit aussi."}, {"text": "السلام لكل — ولروحك أيضا.", "translation": "La paix à tous — Et à ton esprit aussi."}]'::jsonb, null, '{"id": "ar.d.wi_liruhak_ayan", "word": "ولروحك أيضا", "translation": "et à ton esprit aussi", "partOfSpeech": "expression", "explanation": "La réponse du peuple à السلام لكل. Selon les livres, on écrit أيضا ou أيضًا avec un signe.", "examples": [{"text": "ولروحك أيضا.", "translation": "Et à ton esprit aussi."}, {"text": "السلام لكل — ولروحك أيضا.", "translation": "La paix à tous — Et à ton esprit aussi."}], "unitId": "ar.v.wi_liruhak_ayan"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.magd_lak', 'ar', 'المجد لك يا رب', 'gloire à toi, Seigneur', 'Une louange de l''assemblée. Elle contient ال + مجد (la gloire), لك (à toi) et يا رب (Seigneur).', '[{"text": "المجد لك يا رب.", "translation": "Gloire à toi, Seigneur."}, {"text": "المجد لك يا رب، المجد لك.", "translation": "Gloire à toi, Seigneur, gloire à toi."}]'::jsonb, null, '{"id": "ar.d.magd_lak", "word": "المجد لك يا رب", "translation": "gloire à toi, Seigneur", "partOfSpeech": "expression", "explanation": "Une louange de l''assemblée. Elle contient ال + مجد (la gloire), لك (à toi) et يا رب (Seigneur).", "examples": [{"text": "المجد لك يا رب.", "translation": "Gloire à toi, Seigneur."}, {"text": "المجد لك يا رب، المجد لك.", "translation": "Gloire à toi, Seigneur, gloire à toi."}], "unitId": "ar.v.magd_lak"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tasbiha', 'ar', 'تسبحة', 'office de louange', 'L''office de louange de l''église, fait de chants et de psaumes. Le mot vient de la même idée que « louer ».', '[{"text": "رايح التسبحة النهارده.", "translation": "Je vais à l''office de louange aujourd''hui."}, {"text": "التسبحة بتبدأ بدري.", "translation": "L''office de louange commence tôt."}]'::jsonb, null, '{"id": "ar.d.tasbiha", "word": "تسبحة", "translation": "office de louange", "partOfSpeech": "noun", "explanation": "L''office de louange de l''église, fait de chants et de psaumes. Le mot vient de la même idée que « louer ».", "examples": [{"text": "رايح التسبحة النهارده.", "translation": "Je vais à l''office de louange aujourd''hui."}, {"text": "التسبحة بتبدأ بدري.", "translation": "L''office de louange commence tôt."}], "unitId": "ar.v.tasbiha"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.agbiya', 'ar', 'أجبية', 'livre des heures', 'Le livre des prières des heures de la journée, que beaucoup de Coptes gardent dans leur sac ou sur leur téléphone. On écrit aussi الأجبية avec ال.', '[{"text": "الأجبية في الشنطة.", "translation": "Le livre des heures est dans le sac."}, {"text": "بنصلي من الأجبية.", "translation": "Nous prions avec le livre des heures."}]'::jsonb, null, '{"id": "ar.d.agbiya", "word": "أجبية", "translation": "livre des heures", "partOfSpeech": "noun", "explanation": "Le livre des prières des heures de la journée, que beaucoup de Coptes gardent dans leur sac ou sur leur téléphone. On écrit aussi الأجبية avec ال.", "examples": [{"text": "الأجبية في الشنطة.", "translation": "Le livre des heures est dans le sac."}, {"text": "بنصلي من الأجبية.", "translation": "Nous prions avec le livre des heures."}], "unitId": "ar.v.agbiya"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.halleluya', 'ar', 'هللويا', 'alléluia', 'Un cri de louange qui vient de l''hébreu et veut dire « louez le Seigneur ».', '[{"text": "هللويا!", "translation": "Alléluia !"}, {"text": "هللويا، المسيح قام.", "translation": "Alléluia, le Christ est ressuscité."}]'::jsonb, null, '{"id": "ar.d.halleluya", "word": "هللويا", "translation": "alléluia", "partOfSpeech": "interjection", "explanation": "Un cri de louange qui vient de l''hébreu et veut dire « louez le Seigneur ».", "examples": [{"text": "هللويا!", "translation": "Alléluia !"}, {"text": "هللويا، المسيح قام.", "translation": "Alléluia, le Christ est ressuscité."}], "unitId": "ar.v.halleluya"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.masih_qam', 'ar', 'المسيح قام', 'le Christ est ressuscité', 'Le salut du temps pascal. On répond بالحقيقة قام, « il est vraiment ressuscité ».', '[{"text": "المسيح قام!", "translation": "Le Christ est ressuscité !"}, {"text": "بالحقيقة قام!", "translation": "Il est vraiment ressuscité !"}]'::jsonb, null, '{"id": "ar.d.masih_qam", "word": "المسيح قام", "translation": "le Christ est ressuscité", "partOfSpeech": "expression", "explanation": "Le salut du temps pascal. On répond بالحقيقة قام, « il est vraiment ressuscité ».", "examples": [{"text": "المسيح قام!", "translation": "Le Christ est ressuscité !"}, {"text": "بالحقيقة قام!", "translation": "Il est vraiment ressuscité !"}], "unitId": "ar.v.masih_qam"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.quddus', 'ar', 'قدوس', 'saint', 'Saint, au sens de « consacré à Dieu ». Tu l''entends dans l''hymne qui commence par قدوس الله.', '[{"text": "قدوس الله.", "translation": "Saint Dieu."}, {"text": "قدوس القوي.", "translation": "Saint Fort."}]'::jsonb, null, '{"id": "ar.d.quddus", "word": "قدوس", "translation": "saint", "partOfSpeech": "adjective", "explanation": "Saint, au sens de « consacré à Dieu ». Tu l''entends dans l''hymne qui commence par قدوس الله.", "examples": [{"text": "قدوس الله.", "translation": "Saint Dieu."}, {"text": "قدوس القوي.", "translation": "Saint Fort."}], "unitId": "ar.v.quddus"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kutub_katab', 'ar', 'كتب', 'livres ; il a écrit', 'Un seul squelette de consonnes pour deux mots : كُتُب (livres) et كَتَب (il a écrit). C''est la phrase qui décide.', '[{"text": "عندي كتب كتير.", "translation": "J''ai beaucoup de livres."}, {"text": "بابا كتب جواب.", "translation": "Papa a écrit une lettre."}]'::jsonb, null, '{"id": "ar.d.kutub_katab", "word": "كتب", "translation": "livres ; il a écrit", "partOfSpeech": "noun", "explanation": "Un seul squelette de consonnes pour deux mots : كُتُب (livres) et كَتَب (il a écrit). C''est la phrase qui décide.", "examples": [{"text": "عندي كتب كتير.", "translation": "J''ai beaucoup de livres."}, {"text": "بابا كتب جواب.", "translation": "Papa a écrit une lettre."}], "unitId": "ar.v.kutub_katab", "forms": {"livres": "كُتُب", "il a écrit": "كَتَب"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.alam_ilm', 'ar', 'علم', 'drapeau ; science', 'Deux mots avec les mêmes consonnes : عَلَم (drapeau) et عِلْم (science). Le contexte les sépare.', '[{"text": "علم مصر.", "translation": "Le drapeau de l''Égypte."}, {"text": "العلم نور.", "translation": "La science est une lumière."}]'::jsonb, null, '{"id": "ar.d.alam_ilm", "word": "علم", "translation": "drapeau ; science", "partOfSpeech": "noun", "explanation": "Deux mots avec les mêmes consonnes : عَلَم (drapeau) et عِلْم (science). Le contexte les sépare.", "examples": [{"text": "علم مصر.", "translation": "Le drapeau de l''Égypte."}, {"text": "العلم نور.", "translation": "La science est une lumière."}], "unitId": "ar.v.alam_ilm", "forms": {"drapeau": "عَلَم", "science": "عِلْم"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.akl_akal', 'ar', 'أكل', 'nourriture ; il a mangé', 'Deux mots avec les mêmes consonnes : أَكْل (nourriture) et أَكَل (il a mangé). Avec ال devant, c''est le nom : الأكل.', '[{"text": "الأكل حلو.", "translation": "La nourriture est bonne."}, {"text": "بابا أكل سمك.", "translation": "Papa a mangé du poisson."}]'::jsonb, null, '{"id": "ar.d.akl_akal", "word": "أكل", "translation": "nourriture ; il a mangé", "partOfSpeech": "noun", "explanation": "Deux mots avec les mêmes consonnes : أَكْل (nourriture) et أَكَل (il a mangé). Avec ال devant, c''est le nom : الأكل.", "examples": [{"text": "الأكل حلو.", "translation": "La nourriture est bonne."}, {"text": "بابا أكل سمك.", "translation": "Papa a mangé du poisson."}], "unitId": "ar.v.akl_akal", "forms": {"nourriture": "أَكْل", "il a mangé": "أَكَل"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.andi', 'ar', 'عندي', 'j''ai', 'À la lettre « chez moi » : c''est ainsi qu''on dit « j''ai » en égyptien.', '[{"text": "عندي ولد وبنت.", "translation": "J''ai un garçon et une fille."}, {"text": "عندي موبايل جديد.", "translation": "J''ai un nouveau portable."}]'::jsonb, null, '{"id": "ar.d.andi", "word": "عندي", "translation": "j''ai", "partOfSpeech": "expression", "explanation": "À la lettre « chez moi » : c''est ainsi qu''on dit « j''ai » en égyptien.", "examples": [{"text": "عندي ولد وبنت.", "translation": "J''ai un garçon et une fille."}, {"text": "عندي موبايل جديد.", "translation": "J''ai un nouveau portable."}], "unitId": "ar.v.andi"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kitir', 'ar', 'كتير', 'beaucoup', '« Beaucoup » ou « nombreux ». Il se place après ce qu''il décrit.', '[{"text": "شكرا كتير.", "translation": "Merci beaucoup."}, {"text": "عندي شغل كتير.", "translation": "J''ai beaucoup de travail."}]'::jsonb, null, '{"id": "ar.d.kitir", "word": "كتير", "translation": "beaucoup", "partOfSpeech": "adverb", "explanation": "« Beaucoup » ou « nombreux ». Il se place après ce qu''il décrit.", "examples": [{"text": "شكرا كتير.", "translation": "Merci beaucoup."}, {"text": "عندي شغل كتير.", "translation": "J''ai beaucoup de travail."}], "unitId": "ar.v.kitir"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.gawab', 'ar', 'جواب', 'lettre (courrier)', 'Une lettre, un courrier ; le mot veut dire aussi « réponse ».', '[{"text": "بابا كتب جواب.", "translation": "Papa a écrit une lettre."}, {"text": "مستني جواب منك.", "translation": "J''attends ta réponse."}]'::jsonb, null, '{"id": "ar.d.gawab", "word": "جواب", "translation": "lettre (courrier)", "partOfSpeech": "noun", "explanation": "Une lettre, un courrier ; le mot veut dire aussi « réponse ».", "examples": [{"text": "بابا كتب جواب.", "translation": "Papa a écrit une lettre."}, {"text": "مستني جواب منك.", "translation": "J''attends ta réponse."}], "unitId": "ar.v.gawab"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.masr', 'ar', 'مصر', 'Égypte', 'Le nom de l''Égypte. Dans les provinces, on dit parfois مصر pour parler du Caire.', '[{"text": "أنا من مصر.", "translation": "Je suis d''Égypte."}, {"text": "علم مصر.", "translation": "Le drapeau de l''Égypte."}]'::jsonb, null, '{"id": "ar.d.masr", "word": "مصر", "translation": "Égypte", "partOfSpeech": "noun", "explanation": "Le nom de l''Égypte. Dans les provinces, on dit parfois مصر pour parler du Caire.", "examples": [{"text": "أنا من مصر.", "translation": "Je suis d''Égypte."}, {"text": "علم مصر.", "translation": "Le drapeau de l''Égypte."}], "unitId": "ar.v.masr"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.da', 'ar', 'ده', 'ça, ce (masculin)', '« Ça » ou « ce » pour un mot masculin. Il se place avant ou après le nom : ده بيت (c''est une maison) ou البيت ده (cette maison).', '[{"text": "ده بيت.", "translation": "C''est une maison."}, {"text": "الكتاب ده كويس.", "translation": "Ce livre est bien."}]'::jsonb, null, '{"id": "ar.d.da", "word": "ده", "translation": "ça, ce (masculin)", "partOfSpeech": "pronoun", "explanation": "« Ça » ou « ce » pour un mot masculin. Il se place avant ou après le nom : ده بيت (c''est une maison) ou البيت ده (cette maison).", "examples": [{"text": "ده بيت.", "translation": "C''est une maison."}, {"text": "الكتاب ده كويس.", "translation": "Ce livre est bien."}], "unitId": "ar.v.da", "confusions": [{"word": "دي", "note": "دي est le féminin et دول le pluriel."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
