insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.fi', 'ar', 'في', 'dans ; il y a', 'Deux sens : « dans » (في الكنيسة) et « il y a » (في شاي ؟).', '[{"text": "في الكنيسة.", "translation": "Dans l''église."}, {"text": "في شاي؟", "translation": "Il y a du thé ?"}]'::jsonb, null, '{"id": "ar.d.fi", "word": "في", "translation": "dans ; il y a", "partOfSpeech": "preposition", "explanation": "Deux sens : « dans » (في الكنيسة) et « il y a » (في شاي ؟).", "examples": [{"text": "في الكنيسة.", "translation": "Dans l''église."}, {"text": "في شاي؟", "translation": "Il y a du thé ?"}], "unitId": "ar.v.fi", "confusions": [{"word": "فين", "note": "فين (où) a un ن de plus que في (dans)."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
