insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.rayeh', 'ar', 'رايح', 'je vais, il va', 'À la lettre « allant ». Pour une femme, رايحة ; pour plusieurs personnes, رايحين. Il sert à dire où l''on va.', '[{"text": "أنا رايح الكنيسة.", "translation": "Je vais à l''église."}, {"text": "ماما رايحة الشغل.", "translation": "Maman va au travail."}]'::jsonb, null, '{"id": "ar.d.rayeh", "word": "رايح", "translation": "je vais, il va", "partOfSpeech": "adjective", "explanation": "À la lettre « allant ». Pour une femme, رايحة ; pour plusieurs personnes, رايحين. Il sert à dire où l''on va.", "examples": [{"text": "أنا رايح الكنيسة.", "translation": "Je vais à l''église."}, {"text": "ماما رايحة الشغل.", "translation": "Maman va au travail."}], "unitId": "ar.v.rayeh", "forms": {"féminin": "رايحة", "pluriel": "رايحين"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
