insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.metro', 'ar', 'مترو', 'métro', 'Le métro. Le mot vient du français, écrit comme on le dit.', '[{"text": "المترو سريع.", "translation": "Le métro est rapide."}, {"text": "رايح بالمترو.", "translation": "Je vais en métro."}]'::jsonb, null, '{"id": "ar.d.metro", "word": "مترو", "translation": "métro", "partOfSpeech": "noun", "explanation": "Le métro. Le mot vient du français, écrit comme on le dit.", "examples": [{"text": "المترو سريع.", "translation": "Le métro est rapide."}, {"text": "رايح بالمترو.", "translation": "Je vais en métro."}], "unitId": "ar.v.metro"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.share', 'ar', 'شارع', 'rue', 'La rue. شا | ر | ع : trois blocs, le ا et le ر ferment chacun un bloc.', '[{"text": "الشارع زحمة.", "translation": "La rue est bondée."}, {"text": "الكنيسة في الشارع ده.", "translation": "L''église est dans cette rue."}]'::jsonb, null, '{"id": "ar.d.share", "word": "شارع", "translation": "rue", "partOfSpeech": "noun", "explanation": "La rue. شا | ر | ع : trois blocs, le ا et le ر ferment chacun un bloc.", "examples": [{"text": "الشارع زحمة.", "translation": "La rue est bondée."}, {"text": "الكنيسة في الشارع ده.", "translation": "L''église est dans cette rue."}], "unitId": "ar.v.share", "forms": {"plural": "شوارع"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mahatta', 'ar', 'محطة', 'station', 'Une station de métro, de bus ou de train. Un seul bloc de quatre lettres.', '[{"text": "محطة المترو قريبة.", "translation": "La station de métro est proche."}, {"text": "المحطة الجاية.", "translation": "La prochaine station."}]'::jsonb, null, '{"id": "ar.d.mahatta", "word": "محطة", "translation": "station", "partOfSpeech": "noun", "explanation": "Une station de métro, de bus ou de train. Un seul bloc de quatre lettres.", "examples": [{"text": "محطة المترو قريبة.", "translation": "La station de métro est proche."}, {"text": "المحطة الجاية.", "translation": "La prochaine station."}], "unitId": "ar.v.mahatta", "forms": {"plural": "محطات"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.el_ahad', 'ar', 'الأحد', 'dimanche', 'Le dimanche, premier jour de la semaine en arabe. ا | لأ | حد : trois blocs, avec ال au début.', '[{"text": "القداس يوم الأحد.", "translation": "La liturgie est le dimanche."}, {"text": "الأحد الجاي.", "translation": "Dimanche prochain."}]'::jsonb, null, '{"id": "ar.d.el_ahad", "word": "الأحد", "translation": "dimanche", "partOfSpeech": "noun", "explanation": "Le dimanche, premier jour de la semaine en arabe. ا | لأ | حد : trois blocs, avec ال au début.", "examples": [{"text": "القداس يوم الأحد.", "translation": "La liturgie est le dimanche."}, {"text": "الأحد الجاي.", "translation": "Dimanche prochain."}], "unitId": "ar.v.el_ahad"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.madares_el_ahad', 'ar', 'مدارس الأحد', 'école du dimanche', 'L''école du dimanche de l''église, où enfants et jeunes apprennent la foi. Le mot مدارس est le pluriel de مدرسة.', '[{"text": "أنا رايح مدارس الأحد.", "translation": "Je vais à l''école du dimanche."}, {"text": "مدارس الأحد النهارده.", "translation": "L''école du dimanche, c''est aujourd''hui."}]'::jsonb, null, '{"id": "ar.d.madares_el_ahad", "word": "مدارس الأحد", "translation": "école du dimanche", "partOfSpeech": "expression", "explanation": "L''école du dimanche de l''église, où enfants et jeunes apprennent la foi. Le mot مدارس est le pluriel de مدرسة.", "examples": [{"text": "أنا رايح مدارس الأحد.", "translation": "Je vais à l''école du dimanche."}, {"text": "مدارس الأحد النهارده.", "translation": "L''école du dimanche, c''est aujourd''hui."}], "unitId": "ar.v.madares_el_ahad"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mesa_el_kheir', 'ar', 'مساء الخير', 'bonsoir', 'Salutation de l''après-midi et du soir, littéralement « soir du bien ». On répond مساء النور.', '[{"text": "مساء الخير يا جماعة", "translation": "Bonsoir tout le monde"}, {"text": "مساء الخير، عامل إيه؟", "translation": "Bonsoir, comment ça va ?"}]'::jsonb, null, '{"id": "ar.d.mesa_el_kheir", "word": "مساء الخير", "translation": "bonsoir", "partOfSpeech": "expression", "explanation": "Salutation de l''après-midi et du soir, littéralement « soir du bien ». On répond مساء النور.", "examples": [{"text": "مساء الخير يا جماعة", "translation": "Bonsoir tout le monde"}, {"text": "مساء الخير، عامل إيه؟", "translation": "Bonsoir, comment ça va ?"}], "unitId": "ar.v.mesa_el_kheir", "confusions": [{"word": "صباح الخير", "note": "Le matin, on remplace مساء par صباح."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sabah_el_nur', 'ar', 'صباح النور', 'bonjour (réponse)', 'La réponse à صباح الخير, littéralement « matin de lumière » : on renchérit sur le bien avec la lumière.', '[{"text": "صباح الخير يا مينا — صباح النور", "translation": "Bonjour, Mina — Bonjour (réponse)"}, {"text": "صباح النور يا أبونا", "translation": "Bonjour, notre père (réponse)"}]'::jsonb, null, '{"id": "ar.d.sabah_el_nur", "word": "صباح النور", "translation": "bonjour (réponse)", "partOfSpeech": "expression", "explanation": "La réponse à صباح الخير, littéralement « matin de lumière » : on renchérit sur le bien avec la lumière.", "examples": [{"text": "صباح الخير يا مينا — صباح النور", "translation": "Bonjour, Mina — Bonjour (réponse)"}, {"text": "صباح النور يا أبونا", "translation": "Bonjour, notre père (réponse)"}], "unitId": "ar.v.sabah_el_nur"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
