insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.amel_eih', 'ar', 'عامل إيه', 'comment ça va ?', 'Littéralement « tu fais quoi ? », mais on comprend « comment ça va ? ». À une femme : عاملة إيه.', '[{"text": "عامل إيه يا بيشوي؟", "translation": "Comment ça va, Bishoy ?"}, {"text": "عاملة إيه يا مريم؟", "translation": "Comment ça va, Mariam ?"}]'::jsonb, null, '{"id": "ar.d.amel_eih", "word": "عامل إيه", "translation": "comment ça va ?", "partOfSpeech": "expression", "explanation": "Littéralement « tu fais quoi ? », mais on comprend « comment ça va ? ». À une femme : عاملة إيه.", "examples": [{"text": "عامل إيه يا بيشوي؟", "translation": "Comment ça va, Bishoy ?"}, {"text": "عاملة إيه يا مريم؟", "translation": "Comment ça va, Mariam ?"}], "unitId": "ar.v.amel_eih", "forms": {"féminin": "عاملة إيه"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
