insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.men_fadlak', 'ar', 'من فضلك', 's''il te plaît', 'Littéralement « de ta faveur ». On l''ajoute à une demande précise : une commande, un service.', '[{"text": "من فضلك، عايز شاي", "translation": "S''il te plaît, je veux un thé"}, {"text": "من فضلك يا أستاذ", "translation": "S''il vous plaît, monsieur"}]'::jsonb, null, '{"id": "ar.d.men_fadlak", "word": "من فضلك", "translation": "s''il te plaît", "partOfSpeech": "expression", "explanation": "Littéralement « de ta faveur ». On l''ajoute à une demande précise : une commande, un service.", "examples": [{"text": "من فضلك، عايز شاي", "translation": "S''il te plaît, je veux un thé"}, {"text": "من فضلك يا أستاذ", "translation": "S''il vous plaît, monsieur"}], "unitId": "ar.v.men_fadlak"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
