insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.maalesh', 'ar', 'معلش', 'pardon, ce n''est pas grave', 'Le mot passe-partout : on s''excuse, on console ou on relativise. Le ton fait le sens.', '[{"text": "معلش، اتأخرت", "translation": "Pardon, je suis en retard"}, {"text": "معلش يا حبيبي", "translation": "Ce n''est pas grave, mon chéri"}]'::jsonb, null, '{"id": "ar.d.maalesh", "word": "معلش", "translation": "pardon, ce n''est pas grave", "partOfSpeech": "expression", "explanation": "Le mot passe-partout : on s''excuse, on console ou on relativise. Le ton fait le sens.", "examples": [{"text": "معلش، اتأخرت", "translation": "Pardon, je suis en retard"}, {"text": "معلش يا حبيبي", "translation": "Ce n''est pas grave, mon chéri"}], "unitId": "ar.v.maalesh", "otherTranslations": ["désolé", "tant pis"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
