insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.asir', 'ar', 'عصير', 'jus', 'Le jus de fruits. Le plus célèbre : عصير قصب, le jus de canne à sucre.', '[{"text": "عصير مانجو", "translation": "Jus de mangue"}, {"text": "عصير قصب", "translation": "Jus de canne à sucre"}]'::jsonb, null, '{"id": "ar.d.asir", "word": "عصير", "translation": "jus", "partOfSpeech": "noun", "explanation": "Le jus de fruits. Le plus célèbre : عصير قصب, le jus de canne à sucre.", "examples": [{"text": "عصير مانجو", "translation": "Jus de mangue"}, {"text": "عصير قصب", "translation": "Jus de canne à sucre"}], "unitId": "ar.v.asir"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.lahma', 'ar', 'لحمة', 'viande', 'La viande, surtout le bœuf et l''agneau. Le poulet a son propre mot : فراخ.', '[{"text": "اللحمة غالية", "translation": "La viande est chère"}, {"text": "مفيش لحمة في الصيام", "translation": "Pas de viande pendant le jeûne"}]'::jsonb, null, '{"id": "ar.d.lahma", "word": "لحمة", "translation": "viande", "partOfSpeech": "noun", "explanation": "La viande, surtout le bœuf et l''agneau. Le poulet a son propre mot : فراخ.", "examples": [{"text": "اللحمة غالية", "translation": "La viande est chère"}, {"text": "مفيش لحمة في الصيام", "translation": "Pas de viande pendant le jeûne"}], "unitId": "ar.v.lahma"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
