insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.haga', 'ar', 'حاجة', 'chose, quelque chose', 'Une chose, quelque chose : mot passe-partout. حاجة ساقعة (« une chose froide ») est un soda.', '[{"text": "عايز حاجة؟", "translation": "Tu veux quelque chose ?"}, {"text": "حاجة ساقعة", "translation": "Une boisson fraîche"}]'::jsonb, null, '{"id": "ar.d.haga", "word": "حاجة", "translation": "chose, quelque chose", "partOfSpeech": "noun", "explanation": "Une chose, quelque chose : mot passe-partout. حاجة ساقعة (« une chose froide ») est un soda.", "examples": [{"text": "عايز حاجة؟", "translation": "Tu veux quelque chose ?"}, {"text": "حاجة ساقعة", "translation": "Une boisson fraîche"}], "unitId": "ar.v.haga"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
