insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.baadein', 'ar', 'بعدين', 'plus tard, ensuite', 'Plus tard, ensuite. Pratique pour remettre à plus tard : ماشي، بعدين.', '[{"text": "ماشي، بعدين", "translation": "D''accord, plus tard"}, {"text": "هكلمك بعدين", "translation": "Je t''appellerai plus tard"}]'::jsonb, null, '{"id": "ar.d.baadein", "word": "بعدين", "translation": "plus tard, ensuite", "partOfSpeech": "adverb", "explanation": "Plus tard, ensuite. Pratique pour remettre à plus tard : ماشي، بعدين.", "examples": [{"text": "ماشي، بعدين", "translation": "D''accord, plus tard"}, {"text": "هكلمك بعدين", "translation": "Je t''appellerai plus tard"}], "unitId": "ar.v.baadein"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
